import React, { useState } from 'react';

interface CustomerRegisterProps {
  onRegister: (name: string, whatsapp: string) => void;
  onBack: () => void;
}

const CustomerRegister: React.FC<CustomerRegisterProps> = ({ onRegister, onBack }) => {
  const [name, setName] = useState('');
  const [whatsapp, setWhatsapp] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (name && whatsapp) {
      onRegister(name, whatsapp);
    }
  };

  return (
    <div className="min-h-[80vh] flex items-center justify-center px-4 py-12 bg-tea-50">
      <div className="max-w-md w-full bg-white rounded-3xl shadow-xl overflow-hidden p-8 border border-tea-100">
        <button onClick={onBack} className="text-tea-600 text-sm flex items-center gap-2 mb-8 hover:underline">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
          Voltar
        </button>

        <h2 className="text-3xl font-serif text-tea-900 mb-2">Bem-vinda!</h2>
        <p className="text-gray-500 mb-8">Precisamos de apenas alguns dados para facilitar seu agendamento.</p>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Nome Completo</label>
            <input 
              type="text" 
              required
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-tea-500 focus:ring-2 focus:ring-tea-200 outline-none transition"
              placeholder="Ex: Maria Clara"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">WhatsApp</label>
            <input 
              type="tel" 
              required
              value={whatsapp}
              onChange={(e) => setWhatsapp(e.target.value)}
              className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-tea-500 focus:ring-2 focus:ring-tea-200 outline-none transition"
              placeholder="(00) 00000-0000"
            />
          </div>

          <button 
            type="submit"
            className="w-full bg-tea-500 text-white py-4 rounded-xl font-bold text-lg hover:bg-tea-600 transition shadow-lg shadow-tea-200"
          >
            Cadastrar
          </button>
        </form>

        <p className="mt-8 text-center text-xs text-gray-400">
          Ao se cadastrar, você concorda com nossos Termos de Serviço e Política de Privacidade.
        </p>
      </div>
    </div>
  );
};

export default CustomerRegister;

import React from 'react';
import { Booking, Transaction, Customer } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface AdminDashboardProps {
  bookings: Booking[];
  transactions: Transaction[];
  customers: Customer[];
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ bookings, transactions, customers }) => {
  const totalReceivable = transactions
    .filter(t => t.type === 'receivable')
    .reduce((acc, t) => acc + t.amount, 0);

  const totalPayable = transactions
    .filter(t => t.type === 'payable')
    .reduce((acc, t) => acc + t.amount, 0);

  const stats = [
    { label: 'Agendamentos', value: bookings.length, icon: '📅', color: 'bg-blue-50 text-blue-600' },
    { label: 'Clientes', value: customers.length, icon: '👤', color: 'bg-tea-50 text-tea-600' },
    { label: 'A Receber', value: `R$ ${totalReceivable.toFixed(2)}`, icon: '💰', color: 'bg-green-50 text-green-600' },
    { label: 'A Pagar', value: `R$ ${totalPayable.toFixed(2)}`, icon: '💸', color: 'bg-red-50 text-red-600' },
  ];

  const chartData = [
    { name: 'Receitas', value: totalReceivable },
    { name: 'Despesas', value: totalPayable },
  ];

  return (
    <div className="space-y-8 animate-fade-in">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Resumo Gerencial</h1>
          <p className="text-gray-500">Veja como está o Studio Moriá hoje.</p>
        </div>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {stats.map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <div className={`w-10 h-10 rounded-full ${stat.color} flex items-center justify-center text-xl mb-4`}>
              {stat.icon}
            </div>
            <p className="text-sm text-gray-500 font-medium">{stat.label}</p>
            <p className="text-2xl font-bold text-gray-900">{stat.value}</p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-bold mb-6">Fluxo Financeiro</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip cursor={{fill: 'transparent'}} />
                <Bar dataKey="value" radius={[10, 10, 0, 0]}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={index === 0 ? '#10b981' : '#ef4444'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-bold mb-6">Próximos Agendamentos</h3>
          <div className="space-y-4 max-h-64 overflow-y-auto custom-scroll">
            {bookings.length > 0 ? (
              bookings.slice(0, 5).map((booking) => (
                <div key={booking.id} className="flex items-center justify-between p-4 bg-gray-50 rounded-xl">
                  <div>
                    <p className="font-semibold text-gray-800">{booking.customerName}</p>
                    <p className="text-xs text-gray-500">{booking.serviceName}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-sm font-medium text-tea-700">
                      {new Date(booking.dateTime).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                    </p>
                    <p className="text-[10px] text-gray-400">Hoje</p>
                  </div>
                </div>
              ))
            ) : (
              <p className="text-center text-gray-400 py-10">Nenhum agendamento futuro.</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;

import React, { useState } from 'react';
import { Booking, Service } from '../types';

interface AdminCalendarProps {
  bookings: Booking[];
  setBookings: React.Dispatch<React.SetStateAction<Booking[]>>;
  services: Service[];
}

const AdminCalendar: React.FC<AdminCalendarProps> = ({ bookings, setBookings, services }) => {
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);

  const hours = Array.from({ length: 12 }, (_, i) => `${i + 8}:00`);

  const toggleStatus = (id: string) => {
    setBookings(prev => prev.map(b => 
      b.id === id ? { ...b, status: b.status === 'completed' ? 'scheduled' : 'completed' } : b
    ));
  };

  const removeBooking = (id: string) => {
    if(confirm("Deseja realmente remover este agendamento?")) {
      setBookings(prev => prev.filter(b => b.id !== id));
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold">Agenda Diária</h2>
        <input 
          type="date" 
          value={selectedDate}
          onChange={(e) => setSelectedDate(e.target.value)}
          className="p-2 border rounded-lg outline-none focus:ring-2 focus:ring-tea-200"
        />
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="grid grid-cols-1 divide-y">
          {hours.map((hour) => {
            const bookingAtHour = bookings.find(b => b.dateTime.includes(hour) && b.dateTime.startsWith(selectedDate));

            return (
              <div key={hour} className="flex p-4 hover:bg-gray-50 transition min-h-[100px]">
                <div className="w-20 pt-1">
                  <span className="text-sm font-bold text-gray-400">{hour}</span>
                </div>
                <div className="flex-grow">
                  {bookingAtHour ? (
                    <div className={`p-4 rounded-xl border-l-4 shadow-sm flex justify-between items-center ${bookingAtHour.status === 'completed' ? 'bg-gray-50 border-gray-300' : 'bg-tea-50 border-tea-500'}`}>
                      <div>
                        <p className={`font-bold ${bookingAtHour.status === 'completed' ? 'text-gray-400 line-through' : 'text-tea-900'}`}>{bookingAtHour.customerName}</p>
                        <p className="text-xs text-gray-500">{bookingAtHour.serviceName}</p>
                      </div>
                      <div className="flex gap-2">
                        <button 
                          onClick={() => toggleStatus(bookingAtHour.id)}
                          className="p-2 hover:bg-white rounded-lg transition"
                          title="Marcar como concluído"
                        >
                          {bookingAtHour.status === 'completed' ? '↩️' : '✅'}
                        </button>
                        <button 
                          onClick={() => removeBooking(bookingAtHour.id)}
                          className="p-2 hover:bg-white rounded-lg transition text-red-500"
                          title="Remover"
                        >
                          🗑️
                        </button>
                      </div>
                    </div>
                  ) : (
                    <div className="h-full flex items-center border-2 border-dashed border-gray-100 rounded-xl px-4 text-gray-300 text-sm">
                      Disponível para agendamento
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default AdminCalendar;

import React, { useState } from 'react';
import { Transaction } from '../types';

interface AdminFinanceProps {
  transactions: Transaction[];
  setTransactions: React.Dispatch<React.SetStateAction<Transaction[]>>;
}

const AdminFinance: React.FC<AdminFinanceProps> = ({ transactions, setTransactions }) => {
  const [filter, setFilter] = useState<'all' | 'payable' | 'receivable'>('all');
  const [showAdd, setShowAdd] = useState(false);
  const [newTransaction, setNewTransaction] = useState({ description: '', amount: 0, type: 'receivable' as 'payable' | 'receivable' });

  const handleAdd = () => {
    if (newTransaction.description && newTransaction.amount > 0) {
      const transaction: Transaction = {
        id: Math.random().toString(36).substr(2, 9),
        ...newTransaction,
        date: new Date().toISOString(),
        status: 'pending'
      };
      setTransactions(prev => [...prev, transaction]);
      setShowAdd(false);
      setNewTransaction({ description: '', amount: 0, type: 'receivable' });
    }
  };

  const filtered = transactions.filter(t => filter === 'all' || t.type === filter);

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold">Contas Financeiras</h2>
          <p className="text-gray-500 text-sm">Controle de caixa e pagamentos.</p>
        </div>
        <button 
          onClick={() => setShowAdd(true)}
          className="bg-tea-600 text-white px-4 py-2 rounded-xl font-bold hover:bg-tea-700 transition"
        >
          + Novo Lançamento
        </button>
      </div>

      <div className="flex gap-2">
        {(['all', 'receivable', 'payable'] as const).map(f => (
          <button 
            key={f}
            onClick={() => setFilter(f)}
            className={`px-4 py-2 rounded-full text-xs font-bold transition ${filter === f ? 'bg-tea-600 text-white' : 'bg-gray-100 text-gray-500'}`}
          >
            {f === 'all' ? 'Tudo' : f === 'receivable' ? 'Receitas' : 'Despesas'}
          </button>
        ))}
      </div>

      {showAdd && (
        <div className="bg-white p-6 rounded-2xl shadow-md border border-tea-100 animate-slide-in">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
            <input 
              placeholder="Descrição" 
              className="p-3 border rounded-xl"
              value={newTransaction.description}
              onChange={(e) => setNewTransaction({...newTransaction, description: e.target.value})}
            />
            <input 
              type="number" 
              placeholder="Valor R$" 
              className="p-3 border rounded-xl"
              value={newTransaction.amount || ''}
              onChange={(e) => setNewTransaction({...newTransaction, amount: parseFloat(e.target.value)})}
            />
            <select 
              className="p-3 border rounded-xl"
              value={newTransaction.type}
              onChange={(e) => setNewTransaction({...newTransaction, type: e.target.value as 'payable' | 'receivable'})}
            >
              <option value="receivable">Receita (Entrada)</option>
              <option value="payable">Despesa (Saída)</option>
            </select>
          </div>
          <div className="flex justify-end gap-2">
            <button onClick={() => setShowAdd(false)} className="px-4 py-2 text-gray-500">Cancelar</button>
            <button onClick={handleAdd} className="bg-tea-600 text-white px-6 py-2 rounded-xl font-bold">Salvar</button>
          </div>
        </div>
      )}

      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-gray-50 border-b border-gray-100">
            <tr>
              <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase">Data</th>
              <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase">Descrição</th>
              <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase">Tipo</th>
              <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase">Valor</th>
              <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {filtered.map(t => (
              <tr key={t.id} className="hover:bg-gray-50 transition">
                <td className="px-6 py-4 text-sm text-gray-500">{new Date(t.date).toLocaleDateString()}</td>
                <td className="px-6 py-4 text-sm font-semibold text-gray-800">{t.description}</td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase ${t.type === 'receivable' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                    {t.type === 'receivable' ? 'Receita' : 'Despesa'}
                  </span>
                </td>
                <td className={`px-6 py-4 font-bold ${t.type === 'receivable' ? 'text-green-600' : 'text-red-600'}`}>
                  {t.type === 'receivable' ? '+' : '-'} R$ {t.amount.toFixed(2)}
                </td>
                <td className="px-6 py-4 text-sm">
                  <button onClick={() => setTransactions(prev => prev.filter(x => x.id !== t.id))} className="text-gray-400 hover:text-red-500">Excluir</button>
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr>
                <td colSpan={5} className="px-6 py-12 text-center text-gray-400">Nenhum lançamento encontrado.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

