    e.preventDefault();
    if (name && whatsapp && agreedToTerms) {
      onRegister(name, whatsapp, receivesNotifications);
    } else if (!agreedToTerms) {
      alert("Para sua segurança, é necessário aceitar os termos de uso e política de privacidade.");
    }
