import React, { useState } from 'react';
import { SalonSettings, Service } from '../types';

interface AdminSettingsViewProps {
  settings: SalonSettings;
  setSettings: (s: SalonSettings) => void;
  services: Service[];
  setServices: (s: Service[]) => void;
}

const AdminSettingsView: React.FC<AdminSettingsViewProps> = ({ settings, setSettings, services, setServices }) => {
  const [newService, setNewService] = useState({ name: '', price: 0, duration: 30, description: '' });
  const [newMember, setNewMember] = useState('');

  const updateSetting = (key: string, value: any) => {
    setSettings({ ...settings, [key]: value });
  };

  const addService = () => {
    if (newService.name && newService.price > 0) {
      setServices([...services, { ...newService, id: Math.random().toString(36).substr(2, 9) }]);
      setNewService({ name: '', price: 0, duration: 30, description: '' });
    }
  };

  const removeService = (id: string) => {
    setServices(services.filter(s => s.id !== id));
  };

  const addTeamMember = () => {
    if (newMember.trim()) {
      const updatedMembers = [...(settings.teamMembers || []), newMember.trim()];
      updateSetting('teamMembers', updatedMembers);
      setNewMember('');
    }
  };

  const removeTeamMember = (index: number) => {
    const updatedMembers = (settings.teamMembers || []).filter((_, i) => i !== index);
    updateSetting('teamMembers', updatedMembers);
  };

  return (
    <div className="space-y-12 pb-20 animate-fade-in">
      {/* Visual Identity */}
      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-xl font-bold mb-6 text-tea-900 flex items-center gap-2">
           <span className="text-2xl">✨</span> Identidade Visual & Nome
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div>
            <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Nome do Salão</label>
            <input 
              value={settings.name}
              onChange={(e) => updateSetting('name', e.target.value)}
              className="w-full p-4 border-2 border-gray-50 bg-gray-50 rounded-xl focus:border-tea-200 focus:bg-white outline-none transition-all"
            />
          </div>
          <div>
            <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">URL do Logo (Drive Link)</label>
            <input 
              value={settings.logo}
              onChange={(e) => updateSetting('logo', e.target.value)}
              className="w-full p-4 border-2 border-gray-50 bg-gray-50 rounded-xl focus:border-tea-200 focus:bg-white outline-none transition-all"
            />
          </div>
        </div>
      </section>

      {/* Team Management */}
      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-xl font-bold mb-6 text-tea-900 flex items-center gap-2">
           <span className="text-2xl">👥</span> Gestão da Equipe
        </h2>

        <div className="bg-tea-50 p-6 rounded-2xl mb-8 border border-tea-100">
          <p className="text-sm text-tea-800 font-medium mb-4 italic">Adicione os nomes das profissionais que atendem no Studio.</p>
          <div className="flex gap-4">
            <input 
              placeholder="Nome da Profissional" 
              className="flex-grow p-4 border-2 border-white bg-white rounded-xl focus:border-tea-300 outline-none shadow-sm"
              value={newMember}
              onChange={(e) => setNewMember(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && addTeamMember()}
            />
            <button 
              onClick={addTeamMember}
              className="bg-[#23492d] text-white px-8 py-4 rounded-xl font-bold hover:bg-tea-900 transition-all shadow-lg"
            >
              CADASTRAR
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {(settings.teamMembers || []).map((member, index) => (
            <div key={index} className="flex justify-between items-center p-5 bg-gray-50 border border-gray-100 rounded-2xl group hover:border-tea-200 hover:bg-white transition-all">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-tea-100 rounded-full flex items-center justify-center text-tea-700 font-bold">
                  {member.charAt(0)}
                </div>
                <span className="font-bold text-gray-800">{member}</span>
              </div>
              <button 
                onClick={() => removeTeamMember(index)} 
                className="text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"
                title="Remover"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path>
                </svg>
              </button>
            </div>
          ))}
          {(settings.teamMembers || []).length === 0 && (
             <p className="col-span-full text-center py-8 text-gray-400 italic">Nenhum membro da equipe cadastrado ainda.</p>
          )}
        </div>
      </section>

      {/* Services Management */}
      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-xl font-bold mb-6 text-tea-900 flex items-center gap-2">
           <span className="text-2xl">📋</span> Gestão de Serviços
        </h2>

        <div className="bg-tea-50 p-6 rounded-2xl mb-8 border border-tea-100">
          <h3 className="font-bold text-tea-950 mb-4">Novo Procedimento</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <input 
              placeholder="Nome" 
              className="p-4 border-2 border-white bg-white rounded-xl outline-none"
              value={newService.name}
              onChange={(e) => setNewService({...newService, name: e.target.value})}
            />
            <input 
              type="number" 
              placeholder="Preço R$" 
              className="p-4 border-2 border-white bg-white rounded-xl outline-none"
              value={newService.price || ''}
              onChange={(e) => setNewService({...newService, price: parseFloat(e.target.value)})}
            />
            <input 
              type="number" 
              placeholder="Duração (min)" 
              className="p-4 border-2 border-white bg-white rounded-xl outline-none"
              value={newService.duration || ''}
              onChange={(e) => setNewService({...newService, duration: parseInt(e.target.value)})}
            />
            <button onClick={addService} className="bg-[#23492d] text-white px-6 py-4 rounded-xl font-bold hover:bg-tea-900 transition-all">Adicionar</button>
          </div>
        </div>

        <div className="space-y-4">
          {services.map(s => (
            <div key={s.id} className="flex justify-between items-center p-5 border-2 border-gray-50 rounded-2xl hover:border-tea-50 hover:bg-tea-50/20 transition-all">
              <div>
                <p className="font-bold text-tea-900 text-lg">{s.name}</p>
                <p className="text-sm text-gray-500 font-medium">R$ {s.price.toFixed(2)} • {s.duration} min</p>
              </div>
              <button onClick={() => removeService(s.id)} className="text-red-400 hover:text-red-600 text-xs font-bold uppercase tracking-widest bg-red-50 px-4 py-2 rounded-full">Remover</button>
            </div>
          ))}
        </div>
      </section>

      {/* Content & Social */}
      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-xl font-bold mb-6 text-tea-900 flex items-center gap-2">
           <span className="text-2xl">🔗</span> Redes Sociais & Contato
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div>
            <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Instagram URL</label>
            <input 
              value={settings.socialLinks.instagram}
              onChange={(e) => setSettings({ ...settings, socialLinks: { ...settings.socialLinks, instagram: e.target.value }})}
              className="w-full p-4 border-2 border-gray-50 bg-gray-50 rounded-xl focus:border-tea-200 focus:bg-white outline-none transition-all"
            />
          </div>
          <div>
            <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">WhatsApp Link</label>
            <input 
              value={settings.socialLinks.whatsapp}
              onChange={(e) => setSettings({ ...settings, socialLinks: { ...settings.socialLinks, whatsapp: e.target.value }})}
              className="w-full p-4 border-2 border-gray-50 bg-gray-50 rounded-xl focus:border-tea-200 focus:bg-white outline-none transition-all"
            />
          </div>
        </div>
      </section>
    </div>
  );
};

