import React, { useState } from 'react';
import { SalonSettings, Service } from '../types';

interface AdminSettingsViewProps {
  settings: SalonSettings;
  setSettings: (s: SalonSettings) => void;
  services: Service[];
  setServices: (s: Service[]) => void;
}

const AdminSettingsView: React.FC<AdminSettingsViewProps> = ({ settings, setSettings, services, setServices }) => {
  const [newService, setNewService] = useState({ name: '', price: 0, duration: 30, description: '' });
  const [newMember, setNewMember] = useState('');
  const [editingServiceId, setEditingServiceId] = useState<string | null>(null);
  const [editServiceData, setEditServiceData] = useState<Service | null>(null);

  const updateSetting = (key: string, value: any) => {
    setSettings({ ...settings, [key]: value });
  };

  const addService = () => {
    if (newService.name && newService.price > 0) {
      setServices([...services, { ...newService, id: Math.random().toString(36).substr(2, 9) }]);
      setNewService({ name: '', price: 0, duration: 30, description: '' });
    }
  };

  const startEditingService = (service: Service) => {
    setEditingServiceId(service.id);
    setEditServiceData({ ...service });
  };

  const cancelEditingService = () => {
    setEditingServiceId(null);
    setEditServiceData(null);
  };

  const saveEditedService = () => {
    if (editServiceData) {
      setServices(services.map(s => s.id === editingServiceId ? editServiceData : s));
      setEditingServiceId(null);
      setEditServiceData(null);
    }
  };

  const removeService = (id: string) => {
    if (confirm("Deseja remover este serviço?")) {
      setServices(services.filter(s => s.id !== id));
    }
  };

  const addTeamMember = () => {
    if (newMember.trim()) {
      const updatedMembers = [...(settings.teamMembers || []), newMember.trim()];
      updateSetting('teamMembers', updatedMembers);
      setNewMember('');
    }
