              <span className="text-tea-600 font-bold uppercase tracking-widest text-xs mb-4">Atendimento</span>
              <h3 className="text-4xl font-serif text-tea-950 mb-8 leading-tight">Dúvidas? <br/>Fale agora conosco.</h3>
              <p className="text-gray-600 text-lg font-light leading-relaxed mb-10">Estamos prontas para cuidar de você. Envie sua mensagem e retornaremos via WhatsApp.</p>
              <div className="space-y-6 inline-block mx-auto lg:mx-0">
                <div className="flex items-center gap-4 text-tea-900"><div className="w-10 h-10 bg-white rounded-xl shadow-sm flex items-center justify-center text-tea-600">📍</div><span className="text-sm font-bold uppercase tracking-widest">Praia Grande - SP</span></div>
                <div className="flex items-center gap-4 text-tea-900"><div className="w-10 h-10 bg-white rounded-xl shadow-sm flex items-center justify-center text-tea-600">📸</div><a href={settings.socialLinks.instagram} target="_blank" rel="noreferrer" className="text-sm font-bold uppercase tracking-widest hover:text-tea-600 transition-colors">@studio_moria_estetica</a></div>
              </div>
            </div>
            <div className="lg:w-3/5 p-12 md:p-16">
              <form onSubmit={handleContactSubmit} className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-3"><label className="text-[11px] font-bold text-gray-400 uppercase tracking-widest ml-1">Seu Nome</label><input required type="text" placeholder="Como você se chama?" className="w-full px-8 py-5 rounded-2xl bg-gray-50 border-2 border-transparent focus:border-tea-200 focus:bg-white outline-none transition-all text-gray-800 shadow-inner" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} /></div>
                  <div className="space-y-3"><label className="text-[11px] font-bold text-gray-400 uppercase tracking-widest ml-1">WhatsApp</label><input required type="tel" placeholder="(00) 00000-0000" className="w-full px-8 py-5 rounded-2xl bg-gray-50 border-2 border-transparent focus:border-tea-200 focus:bg-white outline-none transition-all text-gray-800 shadow-inner" value={formData.whatsapp} onChange={(e) => setFormData({...formData, whatsapp: e.target.value})} /></div>
                </div>
                <div className="space-y-3"><label className="text-[11px] font-bold text-gray-400 uppercase tracking-widest ml-1">Mensagem / Procedimento</label><textarea required placeholder="Quais procedimentos você tem interesse?" className="w-full px-8 py-5 rounded-2xl bg-gray-50 border-2 border-transparent focus:border-tea-200 focus:bg-white outline-none transition-all text-gray-800 h-40 resize-none shadow-inner" value={formData.message} onChange={(e) => setFormData({...formData, message: e.target.value})} /></div>
                <button type="submit" className="w-full bg-[#23492d] text-white py-6 rounded-2xl font-bold text-xl hover:bg-tea-900 transition-all shadow-2xl flex items-center justify-center gap-4 group">ENVIAR PARA WHATSAPP <span className="text-2xl group-hover:translate-x-2 transition-transform">→</span></button>
              </form>
            </div>
          </div>
        </div>
      </section>

      <footer className="bg-gray-50 py-16 text-center border-t border-gray-100">
        <div className="max-w-4xl mx-auto px-4 text-center">
          <div className="inline-block p-4 mb-8">
            <img src={settings.logo} className="h-24 md:h-32 w-auto grayscale brightness-50 hover:grayscale-0 hover:brightness-100 transition-all cursor-pointer" alt="Footer Logo" onClick={() => window.scrollTo({top: 0, behavior: 'smooth'})} />
          </div>
          <p className="text-gray-400 text-[10px] font-bold uppercase tracking-[0.4em]">© 2024 Studio Moriá Estética • Beleza e Bem-Estar</p>
        </div>
      </footer>
    </div>
  );
};

export default CustomerHome;

// Definindo os estados de visualização do aplicativo
export enum View {
  CUSTOMER_HOME = 'CUSTOMER_HOME',
  CUSTOMER_REGISTER = 'CUSTOMER_REGISTER',
  CUSTOMER_PROFILE = 'CUSTOMER_PROFILE',
  CUSTOMER_DASHBOARD = 'CUSTOMER_DASHBOARD',
  ADMIN_LOGIN = 'ADMIN_LOGIN',
  ADMIN_DASHBOARD = 'ADMIN_DASHBOARD',
  ADMIN_CALENDAR = 'ADMIN_CALENDAR',
  ADMIN_FINANCE = 'ADMIN_FINANCE',
  ADMIN_CLIENTS = 'ADMIN_CLIENTS',
  ADMIN_VEO = 'ADMIN_VEO',
  ADMIN_SETTINGS = 'ADMIN_SETTINGS'
}

export interface Customer {
  id: string;
  name: string;
  whatsapp: string;
  profilePhoto?: string;
  receivesNotifications: boolean;
  agreedToTerms: boolean;
  history: Booking[];
}

export interface Service {
  id: string;
  name: string;
  price: number;
  duration: number; // in minutes
  description: string;
  isVisible: boolean; // Controla se aparece na home
}

export interface TeamMember {
  id: string;
  name: string;
  assignedServiceIds: string[];
}

export interface Booking {
  id: string;
  customerId: string;
  customerName: string;
  serviceId: string;
  serviceName: string;
  teamMemberId?: string;
  teamMemberName?: string;
  dateTime: string;
  status: 'scheduled' | 'completed' | 'cancelled';
}

export interface Transaction {
  id: string;
  type: 'payable' | 'receivable';
  description: string;
  amount: number;
  date: string;
  dueDate?: string;
  status: 'pending' | 'paid';
  customerId?: string; // Vínculo opcional com cliente
  customerName?: string;
}

export interface SalonSettings {
  name: string;
  primaryColor: string;
  logo: string;
  teamMembers: TeamMember[];
  servicesSectionTitle?: string;
  servicesSectionSubtitle?: string;
  socialLinks: {
    instagram: string;
    facebook: string;
    whatsapp: string;
  };
  usefulLinks: Array<{ label: string; url: string }>;
  comments: Array<{ author: string; text: string }>;
  photos: string[];
}

import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, TeamMember } from './types';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants';
import Navbar from './components/Navbar';
import CustomerHome from './components/CustomerHome';
import CustomerRegister from './components/CustomerRegister';
import CustomerProfile from './components/CustomerProfile';
import AdminDashboard from './components/AdminDashboard';
import AdminCalendar from './components/AdminCalendar';
import AdminFinance from './components/AdminFinance';
import AdminClients from './components/AdminClients';
import AdminSettingsView from './components/AdminSettingsView';
import AdminVeo from './components/AdminVeo';
import AdminLogin from './components/AdminLogin';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>(INITIAL_SERVICES);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem('moria_state');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setSettings(parsed.settings || DEFAULT_SETTINGS);
        setServices(parsed.services || INITIAL_SERVICES);
        setCustomers(parsed.customers || []);
        setBookings(parsed.bookings || []);
        setTransactions(parsed.transactions || []);

        const savedUser = localStorage.getItem('moria_current_user');
        if (savedUser) setCurrentUser(JSON.parse(savedUser));

        const savedAdminAuth = localStorage.getItem('moria_admin_auth');
        if (savedAdminAuth === 'true') setIsAdminAuthenticated(true);
      } catch (e) {
        console.error("Failed to parse saved state", e);
      }
    }
  }, []);

  useEffect(() => {
    const state = { settings, services, customers, bookings, transactions };
    localStorage.setItem('moria_state', JSON.stringify(state));
    if (currentUser) {
      localStorage.setItem('moria_current_user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('moria_current_user');
    }
    localStorage.setItem('moria_admin_auth', isAdminAuthenticated.toString());
  }, [settings, services, customers, bookings, transactions, currentUser, isAdminAuthenticated]);

  const handleRegister = (name: string, whatsapp: string, receivesNotifications: boolean) => {
    const newCustomer: Customer = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      whatsapp,
      receivesNotifications,
      agreedToTerms: true,
      history: []
    };
    setCustomers(prev => [...prev, newCustomer]);
    setCurrentUser(newCustomer);
    setCurrentView(View.CUSTOMER_HOME);
  };

  const handleUpdateNotification = (val: boolean) => {
    if (currentUser) {
      const updatedUser = { ...currentUser, receivesNotifications: val };
      setCurrentUser(updatedUser);
      setCustomers(prev => prev.map(c => c.id === currentUser.id ? updatedUser : c));
    }
  };

  const handleBooking = (serviceId: string, dateTime: string, teamMemberId?: string) => {
    if (!currentUser) {
      setCurrentView(View.CUSTOMER_REGISTER);
      return;
    }
    const service = services.find(s => s.id === serviceId);
    if (!service) return;

    const professional = settings.teamMembers.find(m => m.id === teamMemberId);

    const newBooking: Booking = {
      id: Math.random().toString(36).substr(2, 9),
      customerId: currentUser.id,
      customerName: currentUser.name,
      serviceId,
      serviceName: service.name,
      teamMemberId: professional?.id,
      teamMemberName: professional?.name,
      dateTime,
      status: 'scheduled'
    };
    setBookings(prev => [...prev, newBooking]);
    alert(`Agendamento realizado com sucesso para ${service.name} com ${professional?.name || 'equipe'}!`);
  };

  const handleAdminAuth = (password: string) => {
    if (password === '1234') {
      setIsAdminAuthenticated(true);
      setIsAdmin(true);
      setCurrentView(View.ADMIN_DASHBOARD);
    }
  };

  const toggleAdmin = () => {
    if (isAdmin) {
      setIsAdmin(false);
      setCurrentView(View.CUSTOMER_HOME);
    } else {
      if (isAdminAuthenticated) {
        setIsAdmin(true);
        setCurrentView(View.ADMIN_DASHBOARD);
      } else {
        setCurrentView(View.ADMIN_LOGIN);
      }
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentView(View.CUSTOMER_HOME);
  };

  const handleAdminLogout = () => {
    setIsAdminAuthenticated(false);
    setIsAdmin(false);
    setCurrentView(View.CUSTOMER_HOME);
  };

  return (
    <div className="min-h-screen flex flex-col transition-colors duration-300">
      <Navbar 
        view={currentView} 
        setView={setCurrentView} 
        isAdmin={isAdmin} 
        onToggleAdmin={toggleAdmin}
        salonName={settings.name}
        logo={settings.logo}
        currentUser={currentUser}
        onLogout={handleLogout}
        onAdminLogout={handleAdminLogout}
        isAdminAuthenticated={isAdminAuthenticated}
      />

      <main className="flex-grow pb-20 md:pb-0">
        {!isAdmin && (
          <>
            {currentView === View.CUSTOMER_HOME && (
              <CustomerHome 
                settings={settings} 
                services={services} 
                onBook={handleBooking}
                onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)}
                currentUser={currentUser}
              />
            )}
            {currentView === View.CUSTOMER_REGISTER && (
              <CustomerRegister onRegister={handleRegister} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />
            )}
            {currentView === View.CUSTOMER_PROFILE && currentUser && (
              <CustomerProfile 
                customer={currentUser} 
                transactions={transactions}
                onUpdateNotification={handleUpdateNotification} 
                onBack={() => setCurrentView(View.CUSTOMER_HOME)} 
              />
            )}
            {currentView === View.ADMIN_LOGIN && (
              <AdminLogin onLogin={handleAdminAuth} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />
            )}
          </>
        )}

        {isAdmin && (
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
            {currentView === View.ADMIN_DASHBOARD && (
              <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} />
            )}
            {currentView === View.ADMIN_CALENDAR && (
              <AdminCalendar bookings={bookings} setBookings={setBookings} services={services} />
            )}
            {currentView === View.ADMIN_FINANCE && (
              <AdminFinance transactions={transactions} setTransactions={setTransactions} customers={customers} />
            )}
            {currentView === View.ADMIN_CLIENTS && (
              <AdminClients customers={customers} bookings={bookings} />
            )}
            {currentView === View.ADMIN_VEO && (
              <AdminVeo />
            )}
            {currentView === View.ADMIN_SETTINGS && (
              <AdminSettingsView 
                settings={settings} 
                setSettings={setSettings} 
                services={services} 
                setServices={setServices}
              />
            )}
          </div>
        )}
      </main>

      {isAdmin && (
        <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 flex justify-around py-2 shadow-lg z-50">
          <button onClick={() => setCurrentView(View.ADMIN_DASHBOARD)} className={`flex flex-col items-center p-2 ${currentView === View.ADMIN_DASHBOARD ? 'text-tea-600' : 'text-gray-400'}`}>
            <span className="text-lg">🏠</span>
            <span className="text-[10px] mt-1 font-bold">Dash</span>
          </button>
          <button onClick={() => setCurrentView(View.ADMIN_CALENDAR)} className={`flex flex-col items-center p-2 ${currentView === View.ADMIN_CALENDAR ? 'text-tea-600' : 'text-gray-400'}`}>
            <span className="text-lg">📅</span>
            <span className="text-[10px] mt-1 font-bold">Agenda</span>
          </button>
          <button onClick={() => setCurrentView(View.ADMIN_FINANCE)} className={`flex flex-col items-center p-2 ${currentView === View.ADMIN_FINANCE ? 'text-tea-600' : 'text-gray-400'}`}>
            <span className="text-lg">💰</span>
            <span className="text-[10px] mt-1 font-bold">Finanças</span>
          </button>
          <button onClick={() => setCurrentView(View.ADMIN_SETTINGS)} className={`flex flex-col items-center p-2 ${currentView === View.ADMIN_SETTINGS ? 'text-tea-600' : 'text-gray-400'}`}>
            <span className="text-lg">⚙️</span>
            <span className="text-[10px] mt-1 font-bold">Config</span>
          </button>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Transaction, Customer } from '../types';

interface AdminFinanceProps {
  transactions: Transaction[];
  setTransactions: React.Dispatch<React.SetStateAction<Transaction[]>>;
  customers: Customer[];
}

const AdminFinance: React.FC<AdminFinanceProps> = ({ transactions, setTransactions, customers }) => {
  const [filter, setFilter] = useState<'all' | 'payable' | 'receivable'>('all');
  const [showAdd, setShowAdd] = useState(false);
  const [newTransaction, setNewTransaction] = useState({ 
    description: '', 
    amount: 0, 
    type: 'receivable' as 'payable' | 'receivable',
    customerId: '',
    dueDate: new Date().toISOString().split('T')[0],
    status: 'pending' as 'pending' | 'paid'
  });

  const handleAdd = () => {
    if (newTransaction.description && newTransaction.amount > 0) {
      const selectedCustomer = customers.find(c => c.id === newTransaction.customerId);

      const transaction: Transaction = {
        id: Math.random().toString(36).substr(2, 9),
        description: newTransaction.description,
        amount: newTransaction.amount,
        type: newTransaction.type,
        date: new Date().toISOString(),
        dueDate: newTransaction.dueDate,
        status: newTransaction.status,
        customerId: newTransaction.customerId || undefined,
        customerName: selectedCustomer?.name
      };
      setTransactions(prev => [...prev, transaction]);
      setShowAdd(false);
      setNewTransaction({ 
        description: '', 
        amount: 0, 
        type: 'receivable', 
        customerId: '', 
        dueDate: new Date().toISOString().split('T')[0],
        status: 'pending'
      });
    }
  };

  const toggleStatus = (id: string) => {
    setTransactions(prev => prev.map(t => 
      t.id === id ? { ...t, status: t.status === 'paid' ? 'pending' : 'paid' } : t
    ));
  };

  const sendReminder = (t: Transaction) => {
    const customer = customers.find(c => c.id === t.customerId);
    if (!customer) return;

    const message = `Olá ${customer.name}! Passando para lembrar do seu pagamento de R$ ${t.amount.toFixed(2)} (${t.description}) que vence em ${new Date(t.dueDate!).toLocaleDateString()}. Studio Moriá Estética.`;
    window.open(`https://wa.me/${customer.whatsapp.replace(/\D/g, '')}?text=${encodeURIComponent(message)}`, '_blank');
  };

  const filtered = transactions.filter(t => filter === 'all' || t.type === filter);

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold">Contas Financeiras</h2>
          <p className="text-gray-500 text-sm">Controle de caixa e pagamentos por cliente.</p>
        </div>
        <button 
          onClick={() => setShowAdd(true)}
          className="bg-tea-600 text-white px-4 py-2 rounded-xl font-bold hover:bg-tea-700 transition"
        >
          + Novo Lançamento
        </button>
      </div>

      <div className="flex gap-2">
        {(['all', 'receivable', 'payable'] as const).map(f => (
          <button 
            key={f}
            onClick={() => setFilter(f)}
            className={`px-4 py-2 rounded-full text-xs font-bold transition ${filter === f ? 'bg-tea-600 text-white' : 'bg-gray-100 text-gray-500'}`}
          >
            {f === 'all' ? 'Tudo' : f === 'receivable' ? 'Receitas' : 'Despesas'}
          </button>
        ))}
      </div>

      {showAdd && (
        <div className="bg-white p-8 rounded-3xl shadow-xl border border-tea-100 animate-slide-in">
          <h3 className="font-bold text-tea-900 mb-6">Cadastrar Movimentação</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-6">
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">Descrição</label>
              <input 
                placeholder="Ex: Limpeza de Pele ou Aluguel" 
                className="w-full p-4 border-2 border-gray-50 bg-gray-50 rounded-2xl outline-none focus:border-tea-200 focus:bg-white"
                value={newTransaction.description}
                onChange={(e) => setNewTransaction({...newTransaction, description: e.target.value})}
              />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">Valor R$</label>
              <input 
                type="number" 
                placeholder="0.00" 
                className="w-full p-4 border-2 border-gray-50 bg-gray-50 rounded-2xl outline-none focus:border-tea-200 focus:bg-white"
                value={newTransaction.amount || ''}
                onChange={(e) => setNewTransaction({...newTransaction, amount: parseFloat(e.target.value)})}
              />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">Tipo</label>
              <select 
                className="w-full p-4 border-2 border-gray-50 bg-gray-50 rounded-2xl outline-none focus:border-tea-200 focus:bg-white"
                value={newTransaction.type}
                onChange={(e) => setNewTransaction({...newTransaction, type: e.target.value as 'payable' | 'receivable'})}
              >
                <option value="receivable">Receita (Cliente)</option>
                <option value="payable">Despesa (Salão)</option>
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">Vincular Cliente</label>
              <select 
                className="w-full p-4 border-2 border-gray-50 bg-gray-50 rounded-2xl outline-none focus:border-tea-200 focus:bg-white"
                value={newTransaction.customerId}
                onChange={(e) => setNewTransaction({...newTransaction, customerId: e.target.value})}
              >
                <option value="">Nenhum Cliente (Lançamento Avulso)</option>
                {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">Data de Vencimento</label>
              <input 
                type="date"
                className="w-full p-4 border-2 border-gray-50 bg-gray-50 rounded-2xl outline-none focus:border-tea-200 focus:bg-white"
                value={newTransaction.dueDate}
                onChange={(e) => setNewTransaction({...newTransaction, dueDate: e.target.value})}
              />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">Status Inicial</label>
              <select 
                className="w-full p-4 border-2 border-gray-50 bg-gray-50 rounded-2xl outline-none focus:border-tea-200 focus:bg-white"
                value={newTransaction.status}
                onChange={(e) => setNewTransaction({...newTransaction, status: e.target.value as 'pending' | 'paid'})}
              >
                <option value="pending">Pendente (Aguardando)</option>
                <option value="paid">Pago (Recebido/Liquidado)</option>
              </select>
            </div>
          </div>
          <div className="flex justify-end gap-3">
            <button onClick={() => setShowAdd(false)} className="px-6 py-3 text-gray-400 font-bold">Cancelar</button>
            <button onClick={handleAdd} className="bg-tea-600 text-white px-10 py-3 rounded-2xl font-bold hover:bg-tea-700 shadow-lg transition">Salvar Lançamento</button>
          </div>
        </div>
      )}

      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-gray-50 border-b border-gray-100">
            <tr>
              <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-widest">Vencimento</th>
              <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-widest">Descrição / Cliente</th>
              <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-widest">Status</th>
              <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-widest text-right">Valor</th>
              <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-widest text-center">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {filtered.map(t => (
              <tr key={t.id} className="hover:bg-gray-50 transition group">
                <td className="px-6 py-4 text-sm font-medium text-gray-600">
                  {t.dueDate ? new Date(t.dueDate).toLocaleDateString() : '-'}
                </td>
                <td className="px-6 py-4">
                  <p className="font-bold text-gray-800">{t.description}</p>
                  {t.customerName && <p className="text-[10px] text-tea-600 font-bold uppercase tracking-tighter">Cliente: {t.customerName}</p>}
                </td>
                <td className="px-6 py-4">
                  <button 
                    onClick={() => toggleStatus(t.id)}
                    className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest transition-all ${t.status === 'paid' ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-orange-700 hover:bg-orange-200'}`}
                  >
                    {t.status === 'paid' ? 'Pago' : 'Pendente'}
                  </button>
                </td>
                <td className={`px-6 py-4 font-bold text-right ${t.type === 'receivable' ? 'text-tea-700' : 'text-red-500'}`}>
                  {t.type === 'receivable' ? '+' : '-'} R$ {t.amount.toFixed(2)}
                </td>
                <td className="px-6 py-4 text-center">
                  <div className="flex justify-center gap-2">
                    {t.customerId && t.status === 'pending' && (
                      <button 
                        onClick={() => sendReminder(t)}
                        className="p-2 text-tea-500 hover:bg-tea-50 rounded-lg transition"
                        title="Enviar lembrete WhatsApp"
                      >
                        📱
                      </button>
                    )}
                    <button onClick={() => setTransactions(prev => prev.filter(x => x.id !== t.id))} className="p-2 text-gray-300 hover:text-red-500 rounded-lg transition">
                      🗑️
                    </button>
                  </div>
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr>
                <td colSpan={5} className="px-6 py-20 text-center text-gray-400 italic">Nenhum lançamento financeiro registrado.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default AdminFinance;

import React, { useState } from 'react';
import { Customer, Transaction } from '../types';
import TermsModal from './TermsModal';

interface CustomerProfileProps {
  customer: Customer;
  transactions: Transaction[];
  onUpdateNotification: (val: boolean) => void;
  onBack: () => void;
}

const CustomerProfile: React.FC<CustomerProfileProps> = ({ customer, transactions, onUpdateNotification, onBack }) => {
  const [modalConfig, setModalConfig] = useState<{ open: boolean; title: string; type: 'terms' | 'privacy' }>({
    open: false,
    title: '',
    type: 'terms'
  });

  const openModal = (type: 'terms' | 'privacy') => {
    setModalConfig({
      open: true,
      type,
      title: type === 'terms' ? 'Termos de Uso' : 'Política de Privacidade (LGPD)'
    });
  };

  const myTransactions = transactions.filter(t => t.customerId === customer.id);

  const totalPaid = myTransactions
    .filter(t => t.status === 'paid' && t.type === 'receivable')
    .reduce((sum, t) => sum + t.amount, 0);

  const totalPending = myTransactions
    .filter(t => t.status === 'pending' && t.type === 'receivable')
    .reduce((sum, t) => sum + t.amount, 0);

  const lastPaidTransaction = myTransactions
    .filter(t => t.status === 'paid')
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0];

  const nextDueDate = myTransactions
    .filter(t => t.status === 'pending')
    .sort((a, b) => new Date(a.dueDate!).getTime() - new Date(b.dueDate!).getTime())[0];

  const isDueToday = nextDueDate && nextDueDate.dueDate === new Date().toISOString().split('T')[0];

  return (
    <div className="max-w-4xl mx-auto px-4 py-16 animate-fade-in">
      <button onClick={onBack} className="flex items-center gap-2 text-tea-600 font-bold mb-10 group">
        <svg className="w-5 h-5 group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
        Voltar para a Home
      </button>

      {isDueToday && (
        <div className="mb-8 bg-orange-50 border-l-4 border-orange-400 p-6 rounded-2xl flex items-center justify-between shadow-sm animate-bounce-subtle">
          <div className="flex items-center gap-4">
            <span className="text-3xl">⚠️</span>
            <div>
              <p className="font-bold text-orange-900">Vencimento Hoje!</p>
              <p className="text-sm text-orange-700">Você possui um pagamento de R$ {nextDueDate.amount.toFixed(2)} que vence hoje.</p>
            </div>
          </div>
          <button className="bg-orange-600 text-white px-6 py-2 rounded-xl font-bold text-xs shadow-md">Ver Detalhes</button>
        </div>
      )}

      <div className="bg-white rounded-[2rem] shadow-sm border border-tea-50 overflow-hidden">
        <div className="bg-tea-800 p-10 text-white flex justify-between items-end relative overflow-hidden">
           <div className="absolute top-0 right-0 w-32 h-32 bg-tea-700 rounded-full -mr-16 -mt-16 opacity-30"></div>
          <div>
            <h2 className="text-3xl font-serif font-bold mb-2">{customer.name}</h2>
            <p className="opacity-80">Cliente Moriá • {customer.whatsapp}</p>
          </div>
          <div className="bg-white/10 backdrop-blur-sm px-4 py-2 rounded-full text-xs font-bold uppercase tracking-widest relative z-10 border border-white/20">Perfil Ativo</div>
        </div>

        <div className="p-10 space-y-12">
          {/* Dashboard Financeiro */}
          <section>
            <h3 className="text-xl font-bold text-tea-900 mb-6 flex items-center gap-3">
              <span className="w-8 h-8 rounded-full bg-tea-50 flex items-center justify-center text-sm">💰</span>
              Meu Financeiro
            </h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
              <div className="bg-tea-50 p-8 rounded-3xl border border-tea-100 flex flex-col justify-between h-full">
                <p className="text-xs font-bold text-tea-700 uppercase tracking-widest mb-4">Total Investido em Beleza</p>
                <p className="text-4xl font-serif font-bold text-tea-900">R$ {totalPaid.toFixed(2)}</p>
                {lastPaidTransaction && (
                  <p className="text-[10px] text-tea-600 mt-4 font-bold uppercase">Último pagamento em: {new Date(lastPaidTransaction.date).toLocaleDateString()}</p>
                )}
              </div>
              <div className="bg-orange-50 p-8 rounded-3xl border border-orange-100 flex flex-col justify-between h-full">
                <p className="text-xs font-bold text-orange-700 uppercase tracking-widest mb-4">Valor em Aberto (A Pagar)</p>
                <p className="text-4xl font-serif font-bold text-orange-900">R$ {totalPending.toFixed(2)}</p>
                {nextDueDate && (
                  <p className="text-[10px] text-orange-600 mt-4 font-bold uppercase">Próximo vencimento: {new Date(nextDueDate.dueDate!).toLocaleDateString()}</p>
                )}
              </div>
            </div>
          </section>

          <section>
            <h3 className="text-xl font-bold text-tea-900 mb-6 flex items-center gap-3">
              <span className="w-8 h-8 rounded-full bg-tea-50 flex items-center justify-center text-sm">📱</span>
              Preferências de Comunicação
            </h3>

            <div className="bg-gray-50 p-6 rounded-3xl flex items-center justify-between border border-gray-100">
              <div>
                <p className="font-bold text-gray-800">Notificações WhatsApp</p>
                <p className="text-sm text-gray-500">Avisos automáticos de vencimento e horários.</p>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input 
                  type="checkbox" 
                  className="sr-only peer" 
                  checked={customer.receivesNotifications}
                  onChange={(e) => onUpdateNotification(e.target.checked)}
                />
                <div className="w-14 h-7 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-0.5 after:left-[4px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-6 after:w-6 after:transition-all peer-checked:bg-tea-500"></div>
              </label>
            </div>
          </section>

          <section>
            <h3 className="text-xl font-bold text-tea-900 mb-6 flex items-center gap-3">
              <span className="w-8 h-8 rounded-full bg-tea-50 flex items-center justify-center text-sm">📅</span>
              Histórico de Procedimentos
            </h3>
            <div className="space-y-4">
              {customer.history && customer.history.length > 0 ? (
                customer.history.map(b => (
                   <div key={b.id} className="p-6 border border-gray-100 rounded-[1.5rem] flex justify-between items-center bg-white shadow-sm">
                      <div>
                        <p className="font-bold text-tea-900 text-lg">{b.serviceName}</p>
                        <p className="text-xs text-gray-400 font-medium">{new Date(b.dateTime).toLocaleDateString()} às {new Date(b.dateTime).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                      </div>
                      <span className={`px-4 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-wider ${b.status === 'completed' ? 'bg-green-50 text-green-600' : 'bg-tea-50 text-tea-500'}`}>
                        {b.status === 'completed' ? 'Concluído' : 'Agendado'}
                      </span>
                   </div>
                ))
              ) : (
                <div className="text-center py-16 bg-gray-50 rounded-[2rem] border-2 border-dashed border-gray-100">
                  <p className="text-gray-400 text-sm italic">Você ainda não possui agendamentos realizados.</p>
                  <button onClick={onBack} className="mt-4 text-tea-600 font-bold text-sm hover:underline">Agendar meu primeiro horário</button>
                </div>
              )}
            </div>
          </section>

          <section className="pt-8 border-t border-gray-50">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Privacidade & Dados</h3>
            <div className="flex flex-wrap gap-6">
               <button onClick={() => openModal('terms')} className="text-sm text-tea-600 font-bold hover:underline transition-colors">Ver Termos de Uso</button>
               <button onClick={() => openModal('privacy')} className="text-sm text-tea-600 font-bold hover:underline transition-colors">Privacidade (LGPD)</button>
               <span className="text-gray-100 hidden sm:block">|</span>
               <button className="text-sm text-red-400 font-bold hover:text-red-600 transition-colors">Solicitar exclusão de dados</button>
            </div>
          </section>
        </div>
      </div>

      <TermsModal 
        isOpen={modalConfig.open} 
        onClose={() => setModalConfig({ ...modalConfig, open: false })}
        title={modalConfig.title}
        type={modalConfig.type}
      />
    </div>
  );
};

export default CustomerProfile;

