import React from 'react';
import { View, Customer } from '../types';

interface NavbarProps {
  view: View;
  setView: (v: View) => void;
  isAdmin: boolean;
  onToggleAdmin: () => void;
  salonName: string;
  logo: string;
  currentUser: Customer | null;
  onLogout: () => void;
  onAdminLogout: () => void;
  isAdminAuthenticated: boolean;
}

const Navbar: React.FC<NavbarProps> = ({ 
  view, 
  setView, 
  isAdmin, 
  onToggleAdmin, 
  salonName, 
  logo, 
  currentUser, 
  onLogout, 
  onAdminLogout,
  isAdminAuthenticated 
}) => {
  return (
    <nav className="bg-white border-b border-gray-100 sticky top-0 z-40 h-20 shadow-sm flex items-center">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 w-full">
        <div className="flex justify-between items-center">
          <div 
            className="flex items-center gap-4 cursor-pointer group" 
            onClick={() => setView(isAdmin ? View.ADMIN_DASHBOARD : View.CUSTOMER_HOME)}
          >
            <div className="bg-[#23492d] p-1.5 rounded-xl overflow-hidden flex items-center justify-center h-12 w-12 shadow-sm group-hover:scale-105 transition-transform">
               <span className="text-white font-serif font-bold text-2xl italic">M</span>
            </div>
            <span className="text-lg font-serif font-bold text-tea-900 hidden sm:block tracking-wide">
              {salonName}
            </span>
          </div>

          <div className="flex items-center gap-2">
            {!isAdmin && currentUser && (
               <div className="flex items-center gap-4 mr-2">
                  <button 
                    onClick={() => setView(View.CUSTOMER_PROFILE)}
                    className={`text-sm font-bold ${view === View.CUSTOMER_PROFILE ? 'text-tea-600' : 'text-gray-500 hover:text-tea-400'}`}
                  >
                    Meu Perfil
                  </button>
                  <button 
                    onClick={onLogout}
                    className="text-xs text-red-400 hover:text-red-600 font-bold"
                  >
                    Sair
                  </button>
               </div>
            )}

            {isAdmin && (
              <div className="hidden lg:flex gap-4 mr-4 items-center">
                <button onClick={() => setView(View.ADMIN_DASHBOARD)} className={`px-2 py-1 text-sm font-bold ${view === View.ADMIN_DASHBOARD ? 'text-tea-600 border-b-2 border-tea-600' : 'text-gray-500'}`}>Início</button>
                <button onClick={() => setView(View.ADMIN_CALENDAR)} className={`px-2 py-1 text-sm font-bold ${view === View.ADMIN_CALENDAR ? 'text-tea-600 border-b-2 border-tea-600' : 'text-gray-500'}`}>Agenda</button>
                <button onClick={() => setView(View.ADMIN_FINANCE)} className={`px-2 py-1 text-sm font-bold ${view === View.ADMIN_FINANCE ? 'text-tea-600 border-b-2 border-tea-600' : 'text-gray-500'}`}>Finanças</button>
                <button onClick={() => setView(View.ADMIN_VEO)} className={`px-2 py-1 text-sm font-bold ${view === View.ADMIN_VEO ? 'text-tea-600 border-b-2 border-tea-600' : 'text-gray-500'}`}>IA Cine</button>
                <button onClick={() => setView(View.ADMIN_SETTINGS)} className={`px-2 py-1 text-sm font-bold ${view === View.ADMIN_SETTINGS ? 'text-tea-600 border-b-2 border-tea-600' : 'text-gray-500'}`}>Config</button>
                <button 
                  onClick={onAdminLogout}
                  className="ml-2 text-xs text-red-400 hover:text-red-600 font-bold bg-red-50 px-3 py-1.5 rounded-full"
                >
                  Sair
                </button>
              </div>
            )}

            <div className="flex gap-2">
              {!currentUser && !isAdmin && (
                <button 
                  onClick={() => setView(View.CUSTOMER_LOGIN)}
                  className={`px-4 py-2 rounded-full text-[10px] font-bold transition border-2 uppercase tracking-widest bg-white text-tea-700 border-tea-100 hover:bg-tea-50`}
                >
                  Área do Cliente
                </button>
              )}

              <button 
                onClick={onToggleAdmin}
                className={`px-4 py-2 rounded-full text-[10px] font-bold transition border-2 uppercase tracking-widest ${isAdmin ? 'bg-tea-800 text-white border-tea-800' : 'bg-tea-50 text-tea-700 border-tea-100 hover:bg-tea-100'}`}
              >
                {isAdmin ? 'Ver Site' : 'Área Equipe'}
              </button>
            </div>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;

import React, { useState } from 'react';

interface CustomerLoginViewProps {
  onLogin: (cpf: string, pass: string) => void;
  onRegisterClick: () => void;
  onBack: () => void;
}

const CustomerLoginView: React.FC<CustomerLoginViewProps> = ({ onLogin, onRegisterClick, onBack }) => {
  const [cpf, setCpf] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (cpf && password) {
      onLogin(cpf, password);
    } else {
      alert("Por favor, preencha CPF e Senha.");
    }
  };

  return (
    <div className="min-h-[80vh] flex items-center justify-center px-4 py-12 bg-gray-50">
      <div className="max-w-md w-full bg-white rounded-[3rem] shadow-2xl p-10 md:p-14 border border-tea-50 animate-slide-up">
        <div className="text-center mb-10">
          <h2 className="text-3xl font-serif text-tea-900 mb-2">Bem-vinda de volta!</h2>
          <p className="text-gray-500 font-light text-sm italic">Acesse seu perfil e extrato do Studio Moriá.</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="space-y-1">
            <label className="text-[10px] font-bold text-tea-700 uppercase tracking-widest ml-1">Seu CPF</label>
            <input 
              type="text" 
              placeholder="000.000.000-00"
              className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-2 border-transparent focus:border-tea-200 focus:bg-white outline-none transition-all text-gray-800"
              value={cpf}
              onChange={(e) => setCpf(e.target.value)}
              required
            />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-bold text-tea-700 uppercase tracking-widest ml-1">Sua Senha</label>
            <input 
              type="password" 
              placeholder="••••••••"
              className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-2 border-transparent focus:border-tea-200 focus:bg-white outline-none transition-all text-gray-800"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <button 
            type="submit"
            className="w-full bg-[#23492d] text-white py-5 rounded-2xl font-bold text-lg hover:bg-tea-900 transition-all shadow-xl shadow-tea-100 mt-4"
          >
            Entrar no Perfil
          </button>
        </form>

        <div className="mt-10 pt-8 border-t border-gray-100 text-center">
          <p className="text-sm text-gray-500 mb-4">Ainda não é cadastrada?</p>
          <button 
            onClick={onRegisterClick}
            className="text-tea-600 font-bold hover:underline"
          >
            Criar minha conta agora
          </button>
        </div>

        <button 
          onClick={onBack}
          className="mt-6 w-full text-xs text-gray-400 font-bold hover:text-gray-600 transition-colors"
        >
          Voltar para o site
        </button>
      </div>
    </div>
  );
};

export default CustomerLoginView;

import React, { useState } from 'react';
import TermsModal from './TermsModal';

interface CustomerRegisterProps {
  onRegister: (name: string, whatsapp: string, cpf: string, password: string, receivesNotifications: boolean) => void;
  onBack: () => void;
}

const CustomerRegister: React.FC<CustomerRegisterProps> = ({ onRegister, onBack }) => {
  const [name, setName] = useState('');
  const [whatsapp, setWhatsapp] = useState('');
  const [cpf, setCpf] = useState('');
  const [password, setPassword] = useState('');
  const [receivesNotifications, setReceivesNotifications] = useState(true);
  const [agreedToTerms, setAgreedToTerms] = useState(false);

  // Modal State
  const [modalConfig, setModalConfig] = useState<{ open: boolean; title: string; type: 'terms' | 'privacy' }>({
    open: false,
    title: '',
    type: 'terms'
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (name && whatsapp && cpf && password && agreedToTerms) {
      onRegister(name, whatsapp, cpf, password, receivesNotifications);
    } else if (!agreedToTerms) {
      alert("Para sua segurança, é necessário aceitar os termos de uso e política de privacidade.");
    }
  };

  const openModal = (type: 'terms' | 'privacy') => {
    setModalConfig({
      open: true,
      type,
      title: type === 'terms' ? 'Termos de Uso' : 'Política de Privacidade (LGPD)'
    });
  };

  return (
    <div className="min-h-screen flex items-center justify-center px-4 py-20 bg-[#F9FBFA]">
      <div className="max-w-xl w-full bg-white rounded-[3rem] shadow-[0_40px_100px_rgba(0,0,0,0.05)] overflow-hidden p-12 border border-white">
        <button onClick={onBack} className="text-tea-600 text-sm font-bold flex items-center gap-3 mb-12 hover:-translate-x-1 transition-transform group">
          <svg className="w-5 h-5 group-hover:scale-125 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
          Voltar para Início
        </button>

        <div className="mb-12">
          <h2 className="text-4xl font-serif text-tea-900 mb-4">Sua Conta Moriá</h2>
          <p className="text-gray-500 font-light text-lg">Cadastre-se para acessar seu extrato completo e realizar agendamentos.</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-8">
          <div className="space-y-4">
            <div className="relative group">
              <label className="block text-[11px] font-bold text-tea-700 uppercase tracking-[0.2em] mb-2 ml-2">Nome Completo</label>
              <input 
                type="text" 
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-transparent focus:bg-white focus:border-tea-200 outline-none transition-all placeholder-gray-300 shadow-inner"
                placeholder="Ex: Maria Clara Santos"
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="relative group">
