import React, { useState } from 'react';
import { Customer, Transaction } from '../types';
import TermsModal from './TermsModal';

interface CustomerProfileProps {
  customer: Customer;
  transactions: Transaction[];
  onUpdateNotification: (val: boolean) => void;
  onBack: () => void;
}

const CustomerProfile: React.FC<CustomerProfileProps> = ({ customer, transactions, onUpdateNotification, onBack }) => {
  const [modalConfig, setModalConfig] = useState<{ open: boolean; title: string; type: 'terms' | 'privacy' }>({
    open: false,
    title: '',
    type: 'terms'
  });

  const openModal = (type: 'terms' | 'privacy') => {
    setModalConfig({
      open: true,
      type,
      title: type === 'terms' ? 'Termos de Uso' : 'Política de Privacidade (LGPD)'
    });
  };

  const myTransactions = transactions.filter(t => t.customerId === customer.id);

  const totalPaid = myTransactions
    .filter(t => t.status === 'paid' && t.type === 'receivable')
    .reduce((sum, t) => sum + t.amount, 0);

  const totalPending = myTransactions
    .filter(t => t.status === 'pending' && t.type === 'receivable')
    .reduce((sum, t) => sum + t.amount, 0);

  const lastPaidTransaction = myTransactions
    .filter(t => t.status === 'paid')
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0];

  const nextDueDate = myTransactions
    .filter(t => t.status === 'pending')
    .sort((a, b) => new Date(a.dueDate!).getTime() - new Date(b.dueDate!).getTime())[0];

  const todayStr = new Date().toISOString().split('T')[0];
  const isDueToday = nextDueDate && nextDueDate.dueDate === todayStr;

  return (
    <div className="max-w-4xl mx-auto px-4 py-16 animate-fade-in">
      <button onClick={onBack} className="flex items-center gap-2 text-tea-600 font-bold mb-10 group">
        <svg className="w-5 h-5 group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
        Voltar para a Home
      </button>

      {isDueToday && (
        <div className="mb-8 bg-orange-50 border-l-4 border-orange-400 p-6 rounded-2xl flex items-center justify-between shadow-sm animate-bounce-subtle">
          <div className="flex items-center gap-4">
            <span className="text-3xl">⚠️</span>
            <div>
              <p className="font-bold text-orange-900">Vencimento Hoje!</p>
              <p className="text-sm text-orange-700">Olá {customer.name.split(' ')[0]}, lembramos que você possui um pagamento de R$ {nextDueDate.amount.toFixed(2)} pendente para hoje.</p>
            </div>
          </div>
        </div>
      )}

      <div className="bg-white rounded-[2rem] shadow-sm border border-tea-50 overflow-hidden">
        <div className="bg-tea-800 p-10 text-white flex justify-between items-end relative overflow-hidden">
           <div className="absolute top-0 right-0 w-32 h-32 bg-tea-700 rounded-full -mr-16 -mt-16 opacity-30"></div>
          <div>
            <h2 className="text-3xl font-serif font-bold mb-2">{customer.name}</h2>
            <p className="opacity-80 text-sm">CPF: {customer.cpf} • WhatsApp: {customer.whatsapp}</p>
          </div>
          <div className="bg-white/10 backdrop-blur-sm px-4 py-2 rounded-full text-xs font-bold uppercase tracking-widest relative z-10 border border-white/20">Perfil Verificado</div>
        </div>

        <div className="p-10 space-y-12">
          {/* Dashboard Financeiro Unificado */}
          <section>
            <h3 className="text-xl font-bold text-tea-900 mb-6 flex items-center gap-3">
              <span className="w-8 h-8 rounded-full bg-tea-50 flex items-center justify-center text-sm">💰</span>
              Meu Extrato Financeiro
            </h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mb-8">
              <div className="bg-tea-50 p-8 rounded-3xl border border-tea-100 flex flex-col justify-between h-full">
                <p className="text-xs font-bold text-tea-700 uppercase tracking-widest mb-4">Total Investido (Pago)</p>
                <p className="text-4xl font-serif font-bold text-tea-900">R$ {totalPaid.toFixed(2)}</p>
                {lastPaidTransaction && (
                  <p className="text-[10px] text-tea-600 mt-4 font-bold uppercase">Último Pagamento: {new Date(lastPaidTransaction.date).toLocaleDateString()}</p>
                )}
              </div>
              <div className="bg-orange-50 p-8 rounded-3xl border border-orange-100 flex flex-col justify-between h-full">
                <p className="text-xs font-bold text-orange-700 uppercase tracking-widest mb-4">Total Pendente (A Pagar)</p>
                <p className="text-4xl font-serif font-bold text-orange-900">R$ {totalPending.toFixed(2)}</p>
                {nextDueDate && (
                  <p className="text-[10px] text-orange-600 mt-4 font-bold uppercase tracking-tighter">Vencimento em: {new Date(nextDueDate.dueDate!).toLocaleDateString()}</p>
                )}
              </div>
            </div>

            <div className="overflow-hidden border border-gray-100 rounded-2xl">
              <table className="w-full text-left">
                <thead className="bg-gray-50 text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                  <tr>
                    <th className="px-6 py-4">Data/Venc.</th>
                    <th className="px-6 py-4">Procedimento / Lançamento</th>
                    <th className="px-6 py-4 text-right">Valor</th>
                    <th className="px-6 py-4 text-center">Situação</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {myTransactions.map(t => (
                    <tr key={t.id} className="text-sm hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4 text-gray-500 font-medium">{new Date(t.dueDate || t.date).toLocaleDateString()}</td>
                      <td className="px-6 py-4 font-bold text-gray-800">{t.description}</td>
                      <td className="px-6 py-4 text-right font-bold text-tea-900">R$ {t.amount.toFixed(2)}</td>
                      <td className="px-6 py-4 text-center">
                        <span className={`px-3 py-1 rounded-full text-[9px] font-bold uppercase tracking-widest ${t.status === 'paid' ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-orange-700'}`}>
                          {t.status === 'paid' ? 'Pago' : 'Pendente'}
                        </span>
                      </td>
                    </tr>
                  ))}
                  {myTransactions.length === 0 && (
                    <tr><td colSpan={4} className="px-6 py-12 text-center text-gray-400 italic font-light">Nenhum lançamento financeiro registrado em seu CPF.</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </section>

          <section>
            <h3 className="text-xl font-bold text-tea-900 mb-6 flex items-center gap-3">
              <span className="w-8 h-8 rounded-full bg-tea-50 flex items-center justify-center text-sm">📅</span>
              Histórico de Procedimentos
            </h3>
            <div className="space-y-4">
              {customer.history && customer.history.length > 0 ? (
                customer.history.map(b => (
                   <div key={b.id} className="p-6 border border-gray-100 rounded-[1.5rem] flex justify-between items-center bg-white shadow-sm hover:shadow-md transition-shadow">
                      <div>
                        <p className="font-bold text-tea-900 text-lg">{b.serviceName}</p>
                        <p className="text-xs text-gray-400 font-medium">Realizado em {new Date(b.dateTime).toLocaleDateString()} às {new Date(b.dateTime).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                      </div>
                      <span className={`px-4 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-wider ${b.status === 'completed' ? 'bg-green-50 text-green-600' : 'bg-tea-50 text-tea-500'}`}>
                        {b.status === 'completed' ? 'Finalizado' : 'Agendado'}
                      </span>
                   </div>
                ))
              ) : (
                <div className="text-center py-12 bg-gray-50 rounded-[2rem] border-2 border-dashed border-gray-100">
                  <p className="text-gray-400 text-sm font-light italic">Nenhum procedimento registrado para este CPF ainda.</p>
                </div>
              )}
            </div>
          </section>

          <section className="pt-8 border-t border-gray-50 flex flex-col md:flex-row justify-between items-center gap-6">
            <div className="flex flex-wrap gap-6 justify-center md:justify-start">
               <button onClick={() => openModal('terms')} className="text-xs text-tea-600 font-bold hover:underline">Termos de Uso</button>
               <button onClick={() => openModal('privacy')} className="text-xs text-tea-600 font-bold hover:underline">Privacidade (LGPD)</button>
            </div>
            <div className="bg-gray-50 p-4 rounded-2xl flex items-center gap-4">
              <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Avisos via WhatsApp</p>
              <label className="relative inline-flex items-center cursor-pointer">
                <input 
                  type="checkbox" 
                  className="sr-only peer" 
                  checked={customer.receivesNotifications}
                  onChange={(e) => onUpdateNotification(e.target.checked)}
                />
                <div className="w-10 h-5 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-0.5 after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-tea-500"></div>
              </label>
            </div>
          </section>
        </div>
      </div>

      <TermsModal 
        isOpen={modalConfig.open} 
        onClose={() => setModalConfig({ ...modalConfig, open: false })}
        title={modalConfig.title}
        type={modalConfig.type}
      />
    </div>
  );
};

export default CustomerProfile;

import React, { useState } from 'react';
import { SalonSettings, Service, Customer, TeamMember } from '../types';

interface CustomerHomeProps {
  settings: SalonSettings;
  services: Service[];
  onBook: (serviceId: string, dateTime: string, teamMemberId?: string) => void;
  onRegisterClick: () => void;
  currentUser: Customer | null;
}

const CustomerHome: React.FC<CustomerHomeProps> = ({ settings, services, onBook, onRegisterClick, currentUser }) => {
  const [formData, setFormData] = useState({ name: '', whatsapp: '', message: '' });
  const [bookingModal, setBookingModal] = useState<{ open: boolean; service: Service | null }>({ open: false, service: null });
  const [selectedProfessional, setSelectedProfessional] = useState<string>('');

  const handleContactSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const { name, whatsapp, message } = formData;
    if (!name || !whatsapp || !message) {
      alert("Por favor, preencha todos os campos para falar conosco.");
      return;
    }
    const text = `Olá Studio Moriá!\n\nVi no site e gostaria de informações:\n\n*Nome:* ${name}\n*WhatsApp:* ${whatsapp}\n*Dúvida:* ${message}`;
    const encodedText = encodeURIComponent(text);
    const waNumber = settings.socialLinks.whatsapp.replace(/\D/g, ''); 
    window.open(`https://wa.me/${waNumber}?text=${encodedText}`, '_blank');
  };

  const openBookingSelection = (service: Service) => {
    if (!currentUser) {
      onRegisterClick();
      return;
    }
    setBookingModal({ open: true, service });
  };

  const confirmBooking = () => {
    if (bookingModal.service && selectedProfessional) {
      onBook(bookingModal.service.id, new Date().toISOString(), selectedProfessional);
      setBookingModal({ open: false, service: null });
      setSelectedProfessional('');
    } else {
      alert("Por favor, selecione uma profissional para o atendimento.");
    }
  };

  const availableProfessionals = bookingModal.service 
    ? settings.teamMembers.filter(m => m.assignedServiceIds.includes(bookingModal.service!.id))
    : [];

  const visibleServices = services.filter(s => s.isVisible);

  return (
    <div className="animate-fade-in bg-white">
      {/* Hero Section */}
      <section className="relative min-h-[75vh] flex flex-col items-center justify-center bg-[#23492d] overflow-hidden py-16 px-4">
        <div className="absolute inset-0 opacity-10 pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/natural-paper.png')]"></div>
        <div className="relative z-10 w-full max-w-4xl text-center flex flex-col items-center">
          <div className="mb-8 transform hover:scale-105 transition-transform duration-700 w-full max-w-[450px] md:max-w-[550px] flex justify-center items-center">
             <img src={settings.logo} alt="Studio Moriá Estética" className="w-full h-auto drop-shadow-[0_20px_50px_rgba(0,0,0,0.3)]" crossOrigin="anonymous" />
          </div>
          <h2 className="text-2xl md:text-4xl font-serif text-white/90 mb-12 italic tracking-wide font-light">Cuidando do seu bem estar.</h2>
          <div className="flex flex-col sm:flex-row gap-6">
            {!currentUser ? (
              <button onClick={onRegisterClick} className="bg-white text-[#23492d] px-12 py-5 rounded-full font-bold text-lg hover:bg-tea-50 transition-all shadow-2xl hover:-translate-y-1 active:scale-95 uppercase tracking-widest">
                Ver Serviços e Preços
              </button>
            ) : (
              <div className="bg-white/10 backdrop-blur-md px-10 py-5 rounded-full border border-white/20 text-white font-medium text-lg">
                Bem-vinda, <span className="font-bold text-tea-200">{currentUser.name.split(' ')[0]}</span>!
              </div>
            )}
            <a href="#fale-conosco" className="bg-transparent border-2 border-white/30 text-white px-12 py-5 rounded-full font-bold text-lg hover:bg-white/10 transition-all uppercase tracking-widest text-center">Fale Conosco</a>
          </div>
        </div>
      </section>

      {/* Booking Selection Modal */}
      {bookingModal.open && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white w-full max-w-lg rounded-[3rem] p-10 shadow-2xl animate-slide-up">
            <h3 className="text-2xl font-serif text-tea-900 mb-2">Selecione a Profissional</h3>
            <p className="text-gray-500 mb-8 font-light text-sm italic">Procedimento: <span className="font-bold text-tea-700 uppercase tracking-tighter">{bookingModal.service?.name}</span></p>

            <div className="space-y-4 mb-10">
              {availableProfessionals.length > 0 ? availableProfessionals.map(pro => (
                <button 
                  key={pro.id}
                  onClick={() => setSelectedProfessional(pro.id)}
                  className={`w-full p-5 rounded-2xl border-2 transition-all flex items-center justify-between group ${selectedProfessional === pro.id ? 'border-tea-600 bg-tea-50' : 'border-gray-50 hover:border-tea-100 bg-gray-50'}`}
                >
                  <div className="flex items-center gap-4">
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-white shadow-md ${selectedProfessional === pro.id ? 'bg-tea-600' : 'bg-gray-300'}`}>
                      {pro.name.charAt(0)}
                    </div>
                    <span className={`font-bold ${selectedProfessional === pro.id ? 'text-tea-900' : 'text-gray-600'}`}>{pro.name}</span>
                  </div>
                  {selectedProfessional === pro.id && <span className="text-tea-600">✓</span>}
                </button>
              )) : (
                <div className="p-8 text-center text-gray-400 italic bg-gray-50 rounded-2xl">
                  Nenhuma profissional cadastrada para este serviço no momento.
                </div>
              )}
            </div>

            <div className="flex flex-col gap-3">
              <button 
                onClick={confirmBooking}
                disabled={!selectedProfessional}
                className="w-full bg-[#23492d] text-white py-5 rounded-2xl font-bold text-lg hover:bg-tea-900 transition-all shadow-xl disabled:opacity-50 disabled:cursor-not-allowed uppercase tracking-widest"
              >
                Confirmar Agendamento
              </button>
              <button onClick={() => setBookingModal({ open: false, service: null })} className="w-full py-3 text-gray-400 text-sm font-bold hover:text-gray-600">Cancelar</button>
            </div>
          </div>
        </div>
      )}

      {/* Services Section */}
      <section className="max-w-7xl mx-auto px-4 py-24">
        <div className="text-center mb-16">
          <span className="text-tea-600 font-bold tracking-[0.3em] uppercase text-xs block mb-4">{settings.servicesSectionTitle || "Especialidades"}</span>
          <h2 className="text-4xl md:text-5xl font-serif text-gray-900 mb-6">{settings.servicesSectionSubtitle || "Nossos Procedimentos"}</h2>
          <div className="h-1 w-24 bg-tea-600 mx-auto rounded-full"></div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
          {visibleServices.map(service => (
            <div key={service.id} className="bg-gray-50 p-8 rounded-[2.5rem] border border-transparent hover:border-tea-100 hover:bg-white hover:shadow-2xl transition-all duration-500 group flex flex-col justify-between">
              <div>
                <h3 className="text-xl font-serif font-bold text-gray-800 mb-4 group-hover:text-tea-700 transition-colors">{service.name}</h3>
                <p className="text-gray-500 text-sm leading-relaxed mb-8 font-light">{service.description}</p>
                {currentUser && <p className="text-tea-700 font-bold text-xl mb-6">R$ {service.price.toFixed(2)}</p>}
              </div>
              <button onClick={() => openBookingSelection(service)} className="w-full py-4 rounded-2xl bg-white border border-tea-100 text-tea-700 font-bold text-sm hover:bg-tea-700 hover:text-white transition-all shadow-sm uppercase tracking-widest">
                Agendar Horário
              </button>
            </div>
          ))}
          {visibleServices.length === 0 && (
             <p className="col-span-full text-center py-12 text-gray-400 italic">No momento, não há procedimentos disponíveis para exibição pública.</p>
          )}
        </div>
      </section>

      {/* Fale Conosco Section */}
      <section id="fale-conosco" className="bg-[#23492d] py-24 relative overflow-hidden">
        <div className="absolute -bottom-24 -right-24 w-96 h-96 bg-tea-900 rounded-full opacity-20"></div>
