                {/* Histórico de Procedimentos */}
                <section>
                  <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-6 border-b pb-2">Histórico de Procedimentos</h4>
                  <div className="space-y-4">
                    {bookings.filter(b => b.customerId === selectedCustomer.id).length > 0 ? (
                      bookings.filter(b => b.customerId === selectedCustomer.id).map(booking => (
                        <div key={booking.id} className="flex justify-between p-5 bg-white border border-gray-100 rounded-2xl items-center hover:shadow-md transition-shadow">
                          <div>
                            <p className="font-bold text-gray-800 text-lg">{booking.serviceName}</p>
                            <div className="flex gap-4 items-center mt-1">
                              <p className="text-xs text-gray-400 font-medium">🗓️ {new Date(booking.dateTime).toLocaleDateString()} • {new Date(booking.dateTime).toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'})}</p>
                              <p className="text-[10px] text-tea-600 font-bold uppercase tracking-widest">Atendimento: {booking.teamMemberName || 'Studio Moriá'}</p>
                            </div>
                          </div>
                          <span className={`px-4 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-wider ${booking.status === 'completed' ? 'bg-green-50 text-green-700' : 'bg-tea-50 text-tea-600'}`}>
