                        <p className="text-gray-400 italic font-light">Nenhum registro encontrado para esta cliente.</p>
                      </div>
                    )}
                  </div>
                </section>
              </div>
            </div>
          ) : (
            <div className="h-full min-h-[500px] flex flex-col items-center justify-center bg-gray-50 rounded-[3rem] border-4 border-dashed border-gray-100 p-12 text-center">
              <div className="w-24 h-24 bg-white rounded-full flex items-center justify-center text-4xl mb-6 shadow-sm">👥</div>
              <h3 className="text-2xl font-serif text-tea-900 mb-2">Gestão Seletiva</h3>
              <p className="text-gray-400 max-w-xs mx-auto font-light">Selecione uma cliente na lista à esquerda para visualizar o extrato financeiro completo e histórico de beleza.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

