import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, TeamMember } from './types';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants';
import Navbar from './components/Navbar';
import CustomerHome from './components/CustomerHome';
import CustomerRegister from './components/CustomerRegister';
import CustomerLoginView from './components/CustomerLoginView';
import CustomerProfile from './components/CustomerProfile';
import AdminDashboard from './components/AdminDashboard';
import AdminCalendar from './components/AdminCalendar';
import AdminFinance from './components/AdminFinance';
import AdminClients from './components/AdminClients';
import AdminSettingsView from './components/AdminSettingsView';
import AdminVeo from './components/AdminVeo';
import AdminLogin from './components/AdminLogin';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>(INITIAL_SERVICES);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem('moria_state');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setSettings(parsed.settings || DEFAULT_SETTINGS);
        setServices(parsed.services || INITIAL_SERVICES);
        setCustomers(parsed.customers || []);
        setBookings(parsed.bookings || []);
        setTransactions(parsed.transactions || []);

        const savedUser = localStorage.getItem('moria_current_user');
        if (savedUser) setCurrentUser(JSON.parse(savedUser));

        const savedAdminAuth = localStorage.getItem('moria_admin_auth');
        if (savedAdminAuth === 'true') setIsAdminAuthenticated(true);
      } catch (e) {
        console.error("Failed to parse saved state", e);
      }
    }
  }, []);

  useEffect(() => {
    const state = { settings, services, customers, bookings, transactions };
    localStorage.setItem('moria_state', JSON.stringify(state));
    if (currentUser) {
      localStorage.setItem('moria_current_user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('moria_current_user');
    }
    localStorage.setItem('moria_admin_auth', isAdminAuthenticated.toString());
  }, [settings, services, customers, bookings, transactions, currentUser, isAdminAuthenticated]);

  const handleRegister = (name: string, whatsapp: string, cpf: string, password: string, receivesNotifications: boolean) => {
    if (customers.find(c => c.cpf === cpf)) {
      alert("Este CPF já está cadastrado em nossa base.");
      return;
    }

    const newCustomer: Customer = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      whatsapp,
      cpf,
      password,
      receivesNotifications,
      agreedToTerms: true,
      history: []
    };
    setCustomers(prev => [...prev, newCustomer]);
    setCurrentUser(newCustomer);
    setCurrentView(View.CUSTOMER_HOME);
  };

  const handleDeleteCustomer = (id: string) => {
    if (confirm("Deseja realmente excluir esta cliente? Todos os dados vinculados serão mantidos no histórico financeiro, mas o acesso dela será removido.")) {
      setCustomers(prev => prev.filter(c => c.id !== id));
    }
  };

  const handleUpdateCustomer = (id: string, updatedData: Partial<Customer>) => {
    setCustomers(prev => prev.map(c => c.id === id ? { ...c, ...updatedData } : c));
  };

  const handleCustomerLogin = (cpf: string, pass: string) => {
    const found = customers.find(c => c.cpf === cpf && c.password === pass);
    if (found) {
      setCurrentUser(found);
      setCurrentView(View.CUSTOMER_HOME);
    } else {
      alert("CPF ou Senha incorretos.");
    }
  };

  const handleUpdateNotification = (val: boolean) => {
    if (currentUser) {
      const updatedUser = { ...currentUser, receivesNotifications: val };
      setCurrentUser(updatedUser);
      setCustomers(prev => prev.map(c => c.id === currentUser.id ? updatedUser : c));
    }
  };

  const handleBooking = (serviceId: string, dateTime: string, teamMemberId?: string) => {
    if (!currentUser) {
      setCurrentView(View.CUSTOMER_LOGIN);
      return;
    }
    const service = services.find(s => s.id === serviceId);
    if (!service) return;

    const professional = settings.teamMembers.find(m => m.id === teamMemberId);

    const newBooking: Booking = {
      id: Math.random().toString(36).substr(2, 9),
      customerId: currentUser.id,
      customerName: currentUser.name,
      serviceId,
      serviceName: service.name,
      teamMemberId: professional?.id,
      teamMemberName: professional?.name,
      dateTime,
      status: 'scheduled'
    };
    setBookings(prev => [...prev, newBooking]);
    alert(`Agendamento realizado com sucesso para ${service.name} com ${professional?.name || 'equipe'}!`);
  };

  const handleAdminAuth = (password: string) => {
    if (password === '1234') {
      setIsAdminAuthenticated(true);
      setIsAdmin(true);
      setCurrentView(View.ADMIN_DASHBOARD);
    }
  };

  const toggleAdmin = () => {
    if (isAdmin) {
      setIsAdmin(false);
      setCurrentView(View.CUSTOMER_HOME);
    } else {
      if (isAdminAuthenticated) {
        setIsAdmin(true);
        setCurrentView(View.ADMIN_DASHBOARD);
      } else {
        setCurrentView(View.ADMIN_LOGIN);
      }
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentView(View.CUSTOMER_HOME);
  };

  const handleAdminLogout = () => {
    setIsAdminAuthenticated(false);
    setIsAdmin(false);
    setCurrentView(View.CUSTOMER_HOME);
  };

  return (
    <div className="min-h-screen flex flex-col transition-colors duration-300">
      <Navbar 
        view={currentView} 
        setView={setCurrentView} 
        isAdmin={isAdmin} 
        onToggleAdmin={toggleAdmin}
        salonName={settings.name}
        logo={settings.logo}
        currentUser={currentUser}
        onLogout={handleLogout}
        onAdminLogout={handleAdminLogout}
        isAdminAuthenticated={isAdminAuthenticated}
      />

      <main className="flex-grow pb-20 md:pb-0">
        {!isAdmin && (
          <>
            {currentView === View.CUSTOMER_HOME && (
              <CustomerHome 
                settings={settings} 
                services={services} 
                onBook={handleBooking}
                onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)}
                currentUser={currentUser}
              />
            )}
            {currentView === View.CUSTOMER_LOGIN && (
              <CustomerLoginView 
                onLogin={handleCustomerLogin} 
                onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)}
                onBack={() => setCurrentView(View.CUSTOMER_HOME)}
              />
            )}
            {currentView === View.CUSTOMER_REGISTER && (
              <CustomerRegister 
                onRegister={handleRegister} 
                onBack={() => setCurrentView(View.CUSTOMER_HOME)} 
              />
            )}
            {currentView === View.CUSTOMER_PROFILE && currentUser && (
              <CustomerProfile 
                customer={currentUser} 
                transactions={transactions}
                onUpdateNotification={handleUpdateNotification} 
                onBack={() => setCurrentView(View.CUSTOMER_HOME)} 
              />
            )}
            {currentView === View.ADMIN_LOGIN && (
              <AdminLogin onLogin={handleAdminAuth} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />
            )}
          </>
        )}

        {isAdmin && (
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
            {currentView === View.ADMIN_DASHBOARD && (
              <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} />
            )}
            {currentView === View.ADMIN_CALENDAR && (
              <AdminCalendar bookings={bookings} setBookings={setBookings} services={services} />
            )}
            {currentView === View.ADMIN_FINANCE && (
              <AdminFinance transactions={transactions} setTransactions={setTransactions} customers={customers} services={services} />
            )}
            {currentView === View.ADMIN_CLIENTS && (
              <AdminClients 
                customers={customers} 
                bookings={bookings} 
                transactions={transactions} 
                onDelete={handleDeleteCustomer}
                onUpdate={handleUpdateCustomer}
              />
            )}
            {currentView === View.ADMIN_VEO && (
              <AdminVeo />
            )}
            {currentView === View.ADMIN_SETTINGS && (
              <AdminSettingsView 
                settings={settings} 
                setSettings={setSettings} 
                services={services} 
                setServices={setServices}
              />
            )}
          </div>
        )}
      </main>

      {isAdmin && (
        <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 flex justify-around py-2 shadow-lg z-50">
          <button onClick={() => setCurrentView(View.ADMIN_DASHBOARD)} className={`flex flex-col items-center p-2 ${currentView === View.ADMIN_DASHBOARD ? 'text-tea-600' : 'text-gray-400'}`}>
            <span className="text-lg">🏠</span>
            <span className="text-[10px] mt-1 font-bold">Dash</span>
          </button>
          <button onClick={() => setCurrentView(View.ADMIN_CALENDAR)} className={`flex flex-col items-center p-2 ${currentView === View.ADMIN_CALENDAR ? 'text-tea-600' : 'text-gray-400'}`}>
            <span className="text-lg">📅</span>
            <span className="text-[10px] mt-1 font-bold">Agenda</span>
          </button>
          <button onClick={() => setCurrentView(View.ADMIN_FINANCE)} className={`flex flex-col items-center p-2 ${currentView === View.ADMIN_FINANCE ? 'text-tea-600' : 'text-gray-400'}`}>
            <span className="text-lg">💰</span>
            <span className="text-[10px] mt-1 font-bold">Finanças</span>
          </button>
          <button onClick={() => setCurrentView(View.ADMIN_CLIENTS)} className={`flex flex-col items-center p-2 ${currentView === View.ADMIN_CLIENTS ? 'text-tea-600' : 'text-gray-400'}`}>
            <span className="text-lg">👥</span>
            <span className="text-[10px] mt-1 font-bold">Clientes</span>
          </button>
          <button onClick={() => setCurrentView(View.ADMIN_SETTINGS)} className={`flex flex-col items-center p-2 ${currentView === View.ADMIN_SETTINGS ? 'text-tea-600' : 'text-gray-400'}`}>
            <span className="text-lg">⚙️</span>
            <span className="text-[10px] mt-1 font-bold">Config</span>
          </button>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Customer, Transaction } from '../types';
import TermsModal from './TermsModal';

interface CustomerProfileProps {
  customer: Customer;
  transactions: Transaction[];
  onUpdateNotification: (val: boolean) => void;
  onBack: () => void;
}

const CustomerProfile: React.FC<CustomerProfileProps> = ({ customer, transactions, onUpdateNotification, onBack }) => {
  const [modalConfig, setModalConfig] = useState<{ open: boolean; title: string; type: 'terms' | 'privacy' }>({
    open: false,
    title: '',
    type: 'terms'
  });

  const openModal = (type: 'terms' | 'privacy') => {
    setModalConfig({
      open: true,
      type,
      title: type === 'terms' ? 'Termos de Uso' : 'Política de Privacidade (LGPD)'
    });
  };

  const myTransactions = transactions.filter(t => t.customerId === customer.id);

  const totalPaid = myTransactions
    .filter(t => t.status === 'paid' && t.type === 'receivable')
    .reduce((sum, t) => sum + t.amount, 0);

  const totalPending = myTransactions
    .filter(t => t.status === 'pending' && t.type === 'receivable')
    .reduce((sum, t) => sum + t.amount, 0);

  const lastPaidTransaction = myTransactions
    .filter(t => t.status === 'paid')
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0];

  const nextDueDate = myTransactions
    .filter(t => t.status === 'pending')
    .sort((a, b) => new Date(a.dueDate!).getTime() - new Date(b.dueDate!).getTime())[0];

  const todayStr = new Date().toISOString().split('T')[0];
  const isDueToday = nextDueDate && nextDueDate.dueDate === todayStr;

  return (
    <div className="max-w-4xl mx-auto px-4 py-16 animate-fade-in">
      <button onClick={onBack} className="flex items-center gap-2 text-tea-600 font-bold mb-10 group">
        <svg className="w-5 h-5 group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
        Voltar para a Home
      </button>

      {isDueToday && (
        <div className="mb-8 bg-orange-50 border-l-4 border-orange-400 p-6 rounded-2xl flex items-center justify-between shadow-sm animate-bounce-subtle">
          <div className="flex items-center gap-4">
            <span className="text-3xl">⚠️</span>
            <div>
              <p className="font-bold text-orange-900">Vencimento Hoje!</p>
              <p className="text-sm text-orange-700">Olá {customer.name.split(' ')[0]}, lembramos que você possui um pagamento de R$ {nextDueDate.amount.toFixed(2)} pendente para hoje.</p>
            </div>
          </div>
        </div>
      )}

      <div className="bg-white rounded-[2rem] shadow-sm border border-tea-50 overflow-hidden">
        <div className="bg-tea-800 p-10 text-white flex justify-between items-end relative overflow-hidden">
           <div className="absolute top-0 right-0 w-32 h-32 bg-tea-700 rounded-full -mr-16 -mt-16 opacity-30"></div>
          <div>
            <h2 className="text-3xl font-serif font-bold mb-2">{customer.name}</h2>
            <p className="opacity-80 text-sm">CPF: {customer.cpf} • WhatsApp: {customer.whatsapp}</p>
          </div>
          <div className="bg-white/10 backdrop-blur-sm px-4 py-2 rounded-full text-xs font-bold uppercase tracking-widest relative z-10 border border-white/20">Perfil Verificado</div>
        </div>

        <div className="p-10 space-y-12">
          {/* Dashboard Financeiro Unificado */}
          <section>
            <h3 className="text-xl font-bold text-tea-900 mb-6 flex items-center gap-3">
              <span className="w-8 h-8 rounded-full bg-tea-50 flex items-center justify-center text-sm">💰</span>
              Meu Extrato Financeiro
            </h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mb-8">
              <div className="bg-tea-50 p-8 rounded-3xl border border-tea-100 flex flex-col justify-between h-full">
                <p className="text-xs font-bold text-tea-700 uppercase tracking-widest mb-4">Total Investido (Pago)</p>
                <p className="text-4xl font-serif font-bold text-tea-900">R$ {totalPaid.toFixed(2)}</p>
                {lastPaidTransaction && (
                  <p className="text-[10px] text-tea-600 mt-4 font-bold uppercase">Último Pagamento: {new Date(lastPaidTransaction.date).toLocaleDateString()}</p>
                )}
              </div>
              <div className="bg-orange-50 p-8 rounded-3xl border border-orange-100 flex flex-col justify-between h-full">
                <p className="text-xs font-bold text-orange-700 uppercase tracking-widest mb-4">Total Pendente (A Pagar)</p>
                <p className="text-4xl font-serif font-bold text-orange-900">R$ {totalPending.toFixed(2)}</p>
                {nextDueDate && (
                  <p className="text-[10px] text-orange-600 mt-4 font-bold uppercase tracking-tighter">Vencimento em: {new Date(nextDueDate.dueDate!).toLocaleDateString()}</p>
                )}
              </div>
            </div>

            <div className="overflow-hidden border border-gray-100 rounded-2xl">
              <table className="w-full text-left">
                <thead className="bg-gray-50 text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                  <tr>
                    <th className="px-6 py-4">Data/Venc.</th>
                    <th className="px-6 py-4">Procedimento / Lançamento</th>
                    <th className="px-6 py-4 text-right">Valor</th>
                    <th className="px-6 py-4 text-center">Situação</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {myTransactions.map(t => (
                    <tr key={t.id} className="text-sm hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4 text-gray-500 font-medium">{new Date(t.dueDate || t.date).toLocaleDateString()}</td>
                      <td className="px-6 py-4">
                        <div className="flex flex-col">
                          <span className="font-bold text-gray-800">{t.description}</span>
                          {t.serviceName && <span className="text-[9px] text-tea-600 font-bold uppercase tracking-widest">{t.serviceName}</span>}
                          {t.observation && <span className="text-[10px] text-gray-400 italic font-light mt-0.5">{t.observation}</span>}
