      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-xl font-bold mb-6 text-tea-900 flex items-center gap-2">
           <span className="text-2xl">✨</span> Identidade Visual & Nome
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div>
            <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Nome do Salão</label>
            <input 
              value={settings.name}
              onChange={(e) => updateSetting('name', e.target.value)}
