          <div>
            <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">URL do Logo (Drive Link)</label>
            <input 
              value={settings.logo}
              onChange={(e) => updateSetting('logo', e.target.value)}
              className="w-full p-4 border-2 border-gray-50 bg-gray-50 rounded-xl focus:border-tea-200 focus:bg-white outline-none transition-all"
            />
          </div>
        </div>
      </section>

      {/* Services Section Configuration */}
      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-xl font-bold mb-6 text-tea-900 flex items-center gap-2">
           <span className="text-2xl">🏷️</span> Textos da Seção de Procedimentos
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div>
            <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Título da Seção</label>
            <input 
              value={settings.servicesSectionTitle}
              onChange={(e) => updateSetting('servicesSectionTitle', e.target.value)}
              className="w-full p-4 border-2 border-gray-50 bg-gray-50 rounded-xl focus:border-tea-200 focus:bg-white outline-none transition-all"
            />
          </div>
          <div>
            <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Subtítulo da Seção</label>
            <input 
              value={settings.servicesSectionSubtitle}
              onChange={(e) => updateSetting('servicesSectionSubtitle', e.target.value)}
              className="w-full p-4 border-2 border-gray-50 bg-gray-50 rounded-xl focus:border-tea-200 focus:bg-white outline-none transition-all"
            />
          </div>
        </div>
      </section>

      {/* Equipe */}
      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-xl font-bold mb-6 text-tea-900 flex items-center gap-2">
           <span className="text-2xl">👥</span> Gestão da Equipe & Atribuições
        </h2>
        <div className="bg-tea-50 p-6 rounded-2xl mb-8 border border-tea-100">
          <div className="flex gap-4">
            <input 
              placeholder="Nome completo da profissional" 
              className="flex-grow p-4 border-2 border-white bg-white rounded-xl focus:border-tea-300 outline-none shadow-sm"
              value={newMemberName}
              onChange={(e) => setNewMemberName(e.target.value)}
            />
            <button 
              onClick={addTeamMember}
              className="bg-[#23492d] text-white px-8 py-4 rounded-xl font-bold hover:bg-tea-900 transition-all shadow-lg"
            >
              ADICIONAR
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 gap-6">
          {settings.teamMembers.map((member) => (
            <div key={member.id} className="border-2 border-gray-50 rounded-3xl p-6">
              <div className="flex justify-between items-center mb-6">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-tea-600 rounded-2xl flex items-center justify-center text-white font-bold">{member.name.charAt(0)}</div>
                  <h3 className="text-lg font-bold text-gray-800">{member.name}</h3>
                </div>
                <button onClick={() => removeTeamMember(member.id)} className="text-red-300 hover:text-red-500 transition-all">Remover</button>
              </div>
              <div className="flex flex-wrap gap-2">
                {services.map(s => {
                  const isAssigned = member.assignedServiceIds.includes(s.id);
                  return (
                    <button
                      key={s.id}
                      onClick={() => toggleServiceToMember(member.id, s.id)}
                      className={`px-4 py-2 rounded-xl text-xs font-bold transition-all border-2 ${isAssigned ? 'bg-tea-600 text-white border-tea-600' : 'bg-white text-gray-400 border-gray-100'}`}
                    >
                      {s.name}
                    </button>
                  )
                })}
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Serviços */}
      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-xl font-bold mb-6 text-tea-900 flex items-center gap-2">
           <span className="text-2xl">📋</span> Gestão de Serviços (Procedimentos)
        </h2>

        <div className="bg-tea-50 p-6 rounded-2xl mb-8 border border-tea-100">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-4">
            <input 
              placeholder="Nome" 
              className="p-4 border-2 border-white bg-white rounded-xl outline-none"
              value={newService.name}
              onChange={(e) => setNewService({...newService, name: e.target.value})}
            />
            <input 
              type="number" 
              placeholder="Preço R$" 
              className="p-4 border-2 border-white bg-white rounded-xl outline-none"
              value={newService.price || ''}
              onChange={(e) => setNewService({...newService, price: parseFloat(e.target.value)})}
            />
            <input 
              type="number" 
              placeholder="Duração (min)" 
              className="p-4 border-2 border-white bg-white rounded-xl outline-none"
              value={newService.duration || ''}
              onChange={(e) => setNewService({...newService, duration: parseInt(e.target.value)})}
            />
            <button onClick={addService} className="bg-[#23492d] text-white px-6 py-4 rounded-xl font-bold hover:bg-tea-900 transition-all">Adicionar</button>
          </div>
          <textarea 
             placeholder="Descrição curta..."
             className="w-full p-4 border-2 border-white bg-white rounded-xl outline-none"
             value={newService.description}
             onChange={(e) => setNewService({...newService, description: e.target.value})}
          />
        </div>

        <div className="space-y-4">
          {services.map(s => (
            <div key={s.id} className="p-6 border-2 border-gray-50 rounded-3xl flex justify-between items-center">
              <div>
                <p className="font-bold text-tea-900">{s.name} - R$ {s.price.toFixed(2)}</p>
                <p className="text-xs text-gray-400">{s.duration} min</p>
              </div>
              <div className="flex gap-2">
                <button onClick={() => toggleServiceVisibility(s.id)} className="p-2 text-tea-600 hover:bg-tea-50 rounded-lg">{s.isVisible ? '👁️ Ocultar' : '👁️ Exibir'}</button>
                <button onClick={() => setServices(services.filter(x => x.id !== s.id))} className="p-2 text-red-400 hover:bg-red-50 rounded-lg">Excluir</button>
              </div>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
};

