import React, { useState } from 'react';
import { Customer, Booking, Transaction } from '../types';

interface AdminClientsProps {
  customers: Customer[];
  bookings: Booking[];
  transactions: Transaction[];
  onDelete: (id: string) => void;
  onUpdate: (id: string, data: Partial<Customer>) => void;
}

const AdminClients: React.FC<AdminClientsProps> = ({ customers, bookings, transactions, onDelete, onUpdate }) => {
  const [search, setSearch] = useState('');
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [editData, setEditData] = useState<Partial<Customer>>({});

  const filtered = customers.filter(c => 
    c.name.toLowerCase().includes(search.toLowerCase()) || 
    c.whatsapp.includes(search) ||
    c.cpf.includes(search)
  );

  const handleEditClick = () => {
    if (selectedCustomer) {
      setEditData({ name: selectedCustomer.name, whatsapp: selectedCustomer.whatsapp, cpf: selectedCustomer.cpf });
      setIsEditing(true);
    }
  };

  const handleSaveEdit = () => {
    if (selectedCustomer && editData.name && editData.whatsapp && editData.cpf) {
      onUpdate(selectedCustomer.id, editData);
      setSelectedCustomer({ ...selectedCustomer, ...editData });
      setIsEditing(false);
    }
  };

  const handleDeleteClick = () => {
    if (selectedCustomer) {
      onDelete(selectedCustomer.id);
      setSelectedCustomer(null);
    }
  };

  // Cálculo de histórico e métricas
  const getClientStats = (customerId: string) => {
    const myBookings = bookings.filter(b => b.customerId === customerId);
    const myTransactions = transactions.filter(t => t.customerId === customerId);

    const cancelledCount = myBookings.filter(b => b.status === 'cancelled').length;
    const reschedules = myBookings.reduce((sum, b) => sum + (b.rescheduledCount || 0), 0);

    const latePayments = myTransactions.filter(t => 
      t.status === 'paid' && t.dueDate && t.paidAt && 
      new Date(t.paidAt).setHours(0,0,0,0) > new Date(t.dueDate).setHours(0,0,0,0)
    ).length;

    const paid = myTransactions
      .filter(t => t.status === 'paid' && t.type === 'receivable')
      .reduce((sum, t) => sum + t.amount, 0);
    const pending = myTransactions
      .filter(t => t.status === 'pending' && t.type === 'receivable')
      .reduce((sum, t) => sum + t.amount, 0);

    return { paid, pending, cancelledCount, reschedules, latePayments };
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-tea-950">Gestão de Clientes</h2>
          <p className="text-gray-500 text-sm">Visualize o comportamento e histórico das clientes.</p>
        </div>
        <div className="relative w-full md:w-80">
          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">🔍</span>
          <input 
            placeholder="Nome, WhatsApp ou CPF..." 
            className="w-full pl-12 pr-4 py-3 border-2 border-gray-100 rounded-2xl outline-none focus:border-tea-200 transition-all bg-white shadow-sm"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Lista de Clientes */}
        <div className="lg:col-span-1 bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden flex flex-col h-[700px]">
          <div className="p-6 bg-tea-50 border-b border-tea-100">
            <h3 className="font-bold text-tea-900 uppercase text-[10px] tracking-widest">Base de Dados ({filtered.length})</h3>
          </div>
          <div className="overflow-y-auto flex-grow custom-scroll divide-y divide-gray-50">
            {filtered.map(customer => (
              <div 
                key={customer.id} 
                onClick={() => { setSelectedCustomer(customer); setIsEditing(false); }}
                className={`p-6 cursor-pointer hover:bg-tea-50/50 transition-all group ${selectedCustomer?.id === customer.id ? 'bg-tea-50 border-l-4 border-tea-500' : ''}`}
              >
                <div className="flex justify-between items-start">
                  <div>
                    <p className="font-bold text-gray-800 group-hover:text-tea-700 transition-colors">{customer.name}</p>
                    <p className="text-xs text-gray-400 mt-1">CPF: {customer.cpf}</p>
                  </div>
                  <span className="text-[10px] bg-white px-2 py-1 rounded-full border border-gray-100 text-gray-400 group-hover:border-tea-200 group-hover:text-tea-600 transition-all">Ver Perfil</span>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Detalhes da Cliente */}
        <div className="lg:col-span-2">
          {selectedCustomer ? (
            <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden animate-slide-up h-full flex flex-col">
              <div className="p-8 bg-gray-50 border-b border-gray-100 flex justify-between items-start">
                {isEditing ? (
                  <div className="space-y-4 w-full max-w-md">
                    <input className="w-full p-3 border-2 border-tea-100 rounded-xl outline-none" value={editData.name} onChange={e => setEditData({...editData, name: e.target.value})} />
                    <div className="grid grid-cols-2 gap-4">
                      <input className="w-full p-3 border-2 border-tea-100 rounded-xl outline-none" value={editData.whatsapp} onChange={e => setEditData({...editData, whatsapp: e.target.value})} />
                      <input className="w-full p-3 border-2 border-tea-100 rounded-xl outline-none" value={editData.cpf} onChange={e => setEditData({...editData, cpf: e.target.value})} />
                    </div>
                    <div className="flex gap-2">
                      <button onClick={handleSaveEdit} className="bg-tea-600 text-white px-6 py-2 rounded-xl font-bold text-sm">Salvar</button>
                      <button onClick={() => setIsEditing(false)} className="text-gray-400 font-bold px-4 py-2">Cancelar</button>
                    </div>
                  </div>
                ) : (
                  <>
                    <div className="flex gap-6 items-center">
                      <div className="w-20 h-20 bg-tea-800 rounded-3xl flex items-center justify-center text-white text-3xl font-serif font-bold shadow-lg">
                        {selectedCustomer.name.charAt(0)}
                      </div>
                      <div>
                        <h3 className="text-3xl font-serif text-tea-950 font-bold">{selectedCustomer.name}</h3>
                        <p className="text-sm text-gray-500 font-medium">WhatsApp: {selectedCustomer.whatsapp}</p>
                      </div>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={handleEditClick} className="p-3 bg-white border border-gray-200 rounded-xl hover:border-tea-500 shadow-sm transition-all">✏️</button>
                      <button onClick={handleDeleteClick} className="p-3 bg-white border border-gray-200 rounded-xl hover:border-red-500 shadow-sm transition-all">🗑️</button>
                    </div>
                  </>
                )}
              </div>

              <div className="p-8 flex-grow overflow-y-auto custom-scroll space-y-10">
                {/* Métricas de Comportamento */}
                <section>
                  <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-6 border-b pb-2">Índice de Confiabilidade</h4>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div className="bg-red-50 p-6 rounded-2xl border border-red-100">
                      <p className="text-[10px] font-bold text-red-700 uppercase mb-2">Cancelamentos</p>
                      <p className="text-3xl font-serif font-bold text-red-900">{getClientStats(selectedCustomer.id).cancelledCount}</p>
                    </div>
                    <div className="bg-blue-50 p-6 rounded-2xl border border-blue-100">
                      <p className="text-[10px] font-bold text-blue-700 uppercase mb-2">Remarcações</p>
                      <p className="text-3xl font-serif font-bold text-blue-900">{getClientStats(selectedCustomer.id).reschedules}</p>
                    </div>
                    <div className="bg-orange-50 p-6 rounded-2xl border border-orange-100">
                      <p className="text-[10px] font-bold text-orange-700 uppercase mb-2">Atrasos de Pagto</p>
                      <p className="text-3xl font-serif font-bold text-orange-900">{getClientStats(selectedCustomer.id).latePayments}</p>
                    </div>
                  </div>
                </section>

                <section>
                  <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-6 border-b pb-2">Resumo Financeiro</h4>
                  <div className="grid grid-cols-2 gap-6">
                    <div className="bg-tea-50 p-6 rounded-2xl border border-tea-100">
                      <p className="text-[10px] font-bold text-tea-700 uppercase mb-2">Total Recebido</p>
                      <p className="text-3xl font-serif font-bold text-tea-900">R$ {getClientStats(selectedCustomer.id).paid.toFixed(2)}</p>
                    </div>
                    <div className="bg-gray-50 p-6 rounded-2xl border border-gray-100">
                      <p className="text-[10px] font-bold text-gray-700 uppercase mb-2">Total Pendente</p>
                      <p className="text-3xl font-serif font-bold text-gray-900">R$ {getClientStats(selectedCustomer.id).pending.toFixed(2)}</p>
                    </div>
                  </div>
                </section>

                <section>
                  <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-6 border-b pb-2">Histórico de Procedimentos</h4>
                  <div className="space-y-4">
                    {bookings.filter(b => b.customerId === selectedCustomer.id).map(booking => (
                      <div key={booking.id} className="flex justify-between p-5 bg-white border border-gray-100 rounded-2xl items-center">
                        <div>
                          <p className="font-bold text-gray-800">{booking.serviceName}</p>
                          <p className="text-xs text-gray-400">🗓️ {new Date(booking.dateTime).toLocaleDateString()} • {booking.rescheduledCount ? `${booking.rescheduledCount} remarcações` : 'Horário original'}</p>
