                          {booking.status === 'completed' ? 'Finalizado' : booking.status === 'cancelled' ? 'Cancelado' : 'Agendado'}
                        </span>
                      </div>
                    ))}
                  </div>
                </section>
              </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center bg-gray-50 rounded-[3rem] border-4 border-dashed border-gray-100 p-12 text-center">
              <div className="w-24 h-24 bg-white rounded-full flex items-center justify-center text-4xl mb-6 shadow-sm">👥</div>
              <h3 className="text-2xl font-serif text-tea-900 mb-2">Selecione uma cliente</h3>
              <p className="text-gray-400 max-w-xs mx-auto font-light">Visualize o histórico completo de agendamentos, cancelamentos e pontualidade financeira.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

