                       'Confirmado'}
                    </span>
                 </div>
              ))}
            </div>
          </section>
        </div>
      </div>
      <TermsModal isOpen={modalConfig.open} onClose={() => setModalConfig({ ...modalConfig, open: false })} title={modalConfig.title} type={modalConfig.type} />
    </div>
  );
};

