              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className={`w-full px-6 py-4 rounded-2xl bg-gray-50 border-2 transition-all outline-none text-center text-lg tracking-widest ${error ? 'border-red-300 bg-red-50' : 'border-transparent focus:border-tea-200 focus:bg-white'}`}
            />
            {error && <p className="text-red-500 text-xs font-bold mt-2 animate-bounce">Senha incorreta</p>}
          </div>

          <button 
            type="submit"
            className="w-full bg-tea-600 text-white py-4 rounded-2xl font-bold text-lg hover:bg-tea-700 transition-all shadow-lg shadow-tea-100"
          >
            Entrar no Painel
          </button>
        </form>

        <button 
          onClick={onBack}
          className="mt-8 text-tea-500 font-bold text-sm hover:underline"
        >
          Voltar para o site
        </button>
      </div>
    </div>
  );
};

export default AdminLogin;

import React, { useState, useRef } from 'react';
import { SalonSettings, Service, TeamMember, Customer, Booking, Transaction } from '../types';

interface AdminSettingsViewProps {
  settings: SalonSettings;
  setSettings: (s: SalonSettings) => void;
  services: Service[];
  setServices: (s: Service[]) => void;
  customers: Customer[];
  bookings: Booking[];
  transactions: Transaction[];
  onImport: (data: any) => void;
}

const AdminSettingsView: React.FC<AdminSettingsViewProps> = ({ 
  settings, 
  setSettings, 
  services, 
  setServices,
  customers,
  bookings,
  transactions,
  onImport
}) => {
  const [newService, setNewService] = useState({ name: '', price: 0, duration: 30, description: '', isVisible: true });
  const [newMemberName, setNewMemberName] = useState('');
  const [editingServiceId, setEditingServiceId] = useState<string | null>(null);
  const [editServiceData, setEditServiceData] = useState<Service | null>(null);
  const [isDeploying, setIsDeploying] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleDeploy = () => {
    setIsDeploying(true);
    // Simula um processo de deploy/publicação
    setTimeout(() => {
      setIsDeploying(false);
      alert("Alterações publicadas com sucesso no Studio Moriá Estética! 🚀");
    }, 2000);
  };

  const updateSetting = (key: string, value: any) => {
    setSettings({ ...settings, [key]: value });
  };

  const addService = () => {
    if (newService.name && newService.price > 0) {
      setServices([...services, { ...newService, id: Math.random().toString(36).substr(2, 9) }]);
      setNewService({ name: '', price: 0, duration: 30, description: '', isVisible: true });
    }
  };

  const startEditingService = (service: Service) => {
    setEditingServiceId(service.id);
    setEditServiceData({ ...service });
  };

  const saveEditedService = () => {
    if (editServiceData) {
      setServices(services.map(s => s.id === editingServiceId ? editServiceData : s));
      setEditingServiceId(null);
      setEditServiceData(null);
    }
  };

  const addTeamMember = () => {
    if (newMemberName.trim()) {
      const newMember: TeamMember = {
        id: Math.random().toString(36).substr(2, 9),
        name: newMemberName.trim(),
        assignedServiceIds: []
      };
      updateSetting('teamMembers', [...(settings.teamMembers || []), newMember]);
      setNewMemberName('');
    }
  };

  const removeTeamMember = (id: string) => {
    if (confirm("Deseja remover esta colaboradora?")) {
      updateSetting('teamMembers', (settings.teamMembers || []).filter(m => m.id !== id));
    }
  };

  const toggleServiceToMember = (memberId: string, serviceId: string) => {
    const updatedMembers = settings.teamMembers.map(m => {
      if (m.id === memberId) {
        const hasService = m.assignedServiceIds.includes(serviceId);
        return {
          ...m,
          assignedServiceIds: hasService 
            ? m.assignedServiceIds.filter(id => id !== serviceId)
            : [...m.assignedServiceIds, serviceId]
        };
      }
      return m;
    });
    updateSetting('teamMembers', updatedMembers);
  };

  const toggleServiceVisibility = (id: string) => {
    setServices(services.map(s => s.id === id ? { ...s, isVisible: !s.isVisible } : s));
  };

  const exportBackup = () => {
    const data = {
      settings,
      services,
      customers,
      bookings,
      transactions,
      exportDate: new Date().toISOString()
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `backup_moria_${new Date().toLocaleDateString().replace(/\//g, '-')}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (confirm("ATENÇÃO: Importar um backup substituirá todos os dados atuais do sistema. Deseja continuar?")) {
        const reader = new FileReader();
        reader.onload = (event) => {
          try {
            const json = JSON.parse(event.target?.result as string);
            onImport(json);
          } catch (err) {
            alert("Erro ao ler o arquivo de backup. Verifique se o arquivo é válido.");
          }
        };
        reader.readAsText(file);
      }
    }
  };

  return (
    <div className="space-y-12 pb-20 animate-fade-in">
      {/* Header com Botão de Deploy */}
      <div className="flex justify-between items-center bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
        <div>
          <h2 className="text-2xl font-bold text-tea-950">Painel de Configurações</h2>
          <p className="text-gray-500 text-sm">Gerencie o catálogo, equipe e identidade visual.</p>
        </div>
        <button 
          onClick={handleDeploy}
          disabled={isDeploying}
          className={`px-8 py-3 rounded-2xl font-bold text-sm transition-all flex items-center gap-3 shadow-lg ${isDeploying ? 'bg-gray-100 text-gray-400 cursor-not-allowed' : 'bg-tea-600 text-white hover:bg-tea-700 shadow-tea-100 active:scale-95'}`}
        >
          {isDeploying ? (
            <>
              <span className="w-4 h-4 border-2 border-gray-400 border-t-transparent rounded-full animate-spin"></span>
              PUBLICANDO...
            </>
          ) : (
            <>
              <span className="text-lg">🚀</span>
              PUBLICAR ALTERAÇÕES (DEPLOY)
            </>
          )}
        </button>
      </div>

      {/* Backup & Restore - SEGURANÇA DE DADOS */}
      <section className="bg-[#23492d] p-8 rounded-[2.5rem] shadow-2xl text-white relative overflow-hidden">
        <div className="absolute top-0 right-0 w-48 h-48 bg-white/5 rounded-full -mr-20 -mt-20"></div>
        <div className="relative z-10">
          <h2 className="text-2xl font-serif font-bold mb-4 flex items-center gap-3">
             <span className="text-3xl">🛡️</span> Segurança & Backup dos Dados
          </h2>
          <p className="text-tea-100 text-sm mb-8 max-w-2xl leading-relaxed">
            Mantenha seu Studio Moriá seguro. Recomendamos baixar um backup toda vez que fizer alterações importantes em preços ou cadastros. 
            Isso garante que você nunca perca o histórico financeiro ou de clientes em atualizações do sistema.
          </p>
          <div className="flex flex-col sm:flex-row gap-4">
            <button 
              onClick={exportBackup}
              className="bg-white text-tea-900 px-8 py-4 rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-tea-50 transition-all shadow-xl"
            >
              📥 EXPORTAR BASE COMPLETA
            </button>
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="bg-tea-800 border border-white/20 text-white px-8 py-4 rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-tea-700 transition-all"
            >
              📤 RESTAURAR BACKUP
            </button>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept=".json" 
              onChange={handleFileImport} 
            />
          </div>
        </div>
      </section>

      {/* Identidade Visual */}
      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-xl font-bold mb-6 text-tea-900 flex items-center gap-2">
           <span className="text-2xl">✨</span> Identidade Visual & Nome
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div>
            <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Nome do Salão</label>
            <input 
              value={settings.name}
              onChange={(e) => updateSetting('name', e.target.value)}
              className="w-full p-4 border-2 border-gray-50 bg-gray-50 rounded-xl focus:border-tea-200 focus:bg-white outline-none transition-all"
            />
          </div>
          <div>
            <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">URL do Logo (Drive Link)</label>
            <input 
              value={settings.logo}
              onChange={(e) => updateSetting('logo', e.target.value)}
              className="w-full p-4 border-2 border-gray-50 bg-gray-50 rounded-xl focus:border-tea-200 focus:bg-white outline-none transition-all"
            />
          </div>
        </div>
      </section>

      {/* Services Section Configuration */}
      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-xl font-bold mb-6 text-tea-900 flex items-center gap-2">
           <span className="text-2xl">🏷️</span> Textos da Seção de Procedimentos
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div>
            <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Título da Seção</label>
            <input 
              value={settings.servicesSectionTitle}
              onChange={(e) => updateSetting('servicesSectionTitle', e.target.value)}
              className="w-full p-4 border-2 border-gray-50 bg-gray-50 rounded-xl focus:border-tea-200 focus:bg-white outline-none transition-all"
            />
          </div>
          <div>
            <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Subtítulo da Seção</label>
            <input 
              value={settings.servicesSectionSubtitle}
              onChange={(e) => updateSetting('servicesSectionSubtitle', e.target.value)}
              className="w-full p-4 border-2 border-gray-50 bg-gray-50 rounded-xl focus:border-tea-200 focus:bg-white outline-none transition-all"
            />
          </div>
        </div>
      </section>

      {/* Equipe */}
      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-xl font-bold mb-6 text-tea-900 flex items-center gap-2">
           <span className="text-2xl">👥</span> Gestão da Equipe & Atribuições
        </h2>
        <div className="bg-tea-50 p-6 rounded-2xl mb-8 border border-tea-100">
          <div className="flex gap-4">
            <input 
              placeholder="Nome completo da profissional" 
              className="flex-grow p-4 border-2 border-white bg-white rounded-xl focus:border-tea-300 outline-none shadow-sm"
              value={newMemberName}
              onChange={(e) => setNewMemberName(e.target.value)}
            />
            <button 
              onClick={addTeamMember}
              className="bg-[#23492d] text-white px-8 py-4 rounded-xl font-bold hover:bg-tea-900 transition-all shadow-lg"
            >
              ADICIONAR
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 gap-6">
          {settings.teamMembers.map((member) => (
            <div key={member.id} className="border-2 border-gray-50 rounded-3xl p-6">
              <div className="flex justify-between items-center mb-6">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-tea-600 rounded-2xl flex items-center justify-center text-white font-bold">{member.name.charAt(0)}</div>
                  <h3 className="text-lg font-bold text-gray-800">{member.name}</h3>
                </div>
                <button onClick={() => removeTeamMember(member.id)} className="text-red-300 hover:text-red-500 transition-all">Remover</button>
              </div>
              <div className="flex flex-wrap gap-2">
                {services.map(s => {
                  const isAssigned = member.assignedServiceIds.includes(s.id);
                  return (
                    <button
                      key={s.id}
                      onClick={() => toggleServiceToMember(member.id, s.id)}
                      className={`px-4 py-2 rounded-xl text-xs font-bold transition-all border-2 ${isAssigned ? 'bg-tea-600 text-white border-tea-600' : 'bg-white text-gray-400 border-gray-100'}`}
                    >
                      {s.name}
                    </button>
                  )
                })}
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Serviços */}
      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-xl font-bold mb-6 text-tea-900 flex items-center gap-2">
           <span className="text-2xl">📋</span> Gestão de Serviços (Procedimentos)
        </h2>

        <div className="bg-tea-50 p-6 rounded-2xl mb-8 border border-tea-100">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-4">
            <input 
              placeholder="Nome" 
              className="p-4 border-2 border-white bg-white rounded-xl outline-none"
              value={newService.name}
              onChange={(e) => setNewService({...newService, name: e.target.value})}
            />
            <input 
              type="number" 
              placeholder="Preço R$" 
              className="p-4 border-2 border-white bg-white rounded-xl outline-none"
              value={newService.price || ''}
              onChange={(e) => setNewService({...newService, price: parseFloat(e.target.value)})}
            />
            <input 
              type="number" 
              placeholder="Duração (min)" 
              className="p-4 border-2 border-white bg-white rounded-xl outline-none"
              value={newService.duration || ''}
              onChange={(e) => setNewService({...newService, duration: parseInt(e.target.value)})}
            />
            <button onClick={addService} className="bg-[#23492d] text-white px-6 py-4 rounded-xl font-bold hover:bg-tea-900 transition-all">Adicionar</button>
          </div>
          <textarea 
             placeholder="Descrição curta..."
             className="w-full p-4 border-2 border-white bg-white rounded-xl outline-none"
             value={newService.description}
             onChange={(e) => setNewService({...newService, description: e.target.value})}
          />
        </div>

        <div className="space-y-4">
          {services.map(s => (
            <div key={s.id} className="p-6 border-2 border-gray-50 rounded-3xl flex justify-between items-center">
              <div>
                <p className="font-bold text-tea-900">{s.name} - R$ {s.price.toFixed(2)}</p>
                <p className="text-xs text-gray-400">{s.duration} min</p>
              </div>
              <div className="flex gap-2">
                <button onClick={() => toggleServiceVisibility(s.id)} className="p-2 text-tea-600 hover:bg-tea-50 rounded-lg">{s.isVisible ? '👁️ Ocultar' : '👁️ Exibir'}</button>
                <button onClick={() => setServices(services.filter(x => x.id !== s.id))} className="p-2 text-red-400 hover:bg-red-50 rounded-lg">Excluir</button>
              </div>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
};

export default AdminSettingsView;

import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, TeamMember } from './types';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants';
import Navbar from './components/Navbar';
import CustomerHome from './components/CustomerHome';
import CustomerRegister from './components/CustomerRegister';
import CustomerLoginView from './components/CustomerLoginView';
import CustomerProfile from './components/CustomerProfile';
import AdminDashboard from './components/AdminDashboard';
import AdminCalendar from './components/AdminCalendar';
import AdminFinance from './components/AdminFinance';
import AdminClients from './components/AdminClients';
import AdminConfirmations from './components/AdminConfirmations';
import AdminSettingsView from './components/AdminSettingsView';
import AdminVeo from './components/AdminVeo';
import AdminLogin from './components/AdminLogin';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>(INITIAL_SERVICES);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  // Load state from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('moria_state');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.settings) setSettings(parsed.settings);
        if (parsed.services) setServices(parsed.services);
        if (parsed.customers) setCustomers(parsed.customers);
        if (parsed.bookings) setBookings(parsed.bookings);
        if (parsed.transactions) setTransactions(parsed.transactions);

        const savedUser = localStorage.getItem('moria_current_user');
        if (savedUser) setCurrentUser(JSON.parse(savedUser));

        const savedAdminAuth = localStorage.getItem('moria_admin_auth');
        if (savedAdminAuth === 'true') setIsAdminAuthenticated(true);
      } catch (e) {
        console.error("Failed to parse saved state", e);
      }
    }
  }, []);

  // Save state to localStorage on changes
  useEffect(() => {
    const state = { settings, services, customers, bookings, transactions };
    localStorage.setItem('moria_state', JSON.stringify(state));
    if (currentUser) {
      localStorage.setItem('moria_current_user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('moria_current_user');
    }
    localStorage.setItem('moria_admin_auth', isAdminAuthenticated.toString());
  }, [settings, services, customers, bookings, transactions, currentUser, isAdminAuthenticated]);

  const handleBulkImport = (data: any) => {
    if (data.settings) setSettings(data.settings);
    if (data.services) setServices(data.services);
    if (data.customers) setCustomers(data.customers);
    if (data.bookings) setBookings(data.bookings);
    if (data.transactions) setTransactions(data.transactions);
    alert("Dados restaurados com sucesso!");
  };

  const handleRegister = (name: string, whatsapp: string, cpf: string, password: string, receivesNotifications: boolean) => {
    if (customers.find(c => c.cpf === cpf)) {
      alert("Este CPF já está cadastrado em nossa base.");
      return;
    }

    const newCustomer: Customer = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      whatsapp,
      cpf,
      password,
      receivesNotifications,
      agreedToTerms: true,
      history: []
    };
    setCustomers(prev => [...prev, newCustomer]);
    setCurrentUser(newCustomer);
    setCurrentView(View.CUSTOMER_HOME);
  };

  const handleDeleteCustomer = (id: string) => {
    if (confirm("Deseja realmente excluir esta cliente? Todos os dados vinculados serão mantidos no histórico financeiro, mas o acesso dela será removido.")) {
      setCustomers(prev => prev.filter(c => c.id !== id));
    }
  };

  const handleUpdateCustomer = (id: string, data: Partial<Customer>) => {
    setCustomers(prev => prev.map(c => c.id === id ? { ...c, ...data } : c));
  };

  const handleBook = (serviceId: string, dateTime: string, teamMemberId?: string) => {
    if (!currentUser) return;
    const service = services.find(s => s.id === serviceId);
    if (!service) return;

    const newBooking: Booking = {
      id: Math.random().toString(36).substr(2, 9),
      customerId: currentUser.id,
      customerName: currentUser.name,
      serviceId,
      serviceName: service.name,
      teamMemberId,
      teamMemberName: settings.teamMembers.find(m => m.id === teamMemberId)?.name,
      dateTime,
      status: 'pending'
    };

    setBookings(prev => [...prev, newBooking]);

    // Auto-create a pending transaction for the salon's finance tracking
    const newTransaction: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      type: 'receivable',
      description: service.name,
      amount: service.price,
      date: new Date().toISOString(),
      dueDate: dateTime.split('T')[0],
      status: 'pending',
      customerId: currentUser.id,
      customerName: currentUser.name,
      serviceId,
      serviceName: service.name
    };
    setTransactions(prev => [...prev, newTransaction]);

    alert("Pedido de agendamento enviado! Aguarde a confirmação da equipe.");
  };

  const handleUpdateBookingStatus = (id: string, status: 'scheduled' | 'cancelled' | 'completed') => {
    setBookings(prev => prev.map(b => b.id === id ? { ...b, status } : b));
  };

  const handleLogin = (cpf: string, pass: string) => {
    const user = customers.find(c => c.cpf === cpf && c.password === pass);
    if (user) {
      setCurrentUser(user);
      setCurrentView(View.CUSTOMER_HOME);
    } else {
      alert("CPF ou Senha incorretos.");
    }
  };

  const handleAdminLogin = (password: string) => {
    if (password === '460206') {
      setIsAdminAuthenticated(true);
      setIsAdmin(true);
      setCurrentView(View.ADMIN_DASHBOARD);
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentView(View.CUSTOMER_HOME);
  };

  const handleAdminLogout = () => {
    setIsAdminAuthenticated(false);
    setIsAdmin(false);
    setCurrentView(View.CUSTOMER_HOME);
  };

  const toggleAdminMode = () => {
    if (!isAdminAuthenticated && !isAdmin) {
      setCurrentView(View.ADMIN_LOGIN);
      setIsAdmin(true);
    } else if (isAdmin) {
      setIsAdmin(false);
      setCurrentView(View.CUSTOMER_HOME);
    } else {
      setIsAdmin(true);
      setCurrentView(View.ADMIN_DASHBOARD);
    }
  };

  const pendingBookingsCount = bookings.filter(b => b.status === 'pending').length;

  const renderView = () => {
    if (isAdmin) {
      if (!isAdminAuthenticated) return <AdminLogin onLogin={handleAdminLogin} onBack={() => setIsAdmin(false)} />;
      switch (currentView) {
        case View.ADMIN_DASHBOARD: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} setBookings={setBookings} services={services} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} setTransactions={setTransactions} customers={customers} services={services} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={handleDeleteCustomer} onUpdate={handleUpdateCustomer} />;
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} onUpdateStatus={handleUpdateBookingStatus} />;
        case View.ADMIN_VEO: return <AdminVeo />;
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} setSettings={setSettings} services={services} setServices={setServices} customers={customers} bookings={bookings} transactions={transactions} onImport={handleBulkImport} />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} />;
      }
    }

    switch (currentView) {
      case View.CUSTOMER_HOME: return <CustomerHome settings={settings} services={services} onBook={handleBook} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} currentUser={currentUser} />;
      case View.CUSTOMER_REGISTER: return <CustomerRegister onRegister={handleRegister} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_LOGIN: return <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_PROFILE: return currentUser ? <CustomerProfile customer={currentUser} transactions={transactions} bookings={bookings} onUpdateNotification={(val) => handleUpdateCustomer(currentUser.id, { receivesNotifications: val })} onBack={() => setCurrentView(View.CUSTOMER_HOME)} /> : <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.ADMIN_LOGIN: return <AdminLogin onLogin={handleAdminLogin} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      default: return <CustomerHome settings={settings} services={services} onBook={handleBook} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} currentUser={currentUser} />;
    }
  };

  return (
    <div className="min-h-screen bg-white">
      <Navbar 
        view={currentView} 
        setView={setCurrentView} 
        isAdmin={isAdmin} 
        onToggleAdmin={toggleAdminMode} 
        salonName={settings.name} 
        logo={settings.logo} 
        currentUser={currentUser} 
        onLogout={handleLogout} 
        onAdminLogout={handleAdminLogout}
        isAdminAuthenticated={isAdminAuthenticated}
        pendingBookingsCount={pendingBookingsCount}
      />
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Customer, Booking, Service } from '../types';
import { GoogleGenAI } from '@google/genai';

interface CustomerDashboardProps {
  customer: Customer;
  bookings: Booking[];
  services: Service[];
  onUpdateProfile: (updated: Partial<Customer>) => void;
  onLogout: () => void;
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ customer, bookings, services, onUpdateProfile, onLogout }) => {
  const [activeTab, setActiveTab] = useState<'home' | 'agenda' | 'cuidados' | 'perfil'>('home');
  const [careTips, setCareTips] = useState<string>('');
  const [isLoadingTips, setIsLoadingTips] = useState(false);

  const myBookings = bookings.filter(b => b.customerId === customer.id);

  useEffect(() => {
    if (activeTab === 'cuidados' && !careTips) {
      generateCareTips();
    }
  }, [activeTab]);

  const generateCareTips = async () => {
    setIsLoadingTips(true);
    try {
      // Use the GoogleGenAI instance for content generation
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const lastService = myBookings[0]?.serviceName || "Estética Geral";
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Como especialista em estética do Studio Moriá, forneça 4 dicas curtas e luxuosas de cuidados para uma cliente que realizou ou deseja realizar: ${lastService}. Use um tom acolhedor e profissional. Retorne em formato de lista Markdown.`,
      });
      // Extracting text correctly using .text property (not a method)
      setCareTips(response.text || "Beba bastante água e use protetor solar diariamente para manter os resultados.");
    } catch (error) {
      console.error("AI Tips generation failed:", error);
      setCareTips("Mantenha sua pele hidratada e use sempre protetor solar. Consulte nossas profissionais para um cronograma personalizado.");
    } finally {
      setIsLoadingTips(false);
    }
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        onUpdateProfile({ profilePhoto: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="min-h-screen bg-[#FDFCFB] animate-fade-in pb-24">
      {/* Header Profile Summary */}
      <div className="bg-tea-900 text-white pt-12 pb-24 px-6 rounded-b-[4rem] relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-tea-800 rounded-full -mr-20 -mt-20 opacity-50"></div>
        <div className="max-w-4xl mx-auto flex flex-col md:flex-row items-center gap-8 relative z-10">
          <div className="relative group">
            <div className="w-32 h-32 rounded-[2.5rem] border-4 border-white/30 overflow-hidden bg-tea-800 flex items-center justify-center shadow-2xl">
              {customer.profilePhoto ? (
                <img src={customer.profilePhoto} className="w-full h-full object-cover" alt="Perfil" />
              ) : (
                <span className="text-5xl font-serif">{customer.name.charAt(0)}</span>
              )}
            </div>
            <label className="absolute bottom-0 right-0 bg-white p-2 rounded-xl shadow-lg cursor-pointer hover:scale-110 transition-transform">
              <svg className="w-5 h-5 text-tea-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path>
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path>
              </svg>
              <input type="file" className="hidden" accept="image/*" onChange={handlePhotoUpload} />
            </label>
          </div>
          <div className="text-center md:text-left">
             <h1 className="text-4xl font-serif font-bold mb-2">Olá, {customer.name.split(' ')[0]}!</h1>
             <p className="opacity-70 font-light tracking-wide">Seu Espaço VIP no Studio Moriá Estética</p>
          </div>
        </div>
      </div>

      <div className="max-w-4xl mx-auto px-6 -mt-12 relative z-20 space-y-8">
         <div className="bg-white rounded-[2rem] shadow-xl p-4 flex justify-around">
            <button onClick={() => setActiveTab('home')} className={`flex flex-col items-center gap-2 p-4 rounded-2xl transition-all ${activeTab === 'home' ? 'bg-tea-50 text-tea-700' : 'text-gray-400'}`}>
               <span className="text-xl">🏠</span>
               <span className="text-[10px] font-bold uppercase tracking-widest">Início</span>
            </button>
            <button onClick={() => setActiveTab('agenda')} className={`flex flex-col items-center gap-2 p-4 rounded-2xl transition-all ${activeTab === 'agenda' ? 'bg-tea-50 text-tea-700' : 'text-gray-400'}`}>
               <span className="text-xl">🗓️</span>
               <span className="text-[10px] font-bold uppercase tracking-widest">Agenda</span>
            </button>
            <button onClick={() => setActiveTab('cuidados')} className={`flex flex-col items-center gap-2 p-4 rounded-2xl transition-all ${activeTab === 'cuidados' ? 'bg-tea-50 text-tea-700' : 'text-gray-400'}`}>
