import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, TeamMember } from './types';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants';
import Navbar from './components/Navbar';
import CustomerHome from './components/CustomerHome';
import CustomerRegister from './components/CustomerRegister';
import CustomerLoginView from './components/CustomerLoginView';
import CustomerProfile from './components/CustomerProfile';
import AdminDashboard from './components/AdminDashboard';
import AdminCalendar from './components/AdminCalendar';
import AdminFinance from './components/AdminFinance';
import AdminClients from './components/AdminClients';
import AdminConfirmations from './components/AdminConfirmations';
import AdminSettingsView from './components/AdminSettingsView';
import AdminVeo from './components/AdminVeo';
import AdminLogin from './components/AdminLogin';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>(INITIAL_SERVICES);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  // Carregar dados
  useEffect(() => {
    const saved = localStorage.getItem('moria_state_v2');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.settings) setSettings(parsed.settings);
        if (parsed.services) setServices(parsed.services);
        if (parsed.customers) setCustomers(parsed.customers);
        if (parsed.bookings) setBookings(parsed.bookings);
        if (parsed.transactions) setTransactions(parsed.transactions);
      } catch (e) { console.error(e); }
    }
    const savedUser = localStorage.getItem('moria_current_user');
    if (savedUser) setCurrentUser(JSON.parse(savedUser));
    if (localStorage.getItem('moria_admin_auth') === 'true') setIsAdminAuthenticated(true);
  }, []);

  // Salvar dados
  useEffect(() => {
    const state = { settings, services, customers, bookings, transactions };
    localStorage.setItem('moria_state_v2', JSON.stringify(state));
    if (currentUser) localStorage.setItem('moria_current_user', JSON.stringify(currentUser));
    else localStorage.removeItem('moria_current_user');
    localStorage.setItem('moria_admin_auth', isAdminAuthenticated.toString());
  }, [settings, services, customers, bookings, transactions, currentUser, isAdminAuthenticated]);

  const handleBulkImport = (data: any) => {
    if (data.settings) setSettings(data.settings);
    if (data.services) setServices(data.services);
    if (data.customers) setCustomers(data.customers);
    if (data.bookings) setBookings(data.bookings);
    if (data.transactions) setTransactions(data.transactions);
    alert("Backup restaurado!");
  };

  const handleAdminLogin = (password: string) => {
    if (password === '460206') {
      setIsAdminAuthenticated(true);
      setCurrentView(View.ADMIN_DASHBOARD);
    }
  };

  const toggleAdminMode = () => {
    if (isAdmin) {
      setIsAdmin(false);
      setCurrentView(View.CUSTOMER_HOME);
    } else {
      setIsAdmin(true);
      setCurrentView(isAdminAuthenticated ? View.ADMIN_DASHBOARD : View.ADMIN_LOGIN);
    }
  };

  const handleUpdateBookingStatus = (id: string, status: any) => {
    setBookings(prev => prev.map(b => b.id === id ? { ...b, status } : b));
  };

  const handleDeleteCustomer = (id: string) => {
    if (confirm("Excluir cliente?")) setCustomers(prev => prev.filter(c => c.id !== id));
  };

  const handleUpdateCustomer = (id: string, data: any) => {
    setCustomers(prev => prev.map(c => c.id === id ? { ...c, ...data } : c));
  };

  const renderView = () => {
    if (isAdmin) {
      if (!isAdminAuthenticated) return <AdminLogin onLogin={handleAdminLogin} onBack={() => setIsAdmin(false)} />;
      switch (currentView) {
        case View.ADMIN_DASHBOARD: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} setBookings={setBookings} services={services} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} setTransactions={setTransactions} customers={customers} services={services} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={handleDeleteCustomer} onUpdate={handleUpdateCustomer} />;
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} onUpdateStatus={handleUpdateBookingStatus} />;
        case View.ADMIN_VEO: return <AdminVeo />;
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} setSettings={setSettings} services={services} setServices={setServices} customers={customers} bookings={bookings} transactions={transactions} onImport={handleBulkImport} />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} />;
      }
    }

    switch (currentView) {
      case View.CUSTOMER_REGISTER: return <CustomerRegister onRegister={(n,w,c,p,not) => { /* logic */ }} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_LOGIN: return <CustomerLoginView onLogin={() => {}} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_PROFILE: return currentUser ? <CustomerProfile customer={currentUser} transactions={transactions} bookings={bookings} onUpdateNotification={() => {}} onBack={() => setCurrentView(View.CUSTOMER_HOME)} /> : <CustomerLoginView onLogin={() => {}} onRegisterClick={() => {}} onBack={() => {}} />;
      default: return <CustomerHome settings={settings} services={services} onBook={() => {}} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} currentUser={currentUser} />;
    }
  };

  return (
    <div className="min-h-screen bg-white">
      <Navbar 
        view={currentView} setView={setCurrentView} 
        isAdmin={isAdmin} onToggleAdmin={toggleAdminMode} 
        salonName={settings.name} logo={settings.logo} 
        currentUser={currentUser} onLogout={() => setCurrentUser(null)} 
        onAdminLogout={() => { setIsAdminAuthenticated(false); setIsAdmin(false); }}
        isAdminAuthenticated={isAdminAuthenticated}
        pendingBookingsCount={bookings.filter(b => b.status === 'pending').length}
      />
      <main className="max-w-7xl mx-auto px-4 py-8">
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, TeamMember } from './types';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants';
import Navbar from './components/Navbar';
import CustomerHome from './components/CustomerHome';
import CustomerRegister from './components/CustomerRegister';
import CustomerLoginView from './components/CustomerLoginView';
import CustomerProfile from './components/CustomerProfile';
import AdminDashboard from './components/AdminDashboard';
import AdminCalendar from './components/AdminCalendar';
import AdminFinance from './components/AdminFinance';
import AdminClients from './components/AdminClients';
import AdminConfirmations from './components/AdminConfirmations';
import AdminSettingsView from './components/AdminSettingsView';
import AdminVeo from './components/AdminVeo';
import AdminLogin from './components/AdminLogin';

const STORAGE_KEY = 'moria_database_v4';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);

  // Estados Principais
  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>(INITIAL_SERVICES);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  // 1. Carregamento Inicial (Restore)
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.settings) setSettings(parsed.settings);
        if (parsed.services) setServices(parsed.services);
        if (parsed.customers) setCustomers(parsed.customers);
        if (parsed.bookings) setBookings(parsed.bookings);
        if (parsed.transactions) setTransactions(parsed.transactions);
      } catch (e) {
        console.error("Erro ao restaurar banco de dados local:", e);
      }
    }

    const savedUser = localStorage.getItem('moria_session_user');
    if (savedUser) setCurrentUser(JSON.parse(savedUser));

    if (localStorage.getItem('moria_admin_session') === 'true') {
      setIsAdminAuthenticated(true);
    }
  }, []);

  // 2. Persistência Automática
  useEffect(() => {
    const stateToSave = { settings, services, customers, bookings, transactions };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(stateToSave));

    if (currentUser) {
      localStorage.setItem('moria_session_user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('moria_session_user');
    }

    localStorage.setItem('moria_admin_session', isAdminAuthenticated.toString());
  }, [settings, services, customers, bookings, transactions, currentUser, isAdminAuthenticated]);

  // Handlers
  const handleBulkImport = (data: any) => {
    if (!data || typeof data !== 'object') return;
    if (data.settings) setSettings(data.settings);
    if (data.services) setServices(data.services);
    if (data.customers) setCustomers(data.customers);
    if (data.bookings) setBookings(data.bookings);
    if (data.transactions) setTransactions(data.transactions);
    alert("Backup completo restaurado com sucesso! Todos os clientes, senhas e configurações foram atualizados.");
  };

  const handleRegister = (name: string, whatsapp: string, cpf: string, password: string, receivesNotifications: boolean) => {
    if (customers.find(c => c.cpf === cpf)) {
      alert("Este CPF já possui um cadastro no Studio Moriá.");
      return;
    }

    const newCustomer: Customer = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      whatsapp,
      cpf,
      password, // Senha incluída no objeto para backup
      receivesNotifications,
      agreedToTerms: true,
      history: []
    };

    setCustomers(prev => [...prev, newCustomer]);
    setCurrentUser(newCustomer);
    setCurrentView(View.CUSTOMER_HOME);
    alert(`Bem-vinda, ${name}! Seu cadastro foi realizado com sucesso.`);
  };

  const handleLogin = (cpf: string, pass: string) => {
    const user = customers.find(c => c.cpf === cpf && c.password === pass);
    if (user) {
      setCurrentUser(user);
      setCurrentView(View.CUSTOMER_HOME);
    } else {
      alert("CPF ou Senha incorretos. Caso tenha esquecido, entre em contato com o Studio.");
    }
  };

  const handleAdminLogin = (password: string) => {
    if (password === '460206') {
      setIsAdminAuthenticated(true);
      setCurrentView(View.ADMIN_DASHBOARD);
    }
  };

  const toggleAdminMode = () => {
    if (isAdmin) {
      setIsAdmin(false);
      setCurrentView(View.CUSTOMER_HOME);
    } else {
      setIsAdmin(true);
      setCurrentView(isAdminAuthenticated ? View.ADMIN_DASHBOARD : View.ADMIN_LOGIN);
    }
  };

  const handleUpdateBookingStatus = (id: string, status: any) => {
    setBookings(prev => prev.map(b => b.id === id ? { ...b, status } : b));
  };

  const handleDeleteCustomer = (id: string) => {
    if (confirm("Excluir cliente permanentemente?")) {
      setCustomers(prev => prev.filter(c => c.id !== id));
    }
  };

  const handleUpdateCustomer = (id: string, data: Partial<Customer>) => {
    setCustomers(prev => prev.map(c => c.id === id ? { ...c, ...data } : c));
  };

  const renderView = () => {
    if (isAdmin) {
      if (!isAdminAuthenticated) return <AdminLogin onLogin={handleAdminLogin} onBack={() => setIsAdmin(false)} />;
      switch (currentView) {
        case View.ADMIN_DASHBOARD: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} setBookings={setBookings} services={services} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} setTransactions={setTransactions} customers={customers} services={services} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={handleDeleteCustomer} onUpdate={handleUpdateCustomer} />;
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} onUpdateStatus={handleUpdateBookingStatus} />;
        case View.ADMIN_VEO: return <AdminVeo />;
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} setSettings={setSettings} services={services} setServices={setServices} customers={customers} bookings={bookings} transactions={transactions} onImport={handleBulkImport} />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} />;
      }
    }

    switch (currentView) {
      case View.CUSTOMER_REGISTER: 
        return <CustomerRegister onRegister={handleRegister} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_LOGIN: 
        return <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_PROFILE: 
        return currentUser ? <CustomerProfile customer={currentUser} transactions={transactions} bookings={bookings} onUpdateNotification={(val) => handleUpdateCustomer(currentUser.id, { receivesNotifications: val })} onBack={() => setCurrentView(View.CUSTOMER_HOME)} /> : <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      default: 
        return <CustomerHome settings={settings} services={services} onBook={(sid, dt, mid) => {
          if(!currentUser) { setCurrentView(View.CUSTOMER_LOGIN); return; }
          const service = services.find(s => s.id === sid);
          const newBooking: Booking = {
            id: Math.random().toString(36).substr(2, 9),
            customerId: currentUser.id,
            customerName: currentUser.name,
            serviceId: sid,
            serviceName: service?.name || '',
            dateTime: dt,
            status: 'pending',
            teamMemberId: mid,
            teamMemberName: settings.teamMembers.find(m => m.id === mid)?.name
          };
          setBookings(prev => [...prev, newBooking]);
          alert("Solicitação de agendamento enviada! Aguarde confirmação.");
        }} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} currentUser={currentUser} />;
    }
  };

  return (
    <div className="min-h-screen bg-white">
      <Navbar 
        view={currentView} setView={setCurrentView} 
        isAdmin={isAdmin} onToggleAdmin={toggleAdminMode} 
        salonName={settings.name} logo={settings.logo} 
        currentUser={currentUser} onLogout={() => setCurrentUser(null)} 
        onAdminLogout={() => { setIsAdminAuthenticated(false); setIsAdmin(false); setCurrentView(View.CUSTOMER_HOME); }}
        isAdminAuthenticated={isAdminAuthenticated}
        pendingBookingsCount={bookings.filter(b => b.status === 'pending').length}
      />
      <main className="max-w-7xl mx-auto px-4 py-8">
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { SalonSettings, Service, TeamMember, Customer, Booking, Transaction } from '../types';

interface AdminSettingsViewProps {
  settings: SalonSettings;
  setSettings: (s: SalonSettings) => void;
  services: Service[];
  setServices: (s: Service[]) => void;
  customers: Customer[];
  bookings: Booking[];
  transactions: Transaction[];
  onImport: (data: any) => void;
}

const AdminSettingsView: React.FC<AdminSettingsViewProps> = ({ 
  settings, 
  setSettings, 
  services = [], 
  setServices,
  customers = [],
  bookings = [],
  transactions = [],
  onImport
}) => {
  const [newService, setNewService] = useState({ name: '', price: 0, duration: 30, description: '', isVisible: true });
  const [newMemberName, setNewMemberName] = useState('');
  const [isDeploying, setIsDeploying] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const teamMembers = settings?.teamMembers || [];

  const handleDeploy = () => {
    setIsDeploying(true);
    setTimeout(() => {
      setIsDeploying(false);
      alert("Alterações publicadas com sucesso no Studio Moriá Estética! 🚀\nSeu site já está atualizado para as clientes.");
    }, 1500);
  };

  const updateSetting = (key: string, value: any) => {
    setSettings({ ...settings, [key]: value });
  };

  const addService = () => {
    if (newService.name && newService.price > 0) {
      setServices([...services, { ...newService, id: Math.random().toString(36).substr(2, 9) }]);
      setNewService({ name: '', price: 0, duration: 30, description: '', isVisible: true });
    }
  };

  const addTeamMember = () => {
    if (newMemberName.trim()) {
      const newMember: TeamMember = {
        id: Math.random().toString(36).substr(2, 9),
        name: newMemberName.trim(),
        assignedServiceIds: []
      };
      updateSetting('teamMembers', [...teamMembers, newMember]);
      setNewMemberName('');
    }
  };

  const removeTeamMember = (id: string) => {
    if (confirm("Deseja remover esta colaboradora?")) {
      updateSetting('teamMembers', teamMembers.filter(m => m.id !== id));
    }
  };

  const toggleServiceToMember = (memberId: string, serviceId: string) => {
    const updatedMembers = teamMembers.map(m => {
      if (m.id === memberId) {
        const hasService = m.assignedServiceIds.includes(serviceId);
        return {
          ...m,
          assignedServiceIds: hasService 
            ? m.assignedServiceIds.filter(id => id !== serviceId)
            : [...m.assignedServiceIds, serviceId]
        };
      }
      return m;
    });
    updateSetting('teamMembers', updatedMembers);
  };

  const toggleServiceVisibility = (id: string) => {
    setServices(services.map(s => s.id === id ? { ...s, isVisible: !s.isVisible } : s));
  };

  const exportBackup = () => {
    // Garantimos que todos os dados essenciais (incluindo clientes com senhas) estão no objeto
    const dataToExport = { 
      settings, 
      services, 
      customers, // Contém senhas e histórico
      bookings, 
      transactions, 
      exportDate: new Date().toISOString(),
      version: "4.0"
    };

    const blob = new Blob([JSON.stringify(dataToExport, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `studio_moria_TOTAL_BACKUP_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!confirm("A restauração de backup substituirá todos os dados atuais. Deseja continuar?")) return;

      const reader = new FileReader();
      reader.onload = (event) => {
        try {
          const json = JSON.parse(event.target?.result as string);
          onImport(json);
        } catch (err) {
          alert("Erro crítico: O arquivo de backup selecionado é inválido.");
        }
      };
      reader.readAsText(file);
    }
  };

  return (
    <div className="space-y-12 pb-32 animate-fade-in">
      {/* Header com Deploy */}
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-8 rounded-[2.5rem] shadow-sm border border-gray-100 gap-6">
        <div>
          <h2 className="text-3xl font-serif text-tea-950 font-bold">Gestão Studio Moriá</h2>
          <p className="text-gray-500 font-light">Controle administrativo e identidade visual.</p>
        </div>
        <button 
          onClick={handleDeploy}
          disabled={isDeploying}
          className={`group flex items-center gap-3 px-10 py-5 rounded-2xl font-bold text-lg shadow-2xl transition-all active:scale-95 ${isDeploying ? 'bg-gray-100 text-gray-400' : 'bg-tea-800 text-white hover:bg-tea-900 shadow-tea-100'}`}
        >
          {isDeploying ? (
            <span className="w-6 h-6 border-4 border-gray-300 border-t-transparent rounded-full animate-spin"></span>
          ) : (
            <>
              <span className="text-2xl group-hover:animate-bounce">🚀</span>
              PUBLICAR SITE
            </>
          )}
        </button>
      </div>

      {/* Backup TOTAL */}
      <section className="bg-gradient-to-br from-tea-800 to-tea-950 p-10 rounded-[3rem] shadow-2xl text-white relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -mr-32 -mt-32"></div>
        <div className="relative z-10">
          <h3 className="text-2xl font-serif mb-4 flex items-center gap-3">🛡️ Backup Total do Sistema</h3>
          <p className="text-tea-100 mb-8 max-w-xl font-light">Use esta ferramenta para baixar um arquivo contendo todos os clientes, senhas, agendamentos e histórico financeiro. **Recomendado após qualquer alteração.**</p>
          <div className="flex flex-wrap gap-4">
            <button onClick={exportBackup} className="bg-white text-tea-950 px-8 py-4 rounded-xl font-bold hover:bg-tea-50 transition-all shadow-xl">📥 Baixar Base Completa</button>
            <button onClick={() => fileInputRef.current?.click()} className="bg-tea-700 border border-white/20 text-white px-8 py-4 rounded-xl font-bold hover:bg-tea-600 transition-all">📤 Restaurar de Arquivo</button>
            <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={handleFileImport} />
          </div>
        </div>
      </section>

      {/* Profissionais */}
      <section className="bg-white p-10 rounded-[3rem] shadow-sm border border-gray-100">
        <h3 className="text-2xl font-serif text-tea-900 mb-8 flex items-center gap-3">👥 Equipe do Studio</h3>
        <div className="flex flex-col md:flex-row gap-4 mb-10">
          <input 
            placeholder="Nome da profissional..." 
            className="flex-grow p-5 border-2 border-gray-50 bg-gray-50 rounded-2xl outline-none focus:border-tea-200 focus:bg-white"
            value={newMemberName}
            onChange={(e) => setNewMemberName(e.target.value)}
          />
          <button onClick={addTeamMember} className="bg-tea-600 text-white px-10 py-5 rounded-2xl font-bold hover:bg-tea-700 shadow-lg">ADICIONAR</button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {teamMembers.map(member => (
            <div key={member.id} className="p-8 border-2 border-gray-50 rounded-[2.5rem] hover:border-tea-100 transition-all bg-gray-50/30">
              <div className="flex justify-between items-center mb-6">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-tea-800 rounded-2xl flex items-center justify-center text-white font-bold">{member.name.charAt(0)}</div>
                  <span className="font-bold text-gray-800 text-lg">{member.name}</span>
                </div>
                <button onClick={() => removeTeamMember(member.id)} className="text-red-300 hover:text-red-500 text-sm font-bold underline">Remover</button>
              </div>
              <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-4">Procedimentos Autorizados:</p>
              <div className="flex flex-wrap gap-2">
                {services.map(s => {
                  const isAssigned = member.assignedServiceIds?.includes(s.id);
                  return (
                    <button 
                      key={s.id}
                      onClick={() => toggleServiceToMember(member.id, s.id)}
                      className={`px-3 py-2 rounded-xl text-[10px] font-bold border-2 transition-all ${isAssigned ? 'bg-tea-600 border-tea-600 text-white' : 'bg-white border-gray-100 text-gray-300 hover:border-tea-200'}`}
                    >
                      {s.name}
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Catálogo */}
      <section className="bg-white p-10 rounded-[3rem] shadow-sm border border-gray-100">
        <h3 className="text-2xl font-serif text-tea-900 mb-8 flex items-center gap-3">📋 Catálogo de Serviços</h3>
        <div className="bg-tea-50 p-8 rounded-[2rem] border border-tea-100 mb-10">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6">
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-tea-700 uppercase ml-2">Nome</label>
              <input placeholder="Ex: Microblanding" className="w-full p-4 rounded-xl outline-none border-2 border-white bg-white focus:border-tea-200" value={newService.name} onChange={e => setNewService({...newService, name: e.target.value})} />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-tea-700 uppercase ml-2">Preço R$</label>
              <input type="number" placeholder="0,00" className="w-full p-4 rounded-xl outline-none border-2 border-white bg-white focus:border-tea-200" value={newService.price || ''} onChange={e => setNewService({...newService, price: parseFloat(e.target.value)})} />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-tea-700 uppercase ml-2">Duração (min)</label>
              <input type="number" placeholder="60" className="w-full p-4 rounded-xl outline-none border-2 border-white bg-white focus:border-tea-200" value={newService.duration || ''} onChange={e => setNewService({...newService, duration: parseInt(e.target.value)})} />
            </div>
          </div>
          <button onClick={addService} className="w-full bg-tea-800 text-white py-5 rounded-xl font-bold shadow-lg hover:bg-tea-900 transition-all uppercase tracking-widest text-sm">Adicionar ao Catálogo</button>
        </div>

        <div className="grid grid-cols-1 gap-4">
          {services.map(s => (
            <div key={s.id} className="p-6 border-2 border-gray-50 rounded-3xl flex justify-between items-center group hover:bg-tea-50/20 hover:border-tea-100 transition-all">
              <div>
                <p className="font-bold text-tea-950 text-lg">{s.name}</p>
                <p className="text-xs text-gray-400 font-medium">R$ {s.price.toFixed(2)} • {s.duration} minutos</p>
              </div>
              <div className="flex gap-4">
                <button onClick={() => toggleServiceVisibility(s.id)} className={`text-xs font-bold px-4 py-2 rounded-full border ${s.isVisible ? 'text-tea-600 border-tea-100 bg-white' : 'text-gray-400 border-gray-100 bg-gray-50'}`}>
                  {s.isVisible ? '👁️ No Site' : '🙈 Oculto'}
                </button>
                <button onClick={() => setServices(services.filter(x => x.id !== s.id))} className="text-xs font-bold text-red-300 hover:text-red-500 hover:underline">Excluir</button>
              </div>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
};

export default AdminSettingsView;

import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, TeamMember } from './types';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants';
import Navbar from './components/Navbar';
import CustomerHome from './components/CustomerHome';
import CustomerRegister from './components/CustomerRegister';
import CustomerLoginView from './components/CustomerLoginView';
import CustomerProfile from './components/CustomerProfile';
import AdminDashboard from './components/AdminDashboard';
import AdminCalendar from './components/AdminCalendar';
import AdminFinance from './components/AdminFinance';
import AdminClients from './components/AdminClients';
import AdminConfirmations from './components/AdminConfirmations';
import AdminSettingsView from './components/AdminSettingsView';
import AdminVeo from './components/AdminVeo';
import AdminLogin from './components/AdminLogin';

const STORAGE_KEY = 'moria_db_v5';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);

  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>(INITIAL_SERVICES);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  // Carregar dados salvos
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.settings) setSettings(parsed.settings);
        if (parsed.services) setServices(parsed.services);
        if (parsed.customers) setCustomers(parsed.customers);
        if (parsed.bookings) setBookings(parsed.bookings);
        if (parsed.transactions) setTransactions(parsed.transactions);
      } catch (e) {
        console.error("Erro ao carregar dados locais", e);
      }
    }

    const savedUser = localStorage.getItem('moria_user_session');
    if (savedUser) setCurrentUser(JSON.parse(savedUser));
    if (localStorage.getItem('moria_admin_session') === 'true') setIsAdminAuthenticated(true);
  }, []);

  // Salvar dados automaticamente
  useEffect(() => {
    const data = { settings, services, customers, bookings, transactions };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    if (currentUser) localStorage.setItem('moria_user_session', JSON.stringify(currentUser));
    else localStorage.removeItem('moria_user_session');
    localStorage.setItem('moria_admin_session', isAdminAuthenticated.toString());
  }, [settings, services, customers, bookings, transactions, currentUser, isAdminAuthenticated]);

  const handleBulkImport = (data: any) => {
    if (data.settings) setSettings(data.settings);
    if (data.services) setServices(data.services);
    if (data.customers) setCustomers(data.customers);
    if (data.bookings) setBookings(data.bookings);
    if (data.transactions) setTransactions(data.transactions);
    alert("Sincronização realizada! Este aparelho agora possui os dados atualizados.");
  };

  const handleRegister = (name: string, whatsapp: string, cpf: string, password: string, receivesNotifications: boolean) => {
    if (customers.find(c => c.cpf === cpf)) {
      alert("Este CPF já está cadastrado.");
      return;
    }

    const newCustomer: Customer = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      whatsapp,
      cpf,
      password,
      receivesNotifications,
      agreedToTerms: true,
      history: []
    };

    setCustomers(prev => [...prev, newCustomer]);
    setCurrentUser(newCustomer);
    setCurrentView(View.CUSTOMER_HOME);
    alert("Cadastro realizado com sucesso! Bem-vinda ao Studio Moriá.");
  };

  const handleLogin = (cpf: string, pass: string) => {
    const user = customers.find(c => c.cpf === cpf && c.password === pass);
    if (user) {
      setCurrentUser(user);
      setCurrentView(View.CUSTOMER_HOME);
    } else {
      alert("Acesso negado. Verifique os dados.");
    }
  };

  const renderView = () => {
    if (isAdmin) {
      if (!isAdminAuthenticated) return <AdminLogin onLogin={() => { setIsAdminAuthenticated(true); setCurrentView(View.ADMIN_DASHBOARD); }} onBack={() => setIsAdmin(false)} />;
      switch (currentView) {
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} setSettings={setSettings} services={services} setServices={setServices} customers={customers} bookings={bookings} transactions={transactions} onImport={handleBulkImport} />;
        case View.ADMIN_DASHBOARD: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} setBookings={setBookings} services={services} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} setTransactions={setTransactions} customers={customers} services={services} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={(id) => setCustomers(prev => prev.filter(c => c.id !== id))} onUpdate={(id, data) => setCustomers(prev => prev.map(c => c.id === id ? {...c, ...data} : c))} />;
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} onUpdateStatus={(id, status) => setBookings(prev => prev.map(b => b.id === id ? {...b, status} : b))} />;
        case View.ADMIN_VEO: return <AdminVeo />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} />;
      }
    }

    switch (currentView) {
      case View.CUSTOMER_REGISTER: return <CustomerRegister onRegister={handleRegister} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_LOGIN: return <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_PROFILE: return currentUser ? <CustomerProfile customer={currentUser} transactions={transactions} bookings={bookings} onUpdateNotification={(val) => setCustomers(prev => prev.map(c => c.id === currentUser.id ? {...c, receivesNotifications: val} : c))} onBack={() => setCurrentView(View.CUSTOMER_HOME)} /> : <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      default: return <CustomerHome settings={settings} services={services} onBook={(sid, dt, mid) => {
        if (!currentUser) { setCurrentView(View.CUSTOMER_LOGIN); return; }
        const srv = services.find(s => s.id === sid);
        setBookings(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), customerId: currentUser.id, customerName: currentUser.name, serviceId: sid, serviceName: srv?.name || '', dateTime: dt, status: 'pending', teamMemberId: mid, teamMemberName: settings.teamMembers.find(m => m.id === mid)?.name }]);
        alert("Agendamento solicitado!");
      }} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} currentUser={currentUser} />;
    }
  };

  return (
    <div className="min-h-screen bg-white">
      <Navbar 
        view={currentView} setView={setCurrentView} 
        isAdmin={isAdmin} onToggleAdmin={() => { setIsAdmin(!isAdmin); if(!isAdminAuthenticated) setCurrentView(View.ADMIN_LOGIN); }} 
        salonName={settings.name} logo={settings.logo} 
        currentUser={currentUser} onLogout={() => setCurrentUser(null)} 
        onAdminLogout={() => { setIsAdminAuthenticated(false); setIsAdmin(false); setCurrentView(View.CUSTOMER_HOME); }}
        isAdminAuthenticated={isAdminAuthenticated}
        pendingBookingsCount={bookings.filter(b => b.status === 'pending').length}
      />
      <main className="max-w-7xl mx-auto px-4 py-8">{renderView()}</main>
    </div>
  );
};

export default App;

