import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, TeamMember, WaitlistEntry } from './types';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants';
import Navbar from './components/Navbar';
import CustomerHome from './components/CustomerHome';
import CustomerRegister from './components/CustomerRegister';
import CustomerLoginView from './components/CustomerLoginView';
import CustomerProfile from './components/CustomerProfile';
import AdminDashboard from './components/AdminDashboard';
import AdminCalendar from './components/AdminCalendar';
import AdminFinance from './components/AdminFinance';
import AdminClients from './components/AdminClients';
import AdminConfirmations from './components/AdminConfirmations';
import AdminSettingsView from './components/AdminSettingsView';
import AdminVeo from './components/AdminVeo';
import AdminLogin from './components/AdminLogin';

const STORAGE_KEY = 'moria_db_v6';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);

  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>(INITIAL_SERVICES);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [waitlist, setWaitlist] = useState<WaitlistEntry[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.settings) setSettings(parsed.settings);
        if (parsed.services) setServices(parsed.services);
        if (parsed.customers) setCustomers(parsed.customers);
        if (parsed.bookings) setBookings(parsed.bookings);
        if (parsed.transactions) setTransactions(parsed.transactions);
        if (parsed.waitlist) setWaitlist(parsed.waitlist);
      } catch (e) {
        console.error("Erro ao carregar dados locais", e);
      }
    }
    const savedUser = localStorage.getItem('moria_user_session');
    if (savedUser) setCurrentUser(JSON.parse(savedUser));
    if (localStorage.getItem('moria_admin_session') === 'true') setIsAdminAuthenticated(true);
  }, []);

  useEffect(() => {
    const data = { settings, services, customers, bookings, transactions, waitlist };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    if (currentUser) localStorage.setItem('moria_user_session', JSON.stringify(currentUser));
    else localStorage.removeItem('moria_user_session');
    localStorage.setItem('moria_admin_session', isAdminAuthenticated.toString());
  }, [settings, services, customers, bookings, transactions, waitlist, currentUser, isAdminAuthenticated]);

  const handleBulkImport = (data: any) => {
    if (data.settings) setSettings(data.settings);
    if (data.services) setServices(data.services);
    if (data.customers) setCustomers(data.customers);
    if (data.bookings) setBookings(data.bookings);
    if (data.transactions) setTransactions(data.transactions);
    if (data.waitlist) setWaitlist(data.waitlist);
    alert("Sincronização realizada!");
  };

  const handleRegister = (name: string, whatsapp: string, cpf: string, password: string, receivesNotifications: boolean) => {
    const newCustomer: Customer = { id: Math.random().toString(36).substr(2, 9), name, whatsapp, cpf, password, receivesNotifications, agreedToTerms: true, history: [] };
    setCustomers(prev => [...prev, newCustomer]);
    setCurrentUser(newCustomer);
    setCurrentView(View.CUSTOMER_HOME);
  };

  const handleLogin = (cpf: string, pass: string) => {
    const user = customers.find(c => c.cpf === cpf && c.password === pass);
    if (user) { setCurrentUser(user); setCurrentView(View.CUSTOMER_HOME); }
    else alert("Dados incorretos.");
  };

  const handleAddToWaitlist = (serviceId: string, date: string) => {
    if (!currentUser) return;
    const service = services.find(s => s.id === serviceId);
    const entry: WaitlistEntry = {
      id: Math.random().toString(36).substr(2, 9),
      customerId: currentUser.id,
      customerName: currentUser.name,
      customerWhatsapp: currentUser.whatsapp,
      serviceId,
      serviceName: service?.name || '',
      preferredDate: date,
      createdAt: new Date().toISOString()
    };
    setWaitlist(prev => [...prev, entry]);
    alert("Você foi adicionada à lista de espera! Avisaremos pelo WhatsApp se houver uma desistência.");
  };

  const renderView = () => {
    if (isAdmin) {
      if (!isAdminAuthenticated) return <AdminLogin onLogin={() => { setIsAdminAuthenticated(true); setCurrentView(View.ADMIN_DASHBOARD); }} onBack={() => setIsAdmin(false)} />;
      switch (currentView) {
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} setSettings={setSettings} services={services} setServices={setServices} customers={customers} bookings={bookings} transactions={transactions} onImport={handleBulkImport} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} setBookings={setBookings} services={services} teamMembers={settings.teamMembers} />;
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} onUpdateStatus={(id, status) => setBookings(prev => prev.map(b => b.id === id ? {...b, status} : b))} waitlist={waitlist} onRemoveWaitlist={(id) => setWaitlist(prev => prev.filter(w => w.id !== id))} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={(id) => setCustomers(prev => prev.filter(c => c.id !== id))} onUpdate={(id, data) => setCustomers(prev => prev.map(c => c.id === id ? {...c, ...data} : c))} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} setTransactions={setTransactions} customers={customers} services={services} />;
        case View.ADMIN_VEO: return <AdminVeo />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} />;
      }
    }

    switch (currentView) {
      case View.CUSTOMER_REGISTER: return <CustomerRegister onRegister={handleRegister} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_LOGIN: return <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_PROFILE: return currentUser ? <CustomerProfile customer={currentUser} transactions={transactions} bookings={bookings} onUpdateNotification={(val) => setCustomers(prev => prev.map(c => c.id === currentUser.id ? {...c, receivesNotifications: val} : c))} onBack={() => setCurrentView(View.CUSTOMER_HOME)} /> : <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      default: return <CustomerHome settings={settings} services={services} bookings={bookings} onBook={(sid, dt, mid) => {
        if (!currentUser) { setCurrentView(View.CUSTOMER_LOGIN); return; }
        const srv = services.find(s => s.id === sid);
        setBookings(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), customerId: currentUser.id, customerName: currentUser.name, serviceId: sid, serviceName: srv?.name || '', dateTime: dt, status: 'pending', teamMemberId: mid, teamMemberName: settings.teamMembers.find(m => m.id === mid)?.name }]);
        alert("Solicitação enviada!");
      }} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onAddToWaitlist={handleAddToWaitlist} currentUser={currentUser} />;
    }
  };

  return (
    <div className="min-h-screen bg-white">
      <Navbar view={currentView} setView={setCurrentView} isAdmin={isAdmin} onToggleAdmin={() => { setIsAdmin(!isAdmin); if(!isAdminAuthenticated) setCurrentView(View.ADMIN_LOGIN); }} salonName={settings.name} logo={settings.logo} currentUser={currentUser} onLogout={() => setCurrentUser(null)} onAdminLogout={() => { setIsAdminAuthenticated(false); setIsAdmin(false); setCurrentView(View.CUSTOMER_HOME); }} isAdminAuthenticated={isAdminAuthenticated} pendingBookingsCount={bookings.filter(b => b.status === 'pending').length} />
      <main className="max-w-7xl mx-auto px-4 py-8">{renderView()}</main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { SalonSettings, Service, Customer, Booking } from '../types';

interface CustomerHomeProps {
  settings: SalonSettings;
  services: Service[];
  bookings: Booking[];
  onBook: (serviceId: string, dateTime: string, teamMemberId?: string) => void;
  onRegisterClick: () => void;
  onAddToWaitlist: (serviceId: string, date: string) => void;
  currentUser: Customer | null;
}

const CustomerHome: React.FC<CustomerHomeProps> = ({ settings, services, bookings, onBook, onRegisterClick, onAddToWaitlist, currentUser }) => {
  const [formData, setFormData] = useState({ name: '', whatsapp: '', message: '' });
  const [bookingModal, setBookingModal] = useState<{ open: boolean; service: Service | null; step: 1 | 2 }>({ open: false, service: null, step: 1 });
  const [selectedProfessional, setSelectedProfessional] = useState<string>('');
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedTime, setSelectedTime] = useState<string>('');

  const hours = Array.from({ length: 22 }, (_, i) => {
    const h = Math.floor(i / 2) + 8;
    const m = i % 2 === 0 ? '00' : '30';
    return `${h.toString().padStart(2, '0')}:${m}`;
  });

  const confirmBooking = () => {
    if (bookingModal.service && selectedProfessional && selectedTime) {
      const fullDateTime = `${selectedDate} ${selectedTime}`;
      onBook(bookingModal.service.id, fullDateTime, selectedProfessional);
      setBookingModal({ open: false, service: null, step: 1 });
      setSelectedProfessional('');
      setSelectedTime('');
    } else {
      alert("Por favor, selecione um horário.");
    }
  };

  const getAvailableHours = () => {
    return hours.filter(hour => {
      const isOccupied = bookings.some(b => 
        b.teamMemberId === selectedProfessional && 
        b.dateTime === `${selectedDate} ${hour}` &&
        b.status !== 'cancelled'
      );
      return !isOccupied;
    });
  };

  const availableProfessionals = bookingModal.service 
    ? settings.teamMembers.filter(m => m.assignedServiceIds.includes(bookingModal.service!.id))
    : [];

  return (
    <div className="animate-fade-in bg-white">
      {/* Hero */}
      <section className="relative min-h-[70vh] flex flex-col items-center justify-center bg-tea-900 overflow-hidden py-16 px-4">
        <div className="relative z-10 w-full max-w-4xl text-center flex flex-col items-center">
          <img src={settings.logo} className="h-32 md:h-48 mb-12 drop-shadow-2xl" alt="Logo" />
          <h2 className="text-2xl md:text-4xl font-serif text-white/90 mb-12 italic">Beleza que inspira, cuidado que transforma.</h2>
          <div className="flex flex-col sm:flex-row gap-6">
            {!currentUser ? (
              <button onClick={onRegisterClick} className="bg-white text-tea-900 px-12 py-5 rounded-full font-bold shadow-2xl uppercase tracking-widest hover:scale-105 transition-all">Ver Serviços</button>
            ) : (
              <div className="bg-white/10 backdrop-blur-md px-10 py-5 rounded-full border border-white/20 text-white font-bold">Olá, {currentUser.name.split(' ')[0]}!</div>
            )}
            <a href="#procedimentos" className="border-2 border-white/30 text-white px-12 py-5 rounded-full font-bold uppercase tracking-widest hover:bg-white/10 transition-all">Agendar Agora</a>
          </div>
        </div>
      </section>

      {/* Modal Agendamento */}
      {bookingModal.open && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white w-full max-w-lg rounded-[3rem] p-8 shadow-2xl animate-slide-up">
            <h3 className="text-2xl font-serif text-tea-900 mb-4">{bookingModal.step === 1 ? 'Quem irá te atender?' : 'Escolha o melhor horário'}</h3>

            {bookingModal.step === 1 ? (
              <div className="space-y-4 mb-8">
                {availableProfessionals.map(pro => (
                  <button key={pro.id} onClick={() => { setSelectedProfessional(pro.id); setBookingModal({...bookingModal, step: 2}); }} className="w-full p-5 rounded-2xl border-2 border-gray-50 bg-gray-50 hover:border-tea-200 transition-all flex items-center gap-4">
                    <div className="w-10 h-10 rounded-full bg-tea-800 flex items-center justify-center text-white font-bold">{pro.name.charAt(0)}</div>
                    <span className="font-bold text-tea-950">{pro.name}</span>
                  </button>
                ))}
              </div>
            ) : (
              <div className="space-y-6">
                <input type="date" value={selectedDate} onChange={(e) => setSelectedDate(e.target.value)} className="w-full p-4 border-2 border-tea-50 rounded-xl outline-none" min={new Date().toISOString().split('T')[0]} />
                <div className="grid grid-cols-4 gap-2 max-h-48 overflow-y-auto p-2 border border-gray-50 rounded-xl">
                  {getAvailableHours().map(h => (
                    <button key={h} onClick={() => setSelectedTime(h)} className={`p-2 rounded-lg text-xs font-bold transition-all ${selectedTime === h ? 'bg-tea-800 text-white' : 'bg-tea-50 text-tea-700 hover:bg-tea-100'}`}>{h}</button>
                  ))}
                  {getAvailableHours().length === 0 && <p className="col-span-4 text-center py-4 text-gray-400 text-xs">Nenhum horário disponível para este dia.</p>}
                </div>

                <div className="bg-orange-50 p-4 rounded-2xl border border-orange-100">
                  <p className="text-[10px] text-orange-800 font-bold uppercase mb-2">Não achou o horário que queria?</p>
                  <button onClick={() => { onAddToWaitlist(bookingModal.service!.id, selectedDate); setBookingModal({open: false, service: null, step: 1}); }} className="w-full py-2 text-xs font-bold text-orange-600 border-2 border-orange-200 rounded-lg hover:bg-orange-100 transition-all">Me avise se houver desistência</button>
                </div>

                <div className="flex gap-2">
                  <button onClick={() => setBookingModal({...bookingModal, step: 1})} className="flex-1 py-4 text-gray-400 font-bold">Voltar</button>
                  <button onClick={confirmBooking} disabled={!selectedTime} className="flex-[2] bg-tea-800 text-white py-4 rounded-xl font-bold shadow-xl disabled:opacity-50">Confirmar Horário</button>
                </div>
              </div>
            )}
            {bookingModal.step === 1 && <button onClick={() => setBookingModal({open: false, service: null, step: 1})} className="w-full mt-4 text-gray-400 text-sm font-bold">Fechar</button>}
          </div>
        </div>
      )}

      {/* Serviços */}
      <section id="procedimentos" className="max-w-7xl mx-auto px-4 py-24">
        <div className="text-center mb-16">
          <h2 className="text-4xl font-serif text-gray-900 mb-4">Procedimentos</h2>
          <div className="h-1 w-20 bg-tea-600 mx-auto rounded-full"></div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {services.filter(s => s.isVisible).map(service => (
            <div key={service.id} className="bg-gray-50 p-8 rounded-[2.5rem] flex flex-col justify-between border-2 border-transparent hover:border-tea-100 hover:bg-white transition-all group">
              <div>
                <h3 className="text-xl font-serif font-bold text-tea-950 mb-4">{service.name}</h3>
                <p className="text-gray-500 text-sm font-light mb-8 line-clamp-3">{service.description}</p>
                {currentUser && <p className="text-tea-800 font-bold text-xl mb-6">R$ {service.price.toFixed(2)}</p>}
              </div>
              <button onClick={() => { if(!currentUser) onRegisterClick(); else setBookingModal({open: true, service, step: 1}); }} className="w-full py-4 rounded-xl border border-tea-100 text-tea-700 font-bold uppercase tracking-widest text-xs hover:bg-tea-800 hover:text-white transition-all">Agendar Horário</button>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
};

export default CustomerHome;

import React, { useState } from 'react';
import { Booking, Service, TeamMember } from '../types';

interface AdminCalendarProps {
  bookings: Booking[];
  setBookings: React.Dispatch<React.SetStateAction<Booking[]>>;
  services: Service[];
  teamMembers: TeamMember[];
}

const AdminCalendar: React.FC<AdminCalendarProps> = ({ bookings, setBookings, services, teamMembers }) => {
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedPro, setSelectedPro] = useState(teamMembers[0]?.id || '');

  const hours = Array.from({ length: 22 }, (_, i) => {
    const h = Math.floor(i / 2) + 8;
    const m = i % 2 === 0 ? '00' : '30';
    return `${h.toString().padStart(2, '0')}:${m}`;
  });

  const blockSlot = (hour: string) => {
    const dateTime = `${selectedDate} ${hour}`;
    const pro = teamMembers.find(m => m.id === selectedPro);
    const newBlocked: Booking = {
      id: Math.random().toString(36).substr(2, 9),
      customerId: 'admin-block',
      customerName: 'HORÁRIO BLOQUEADO',
      serviceId: 'block',
      serviceName: 'Indisponível (Folga/Pausa)',
      teamMemberId: selectedPro,
      teamMemberName: pro?.name,
      dateTime: dateTime,
      status: 'blocked'
    };
    setBookings(prev => [...prev, newBlocked]);
  };

  const removeBlock = (id: string) => {
    setBookings(prev => prev.filter(b => b.id !== id));
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-6 rounded-[2rem] border border-gray-100 shadow-sm">
        <div className="flex gap-4 items-center">
          <input type="date" value={selectedDate} onChange={(e) => setSelectedDate(e.target.value)} className="p-3 border-2 border-tea-50 rounded-xl outline-none" />
          <select value={selectedPro} onChange={(e) => setSelectedPro(e.target.value)} className="p-3 border-2 border-tea-50 rounded-xl outline-none">
            {teamMembers.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
          </select>
        </div>
        <p className="text-xs font-bold text-tea-600 uppercase tracking-widest">Clique em horários livres para bloquear</p>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border border-gray-100 overflow-hidden divide-y divide-gray-50">
        {hours.map(hour => {
          const booking = bookings.find(b => b.teamMemberId === selectedPro && b.dateTime === `${selectedDate} ${hour}` && b.status !== 'cancelled');
          return (
            <div key={hour} className="flex items-center p-6 hover:bg-gray-50/30 transition-all">
              <div className="w-20 font-serif font-bold text-tea-900 text-lg border-r border-gray-100 pr-4">{hour}</div>
              <div className="flex-grow pl-6">
                {booking ? (
                  <div className={`p-4 rounded-2xl flex justify-between items-center ${booking.status === 'blocked' ? 'bg-gray-100 border-l-4 border-gray-400' : 'bg-tea-50 border-l-4 border-tea-600'}`}>
                    <div>
                      <p className="font-bold text-tea-950 text-sm">{booking.customerName}</p>
                      <p className="text-[10px] text-tea-700 font-bold uppercase">{booking.serviceName}</p>
                    </div>
                    <div className="flex gap-2">
                       {booking.status === 'blocked' ? (
                         <button onClick={() => removeBlock(booking.id)} className="p-2 bg-white rounded-lg text-[10px] font-bold shadow-sm">LIBERAR HORÁRIO</button>
                       ) : (
                         <p className="text-[10px] font-bold text-tea-500 uppercase">Ocupado</p>
                       )}
                    </div>
                  </div>
                ) : (
                  <button onClick={() => blockSlot(hour)} className="w-full text-left py-4 px-6 border-2 border-dashed border-gray-50 rounded-2xl text-gray-300 text-xs italic font-light hover:border-tea-100 hover:text-tea-400 transition-all">
                    Horário Livre • Clique para Bloquear
                  </button>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

