            <img 
              src={settings.logo} 
              className="h-[15rem] md:h-[28rem] lg:h-[38rem] w-auto drop-shadow-[0_45px_80px_rgba(0,0,0,0.5)] object-contain animate-float" 
              alt="Logo Studio Moriá" 
            />
          </div>

          {/* Slogan e Botões elevados (posicionados mais abaixo mas compactos) */}
          <div className="pb-16 md:pb-24 text-center">
