                className="bg-white text-tea-900 px-10 md:px-14 py-5 rounded-full font-bold shadow-2xl uppercase tracking-widest hover:scale-105 hover:bg-tea-50 transition-all text-[11px] md:text-xs"
              >
                Ver Serviços
              </button>

              {/* Botão 2: Agendar Agora */}
