        <div className="relative z-10 w-full max-w-7xl mx-auto flex flex-col items-center -mt-16 md:-mt-24">

          {/* Logotipo centralizado no espaço superior */}
          <div className="mb-6 md:mb-10">
            <img 
              src={settings.logo} 
              className="h-[12rem] md:h-[22rem] lg:h-[32rem] w-auto drop-shadow-[0_45px_100px_rgba(0,0,0,0.6)] object-contain animate-float" 
              alt="Logo Studio Moriá" 
            />
          </div>

          {/* Slogan e Tríade de Botões - Agora mais altos */}
          <div className="text-center">
            <h2 className="text-3xl md:text-5xl lg:text-7xl font-serif text-white mb-8 md:mb-12 italic tracking-tight leading-tight max-w-4xl mx-auto px-4">
              Cuidando do seu bem estar
            </h2>

            <div className="flex flex-col sm:flex-row flex-wrap justify-center gap-4 md:gap-6">
              {/* Botão 1: Ver Serviços */}
              <button 
                onClick={() => scrollToId('procedimentos')} 
                className="bg-white text-tea-900 px-10 md:px-14 py-5 rounded-full font-bold shadow-2xl uppercase tracking-widest hover:scale-105 hover:bg-tea-50 transition-all text-[11px] md:text-xs"
              >
                Ver Serviços
              </button>

              {/* Botão 2: Agendar Agora */}
              <button 
                onClick={() => currentUser ? scrollToId('procedimentos') : onAuthClick()} 
                className="bg-tea-800 text-white border-2 border-tea-700 px-10 md:px-14 py-5 rounded-full font-bold uppercase tracking-widest hover:bg-tea-950 transition-all text-[11px] md:text-xs shadow-xl"
              >
                Agendar Agora
              </button>

              {/* Botão 3: Fale Conosco */}
              <button 
                onClick={() => scrollToId('contato')} 
                className="border-2 border-white/30 text-white px-10 md:px-14 py-5 rounded-full font-bold uppercase tracking-widest hover:bg-white/10 transition-all text-[11px] md:text-xs"
              >
