            </h2>

            {/* Tríade de Botões - Sempre um abaixo do outro */}
            <div className="flex flex-col items-center gap-4 w-full max-w-xs mx-auto">
              {/* Botão 1: Ver Serviços */}
              <button 
                onClick={() => scrollToId('procedimentos')} 
