              >
                <span>Enviar Mensagem via WhatsApp</span>
                <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M12.031 6.172c-3.181 0-5.767 2.586-5.768 5.766-.001 1.298.38 2.27 1.019 3.287l-.539 2.016 2.041-.534c1.019.568 2.126.966 3.283.967 3.18 0 5.767-2.587 5.768-5.766.001-3.18-2.586-5.767-5.766-5.767zm3.336 8.3c-.145.412-.731.762-1.209.809-.434.043-.913.064-2.142-.444-1.648-.678-2.675-2.333-2.756-2.44-.083-.109-.667-.883-.667-1.685 0-.802.417-1.196.565-1.353.148-.155.32-.234.426-.234.106 0 .214.002.307.006.097.004.227-.037.355.271.132.318.453 1.102.492 1.182.04.081.066.175.012.285-.054.11-.082.179-.163.272-.081.094-.171.21-.244.281-.082.079-.168.165-.072.331.097.166.428.705.918 1.141.63.562 1.16.736 1.326.821.166.086.264.072.361-.039.097-.11.417-.484.529-.648.112-.165.223-.138.377-.081.155.056.979.462 1.148.546.17.085.283.126.324.198.041.071.041.412-.104.825z"/></svg>
              </button>
            </form>
          </div>
        </div>
      </section>

      {/* Modal Agendamento */}
      {bookingModal.open && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white w-full max-w-lg rounded-[3rem] p-8 shadow-2xl animate-slide-up">
            <h3 className="text-2xl font-serif text-tea-900 mb-4">{bookingModal.step === 1 ? 'Quem irá te atender?' : 'Escolha o melhor horário'}</h3>
            {bookingModal.step === 1 ? (
              <div className="space-y-4 mb-8">
                {availableProfessionals.map(pro => (
                  <button key={pro.id} onClick={() => { setSelectedProfessional(pro.id); setBookingModal({...bookingModal, step: 2}); }} className="w-full p-5 rounded-2xl border-2 border-gray-50 bg-gray-50 hover:border-tea-200 transition-all flex items-center gap-4">
                    <div className="w-10 h-10 rounded-full bg-tea-800 flex items-center justify-center text-white font-bold">{pro.name.charAt(0)}</div>
                    <span className="font-bold text-tea-950">{pro.name}</span>
                  </button>
                ))}
              </div>
            ) : (
              <div className="space-y-6">
                <input type="date" value={selectedDate} onChange={(e) => setSelectedDate(e.target.value)} className="w-full p-4 border-2 border-tea-50 rounded-xl outline-none" min={new Date().toISOString().split('T')[0]} />
                <div className="grid grid-cols-4 gap-2 max-h-48 overflow-y-auto p-2 border border-gray-50 rounded-xl">
                  {getAvailableHours().map(h => (
                    <button key={h} onClick={() => setSelectedTime(h)} className={`p-2 rounded-lg text-xs font-bold transition-all ${selectedTime === h ? 'bg-tea-800 text-white' : 'bg-tea-50 text-tea-700 hover:bg-tea-100'}`}>{h}</button>
                  ))}
                </div>
                <div className="flex gap-2">
                  <button onClick={() => setBookingModal({...bookingModal, step: 1})} className="flex-1 py-4 text-gray-400 font-bold">Voltar</button>
                  <button onClick={confirmBooking} disabled={!selectedTime} className="flex-[2] bg-tea-800 text-white py-4 rounded-xl font-bold shadow-xl">Confirmar Horário</button>
                </div>
              </div>
            )}
            <button onClick={() => setBookingModal({open: false, service: null, step: 1})} className="w-full mt-4 text-gray-400 text-sm font-bold">Fechar</button>
          </div>
        </div>
      )}

      <style>{`
        @keyframes float {
          0% { transform: translateY(0px); }
          50% { transform: translateY(-20px); }
          100% { transform: translateY(0px); }
        }
        .animate-float {
          animation: float 7s ease-in-out infinite;
        }
      `}</style>
    </div>
  );
};

export default CustomerHome;

import React, { useState, useRef } from 'react';
import { SalonSettings, Service, TeamMember, Customer, Booking, Transaction } from '../types.ts';

interface AdminSettingsViewProps {
  settings: SalonSettings;
  setSettings: (s: SalonSettings) => void;
  services: Service[];
  setServices: (s: Service[]) => void;
  customers: Customer[];
  bookings: Booking[];
  transactions: Transaction[];
  onImport: (data: any) => void;
}

const AdminSettingsView: React.FC<AdminSettingsViewProps> = ({ 
  settings, 
  setSettings, 
  services = [], 
  setServices,
  customers = [],
  bookings = [],
  transactions = [],
  onImport
}) => {
  const [newService, setNewService] = useState({ name: '', price: 0, duration: 30, description: '', isVisible: true });
  const [newMemberName, setNewMemberName] = useState('');
  const [isDeploying, setIsDeploying] = useState(false);
  const [showCodeGen, setShowCodeGen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const teamMembers = settings?.teamMembers || [];

  const handleExportFile = () => {
    setIsDeploying(true);
    setTimeout(() => {
      setIsDeploying(false);
      const dataToExport = { settings, services, customers, bookings, transactions, version: "6.0" };
      const blob = new Blob([JSON.stringify(dataToExport, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `moria_backup_${new Date().toISOString().split('T')[0]}.json`;
      link.click();
      alert("ARQUIVO DE BACKUP GERADO! Use este arquivo para importar seus dados em outro celular ou computador.");
    }, 800);
  };

  const generateConstantsCode = () => {
    const code = `
import { Service, SalonSettings } from './types';

export const INITIAL_SERVICES: Service[] = ${JSON.stringify(services, null, 2)};

export const DEFAULT_SETTINGS: SalonSettings = ${JSON.stringify(settings, null, 2)};
    `;
    return code.trim();
  };

  const updateSetting = (key: string, value: any) => {
    setSettings({ ...settings, [key]: value });
  };

  const addTeamMember = () => {
    if (newMemberName.trim()) {
      const newMember: TeamMember = {
        id: Math.random().toString(36).substr(2, 9),
        name: newMemberName.trim(),
        assignedServiceIds: []
      };
      updateSetting('teamMembers', [...teamMembers, newMember]);
      setNewMemberName('');
    }
  };

  const removeTeamMember = (id: string) => {
    if (confirm(`Deseja remover ${teamMembers.find(m => m.id === id)?.name} da equipe?`)) {
      updateSetting('teamMembers', teamMembers.filter(m => m.id !== id));
    }
  };

  const toggleServiceToMember = (memberId: string, serviceId: string) => {
    const updatedMembers = teamMembers.map(m => {
      if (m.id === memberId) {
        const hasService = m.assignedServiceIds.includes(serviceId);
        return {
          ...m,
          assignedServiceIds: hasService 
            ? m.assignedServiceIds.filter(id => id !== serviceId)
            : [...m.assignedServiceIds, serviceId]
        };
      }
      return m;
    });
    updateSetting('teamMembers', updatedMembers);
  };

  const toggleServiceVisibility = (id: string) => {
    setServices(services.map(s => s.id === id ? { ...s, isVisible: !s.isVisible } : s));
  };

  const addService = () => {
    if (newService.name && newService.price > 0) {
      setServices([...services, { ...newService, id: Math.random().toString(36).substr(2, 9) }]);
      setNewService({ name: '', price: 0, duration: 30, description: '', isVisible: true });
    }
  };

  return (
    <div className="space-y-12 pb-32 animate-fade-in">
      {/* HEADER DE GESTÃO */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center bg-white p-10 rounded-[3rem] shadow-sm border border-gray-100 gap-8">
        <div>
          <h2 className="text-3xl font-serif text-tea-950 font-bold mb-2">Configurações Gerais</h2>
          <p className="text-gray-500 font-light max-w-md">As alterações salvas abaixo ficam guardadas neste navegador. Para que todos os clientes vejam, use a opção de "Atualizar Código Fonte".</p>
        </div>

        <div className="flex flex-col sm:flex-row gap-4 w-full lg:w-auto">
          <button 
            onClick={() => setShowCodeGen(true)}
            className="flex-1 bg-tea-800 text-white px-8 py-5 rounded-[2rem] font-bold hover:bg-tea-950 transition-all shadow-xl flex items-center justify-center gap-3 uppercase text-xs tracking-widest"
          >
            <span>💻 Atualizar no GitHub</span>
          </button>
          <button 
            onClick={handleExportFile}
            className="flex-1 bg-white text-tea-800 border-2 border-tea-100 px-8 py-5 rounded-[2rem] font-bold hover:bg-tea-50 transition-all flex items-center justify-center gap-3 uppercase text-xs tracking-widest"
          >
            <span>📱 Sincronizar Dispositivos</span>
          </button>
        </div>
      </div>

      {/* MODAL DE CÓDIGO FONTE */}
      {showCodeGen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
          <div className="bg-white w-full max-w-4xl rounded-[3rem] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-8 border-b border-gray-100 flex justify-between items-center bg-tea-50/30">
              <div>
                <h3 className="text-xl font-serif font-bold text-tea-900">Código para constants.ts</h3>
                <p className="text-xs text-tea-600 mt-1 uppercase tracking-widest font-bold">Copie este código para atualizar o Vercel</p>
              </div>
              <button onClick={() => setShowCodeGen(false)} className="p-3 hover:bg-red-50 text-red-400 rounded-full transition-colors font-bold">FECHAR</button>
            </div>
            <div className="p-8 overflow-y-auto bg-gray-950 text-tea-300 font-mono text-xs leading-relaxed custom-scroll">
              <pre className="whitespace-pre-wrap">{generateConstantsCode()}</pre>
            </div>
            <div className="p-8 bg-gray-50 border-t border-gray-100">
               <div className="flex flex-col md:flex-row gap-6 items-center">
                  <div className="flex-1 text-sm text-gray-500 italic">
                    Para que a mudança seja global: <br/>
                    1. Copie o texto acima. <br/>
                    2. Cole no seu arquivo <b>constants.ts</b>. <br/>
                    3. Salve e publique no GitHub/Vercel.
                  </div>
                  <button 
                    onClick={() => {
                      navigator.clipboard.writeText(generateConstantsCode());
                      alert("Código copiado! Agora basta colar no arquivo constants.ts do seu projeto.");
                    }}
                    className="bg-tea-700 text-white px-10 py-4 rounded-2xl font-bold hover:bg-tea-800 shadow-lg shadow-tea-100 uppercase text-xs tracking-widest"
                  >
                    Copiar Código
                  </button>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* HORÁRIO DE FUNCIONAMENTO */}
      <section className="bg-white p-10 rounded-[3rem] shadow-sm border border-gray-100">
        <h3 className="text-2xl font-serif text-tea-900 mb-8 flex items-center gap-3">🕒 Horário de Funcionamento</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="space-y-2">
            <label className="text-[11px] font-bold text-gray-400 uppercase tracking-widest ml-2">Abertura do Estúdio</label>
            <input 
              type="time" 
              className="w-full p-5 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-tea-200 outline-none font-bold"
              value={settings.businessHours?.start || "08:00"}
              onChange={(e) => updateSetting('businessHours', { ...settings.businessHours, start: e.target.value })}
            />
          </div>
          <div className="space-y-2">
            <label className="text-[11px] font-bold text-gray-400 uppercase tracking-widest ml-2">Fechamento do Estúdio</label>
            <input 
              type="time" 
              className="w-full p-5 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-tea-200 outline-none font-bold"
              value={settings.businessHours?.end || "19:00"}
              onChange={(e) => updateSetting('businessHours', { ...settings.businessHours, end: e.target.value })}
            />
          </div>
        </div>
      </section>

      {/* GESTÃO DE EQUIPE */}
      <section className="bg-white p-10 rounded-[3rem] shadow-sm border border-gray-100">
        <div className="flex justify-between items-center mb-10">
          <h3 className="text-2xl font-serif text-tea-900 flex items-center gap-3">👥 Profissionais & Atribuições</h3>
        </div>

        <div className="bg-gray-50/50 p-8 rounded-[2.5rem] border border-gray-100 mb-10">
          <p className="text-[11px] font-bold text-gray-400 uppercase mb-4 ml-1 tracking-widest">Adicionar Nova Colaboradora:</p>
          <div className="flex flex-col md:flex-row gap-4">
            <input 
              placeholder="Nome da profissional..." 
              className="flex-grow p-5 border-2 border-transparent bg-white rounded-2xl outline-none focus:border-tea-200 shadow-sm font-bold"
              value={newMemberName}
              onChange={(e) => setNewMemberName(e.target.value)}
            />
            <button onClick={addTeamMember} className="bg-tea-600 text-white px-12 py-5 rounded-2xl font-bold hover:bg-tea-700 transition-all">ADICIONAR</button>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {teamMembers.map(member => (
            <div key={member.id} className="bg-white p-8 border-2 border-gray-50 rounded-[2.5rem] hover:border-tea-100 transition-all shadow-sm">
              <div className="flex justify-between items-start mb-8">
                <div className="flex items-center gap-5">
                  <div className="w-16 h-16 bg-tea-800 rounded-3xl flex items-center justify-center text-white text-2xl font-bold">{member.name.charAt(0)}</div>
                  <h4 className="font-bold text-tea-950 text-xl">{member.name}</h4>
                </div>
                <button onClick={() => removeTeamMember(member.id)} className="text-red-300 hover:text-red-500 text-xs font-bold uppercase tracking-widest">Remover</button>
              </div>

              <div className="space-y-4">
                <p className="text-[11px] font-bold text-gray-400 uppercase tracking-widest border-b border-gray-50 pb-2">Atribuir Procedimentos:</p>
                <div className="flex flex-wrap gap-2">
                  {services.map(s => {
                    const isAssigned = member.assignedServiceIds?.includes(s.id);
                    return (
                      <button 
                        key={s.id}
                        onClick={() => toggleServiceToMember(member.id, s.id)}
                        className={`px-4 py-3 rounded-xl text-[10px] font-bold border-2 transition-all ${isAssigned ? 'bg-tea-600 border-tea-600 text-white' : 'bg-gray-50 border-gray-100 text-gray-400 hover:border-tea-200'}`}
                      >
                        {isAssigned ? '✅' : '➕'} {s.name}
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* GESTÃO DE SERVIÇOS */}
      <section className="bg-white p-10 rounded-[3rem] shadow-sm border border-gray-100">
        <h3 className="text-2xl font-serif text-tea-900 mb-8 flex items-center gap-3">📋 Catálogo de Procedimentos</h3>

        <div className="bg-tea-50/50 p-8 rounded-[2.5rem] border border-tea-100 mb-10">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6">
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-tea-700 uppercase ml-2">Nome</label>
              <input className="w-full p-4 rounded-xl border-2 border-white bg-white focus:border-tea-200 outline-none font-bold" value={newService.name} onChange={e => setNewService({...newService, name: e.target.value})} />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-tea-700 uppercase ml-2">Preço R$</label>
              <input type="number" className="w-full p-4 rounded-xl border-2 border-white bg-white focus:border-tea-200 outline-none font-bold" value={newService.price || ''} onChange={e => setNewService({...newService, price: parseFloat(e.target.value)})} />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-tea-700 uppercase ml-2">Minutos</label>
              <input type="number" className="w-full p-4 rounded-xl border-2 border-white bg-white focus:border-tea-200 outline-none font-bold" value={newService.duration || ''} onChange={e => setNewService({...newService, duration: parseInt(e.target.value)})} />
            </div>
          </div>
          <button onClick={addService} className="w-full bg-tea-800 text-white py-5 rounded-2xl font-bold hover:bg-tea-950 transition-all uppercase tracking-widest text-xs">Salvar Novo Serviço</button>
        </div>

        <div className="grid grid-cols-1 gap-4">
          {services.map(s => (
            <div key={s.id} className={`p-6 border-2 rounded-3xl flex justify-between items-center transition-all ${s.isVisible ? 'border-gray-50 bg-white shadow-sm' : 'border-red-50 bg-red-50/10 opacity-60'}`}>
              <div>
                <p className={`font-bold text-lg ${s.isVisible ? 'text-tea-950' : 'text-gray-400'}`}>{s.name}</p>
                <p className="text-xs text-gray-400 font-bold">R$ {s.price.toFixed(2)} • {s.duration} min</p>
              </div>
              <div className="flex gap-3">
                <button 
                  onClick={() => toggleServiceVisibility(s.id)} 
                  className={`px-6 py-3 rounded-xl text-[10px] font-bold border-2 transition-all ${s.isVisible ? 'bg-white border-tea-100 text-tea-700' : 'bg-tea-800 border-tea-800 text-white'}`}
                >
                  {s.isVisible ? 'OCULTAR NO SITE' : 'EXIBIR NO SITE'}
                </button>
                <button onClick={() => setServices(services.filter(x => x.id !== s.id))} className="p-3 text-red-200 hover:text-red-500 transition-colors">🗑️</button>
              </div>
            </div>
