  };

  const generateConstantsCode = () => {
    // Ao gerar o código, atualizamos o carimbo de data para que o App.tsx saiba que esta versão é a mais nova.
    const syncSettings = { ...settings, lastUpdated: Date.now() };
    const code = `
import { Service, SalonSettings } from './types';

export const INITIAL_SERVICES: Service[] = ${JSON.stringify(services, null, 2)};

export const DEFAULT_SETTINGS: SalonSettings = ${JSON.stringify(syncSettings, null, 2)};
    `;
    return code.trim();
  };

  const updateSetting = (key: string, value: any) => {
    setSettings({ ...settings, [key]: value, lastUpdated: Date.now() });
  };

  const addTeamMember = () => {
    if (newMemberName.trim()) {
      const newMember: TeamMember = {
        id: Math.random().toString(36).substr(2, 9),
        name: newMemberName.trim(),
        assignedServiceIds: []
      };
      updateSetting('teamMembers', [...teamMembers, newMember]);
      setNewMemberName('');
    }
  };

  const removeTeamMember = (id: string) => {
    if (confirm(`Remover ${teamMembers.find(m => m.id === id)?.name}?`)) {
      updateSetting('teamMembers', teamMembers.filter(m => m.id !== id));
    }
  };

  const toggleServiceToMember = (memberId: string, serviceId: string) => {
    const updatedMembers = teamMembers.map(m => {
      if (m.id === memberId) {
        const hasService = m.assignedServiceIds.includes(serviceId);
        return {
          ...m,
          assignedServiceIds: hasService 
            ? m.assignedServiceIds.filter(id => id !== serviceId)
            : [...m.assignedServiceIds, serviceId]
        };
      }
      return m;
    });
    updateSetting('teamMembers', updatedMembers);
  };

  const toggleServiceVisibility = (id: string) => {
    const updated = services.map(s => s.id === id ? { ...s, isVisible: !s.isVisible } : s);
    setServices(updated);
    setSettings({ ...settings, lastUpdated: Date.now() });
  };

  const addService = () => {
    if (newService.name && newService.price > 0) {
      setServices([...services, { ...newService, id: Math.random().toString(36).substr(2, 9) }]);
      setNewService({ name: '', price: 0, duration: 30, description: '', isVisible: true });
      setSettings({ ...settings, lastUpdated: Date.now() });
    }
  };

  return (
    <div className="space-y-12 pb-32 animate-fade-in">
      {/* HEADER DE GESTÃO */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center bg-white p-10 rounded-[3rem] shadow-sm border border-gray-100 gap-8">
        <div>
          <h2 className="text-3xl font-serif text-tea-950 font-bold mb-2">Publicar Mudanças</h2>
          <p className="text-gray-500 font-light max-w-md">Para que todos os clientes vejam novos serviços ou preços, use o botão azul abaixo e siga as instruções.</p>
        </div>

        <div className="flex flex-col sm:flex-row gap-4 w-full lg:w-auto">
          <button 
            onClick={() => setShowCodeGen(true)}
            className="flex-1 bg-tea-800 text-white px-8 py-5 rounded-[2rem] font-bold hover:bg-tea-950 transition-all shadow-xl flex items-center justify-center gap-3 uppercase text-xs tracking-widest"
          >
            <span>🚀 Atualizar Site no GitHub</span>
          </button>
          <button 
            onClick={handleExportFile}
            className="flex-1 bg-white text-tea-800 border-2 border-tea-100 px-8 py-5 rounded-[2rem] font-bold hover:bg-tea-50 transition-all flex items-center justify-center gap-3 uppercase text-xs tracking-widest"
          >
            <span>💾 Backup de Segurança</span>
          </button>
        </div>
      </div>

      {/* MODAL DE CÓDIGO FONTE */}
      {showCodeGen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
          <div className="bg-white w-full max-w-4xl rounded-[3rem] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-8 border-b border-gray-100 flex justify-between items-center bg-tea-50/30">
              <div>
                <h3 className="text-xl font-serif font-bold text-tea-900">Passo 2: Atualizar o GitHub</h3>
                <p className="text-xs text-tea-600 mt-1 uppercase tracking-widest font-bold">Copie o código abaixo e cole no seu arquivo constants.ts</p>
              </div>
              <button onClick={() => setShowCodeGen(false)} className="p-3 hover:bg-red-50 text-red-400 rounded-full transition-colors font-bold">FECHAR</button>
            </div>
            <div className="p-8 overflow-y-auto bg-gray-950 text-tea-300 font-mono text-xs leading-relaxed custom-scroll">
              <pre className="whitespace-pre-wrap">{generateConstantsCode()}</pre>
            </div>
            <div className="p-8 bg-gray-50 border-t border-gray-100">
               <div className="flex flex-col md:flex-row gap-6 items-center">
                  <div className="flex-1 text-sm text-gray-500 italic">
                    Ao colar este código no seu GitHub, o Vercel atualizará o site e o <b>Moriá Sync</b> forçará todos os celulares dos seus clientes a baixar as novas informações.
                  </div>
                  <button 
                    onClick={() => {
                      navigator.clipboard.writeText(generateConstantsCode());
                      alert("Código copiado! Vá no GitHub, abra o constants.ts, apague tudo e cole este novo texto.");
                    }}
                    className="bg-tea-700 text-white px-10 py-4 rounded-2xl font-bold hover:bg-tea-800 shadow-lg uppercase text-xs tracking-widest"
                  >
                    Copiar Código
                  </button>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* Restante das seções (Horário, Equipe, Serviços) permanece o mesmo mas chamando as funções atualizadas */}
      <section className="bg-white p-10 rounded-[3rem] shadow-sm border border-gray-100">
        <h3 className="text-2xl font-serif text-tea-900 mb-8 flex items-center gap-3">🕒 Horário de Funcionamento</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="space-y-2">
            <label className="text-[11px] font-bold text-gray-400 uppercase tracking-widest ml-2">Abertura</label>
            <input 
              type="time" 
              className="w-full p-5 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-tea-200 outline-none font-bold"
              value={settings.businessHours?.start || "08:00"}
              onChange={(e) => updateSetting('businessHours', { ...settings.businessHours, start: e.target.value })}
            />
          </div>
          <div className="space-y-2">
            <label className="text-[11px] font-bold text-gray-400 uppercase tracking-widest ml-2">Fechamento</label>
            <input 
              type="time" 
              className="w-full p-5 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-tea-200 outline-none font-bold"
              value={settings.businessHours?.end || "19:00"}
              onChange={(e) => updateSetting('businessHours', { ...settings.businessHours, end: e.target.value })}
            />
          </div>
        </div>
      </section>

      {/* GESTÃO DE EQUIPE */}
      <section className="bg-white p-10 rounded-[3rem] shadow-sm border border-gray-100">
        <h3 className="text-2xl font-serif text-tea-900 mb-8">👥 Equipe</h3>
        <div className="bg-gray-50/50 p-8 rounded-[2.5rem] mb-10">
          <div className="flex flex-col md:flex-row gap-4">
            <input 
              placeholder="Nome da colaboradora..." 
              className="flex-grow p-5 bg-white rounded-2xl outline-none focus:border-tea-200 shadow-sm font-bold"
              value={newMemberName}
              onChange={(e) => setNewMemberName(e.target.value)}
            />
            <button onClick={addTeamMember} className="bg-tea-600 text-white px-12 py-5 rounded-2xl font-bold hover:bg-tea-700 transition-all">ADICIONAR</button>
          </div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {teamMembers.map(member => (
            <div key={member.id} className="bg-white p-8 border-2 border-gray-50 rounded-[2.5rem] shadow-sm">
              <div className="flex justify-between items-start mb-6">
                <h4 className="font-bold text-tea-950 text-xl">{member.name}</h4>
                <button onClick={() => removeTeamMember(member.id)} className="text-red-300 text-xs font-bold uppercase">Remover</button>
              </div>
              <div className="flex flex-wrap gap-2">
                {services.map(s => (
                  <button 
                    key={s.id}
                    onClick={() => toggleServiceToMember(member.id, s.id)}
                    className={`px-3 py-2 rounded-xl text-[9px] font-bold border-2 transition-all ${member.assignedServiceIds?.includes(s.id) ? 'bg-tea-600 text-white' : 'bg-gray-50 text-gray-400'}`}
                  >
                    {s.name}
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* GESTÃO DE SERVIÇOS */}
      <section className="bg-white p-10 rounded-[3rem] shadow-sm border border-gray-100">
        <h3 className="text-2xl font-serif text-tea-900 mb-8">📋 Serviços</h3>
        <div className="grid grid-cols-1 gap-4">
          {services.map(s => (
            <div key={s.id} className={`p-6 border-2 rounded-3xl flex justify-between items-center ${s.isVisible ? 'border-gray-50' : 'bg-red-50/10 opacity-60'}`}>
              <div>
                <p className="font-bold text-lg text-tea-950">{s.name}</p>
                <p className="text-xs text-gray-400">R$ {s.price.toFixed(2)}</p>
              </div>
              <button 
                onClick={() => toggleServiceVisibility(s.id)} 
                className={`px-6 py-3 rounded-xl text-[10px] font-bold border-2 ${s.isVisible ? 'bg-white text-tea-700' : 'bg-tea-800 text-white'}`}
              >
                {s.isVisible ? 'OCULTAR NO SITE' : 'EXIBIR NO SITE'}
              </button>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
};

export default AdminSettingsView;

import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, TeamMember, WaitlistEntry } from './types.ts';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants.ts';
import Navbar from './components/Navbar.tsx';
import CustomerHome from './components/CustomerHome.tsx';
import CustomerRegister from './components/CustomerRegister.tsx';
import CustomerLoginView from './components/CustomerLoginView.tsx';
import CustomerProfile from './components/CustomerProfile.tsx';
import AdminDashboard from './components/AdminDashboard.tsx';
import AdminCalendar from './components/AdminCalendar.tsx';
import AdminFinance from './components/AdminFinance.tsx';
import AdminClients from './components/AdminClients.tsx';
import AdminConfirmations from './components/AdminConfirmations.tsx';
import AdminSettingsView from './components/AdminSettingsView.tsx';
import AdminVeo from './components/AdminVeo.tsx';
import AdminLogin from './components/AdminLogin.tsx';

const STORAGE_KEY = 'moria_db_v8_bridge';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);

  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>(INITIAL_SERVICES);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [waitlist, setWaitlist] = useState<WaitlistEntry[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  // --- MORIÁ SYNC BRIDGE ENGINE ---
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const syncData = params.get('sync');

    if (syncData) {
      try {
        const decoded = JSON.parse(atob(syncData));
        console.log("Moriá Bridge: Dados de sincronização detectados!", decoded);

        if (decoded.type === 'new_customer') {
          setCustomers(prev => {
            if (prev.find(c => c.cpf === decoded.data.cpf)) return prev;
            return [...prev, decoded.data];
          });
          alert(`Nova cliente sincronizada: ${decoded.data.name}`);
        } else if (decoded.type === 'full_sync') {
          if (decoded.data.settings) setSettings(decoded.data.settings);
          if (decoded.data.services) setServices(decoded.data.services);
          if (decoded.data.customers) setCustomers(decoded.data.customers);
          alert("Sincronização total do estúdio realizada!");
        }

        // Limpa a URL após sincronizar
        window.history.replaceState({}, document.title, window.location.pathname);
      } catch (e) {
        console.error("Erro na sincronização Bridge", e);
      }
    }
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        const codeDate = DEFAULT_SETTINGS.lastUpdated || 0;
        const savedDate = parsed.settings?.lastUpdated || 0;

        if (codeDate > savedDate) {
          setSettings(DEFAULT_SETTINGS);
          setServices(INITIAL_SERVICES);
        } else {
          if (parsed.settings) setSettings(parsed.settings);
          if (parsed.services) setServices(parsed.services);
        }

        if (parsed.customers) setCustomers(parsed.customers);
        if (parsed.bookings) setBookings(parsed.bookings);
        if (parsed.transactions) setTransactions(parsed.transactions);
        if (parsed.waitlist) setWaitlist(parsed.waitlist);
      } catch (e) {
        console.error("Erro ao carregar dados locais", e);
      }
    }

    const savedUser = localStorage.getItem('moria_user_session');
    if (savedUser) setCurrentUser(JSON.parse(savedUser));
    if (localStorage.getItem('moria_admin_session') === 'true') setIsAdminAuthenticated(true);
  }, []);

  useEffect(() => {
    const data = { settings, services, customers, bookings, transactions, waitlist };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    if (currentUser) localStorage.setItem('moria_user_session', JSON.stringify(currentUser));
    else localStorage.removeItem('moria_user_session');
    localStorage.setItem('moria_admin_session', isAdminAuthenticated.toString());
  }, [settings, services, customers, bookings, transactions, waitlist, currentUser, isAdminAuthenticated]);

  const handleRegister = (name: string, whatsapp: string, cpf: string, password: string, receivesNotifications: boolean) => {
    const newCustomer: Customer = { 
      id: Math.random().toString(36).substr(2, 9), 
      name, whatsapp, cpf, password, receivesNotifications, 
      agreedToTerms: true, history: [] 
    };

    setCustomers(prev => [...prev, newCustomer]);
    setCurrentUser(newCustomer);

    // Gerar link de sincronização para a dona
    const syncPayload = btoa(JSON.stringify({ type: 'new_customer', data: newCustomer }));
    const syncUrl = `${window.location.origin}${window.location.pathname}?sync=${syncPayload}`;

    const message = `Olá Studio Moriá! Acabei de me cadastrar no site.\n\nNome: ${name}\nCPF: ${cpf}\n\nClique no link abaixo para validar meu cadastro no seu sistema:\n${syncUrl}`;

    setTimeout(() => {
      window.open(`https://wa.me/${settings.socialLinks.whatsapp.replace(/\D/g, '')}?text=${encodeURIComponent(message)}`, '_blank');
      setCurrentView(View.CUSTOMER_HOME);
    }, 500);
  };

  const handleLogin = (cpf: string, pass: string) => {
    const user = customers.find(c => c.cpf === cpf && c.password === pass);
    if (user) { setCurrentUser(user); setCurrentView(View.CUSTOMER_HOME); }
    else alert("Dados incorretos.");
  };

  const handleAddToWaitlist = (serviceId: string, date: string) => {
    if (!currentUser) return;
    const service = services.find(s => s.id === serviceId);
    const entry: WaitlistEntry = {
      id: Math.random().toString(36).substr(2, 9),
      customerId: currentUser.id, customerName: currentUser.name,
      customerWhatsapp: currentUser.whatsapp, serviceId,
      serviceName: service?.name || '', preferredDate: date, createdAt: new Date().toISOString()
    };
    setWaitlist(prev => [...prev, entry]);
    alert("Você está na lista de espera!");
  };

  const renderView = () => {
    if (isAdmin) {
      if (!isAdminAuthenticated) return <AdminLogin onLogin={() => { setIsAdminAuthenticated(true); setCurrentView(View.ADMIN_DASHBOARD); }} onBack={() => setIsAdmin(false)} />;
      switch (currentView) {
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} setSettings={setSettings} services={services} setServices={setServices} customers={customers} bookings={bookings} transactions={transactions} onImport={(data) => { setSettings(data.settings); setServices(data.services); setCustomers(data.customers); }} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} setBookings={setBookings} services={services} teamMembers={settings.teamMembers} settings={settings} />;
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} onUpdateStatus={(id, status) => setBookings(prev => prev.map(b => b.id === id ? {...b, status} : b))} waitlist={waitlist} onRemoveWaitlist={(id) => setWaitlist(prev => prev.filter(w => w.id !== id))} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={(id) => setCustomers(prev => prev.filter(c => c.id !== id))} onUpdate={(id, data) => setCustomers(prev => prev.map(c => c.id === id ? {...c, ...data} : c))} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} setTransactions={setTransactions} customers={customers} services={services} />;
        case View.ADMIN_VEO: return <AdminVeo />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} />;
      }
    }

    switch (currentView) {
      case View.CUSTOMER_REGISTER: return <CustomerRegister onRegister={handleRegister} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_LOGIN: return <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_PROFILE: return currentUser ? <CustomerProfile customer={currentUser} transactions={transactions} bookings={bookings} onUpdateNotification={(val) => setCustomers(prev => prev.map(c => c.id === currentUser.id ? {...c, receivesNotifications: val} : c))} onBack={() => setCurrentView(View.CUSTOMER_HOME)} /> : <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      default: return (
        <CustomerHome 
          settings={settings} services={services} bookings={bookings} 
          onBook={(sid, dt, mid) => {
            if (!currentUser) { setCurrentView(View.CUSTOMER_LOGIN); return; }
            const srv = services.find(s => s.id === sid);
            setBookings(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), customerId: currentUser.id, customerName: currentUser.name, serviceId: sid, serviceName: srv?.name || '', dateTime: dt, status: 'pending', teamMemberId: mid, teamMemberName: settings.teamMembers.find(m => m.id === mid)?.name }]);
            alert("Solicitação enviada!");
          }} 
          onAuthClick={() => setCurrentView(View.CUSTOMER_LOGIN)} 
          onAddToWaitlist={handleAddToWaitlist} currentUser={currentUser} 
        />
      );
    }
  };

  return (
    <div className="min-h-screen bg-white">
      <Navbar view={currentView} setView={setCurrentView} isAdmin={isAdmin} onToggleAdmin={() => { setIsAdmin(!isAdmin); if(!isAdminAuthenticated) setCurrentView(View.ADMIN_LOGIN); else setCurrentView(isAdmin ? View.CUSTOMER_HOME : View.ADMIN_DASHBOARD); }} salonName={settings.name} logo={settings.logo} currentUser={currentUser} onLogout={() => setCurrentUser(null)} onAdminLogout={() => { setIsAdminAuthenticated(false); setIsAdmin(false); setCurrentView(View.CUSTOMER_HOME); }} isAdminAuthenticated={isAdminAuthenticated} pendingBookingsCount={bookings.filter(b => b.status === 'pending').length} />
      <main className="max-w-7xl mx-auto px-4 py-8">{renderView()}</main>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { SalonSettings, Service, TeamMember, Customer, Booking, Transaction } from '../types.ts';

interface AdminSettingsViewProps {
  settings: SalonSettings;
  setSettings: (s: SalonSettings) => void;
  services: Service[];
  setServices: (s: Service[]) => void;
  customers: Customer[];
  bookings: Booking[];
  transactions: Transaction[];
  onImport: (data: any) => void;
}

const AdminSettingsView: React.FC<AdminSettingsViewProps> = ({ 
  settings, 
  setSettings, 
  services = [], 
  setServices,
  customers = [],
  bookings = [],
  transactions = [],
  onImport
}) => {
  const [newService, setNewService] = useState({ name: '', price: 0, duration: 30, description: '', isVisible: true });
  const [newMemberName, setNewMemberName] = useState('');
  const [showCodeGen, setShowCodeGen] = useState(false);

  const teamMembers = settings?.teamMembers || [];

  const handleExportFullSync = () => {
    const fullData = { settings, services, customers, bookings, transactions };
    const syncPayload = btoa(JSON.stringify({ type: 'full_sync', data: fullData }));
    const syncUrl = `${window.location.origin}${window.location.pathname}?sync=${syncPayload}`;

    // Abrir modal com o link para copiar ou enviar via WhatsApp
    const message = `Moriá Sync: Aqui está o link de sincronização total do Studio Moriá.\n\nAbra este link em outro celular para espelhar todo o sistema:\n${syncUrl}`;
    window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank');
  };

  const handleExportFile = () => {
    const dataToExport = { settings, services, customers, bookings, transactions, version: "8.0" };
    const blob = new Blob([JSON.stringify(dataToExport, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `moria_backup_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    alert("BACKUP REALIZADO! Guarde este arquivo.");
  };

  const generateConstantsCode = () => {
    const syncSettings = { ...settings, lastUpdated: Date.now() };
    const code = `
import { Service, SalonSettings } from './types';

export const INITIAL_SERVICES: Service[] = ${JSON.stringify(services, null, 2)};

export const DEFAULT_SETTINGS: SalonSettings = ${JSON.stringify(syncSettings, null, 2)};
    `;
    return code.trim();
  };

  const updateSetting = (key: string, value: any) => {
    setSettings({ ...settings, [key]: value, lastUpdated: Date.now() });
  };

  const addTeamMember = () => {
    if (newMemberName.trim()) {
      const newMember: TeamMember = {
        id: Math.random().toString(36).substr(2, 9),
        name: newMemberName.trim(),
        assignedServiceIds: []
      };
      updateSetting('teamMembers', [...teamMembers, newMember]);
      setNewMemberName('');
    }
  };

  const removeTeamMember = (id: string) => {
    if (confirm(`Remover ${teamMembers.find(m => m.id === id)?.name}?`)) {
      updateSetting('teamMembers', teamMembers.filter(m => m.id !== id));
    }
  };

  const toggleServiceToMember = (memberId: string, serviceId: string) => {
    const updatedMembers = teamMembers.map(m => {
      if (m.id === memberId) {
        const hasService = m.assignedServiceIds.includes(serviceId);
        return {
          ...m,
          assignedServiceIds: hasService 
            ? m.assignedServiceIds.filter(id => id !== serviceId)
            : [...m.assignedServiceIds, serviceId]
        };
      }
      return m;
    });
    updateSetting('teamMembers', updatedMembers);
  };

  const toggleServiceVisibility = (id: string) => {
    const updated = services.map(s => s.id === id ? { ...s, isVisible: !s.isVisible } : s);
    setServices(updated);
    setSettings({ ...settings, lastUpdated: Date.now() });
  };

  const addService = () => {
    if (newService.name && newService.price > 0) {
      setServices([...services, { ...newService, id: Math.random().toString(36).substr(2, 9) }]);
      setNewService({ name: '', price: 0, duration: 30, description: '', isVisible: true });
      setSettings({ ...settings, lastUpdated: Date.now() });
    }
  };

  return (
    <div className="space-y-12 pb-32 animate-fade-in">
      {/* HEADER DE GESTÃO - BRIDGE SYNC */}
      <div className="bg-tea-900 text-white p-10 rounded-[3rem] shadow-xl relative overflow-hidden">
        <div className="relative z-10">
          <h2 className="text-3xl font-serif font-bold mb-4">Sincronização Bridge</h2>
          <p className="text-tea-100 font-light max-w-xl mb-8 leading-relaxed">
            Como não usamos um servidor central, use estas ferramentas para "passar" seus dados para outros celulares da equipe ou clientes.
          </p>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <button 
              onClick={() => setShowCodeGen(true)}
              className="bg-white text-tea-900 px-6 py-4 rounded-2xl font-bold hover:scale-105 transition-all text-xs uppercase tracking-widest shadow-lg"
            >
              🚀 Atualizar Site (GitHub)
            </button>
            <button 
              onClick={handleExportFullSync}
              className="bg-tea-800 border-2 border-tea-700 text-white px-6 py-4 rounded-2xl font-bold hover:bg-tea-950 transition-all text-xs uppercase tracking-widest"
            >
              📱 Link para outro celular
            </button>
            <button 
              onClick={handleExportFile}
              className="bg-tea-900/50 border border-tea-700 text-tea-200 px-6 py-4 rounded-2xl font-bold hover:bg-tea-800 transition-all text-xs uppercase tracking-widest"
            >
              💾 Baixar Backup JSON
            </button>
          </div>
        </div>
        <div className="absolute -right-20 -bottom-20 w-64 h-64 bg-tea-800 rounded-full opacity-50 blur-3xl"></div>
      </div>

      {/* MODAL DE CÓDIGO FONTE */}
      {showCodeGen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
          <div className="bg-white w-full max-w-4xl rounded-[3rem] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-8 border-b border-gray-100 flex justify-between items-center bg-tea-50/30">
              <div>
                <h3 className="text-xl font-serif font-bold text-tea-900">Atualizar Site (Vercel/GitHub)</h3>
                <p className="text-xs text-tea-600 mt-1 uppercase tracking-widest font-bold">Copie o código abaixo para o seu constants.ts</p>
              </div>
              <button onClick={() => setShowCodeGen(false)} className="p-3 hover:bg-red-50 text-red-400 rounded-full transition-colors font-bold">FECHAR</button>
            </div>
            <div className="p-8 overflow-y-auto bg-gray-950 text-tea-300 font-mono text-xs leading-relaxed custom-scroll">
              <pre className="whitespace-pre-wrap">{generateConstantsCode()}</pre>
            </div>
            <div className="p-8 bg-gray-50 border-t border-gray-100">
               <div className="flex flex-col md:flex-row gap-6 items-center">
                  <div className="flex-1 text-sm text-gray-500 italic">
                    Ao colar este código no seu GitHub, o site atualizará para todos os clientes.
                  </div>
                  <button 
                    onClick={() => {
                      navigator.clipboard.writeText(generateConstantsCode());
                      alert("Código copiado! Vá no GitHub e cole no arquivo constants.ts.");
                    }}
                    className="bg-tea-700 text-white px-10 py-4 rounded-2xl font-bold hover:bg-tea-800 shadow-lg uppercase text-xs tracking-widest"
                  >
                    Copiar Código
                  </button>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* HORÁRIO DE FUNCIONAMENTO */}
      <section className="bg-white p-10 rounded-[3rem] shadow-sm border border-gray-100">
        <h3 className="text-2xl font-serif text-tea-900 mb-8">🕒 Horário</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <input type="time" className="p-5 bg-gray-50 rounded-2xl outline-none font-bold" value={settings.businessHours?.start || "08:00"} onChange={(e) => updateSetting('businessHours', { ...settings.businessHours, start: e.target.value })} />
          <input type="time" className="p-5 bg-gray-50 rounded-2xl outline-none font-bold" value={settings.businessHours?.end || "19:00"} onChange={(e) => updateSetting('businessHours', { ...settings.businessHours, end: e.target.value })} />
        </div>
      </section>

      {/* EQUIPE */}
      <section className="bg-white p-10 rounded-[3rem] shadow-sm border border-gray-100">
        <h3 className="text-2xl font-serif text-tea-900 mb-8">👥 Equipe</h3>
        <div className="flex flex-col md:flex-row gap-4 mb-8">
          <input placeholder="Nome..." className="flex-grow p-5 bg-gray-50 rounded-2xl font-bold outline-none" value={newMemberName} onChange={(e) => setNewMemberName(e.target.value)} />
          <button onClick={addTeamMember} className="bg-tea-600 text-white px-10 py-5 rounded-2xl font-bold">Adicionar</button>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {teamMembers.map(member => (
            <div key={member.id} className="p-8 border-2 border-gray-50 rounded-3xl">
              <div className="flex justify-between items-center mb-4">
                <span className="font-bold text-xl">{member.name}</span>
                <button onClick={() => removeTeamMember(member.id)} className="text-red-300 hover:text-red-500">🗑️</button>
              </div>
              <div className="flex flex-wrap gap-2">
                {services.map(s => (
                  <button key={s.id} onClick={() => toggleServiceToMember(member.id, s.id)} className={`px-3 py-1.5 rounded-xl text-[10px] font-bold border-2 ${member.assignedServiceIds?.includes(s.id) ? 'bg-tea-600 text-white border-tea-600' : 'bg-gray-50 text-gray-400 border-gray-50'}`}>
                    {s.name}
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* SERVIÇOS */}
      <section className="bg-white p-10 rounded-[3rem] shadow-sm border border-gray-100">
        <h3 className="text-2xl font-serif text-tea-900 mb-8">📋 Catálogo</h3>
        <div className="grid grid-cols-1 gap-4">
          {services.map(s => (
            <div key={s.id} className={`p-6 border-2 rounded-3xl flex justify-between items-center ${s.isVisible ? 'border-gray-50' : 'bg-red-50/10 opacity-50'}`}>
              <div>
                <p className="font-bold text-lg">{s.name}</p>
                <p className="text-xs text-gray-400">R$ {s.price.toFixed(2)}</p>
              </div>
              <button onClick={() => toggleServiceVisibility(s.id)} className={`px-6 py-3 rounded-xl text-[10px] font-bold border-2 ${s.isVisible ? 'bg-white text-tea-700' : 'bg-tea-800 text-white border-tea-800'}`}>
                {s.isVisible ? 'VISÍVEL' : 'OCULTO'}
              </button>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
};

export default AdminSettingsView;

