                      onClick={() => onAddToWaitlist(bookingModal.service!.id, selectedDate)}
                      className="text-[10px] bg-orange-600 text-white px-4 py-2 rounded-full font-bold uppercase tracking-widest"
                    >
                      Entrar na Lista de Espera
                    </button>
                  </div>
                )}
              </div>
            )}

            {/* Passo 2: Seleção de Profissional (Se houver mais de uma livre) */}
            {bookingModal.step === 2 && (
              <div className="space-y-8">
                <div className="text-center">
                  <h3 className="text-2xl font-serif text-tea-900 mb-2">Com quem deseja agendar?</h3>
                  <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">Horário: {selectedDate} às {selectedTime}</p>
                </div>

                <div className="space-y-3">
                   {slotsAvailability[selectedTime]?.map(pro => (
                     <button 
                        key={pro.id} 
                        onClick={() => setSelectedProfessional(pro.id)}
                        className={`w-full p-6 rounded-3xl border-2 transition-all flex items-center gap-4 ${
                          selectedProfessional === pro.id 
                          ? 'border-tea-600 bg-tea-50' 
                          : 'border-gray-50 bg-gray-50 hover:border-tea-200'
                        }`}
                     >
                        <div className="w-12 h-12 bg-tea-800 text-white rounded-2xl flex items-center justify-center font-bold text-xl">{pro.name.charAt(0)}</div>
                        <div className="text-left">
                          <p className="font-bold text-tea-950">{pro.name}</p>
                          <p className="text-[10px] text-tea-600 uppercase font-bold tracking-tighter">Disponível agora</p>
                        </div>
                     </button>
                   ))}
                </div>

                <div className="bg-orange-50 p-5 rounded-3xl border border-orange-100">
                  <p className="text-[10px] text-orange-700 font-bold uppercase tracking-widest mb-1">⚠️ Aviso de Garantia</p>
                  <p className="text-[11px] text-orange-800 leading-relaxed">Seu agendamento só será validado após a análise da equipe e o pagamento do sinal.</p>
                </div>

                <div className="flex gap-4">
                   <button onClick={() => setBookingModal(prev => ({ ...prev, step: 1 }))} className="flex-1 py-4 text-gray-400 font-bold">Voltar</button>
                   <button 
                    onClick={confirmBooking} 
                    disabled={!selectedProfessional}
                    className="flex-[2] bg-tea-800 text-white py-4 rounded-2xl font-bold shadow-xl disabled:opacity-50"
                   >
                     Solicitar Agendamento
                   </button>
                </div>
              </div>
            )}

            {/* Passo 3: Feedback de Envio */}
            {bookingModal.step === 3 && (
              <div className="text-center py-10 space-y-6">
                <div className="w-24 h-24 bg-tea-50 text-tea-600 rounded-full flex items-center justify-center text-5xl mx-auto animate-bounce">⏳</div>
                <h3 className="text-3xl font-serif text-tea-900 font-bold italic">Quase lá!</h3>
                <p className="text-gray-500 text-sm leading-relaxed px-4">
                  Sua solicitação para <b>{bookingModal.service?.name}</b> foi enviada. <br/><br/>
                  Para garantir sua vaga, envie agora o <b>comprovante do sinal</b> clicando no botão abaixo.
                </p>
                <button 
                  onClick={() => {
                    const msg = `Olá Studio Moriá! Solicitei ${bookingModal.service?.name} para ${selectedDate} às ${selectedTime}. Segue o comprovante do sinal.`;
                    window.open(`https://wa.me/${settings.socialLinks.whatsapp.replace(/\D/g, '')}?text=${encodeURIComponent(msg)}`, '_blank');
                    setBookingModal({open: false, service: null, step: 1});
                  }}
                  className="w-full bg-tea-800 text-white py-6 rounded-3xl font-bold shadow-2xl flex items-center justify-center gap-4 hover:scale-105 transition-transform"
                >
                  Confirmar via WhatsApp 📱
                </button>
                <button onClick={() => setBookingModal({open: false, service: null, step: 1})} className="text-xs text-gray-400 font-bold uppercase tracking-widest hover:text-tea-800">Fechar e ver depois</button>
              </div>
            )}
          </div>
        </div>
      )}

      <style>{`
        @keyframes float { 0% { transform: translateY(0px); } 50% { transform: translateY(-20px); } 100% { transform: translateY(0px); } }
        .animate-float { animation: float 7s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

export default CustomerHome;

import React, { useState, useEffect, useMemo } from 'react';
import { Customer, Booking, Service } from '../types';
import { GoogleGenAI } from '@google/genai';

interface CustomerDashboardProps {
  customer: Customer;
  bookings: Booking[];
  services: Service[];
  onUpdateProfile: (updated: Partial<Customer>) => void;
  onLogout: () => void;
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ customer, bookings, services, onUpdateProfile, onLogout }) => {
  const [activeTab, setActiveTab] = useState<'home' | 'agenda' | 'cuidados' | 'perfil'>('home');
  const [careTips, setCareTips] = useState<string>('');
  const [isLoadingTips, setIsLoadingTips] = useState(false);

  const myBookings = useMemo(() => 
    bookings.filter(b => b.customerId === customer.id)
      .sort((a, b) => new Date(a.dateTime).getTime() - new Date(b.dateTime).getTime()),
    [bookings, customer.id]
  );

  const nextBooking = useMemo(() => 
    myBookings.find(b => b.status === 'scheduled' || b.status === 'pending'),
    [myBookings]
  );

  useEffect(() => {
    if (activeTab === 'cuidados' && !careTips) {
      generateCareTips();
    }
  }, [activeTab]);

  const generateCareTips = async () => {
    setIsLoadingTips(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const lastService = myBookings[0]?.serviceName || "Estética Geral";
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Como especialista em estética do Studio Moriá, forneça 4 dicas curtas e luxuosas de cuidados pós-procedimento para: ${lastService}. Use emojis e um tom de spa.`,
      });
      setCareTips(response.text || "Mantenha a hidratação e use filtro solar.");
    } catch (error) {
      setCareTips("Beba água e use protetor solar diariamente.");
    } finally {
      setIsLoadingTips(false);
    }
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => onUpdateProfile({ profilePhoto: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="min-h-screen bg-[#F8F9F8] animate-fade-in pb-32">
      {/* Header Estilizado */}
      <div className="bg-tea-900 text-white pt-10 pb-20 px-6 rounded-b-[3.5rem] shadow-2xl relative overflow-hidden">
        <div className="absolute -top-10 -right-10 w-48 h-48 bg-white/5 rounded-full blur-3xl"></div>
        <div className="max-w-4xl mx-auto flex items-center gap-5 relative z-10">
          <div className="relative">
            <div className="w-16 h-16 md:w-24 md:h-24 rounded-2xl border-2 border-white/20 overflow-hidden bg-tea-800 flex items-center justify-center shadow-lg">
              {customer.profilePhoto ? (
                <img src={customer.profilePhoto} className="w-full h-full object-cover" alt="Perfil" />
              ) : (
                <span className="text-3xl font-serif">{customer.name.charAt(0)}</span>
              )}
            </div>
            <label className="absolute -bottom-1 -right-1 bg-white p-1.5 rounded-lg shadow-md cursor-pointer">
              <svg className="w-3 h-3 text-tea-800" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path></svg>
              <input type="file" className="hidden" onChange={handlePhotoUpload} />
            </label>
          </div>
          <div>
             <p className="text-[10px] font-bold uppercase tracking-[0.2em] text-tea-300 mb-1">Área Exclusiva</p>
             <h1 className="text-2xl md:text-3xl font-serif font-bold italic leading-tight">Olá, {customer.name.split(' ')[0]}</h1>
          </div>
        </div>
      </div>

      <div className="max-w-4xl mx-auto px-4 -mt-10 relative z-20 space-y-6">
