import React, { useState } from 'react';
import { SalonSettings, Service, TeamMember, BusinessHours } from '../types.ts';
import { db } from '../firebase.ts';
import { doc, setDoc, deleteDoc, updateDoc } from "firebase/firestore";

interface AdminSettingsViewProps {
  settings: SalonSettings;
  setSettings: (s: SalonSettings) => void;
  services: Service[];
  setServices: (s: Service[]) => void;
  customers: any[];
  bookings: any[];
  transactions: any[];
  onImport: (data: any) => void;
}

const AdminSettingsView: React.FC<AdminSettingsViewProps> = ({ 
  settings, 
  services = [],
}) => {
  const [newService, setNewService] = useState({ name: '', price: 0, duration: 30, description: '', isVisible: true });
  const [editingService, setEditingService] = useState<Service | null>(null);
  const [newMemberName, setNewMemberName] = useState('');

  const updateGlobalSettings = async (newSet: SalonSettings) => {
    await setDoc(doc(db, "settings", "main"), newSet);
  };

  const addTeamMember = () => {
    if (newMemberName.trim()) {
      const newMember: TeamMember = {
        id: Math.random().toString(36).substr(2, 9),
        name: newMemberName.trim(),
        assignedServiceIds: [],
        businessHours: { start: settings.businessHours.start, end: settings.businessHours.end },
        offDays: [0] // Domingo como folga padrão
      };
      const updated = { ...settings, teamMembers: [...settings.teamMembers, newMember] };
      updateGlobalSettings(updated);
      setNewMemberName('');
    }
  };

  const removeTeamMember = (id: string) => {
    if (confirm("Remover profissional?")) {
      const updated = { ...settings, teamMembers: settings.teamMembers.filter(m => m.id !== id) };
      updateGlobalSettings(updated);
    }
  };

  const updateMemberField = (memberId: string, field: keyof TeamMember, value: any) => {
    const updatedMembers = settings.teamMembers.map(m => {
      if (m.id === memberId) {
        return { ...m, [field]: value };
      }
      return m;
    });
    updateGlobalSettings({ ...settings, teamMembers: updatedMembers });
  };

  const toggleOffDay = (memberId: string, day: number) => {
    const member = settings.teamMembers.find(m => m.id === memberId);
    if (!member) return;
    const currentOffDays = member.offDays || [];
    const newOffDays = currentOffDays.includes(day)
      ? currentOffDays.filter(d => d !== day)
      : [...currentOffDays, day];
    updateMemberField(memberId, 'offDays', newOffDays);
  };

  const toggleServiceToMember = (memberId: string, serviceId: string) => {
    const member = settings.teamMembers.find(m => m.id === memberId);
    if (!member) return;
    const hasService = member.assignedServiceIds.includes(serviceId);
    const newServices = hasService 
      ? member.assignedServiceIds.filter(id => id !== serviceId)
      : [...member.assignedServiceIds, serviceId];
    updateMemberField(memberId, 'assignedServiceIds', newServices);
  };

  const addService = async () => {
    if (newService.name && newService.price > 0) {
      const id = Math.random().toString(36).substr(2, 9);
      await setDoc(doc(db, "services", id), { ...newService, id });
      setNewService({ name: '', price: 0, duration: 30, description: '', isVisible: true });
    }
  };

  const saveEditedService = async () => {
    if (editingService && editingService.name && editingService.price > 0) {
      const serviceRef = doc(db, "services", editingService.id);
      await updateDoc(serviceRef, {
        name: editingService.name,
        price: editingService.price,
        duration: editingService.duration,
        description: editingService.description
      });
      setEditingService(null);
    }
  };

  const toggleServiceVisibility = async (id: string, current: boolean) => {
    await setDoc(doc(db, "services", id), { isVisible: !current }, { merge: true });
  };

  const handleDeleteService = async (id: string) => {
    if (confirm("Tem certeza que deseja excluir permanentemente este serviço?")) {
      await deleteDoc(doc(db, "services", id));
    }
  };

  const weekDays = [
    { n: 0, label: 'Dom' },
    { n: 1, label: 'Seg' },
    { n: 2, label: 'Ter' },
    { n: 3, label: 'Qua' },
    { n: 4, label: 'Qui' },
    { n: 5, label: 'Sex' },
    { n: 6, label: 'Sáb' },
  ];

  return (
    <div className="space-y-12 pb-32 animate-fade-in">
      <div className="bg-tea-900 text-white p-10 rounded-[3rem] shadow-xl">
        <h2 className="text-3xl font-serif font-bold mb-2">Configurações Gerais</h2>
        <p className="text-tea-100 font-light text-sm italic">Defina as bases do seu salão e personalize a agenda individual de cada profissional.</p>
      </div>

      <section className="bg-white p-10 rounded-[3rem] border border-gray-100 shadow-sm">
        <h3 className="text-2xl font-serif text-tea-900 mb-8 italic tracking-tight flex items-center gap-3">
          <span className="text-3xl">🏢</span> Horário do Salão (Geral)
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="space-y-2">
             <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Abertura Máxima</label>
             <input type="time" className="w-full p-5 bg-gray-50 rounded-2xl border-none font-bold" value={settings.businessHours.start} onChange={e => updateGlobalSettings({...settings, businessHours: {...settings.businessHours, start: e.target.value}})} />
          </div>
          <div className="space-y-2">
             <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Fechamento Máximo</label>
             <input type="time" className="w-full p-5 bg-gray-50 rounded-2xl border-none font-bold" value={settings.businessHours.end} onChange={e => updateGlobalSettings({...settings, businessHours: {...settings.businessHours, end: e.target.value}})} />
          </div>
        </div>
        <p className="mt-6 text-[11px] text-gray-400 italic">* Este horário define o limite máximo de exibição da agenda no site.</p>
      </section>

      <section className="bg-white p-10 rounded-[3rem] border border-gray-100 shadow-sm">
        <h3 className="text-2xl font-serif text-tea-900 mb-8 italic tracking-tight flex items-center gap-3">
           <span className="text-3xl">👥</span> Gestão da Equipe & Agendas
        </h3>
        <div className="flex gap-4 mb-10">
          <input placeholder="Nome da nova profissional..." className="flex-grow p-5 bg-gray-50 rounded-2xl font-bold outline-none shadow-inner" value={newMemberName} onChange={e => setNewMemberName(e.target.value)} />
          <button onClick={addTeamMember} className="bg-tea-800 text-white px-10 py-5 rounded-2xl font-bold hover:bg-tea-950 transition-colors shadow-lg">Adicionar</button>
        </div>

        <div className="space-y-8">
          {settings.teamMembers.map(member => (
            <div key={member.id} className="p-8 border-2 border-gray-50 rounded-[2.5rem] bg-white shadow-sm hover:border-tea-100 transition-all space-y-8">
              <div className="flex justify-between items-center border-b border-gray-50 pb-6">
                <div>
                  <span className="font-serif font-bold text-2xl text-tea-950">{member.name}</span>
                  <p className="text-[10px] text-tea-600 font-bold uppercase tracking-widest mt-1">Configurações de Disponibilidade</p>
                </div>
                <button onClick={() => removeTeamMember(member.id)} className="text-red-400 text-xs font-bold uppercase tracking-widest hover:text-red-600 p-3 bg-red-50 rounded-xl">Remover do Time</button>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                {/* Horários e Folgas */}
                <div className="space-y-6">
                  <div>
                    <h4 className="text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-4">⏰ Horário de Trabalho Individual</h4>
                    <div className="flex items-center gap-4">
                      <input 
                        type="time" 
                        className="flex-1 p-4 bg-gray-50 rounded-xl border-none font-bold text-sm" 
                        value={member.businessHours?.start || settings.businessHours.start} 
                        onChange={e => updateMemberField(member.id, 'businessHours', { ... (member.businessHours || settings.businessHours), start: e.target.value })} 
                      />
                      <span className="text-gray-300">até</span>
                      <input 
                        type="time" 
                        className="flex-1 p-4 bg-gray-50 rounded-xl border-none font-bold text-sm" 
                        value={member.businessHours?.end || settings.businessHours.end} 
                        onChange={e => updateMemberField(member.id, 'businessHours', { ... (member.businessHours || settings.businessHours), end: e.target.value })} 
                      />
                    </div>
                  </div>

                  <div>
                    <h4 className="text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-4">📅 Dias de Folga (Bloqueados)</h4>
                    <div className="flex flex-wrap gap-2">
                      {weekDays.map(day => (
                        <button 
                          key={day.n}
                          onClick={() => toggleOffDay(member.id, day.n)}
                          className={`px-4 py-2 rounded-xl text-[10px] font-bold border-2 transition-all ${member.offDays?.includes(day.n) ? 'bg-red-500 border-red-500 text-white' : 'bg-tea-50 border-tea-100 text-tea-700 hover:bg-tea-100'}`}
                        >
                          {day.label}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>

                {/* Serviços Autorizados */}
                <div className="space-y-6">
                  <h4 className="text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-4">💅 Serviços que realiza</h4>
                  <div className="flex flex-wrap gap-2">
                    {services.map(s => (
                      <button 
                        key={s.id} 
                        onClick={() => toggleServiceToMember(member.id, s.id)} 
                        className={`px-4 py-2 rounded-xl text-[10px] font-bold border-2 transition-all ${member.assignedServiceIds?.includes(s.id) ? 'bg-tea-800 border-tea-800 text-white' : 'bg-gray-50 border-gray-100 text-gray-400 hover:bg-gray-100'}`}
                      >
                        {s.name}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>

      <section className="bg-white p-10 rounded-[3rem] border border-gray-100 shadow-sm">
        <h3 className="text-2xl font-serif text-tea-900 mb-8 italic tracking-tight flex items-center gap-3">
           <span className="text-3xl">📋</span> Catálogo de Serviços
        </h3>

        {/* Formulário de Novo Serviço */}
        <div className="bg-tea-50/50 p-8 rounded-3xl mb-10 border border-tea-100">
           <h4 className="text-[10px] font-bold text-tea-700 uppercase tracking-widest mb-6 ml-1">Criar Novo Procedimento</h4>
           <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
              <input placeholder="Ex: Micropigmentação" className="p-4 rounded-xl bg-white outline-none font-bold shadow-inner" value={newService.name} onChange={e => setNewService({...newService, name: e.target.value})} />
              <input type="number" placeholder="Preço Base R$" className="p-4 rounded-xl bg-white outline-none font-bold shadow-inner" value={newService.price || ''} onChange={e => setNewService({...newService, price: parseFloat(e.target.value)})} />
              <input type="number" placeholder="Minutos (aprox)" className="p-4 rounded-xl bg-white outline-none font-bold shadow-inner" value={newService.duration || ''} onChange={e => setNewService({...newService, duration: parseInt(e.target.value)})} />
           </div>
           <button onClick={addService} className="w-full bg-tea-800 text-white py-5 rounded-2xl font-bold uppercase tracking-widest text-[11px] hover:bg-tea-950 transition-all shadow-lg">Salvar Novo Procedimento</button>
        </div>

        {/* Listagem de Serviços */}
        <div className="space-y-4">
          {services.map(s => (
            <div key={s.id} className={`p-6 border-2 rounded-3xl flex justify-between items-center transition-all ${s.isVisible ? 'border-gray-50 hover:bg-gray-50/30' : 'bg-red-50/10 opacity-60 border-transparent'}`}>
              <div>
                <p className="font-bold text-lg text-tea-950">{s.name}</p>
                <p className="text-[10px] text-gray-400 font-bold uppercase">R$ {s.price.toFixed(2)} • {s.duration} min</p>
              </div>
              <div className="flex gap-2 items-center">
                <button 
                  onClick={() => setEditingService(s)} 
                  className="p-3 bg-white text-tea-600 rounded-xl border border-tea-50 hover:border-tea-200 transition-all shadow-sm"
                  title="Editar Serviço"
                >
                  ✏️
                </button>
                <button 
                  onClick={() => toggleServiceVisibility(s.id, s.isVisible)} 
                  className={`px-6 py-3 rounded-xl text-[10px] font-bold border-2 transition-all ${s.isVisible ? 'bg-white text-tea-700 border-tea-100 hover:bg-tea-50' : 'bg-tea-800 text-white border-tea-800 hover:bg-tea-900'}`}
                >
                  {s.isVisible ? 'OCULTAR' : 'EXIBIR'}
                </button>
                <button onClick={() => handleDeleteService(s.id)} className="p-3 text-red-200 hover:text-red-500 transition-colors">🗑️</button>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Modal de Edição de Serviço */}
      {editingService && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
          <div className="bg-white w-full max-w-lg rounded-[3rem] p-10 shadow-2xl animate-slide-up">
            <h3 className="text-2xl font-serif text-tea-900 mb-8 italic">Editar Procedimento</h3>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Nome do Procedimento</label>
                <input 
                  className="w-full p-4 rounded-2xl bg-gray-50 border-2 border-transparent focus:border-tea-200 focus:bg-white outline-none font-bold transition-all"
                  value={editingService.name}
                  onChange={e => setEditingService({...editingService, name: e.target.value})}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Preço Base R$</label>
                  <input 
                    type="number"
                    className="w-full p-4 rounded-2xl bg-gray-50 border-2 border-transparent focus:border-tea-200 focus:bg-white outline-none font-bold transition-all"
                    value={editingService.price}
                    onChange={e => setEditingService({...editingService, price: parseFloat(e.target.value)})}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Duração (Min)</label>
                  <input 
                    type="number"
                    className="w-full p-4 rounded-2xl bg-gray-50 border-2 border-transparent focus:border-tea-200 focus:bg-white outline-none font-bold transition-all"
                    value={editingService.duration}
                    onChange={e => setEditingService({...editingService, duration: parseInt(e.target.value)})}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Descrição curta</label>
                <textarea 
                  className="w-full p-4 rounded-2xl bg-gray-50 border-2 border-transparent focus:border-tea-200 focus:bg-white outline-none transition-all resize-none h-24"
                  value={editingService.description}
                  onChange={e => setEditingService({...editingService, description: e.target.value})}
                />
              </div>

              <div className="flex gap-4 pt-4">
                <button 
                  onClick={() => setEditingService(null)} 
                  className="flex-1 py-4 text-gray-400 font-bold hover:text-gray-600 transition-colors"
                >
                  Cancelar
                </button>
                <button 
                  onClick={saveEditedService}
                  className="flex-[2] bg-tea-800 text-white py-4 rounded-2xl font-bold shadow-xl hover:bg-tea-950 transition-all"
                >
                  Salvar Alterações
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminSettingsView;

import React, { useState, useEffect, useMemo } from 'react';
import { SalonSettings, Service, Customer, Booking, TeamMember } from '../types.ts';

interface CustomerHomeProps {
  settings: SalonSettings;
  services: Service[];
  bookings: Booking[];
  onBook: (serviceId: string, dateTime: string, teamMemberId?: string) => void;
  onAuthClick: () => void;
  onAddToWaitlist: (serviceId: string, date: string) => void;
  currentUser: Customer | null;
}

const CustomerHome: React.FC<CustomerHomeProps> = ({ settings, services, bookings, onBook, onAuthClick, onAddToWaitlist, currentUser }) => {
  const [formData, setFormData] = useState({ name: '', whatsapp: '', message: '' });
  const [bookingModal, setBookingModal] = useState<{ open: boolean; service: Service | null; step: 1 | 2 | 3 }>({ open: false, service: null, step: 1 });

  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedTime, setSelectedTime] = useState<string>('');
  const [selectedProfessional, setSelectedProfessional] = useState<string>('');

  useEffect(() => {
    if (currentUser) {
      setFormData(prev => ({ ...prev, name: currentUser.name, whatsapp: currentUser.whatsapp }));
    }
  }, [currentUser]);

  // Gera todos os horários possíveis baseados no funcionamento GLOBAL do salão
  const allPossibleSlots = useMemo(() => {
    const slots: string[] = [];
    const start = parseInt((settings.businessHours?.start || "08:00").split(':')[0]);
    const end = parseInt((settings.businessHours?.end || "19:00").split(':')[0]);

    for (let h = start; h < end; h++) {
      slots.push(`${h.toString().padStart(2, '0')}:00`);
      slots.push(`${h.toString().padStart(2, '0')}:30`);
    }
    return slots;
  }, [settings.businessHours]);

  // Filtra profissionais que fazem o serviço selecionado
  const professionalsForService = useMemo(() => {
    if (!bookingModal.service) return [];
    return settings.teamMembers.filter(m => m.assignedServiceIds.includes(bookingModal.service!.id));
  }, [bookingModal.service, settings.teamMembers]);

  // Verifica disponibilidade considerando horário individual e folgas
  const slotsAvailability = useMemo(() => {
    if (!bookingModal.service) return {};

    const availability: Record<string, TeamMember[]> = {};
    const dateObj = new Date(selectedDate + 'T12:00:00'); // Evita problemas de fuso
    const dayOfWeek = dateObj.getDay(); // 0=Domingo, 1=Segunda...

    allPossibleSlots.forEach(slot => {
      const fullDateTime = `${selectedDate} ${slot}`;

      // Encontra profissionais livres, dentro de seus horários e fora de suas folgas
      const freePros = professionalsForService.filter(pro => {
        // 1. Verifica se é dia de folga da profissional
        if (pro.offDays?.includes(dayOfWeek)) return false;

        // 2. Verifica se o horário está dentro do horário de trabalho individual dela
        const proStart = pro.businessHours?.start || settings.businessHours.start;
        const proEnd = pro.businessHours?.end || settings.businessHours.end;
        if (slot < proStart || slot >= proEnd) return false;

        // 3. Verifica se ela já tem compromisso ou bloqueio
        const isOccupied = bookings.some(b => 
          b.teamMemberId === pro.id && 
          b.dateTime === fullDateTime && 
          b.status !== 'cancelled'
        );
        return !isOccupied;
      });

      if (freePros.length > 0) {
        availability[slot] = freePros;
      }
    });

    return availability;
  }, [allPossibleSlots, selectedDate, professionalsForService, bookings, bookingModal.service, settings.businessHours]);

  const handleTimeSelect = (time: string) => {
    setSelectedTime(time);
    setBookingModal(prev => ({ ...prev, step: 2 }));
  };

  const confirmBooking = () => {
    if (bookingModal.service && selectedProfessional && selectedTime) {
      const fullDateTime = `${selectedDate} ${selectedTime}`;
      onBook(bookingModal.service.id, fullDateTime, selectedProfessional);
      setBookingModal({ ...bookingModal, step: 3 });
    }
  };

  const scrollToId = (id: string) => {
    const element = document.getElementById(id);
    if (element) element.scrollIntoView({ behavior: 'smooth' });
  };

  const handleContactSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const message = `Olá! Me chamo ${formData.name}. ${formData.message}`;
    window.open(`https://wa.me/${settings.socialLinks.whatsapp.replace(/\D/g, '')}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="animate-fade-in bg-white text-gray-900">
      {/* Hero Section */}
      <section className="relative min-h-[95vh] flex flex-col items-center justify-center force-brand-bg bg-tea-900 overflow-hidden px-4">
        <div className="relative z-10 w-full max-w-7xl mx-auto flex flex-col items-center -mt-24 md:-mt-36">
          <div className="mb-6 md:mb-10">
            <img src={settings.logo} className="h-[12rem] md:h-[22rem] lg:h-[32rem] w-auto drop-shadow-[0_45px_100px_rgba(0,0,0,0.6)] object-contain animate-float" alt="Logo Studio Moriá" />
          </div>
          <div className="text-center">
            <h2 className="text-3xl md:text-5xl lg:text-7xl font-serif text-white mb-10 italic tracking-tight leading-tight max-w-4xl mx-auto px-4">Cuidando do seu bem estar</h2>
            <div className="flex flex-col items-center gap-4 w-full max-w-xs mx-auto">
              <button onClick={() => scrollToId('procedimentos')} className="w-full bg-white text-tea-900 px-8 py-5 rounded-full font-bold shadow-2xl uppercase tracking-widest hover:scale-105 hover:bg-tea-50 transition-all text-[11px]">Ver Serviços</button>
              <button onClick={() => currentUser ? scrollToId('procedimentos') : onAuthClick()} className="w-full bg-tea-800 text-white border-2 border-tea-700 px-8 py-5 rounded-full font-bold uppercase tracking-widest hover:bg-tea-950 transition-all text-[11px] shadow-xl">Agendar Agora</button>
              <button onClick={() => scrollToId('contato')} className="w-full bg-transparent text-white border-2 border-white/20 px-8 py-5 rounded-full font-bold uppercase tracking-widest hover:bg-white/10 transition-all text-[11px]">Fale Conosco</button>
            </div>
          </div>
        </div>
        <div className="absolute inset-0 opacity-10 pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/pinstriped-suit.png')]"></div>
      </section>

      {/* Procedimentos Section */}
      <section id="procedimentos" className="max-w-7xl mx-auto px-4 py-24 bg-white">
        <div className="text-center mb-16">
          <h2 className="text-4xl font-serif text-gray-900 mb-4">Procedimentos</h2>
          <div className="h-1 w-20 bg-tea-600 mx-auto rounded-full"></div>
          <p className="mt-4 text-xs text-gray-400 font-medium italic">*Valores podem variar sob consulta profissional</p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {services.filter(s => s.isVisible).map(service => (
            <div key={service.id} className="bg-gray-50 p-8 rounded-[2.5rem] flex flex-col justify-between border-2 border-transparent hover:border-tea-100 hover:bg-white transition-all group shadow-sm">
              <div>
                <h3 className="text-xl font-serif font-bold text-tea-950 mb-4">{service.name}</h3>
                <p className="text-gray-500 text-sm font-light mb-8 line-clamp-3 leading-relaxed">{service.description}</p>
                {currentUser && (
                  <div className="mb-6">
                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest mb-1">A partir de</p>
                    <p className="text-tea-800 font-bold text-2xl">R$ {service.price.toFixed(2)}</p>
                  </div>
                )}
              </div>
              <button onClick={() => { if(!currentUser) onAuthClick(); else setBookingModal({open: true, service, step: 1}); }} className="w-full py-4 rounded-xl border border-tea-100 text-tea-700 font-bold uppercase tracking-widest text-xs hover:bg-tea-800 hover:text-white transition-all">Ver Horários</button>
            </div>
          ))}
        </div>
      </section>

      {/* Contato Section */}
      <section id="contato" className="bg-tea-50 py-24 px-4">
        <div className="max-w-4xl mx-auto text-center">
           <h2 className="text-4xl font-serif text-tea-900 mb-4">Fale Conosco</h2>
           <div className="bg-white p-10 md:p-16 rounded-[4rem] shadow-2xl border border-white mt-10">
            <form onSubmit={handleContactSubmit} className="space-y-8 text-left">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <input required placeholder="Seu nome" className="w-full px-8 py-5 rounded-3xl bg-gray-50 border-none outline-none shadow-inner" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} />
                <input required placeholder="Seu WhatsApp" className="w-full px-8 py-5 rounded-3xl bg-gray-50 border-none outline-none shadow-inner" value={formData.whatsapp} onChange={(e) => setFormData({...formData, whatsapp: e.target.value})} />
              </div>
              <textarea required rows={4} placeholder="Como podemos ajudar?" className="w-full px-8 py-5 rounded-3xl bg-gray-50 border-none outline-none shadow-inner resize-none" value={formData.message} onChange={(e) => setFormData({...formData, message: e.target.value})}></textarea>
              <button type="submit" className="w-full bg-tea-800 text-white py-6 rounded-3xl font-bold text-xl shadow-xl hover:bg-tea-900 transition-all">Enviar via WhatsApp</button>
            </form>
           </div>
        </div>
      </section>

      {/* MODAL DE AGENDAMENTO COM GRADE DE HORÁRIOS */}
      {bookingModal.open && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white w-full max-w-xl rounded-[3rem] p-8 shadow-2xl animate-slide-up max-h-[90vh] overflow-y-auto custom-scroll">

            {/* Passo 1: Seleção de Data e Horário (A Grade) */}
            {bookingModal.step === 1 && (
              <div className="space-y-6">
                <div className="flex justify-between items-center mb-4">
                  <h3 className="text-2xl font-serif text-tea-900">Horários Disponíveis</h3>
                  <button onClick={() => setBookingModal({open: false, service: null, step: 1})} className="text-gray-400 hover:text-tea-800 text-2xl">&times;</button>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Selecione o Dia</label>
                  <input 
                    type="date" 
                    value={selectedDate} 
                    onChange={(e) => { setSelectedDate(e.target.value); setSelectedTime(''); }} 
                    className="w-full p-4 border-2 border-tea-50 rounded-2xl outline-none focus:border-tea-200 transition-all font-bold text-tea-900" 
                    min={new Date().toISOString().split('T')[0]} 
                  />
                </div>

                <div className="space-y-4">
                   <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Horários para {bookingModal.service?.name}</label>
                   <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
                      {allPossibleSlots.map(slot => {
                        const isAvailable = !!slotsAvailability[slot];
                        return (
                          <button 
                            key={slot}
                            disabled={!isAvailable}
                            onClick={() => handleTimeSelect(slot)}
                            className={`p-4 rounded-2xl text-xs font-bold transition-all border-2 ${
                              isAvailable 
                              ? 'bg-tea-50 border-tea-100 text-tea-800 hover:bg-tea-800 hover:text-white hover:scale-105' 
                              : 'bg-gray-50 border-transparent text-gray-300 cursor-not-allowed line-through'
                            }`}
                          >
                            {slot}
                          </button>
                        );
                      })}
                   </div>
                </div>

                {Object.keys(slotsAvailability).length === 0 && (
                  <div className="bg-orange-50 p-6 rounded-3xl border border-orange-100 text-center space-y-3">
                    <p className="text-orange-800 font-bold text-sm">Poxa, sem horários para este dia!</p>
                    <button 
                      onClick={() => onAddToWaitlist(bookingModal.service!.id, selectedDate)}
                      className="text-[10px] bg-orange-600 text-white px-4 py-2 rounded-full font-bold uppercase tracking-widest"
                    >
                      Entrar na Lista de Espera
                    </button>
                  </div>
                )}
              </div>
            )}

            {/* Passo 2: Seleção de Profissional */}
            {bookingModal.step === 2 && (
              <div className="space-y-8">
                <div className="text-center">
                  <h3 className="text-2xl font-serif text-tea-900 mb-2">Com quem deseja agendar?</h3>
                  <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">Horário: {selectedDate} às {selectedTime}</p>
                </div>

                <div className="space-y-3">
                   {slotsAvailability[selectedTime]?.map(pro => (
                     <button 
                        key={pro.id} 
                        onClick={() => setSelectedProfessional(pro.id)}
                        className={`w-full p-6 rounded-3xl border-2 transition-all flex items-center gap-4 ${
                          selectedProfessional === pro.id 
                          ? 'border-tea-600 bg-tea-50' 
                          : 'border-gray-50 bg-gray-50 hover:border-tea-200'
                        }`}
                     >
                        <div className="w-12 h-12 bg-tea-800 text-white rounded-2xl flex items-center justify-center font-bold text-xl">{pro.name.charAt(0)}</div>
                        <div className="text-left">
                          <p className="font-bold text-tea-950">{pro.name}</p>
                          <p className="text-[10px] text-tea-600 uppercase font-bold tracking-tighter">Disponível</p>
                        </div>
                     </button>
                   ))}
                </div>

                <div className="bg-orange-50 p-5 rounded-3xl border border-orange-100">
                  <p className="text-[10px] text-orange-700 font-bold uppercase tracking-widest mb-1">⚠️ Aviso de Garantia</p>
                  <p className="text-[11px] text-orange-800 leading-relaxed">Seu agendamento só será validado após a análise da equipe e o pagamento do sinal.</p>
                </div>

                <div className="flex gap-4">
                   <button onClick={() => setBookingModal(prev => ({ ...prev, step: 1 }))} className="flex-1 py-4 text-gray-400 font-bold">Voltar</button>
                   <button 
                    onClick={confirmBooking} 
                    disabled={!selectedProfessional}
                    className="flex-[2] bg-tea-800 text-white py-4 rounded-2xl font-bold shadow-xl disabled:opacity-50"
                   >
                     Solicitar Agendamento
                   </button>
                </div>
              </div>
            )}

            {/* Passo 3: Feedback de Envio */}
            {bookingModal.step === 3 && (
              <div className="text-center py-10 space-y-6">
                <div className="w-24 h-24 bg-tea-50 text-tea-600 rounded-full flex items-center justify-center text-5xl mx-auto animate-bounce">⏳</div>
                <h3 className="text-3xl font-serif text-tea-900 font-bold italic">Quase lá!</h3>
                <p className="text-gray-500 text-sm leading-relaxed px-4">
                  Sua solicitação para <b>{bookingModal.service?.name}</b> foi enviada. <br/><br/>
                  Para garantir sua vaga, envie agora o <b>comprovante do sinal</b> clicando no botão abaixo.
                </p>
                <button 
                  onClick={() => {
                    const msg = `Olá Studio Moriá! Solicitei ${bookingModal.service?.name} para ${selectedDate} às ${selectedTime}. Segue o comprovante do sinal.`;
                    window.open(`https://wa.me/${settings.socialLinks.whatsapp.replace(/\D/g, '')}?text=${encodeURIComponent(msg)}`, '_blank');
                    setBookingModal({open: false, service: null, step: 1});
                  }}
                  className="w-full bg-tea-800 text-white py-6 rounded-3xl font-bold shadow-2xl flex items-center justify-center gap-4 hover:scale-105 transition-transform"
                >
                  Confirmar via WhatsApp 📱
                </button>
                <button onClick={() => setBookingModal({open: false, service: null, step: 1})} className="text-xs text-gray-400 font-bold uppercase tracking-widest hover:text-tea-800">Fechar e ver depois</button>
              </div>
            )}
          </div>
        </div>
      )}

      <style>{`
        @keyframes float { 0% { transform: translateY(0px); } 50% { transform: translateY(-20px); } 100% { transform: translateY(0px); } }
        .animate-float { animation: float 7s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

