import React, { useState } from 'react';
import { Booking, Service, TeamMember, SalonSettings } from '../types';

interface AdminCalendarProps {
  bookings: Booking[];
  setBookings: React.Dispatch<React.SetStateAction<Booking[]>>;
  services: Service[];
  teamMembers: TeamMember[];
  settings?: SalonSettings; 
}

const AdminCalendar: React.FC<AdminCalendarProps> = ({ bookings, setBookings, services, teamMembers, settings }) => {
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedProId, setSelectedProId] = useState(teamMembers[0]?.id || '');

  const selectedPro = teamMembers.find(m => m.id === selectedProId);
  const startHour = settings?.businessHours?.start || "08:00";
  const endHour = settings?.businessHours?.end || "19:00";

  const dateObj = new Date(selectedDate + 'T12:00:00');
  const dayOfWeek = dateObj.getDay();

  const hours = Array.from({ length: 30 }, (_, i) => {
    const totalMinutes = 7 * 60 + i * 30; // Começa as 07:00
    const h = Math.floor(totalMinutes / 60);
    const m = totalMinutes % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  });

  const blockSlot = (hour: string) => {
    const dateTime = `${selectedDate} ${hour}`;
    if (!selectedPro) return;

    if (bookings.some(b => b.teamMemberId === selectedProId && b.dateTime === dateTime && b.status !== 'cancelled')) return;

    const newBlocked: Booking = {
      id: Math.random().toString(36).substr(2, 9),
      customerId: 'admin-block',
      customerName: 'HORÁRIO BLOQUEADO',
      serviceId: 'block',
      serviceName: 'Indisponível (Folga/Pausa)',
      teamMemberId: selectedProId,
      teamMemberName: selectedPro.name,
      dateTime: dateTime,
      status: 'blocked',
      depositStatus: 'paid'
    };
    setBookings(prev => [...prev, newBlocked]);
  };

  const massBlock = (type: 'day' | 'morning' | 'afternoon') => {
    if (!selectedPro) return;

    let targetHours: string[] = [];
    if (type === 'day') targetHours = hours;
    if (type === 'morning') targetHours = hours.filter(h => h < "12:00");
    if (type === 'afternoon') targetHours = hours.filter(h => h >= "12:00");

    const newBlocks: Booking[] = targetHours
      .filter(hour => !bookings.some(b => b.teamMemberId === selectedProId && b.dateTime === `${selectedDate} ${hour}` && b.status !== 'cancelled'))
      .map(hour => ({
        id: Math.random().toString(36).substr(2, 9),
        customerId: 'admin-block',
        customerName: 'HORÁRIO BLOQUEADO',
        serviceId: 'block',
        serviceName: 'Bloqueio em Massa',
        teamMemberId: selectedProId,
        teamMemberName: selectedPro.name,
        dateTime: `${selectedDate} ${hour}`,
        status: 'blocked',
        depositStatus: 'paid'
      }));

    setBookings(prev => [...prev, ...newBlocks]);
    alert(`Bloqueio realizado com sucesso!`);
  };

  const removeBlock = (id: string) => {
    setBookings(prev => prev.filter(b => b.id !== id));
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm">
        <div className="flex flex-wrap gap-4 items-center">
          <div className="space-y-1">
            <label className="text-[10px] font-bold text-gray-400 uppercase ml-2 tracking-widest">Data Agenda</label>
            <input type="date" value={selectedDate} onChange={(e) => setSelectedDate(e.target.value)} className="p-3 bg-gray-50 border-2 border-transparent focus:border-tea-200 rounded-xl outline-none text-sm font-bold" />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-bold text-gray-400 uppercase ml-2 tracking-widest">Profissional</label>
            <select value={selectedProId} onChange={(e) => setSelectedProId(e.target.value)} className="p-3 bg-gray-50 border-2 border-transparent focus:border-tea-200 rounded-xl outline-none text-sm font-bold">
              {teamMembers.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
            </select>
          </div>
        </div>

        <div className="flex flex-wrap gap-2">
          <button onClick={() => massBlock('morning')} className="px-4 py-2 bg-tea-50 text-tea-700 text-[10px] font-bold rounded-lg hover:bg-tea-100 transition-all uppercase tracking-widest border border-tea-100">Bloquear Manhã</button>
          <button onClick={() => massBlock('afternoon')} className="px-4 py-2 bg-tea-50 text-tea-700 text-[10px] font-bold rounded-lg hover:bg-tea-100 transition-all uppercase tracking-widest border border-tea-100">Bloquear Tarde</button>
          <button onClick={() => massBlock('day')} className="px-4 py-2 bg-tea-800 text-white text-[10px] font-bold rounded-lg hover:bg-tea-950 transition-all uppercase tracking-widest shadow-lg">Bloquear Dia</button>
        </div>
      </div>

      {selectedPro?.offDays?.includes(dayOfWeek) && (
        <div className="bg-red-50 p-6 rounded-3xl border border-red-100 text-center animate-pulse">
           <p className="text-red-800 font-bold text-sm">🗓️ HOJE É FOLGA DE {selectedPro.name.toUpperCase()}!</p>
           <p className="text-red-600 text-[10px] font-medium uppercase mt-1 tracking-widest">A agenda está bloqueada para clientes neste dia.</p>
        </div>
      )}

      <div className="bg-white rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden divide-y divide-gray-50">
        <div className="bg-gray-50 px-8 py-4 flex justify-between items-center">
           <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Agenda Individual</span>
           <div className="flex gap-4">
              <span className="text-[10px] font-bold text-tea-600 uppercase tracking-widest">Turno: {selectedPro?.businessHours?.start || startHour} - {selectedPro?.businessHours?.end || endHour}</span>
           </div>
        </div>

        {hours.map(hour => {
          const booking = bookings.find(b => b.teamMemberId === selectedProId && b.dateTime === `${selectedDate} ${hour}` && b.status !== 'cancelled');

          const proStart = selectedPro?.businessHours?.start || startHour;
          const proEnd = selectedPro?.businessHours?.end || endHour;
          const isOutsideProHours = hour < proStart || hour >= proEnd;
          const isFolga = selectedPro?.offDays?.includes(dayOfWeek);

          return (
            <div key={hour} className={`flex items-center p-6 transition-all ${(isOutsideProHours || isFolga) ? 'bg-gray-50/40 opacity-60' : 'hover:bg-gray-50/30'}`}>
              <div className="w-24 font-serif font-bold text-tea-900 text-lg border-r border-gray-100 pr-6 relative">
                 {hour}
                 {(isOutsideProHours || isFolga) && <span className="absolute -bottom-4 left-0 text-[8px] text-red-400 font-bold uppercase tracking-tighter">{isFolga ? 'FOLGA' : 'FORA TURNO'}</span>}
              </div>
              <div className="flex-grow pl-8">
                {booking ? (
                  <div className={`p-5 rounded-[1.5rem] flex justify-between items-center shadow-sm ${booking.status === 'blocked' ? 'bg-white border-2 border-gray-100' : 'bg-tea-50 border-l-4 border-tea-600'}`}>
                    <div>
                      <div className="flex items-center gap-2">
                         <p className={`font-bold text-sm ${booking.status === 'blocked' ? 'text-gray-400 italic' : 'text-tea-950'}`}>{booking.customerName}</p>
                         {booking.status === 'blocked' && <span className="text-[8px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded-full font-bold">BLOQUEADO</span>}
                      </div>
                      <p className="text-[10px] text-tea-700 font-medium uppercase tracking-tight mt-0.5">{booking.serviceName}</p>
                    </div>
                    <div className="flex gap-2">
                       {booking.status === 'blocked' ? (
                         <button onClick={() => removeBlock(booking.id)} className="px-4 py-2 bg-white border border-gray-200 rounded-xl text-[9px] font-bold text-tea-600 hover:border-tea-300 transition-all uppercase tracking-widest shadow-sm">Liberar</button>
                       ) : (
                         <div className="text-right">
                           <p className="text-[9px] font-bold text-tea-500 uppercase tracking-widest">Agendado</p>
                           <p className="text-[8px] text-gray-400">{booking.status}</p>
                         </div>
                       )}
                    </div>
                  </div>
                ) : (
                  <button 
                    onClick={() => blockSlot(hour)} 
                    className={`w-full text-left py-5 px-8 border-2 border-dashed rounded-[1.5rem] text-[10px] font-medium uppercase tracking-widest transition-all ${isOutsideProHours || isFolga ? 'border-red-100 text-red-300' : 'border-gray-50 text-gray-400 hover:border-tea-100 hover:text-tea-600 hover:bg-white'}`}
                  >
                    {isFolga ? '🚫 Profissional de Folga • Clique para forçar bloqueio' : isOutsideProHours ? '🚫 Horário Individual Indisponível • Bloquear' : '➕ Horário Livre • Clique para Bloquear'}
                  </button>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default AdminCalendar;

import React, { useState } from 'react';
import { Booking, Service, TeamMember, SalonSettings } from '../types';
import { db } from '../firebase.ts';
import { collection, addDoc, deleteDoc, doc } from "firebase/firestore";

interface AdminCalendarProps {
  bookings: Booking[];
  setBookings?: React.Dispatch<React.SetStateAction<Booking[]>>;
  services: Service[];
  teamMembers: TeamMember[];
  settings?: SalonSettings; 
}

const AdminCalendar: React.FC<AdminCalendarProps> = ({ bookings, services, teamMembers, settings }) => {
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedProId, setSelectedProId] = useState(teamMembers[0]?.id || '');

  const selectedPro = teamMembers.find(m => m.id === selectedProId);
  const startHour = settings?.businessHours?.start || "08:00";
  const endHour = settings?.businessHours?.end || "19:00";

  const dateObj = new Date(selectedDate + 'T12:00:00');
  const dayOfWeek = dateObj.getDay();

  // Gera horários de 30 em 30 min das 07:00 as 21:00 para controle total
  const timeSlots = Array.from({ length: 29 }, (_, i) => {
    const totalMinutes = 7 * 60 + i * 30; 
    const h = Math.floor(totalMinutes / 60);
    const m = totalMinutes % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  });

  const toggleSlot = async (hour: string) => {
    const dateTime = `${selectedDate} ${hour}`;
    if (!selectedPro) return;

    const existing = bookings.find(b => 
      b.teamMemberId === selectedProId && 
      b.dateTime === dateTime && 
      b.status !== 'cancelled'
    );

    if (existing) {
      if (existing.status === 'blocked') {
        // Se estava bloqueado, libera (deleta o registro de bloqueio)
        await deleteDoc(doc(db, "bookings", existing.id));
      } else {
        // Se for um agendamento real, não permite alternar por aqui para evitar erros
        alert("Este horário possui um agendamento. Use a aba de Confirmações para gerenciar o cliente.");
      }
    } else {
      // Se estava livre, bloqueia
      const newBlocked = {
        customerId: 'admin-block',
        customerName: 'HORÁRIO BLOQUEADO',
        serviceId: 'block',
        serviceName: 'Indisponível (Pausa/Bloqueio)',
        teamMemberId: selectedProId,
        teamMemberName: selectedPro.name,
        dateTime: dateTime,
        status: 'blocked',
        depositStatus: 'paid'
      };
      await addDoc(collection(db, "bookings"), newBlocked);
    }
  };

  const massAction = async (action: 'block' | 'open', period: 'all' | 'morning' | 'afternoon') => {
    if (!selectedPro) return;

    let targetHours = [...timeSlots];
    if (period === 'morning') targetHours = timeSlots.filter(h => h < "12:00");
    if (period === 'afternoon') targetHours = timeSlots.filter(h => h >= "12:00");

    for (const hour of targetHours) {
      const dateTime = `${selectedDate} ${hour}`;
      const existing = bookings.find(b => b.teamMemberId === selectedProId && b.dateTime === dateTime && b.status !== 'cancelled');

      if (action === 'block' && !existing) {
        await addDoc(collection(db, "bookings"), {
          customerId: 'admin-block',
          customerName: 'HORÁRIO BLOQUEADO',
          serviceId: 'block',
          serviceName: 'Bloqueio em Massa',
          teamMemberId: selectedProId,
          teamMemberName: selectedPro.name,
          dateTime: dateTime,
          status: 'blocked',
          depositStatus: 'paid'
        });
      } else if (action === 'open' && existing?.status === 'blocked') {
        await deleteDoc(doc(db, "bookings", existing.id));
      }
    }
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20 px-2 md:px-0">
      {/* Cabeçalho de Controle */}
      <div className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm space-y-8">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
          <div className="flex flex-wrap gap-4 items-center w-full md:w-auto">
            <div className="flex-1 md:flex-none">
              <label className="text-[10px] font-bold text-gray-400 uppercase ml-2 tracking-widest block mb-1">Selecione o Dia</label>
              <input 
                type="date" 
                value={selectedDate} 
                onChange={(e) => setSelectedDate(e.target.value)} 
                className="w-full p-4 bg-gray-50 border-2 border-transparent focus:border-tea-200 rounded-2xl outline-none font-bold text-tea-900" 
              />
            </div>
            <div className="flex-1 md:flex-none">
              <label className="text-[10px] font-bold text-gray-400 uppercase ml-2 tracking-widest block mb-1">Profissional</label>
              <select 
                value={selectedProId} 
                onChange={(e) => setSelectedProId(e.target.value)} 
                className="w-full p-4 bg-gray-50 border-2 border-transparent focus:border-tea-200 rounded-2xl outline-none font-bold text-tea-900"
              >
                {teamMembers.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
              </select>
            </div>
          </div>

          <div className="flex flex-wrap gap-2 w-full md:w-auto">
             <button onClick={() => massAction('block', 'all')} className="flex-1 md:flex-none px-6 py-4 bg-red-50 text-red-600 text-[10px] font-bold rounded-2xl hover:bg-red-100 transition-all uppercase tracking-widest border border-red-100">Bloquear Tudo</button>
             <button onClick={() => massAction('open', 'all')} className="flex-1 md:flex-none px-6 py-4 bg-tea-50 text-tea-700 text-[10px] font-bold rounded-2xl hover:bg-tea-100 transition-all uppercase tracking-widest border border-tea-100">Abrir Tudo</button>
          </div>
        </div>

        {selectedPro?.offDays?.includes(dayOfWeek) && (
          <div className="bg-orange-50 p-5 rounded-2xl border border-orange-100 flex items-center gap-4 animate-pulse">
            <span className="text-2xl">📅</span>
            <div>
              <p className="text-orange-800 font-bold text-sm uppercase">Atenção: Hoje é folga padrão de {selectedPro.name}</p>
              <p className="text-orange-600 text-[10px] font-medium leading-tight">A agenda para clientes está fechada. Você pode abrir horários específicos clicando neles abaixo se desejar realizar um atendimento extra.</p>
            </div>
          </div>
        )}
      </div>

      {/* Grade de Horários Estilo Seletor */}
      <div className="bg-white rounded-[3.5rem] shadow-sm border border-gray-100 overflow-hidden">
        <div className="bg-tea-900 text-white px-8 py-5 flex justify-between items-center">
           <div>
              <h3 className="font-serif font-bold italic text-lg">Gestão de Disponibilidade</h3>
              <p className="text-[9px] uppercase tracking-[0.2em] text-tea-300">Toque em um horário para abrir ou fechar</p>
           </div>
           <div className="hidden md:flex gap-6 items-center">
              <div className="flex items-center gap-2"><div className="w-3 h-3 rounded-full bg-white/20 border border-white/40"></div> <span className="text-[9px] font-bold uppercase">Livre</span></div>
              <div className="flex items-center gap-2"><div className="w-3 h-3 rounded-full bg-tea-500"></div> <span className="text-[9px] font-bold uppercase">Agendado</span></div>
              <div className="flex items-center gap-2"><div className="w-3 h-3 rounded-full bg-gray-200"></div> <span className="text-[9px] font-bold uppercase">Fechado</span></div>
           </div>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 p-8">
          {timeSlots.map(hour => {
            const booking = bookings.find(b => b.teamMemberId === selectedProId && b.dateTime === `${selectedDate} ${hour}` && b.status !== 'cancelled');

            const isBlocked = booking?.status === 'blocked';
            const isScheduled = booking && booking.status !== 'blocked';
            const proStart = selectedPro?.businessHours?.start || startHour;
            const proEnd = selectedPro?.businessHours?.end || endHour;
            const isOutsidePattern = hour < proStart || hour >= proEnd;
            const isStandardOffDay = selectedPro?.offDays?.includes(dayOfWeek);

            // Definindo se está efetivamente livre para o cliente
            const isEffectivelyFree = !booking && !isStandardOffDay && !isOutsidePattern;

            return (
              <button
                key={hour}
                onClick={() => toggleSlot(hour)}
                className={`relative group p-5 rounded-3xl border-2 transition-all flex flex-col items-center justify-center gap-1 ${
                  isScheduled 
                    ? 'bg-tea-600 border-tea-600 text-white cursor-default' 
                    : isBlocked || isStandardOffDay || isOutsidePattern 
                      ? 'bg-gray-50 border-gray-100 text-gray-400 hover:border-tea-200' 
                      : 'bg-white border-tea-50 text-tea-900 hover:border-tea-400 shadow-sm'
                }`}
              >
                <span className="text-xl font-serif font-bold italic leading-none">{hour}</span>
                <span className="text-[8px] font-bold uppercase tracking-widest opacity-60">
                  {isScheduled ? 'Agendado' : isBlocked ? 'Fechado' : isEffectivelyFree ? 'Livre' : 'Inativo'}
                </span>

                {/* Badge de Horário Especial (fora do turno padrão mas aberto) */}
                {!booking && (isStandardOffDay || isOutsidePattern) && (
                   <div className="absolute -top-1 -right-1 w-3 h-3 bg-orange-400 rounded-full border-2 border-white shadow-sm" title="Horário fora do padrão/folga"></div>
                )}

                {/* Hover Indicator */}
                {!isScheduled && (
                  <div className="absolute inset-0 bg-tea-900/5 opacity-0 group-hover:opacity-100 rounded-[inherit] transition-opacity"></div>
                )}
              </button>
            );
          })}
        </div>

        <div className="bg-gray-50 p-6 border-t border-gray-100 flex flex-wrap gap-6 justify-center text-[10px] text-gray-400 font-bold uppercase tracking-widest">
           <div className="flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-orange-400"></span> Horário Extra / Folga</div>
           <div className="flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-tea-600"></span> Cliente Confirmado</div>
           <div className="flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-gray-200"></span> Bloqueio Administrativo</div>
        </div>
      </div>
    </div>
  );
};

export default AdminCalendar;

import React, { useState } from 'react';
import { SalonSettings, Service, TeamMember, BusinessHours } from '../types.ts';
import { db } from '../firebase.ts';
import { doc, setDoc, deleteDoc, updateDoc } from "firebase/firestore";

interface AdminSettingsViewProps {
  settings: SalonSettings;
  setSettings: (s: SalonSettings) => void;
  services: Service[];
  setServices: (s: Service[]) => void;
  customers: any[];
  bookings: any[];
  transactions: any[];
  onImport: (data: any) => void;
}

const AdminSettingsView: React.FC<AdminSettingsViewProps> = ({ 
  settings, 
  services = [],
}) => {
  const [newService, setNewService] = useState({ name: '', price: 0, duration: 30, description: '', isVisible: true });
  const [editingService, setEditingService] = useState<Service | null>(null);
  const [newMemberName, setNewMemberName] = useState('');

  const updateGlobalSettings = async (newSet: SalonSettings) => {
    await setDoc(doc(db, "settings", "main"), newSet);
  };

  const addTeamMember = () => {
    if (newMemberName.trim()) {
      const newMember: TeamMember = {
        id: Math.random().toString(36).substr(2, 9),
        name: newMemberName.trim(),
        assignedServiceIds: [],
        businessHours: { start: settings.businessHours.start, end: settings.businessHours.end },
        offDays: [0] // Domingo como folga padrão
      };
      const updated = { ...settings, teamMembers: [...settings.teamMembers, newMember] };
      updateGlobalSettings(updated);
      setNewMemberName('');
    }
  };

  const removeTeamMember = (id: string) => {
    if (confirm("Remover profissional?")) {
      const updated = { ...settings, teamMembers: settings.teamMembers.filter(m => m.id !== id) };
      updateGlobalSettings(updated);
    }
  };

  const updateMemberField = (memberId: string, field: keyof TeamMember, value: any) => {
    const updatedMembers = settings.teamMembers.map(m => {
      if (m.id === memberId) {
        return { ...m, [field]: value };
      }
      return m;
    });
    updateGlobalSettings({ ...settings, teamMembers: updatedMembers });
  };

  const toggleOffDay = (memberId: string, day: number) => {
    const member = settings.teamMembers.find(m => m.id === memberId);
    if (!member) return;
    const currentOffDays = member.offDays || [];
    const newOffDays = currentOffDays.includes(day)
      ? currentOffDays.filter(d => d !== day)
      : [...currentOffDays, day];
    updateMemberField(memberId, 'offDays', newOffDays);
  };

  const toggleServiceToMember = (memberId: string, serviceId: string) => {
    const member = settings.teamMembers.find(m => m.id === memberId);
    if (!member) return;
    const hasService = member.assignedServiceIds.includes(serviceId);
    const newServices = hasService 
      ? member.assignedServiceIds.filter(id => id !== serviceId)
      : [...member.assignedServiceIds, serviceId];
    updateMemberField(memberId, 'assignedServiceIds', newServices);
  };

  const addService = async () => {
    if (newService.name && newService.price > 0) {
      const id = Math.random().toString(36).substr(2, 9);
      await setDoc(doc(db, "services", id), { ...newService, id });
      setNewService({ name: '', price: 0, duration: 30, description: '', isVisible: true });
    }
  };

  const saveEditedService = async () => {
    if (editingService && editingService.name && editingService.price > 0) {
      const serviceRef = doc(db, "services", editingService.id);
      await updateDoc(serviceRef, {
        name: editingService.name,
        price: editingService.price,
        duration: editingService.duration,
        description: editingService.description
      });
      setEditingService(null);
    }
  };

  const toggleServiceVisibility = async (id: string, current: boolean) => {
    await setDoc(doc(db, "services", id), { isVisible: !current }, { merge: true });
  };

  const handleDeleteService = async (id: string) => {
    if (confirm("Tem certeza que deseja excluir permanentemente este serviço?")) {
      await deleteDoc(doc(db, "services", id));
    }
  };

  const weekDays = [
    { n: 0, label: 'Dom' },
    { n: 1, label: 'Seg' },
    { n: 2, label: 'Ter' },
    { n: 3, label: 'Qua' },
    { n: 4, label: 'Qui' },
    { n: 5, label: 'Sex' },
    { n: 6, label: 'Sáb' },
  ];

  return (
    <div className="space-y-12 pb-32 animate-fade-in">
      <div className="bg-tea-900 text-white p-10 rounded-[3rem] shadow-xl">
        <h2 className="text-3xl font-serif font-bold mb-2">Configurações Gerais</h2>
        <p className="text-tea-100 font-light text-sm italic">Defina as bases do seu salão. Estas configurações servem como padrões para a agenda.</p>
      </div>

      <section className="bg-white p-10 rounded-[3rem] border border-gray-100 shadow-sm">
        <h3 className="text-2xl font-serif text-tea-900 mb-8 italic tracking-tight flex items-center gap-3">
          <span className="text-3xl">🏢</span> Turno Padrão do Salão
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="space-y-2">
             <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Abertura Padrão</label>
             <input type="time" className="w-full p-5 bg-gray-50 rounded-2xl border-none font-bold" value={settings.businessHours.start} onChange={e => updateGlobalSettings({...settings, businessHours: {...settings.businessHours, start: e.target.value}})} />
          </div>
          <div className="space-y-2">
             <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Fechamento Padrão</label>
             <input type="time" className="w-full p-5 bg-gray-50 rounded-2xl border-none font-bold" value={settings.businessHours.end} onChange={e => updateGlobalSettings({...settings, businessHours: {...settings.businessHours, end: e.target.value}})} />
          </div>
        </div>
      </section>

      <section className="bg-white p-10 rounded-[3rem] border border-gray-100 shadow-sm">
        <h3 className="text-2xl font-serif text-tea-900 mb-8 italic tracking-tight flex items-center gap-3">
           <span className="text-3xl">👥</span> Profissionais & Disponibilidade Base
        </h3>
        <div className="flex gap-4 mb-10">
          <input placeholder="Nome da nova profissional..." className="flex-grow p-5 bg-gray-50 rounded-2xl font-bold outline-none shadow-inner" value={newMemberName} onChange={e => setNewMemberName(e.target.value)} />
          <button onClick={addTeamMember} className="bg-tea-800 text-white px-10 py-5 rounded-2xl font-bold hover:bg-tea-950 transition-colors shadow-lg">Adicionar</button>
        </div>

        <div className="space-y-8">
          {settings.teamMembers.map(member => (
            <div key={member.id} className="p-8 border-2 border-gray-50 rounded-[2.5rem] bg-white shadow-sm hover:border-tea-100 transition-all space-y-8">
              <div className="flex justify-between items-center border-b border-gray-50 pb-6">
                <div>
                  <span className="font-serif font-bold text-2xl text-tea-950">{member.name}</span>
                  <p className="text-[10px] text-tea-600 font-bold uppercase tracking-widest mt-1">Definições Semanais Padrão</p>
                </div>
                <button onClick={() => removeTeamMember(member.id)} className="text-red-400 text-xs font-bold uppercase tracking-widest hover:text-red-600 p-3 bg-red-50 rounded-xl">Remover do Time</button>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                <div className="space-y-6">
                  <div>
                    <h4 className="text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-4">⏰ Turno de Trabalho Semanal</h4>
                    <div className="flex items-center gap-4">
                      <input 
                        type="time" 
                        className="flex-1 p-4 bg-gray-50 rounded-xl border-none font-bold text-sm" 
                        value={member.businessHours?.start || settings.businessHours.start} 
                        onChange={e => updateMemberField(member.id, 'businessHours', { ... (member.businessHours || settings.businessHours), start: e.target.value })} 
                      />
                      <span className="text-gray-300">até</span>
                      <input 
                        type="time" 
                        className="flex-1 p-4 bg-gray-50 rounded-xl border-none font-bold text-sm" 
                        value={member.businessHours?.end || settings.businessHours.end} 
                        onChange={e => updateMemberField(member.id, 'businessHours', { ... (member.businessHours || settings.businessHours), end: e.target.value })} 
                      />
                    </div>
                  </div>

                  <div>
                    <h4 className="text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-4">📅 Folgas Semanais Fixas</h4>
                    <div className="flex flex-wrap gap-2">
                      {weekDays.map(day => (
                        <button 
                          key={day.n}
                          onClick={() => toggleOffDay(member.id, day.n)}
                          className={`px-4 py-2 rounded-xl text-[10px] font-bold border-2 transition-all ${member.offDays?.includes(day.n) ? 'bg-red-500 border-red-500 text-white' : 'bg-tea-50 border-tea-100 text-tea-700 hover:bg-tea-100'}`}
                        >
                          {day.label}
                        </button>
