import React, { useState, useEffect, useMemo } from 'react';
import { Customer, Booking, Service, SalonSettings, TeamMember } from '../types';
import { GoogleGenAI } from '@google/genai';

interface CustomerDashboardProps {
  customer: Customer;
  bookings: Booking[];
  services: Service[];
  settings: SalonSettings;
  onBook: (serviceId: string, dateTime: string, teamMemberId?: string) => void;
  onUpdateProfile: (updated: Partial<Customer>) => void;
  onLogout: () => void;
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ 
  customer, 
  bookings, 
  services, 
  settings,
  onBook,
  onUpdateProfile, 
  onLogout 
}) => {
  const [activeTab, setActiveTab] = useState<'home' | 'agendar' | 'agenda' | 'perfil'>('home');
  const [careTips, setCareTips] = useState<string>('');
  const [isLoadingTips, setIsLoadingTips] = useState(false);

  const [bookingStep, setBookingStep] = useState<1 | 2 | 3>(1);
  const [selectedService, setSelectedService] = useState<Service | null>(null);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedTime, setSelectedTime] = useState<string>('');
  const [selectedProId, setSelectedProId] = useState<string>('');

  const myBookings = useMemo(() => 
    bookings.filter(b => b.customerId === customer.id && b.status !== 'cancelled')
      .sort((a, b) => new Date(b.dateTime).getTime() - new Date(a.dateTime).getTime()),
    [bookings, customer.id]
  );

  const nextBooking = useMemo(() => 
    myBookings.find(b => b.status === 'scheduled' || b.status === 'pending'),
    [myBookings]
  );

  const allPossibleSlots = useMemo(() => {
    const slots: string[] = [];
    const start = parseInt((settings.businessHours?.start || "08:00").split(':')[0]);
    const end = parseInt((settings.businessHours?.end || "19:00").split(':')[0]);
    for (let h = start; h < end; h++) {
      slots.push(`${h.toString().padStart(2, '0')}:00`);
      slots.push(`${h.toString().padStart(2, '0')}:30`);
    }
    return slots;
  }, [settings.businessHours]);

  const timeToMinutes = (time: string) => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
  };

  const currentSlotsAvailability = useMemo(() => {
    if (!selectedService) return {};
    const availability: Record<string, TeamMember[]> = {};
    const dateObj = new Date(selectedDate + 'T12:00:00');
    const dayOfWeek = dateObj.getDay();
    const pros = settings.teamMembers.filter(m => m.assignedServiceIds.includes(selectedService.id));

    allPossibleSlots.forEach(slot => {
      const slotStartMin = timeToMinutes(slot);
      const slotEndMin = slotStartMin + selectedService.duration;
      const freePros = pros.filter(pro => {
        if (pro.offDays?.includes(dayOfWeek)) return false;
        const proStartMin = timeToMinutes(pro.businessHours?.start || settings.businessHours.start);
        const proEndMin = timeToMinutes(pro.businessHours?.end || settings.businessHours.end);
        if (slotStartMin < proStartMin || slotEndMin > proEndMin) return false;
        const hasConflict = bookings.some(b => {
          if (b.teamMemberId !== pro.id || b.status === 'cancelled' || !b.dateTime.startsWith(selectedDate)) return false;
          const bStartMin = timeToMinutes(b.dateTime.split(' ')[1]);
          const bEndMin = bStartMin + (b.duration || 30);
          return slotStartMin < bEndMin && slotEndMin > bStartMin;
        });
        return !hasConflict;
      });
      if (freePros.length > 0) availability[slot] = freePros;
    });
    return availability;
  }, [selectedService, selectedDate, settings, bookings, allPossibleSlots]);

  const handleBookSubmit = () => {
    if (selectedService && selectedProId && selectedTime) {
      onBook(selectedService.id, `${selectedDate} ${selectedTime}`, selectedProId);
      setBookingStep(3);
    }
  };

  useEffect(() => {
    if (activeTab === 'home' && myBookings.length > 0 && !careTips) {
      generateCareTips();
    }
  }, [activeTab]);

  const generateCareTips = async () => {
    setIsLoadingTips(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const lastService = myBookings[0]?.serviceName || "Estética";
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Dê 3 dicas curtas de cuidados para quem acabou de fazer ${lastService}. Seja elegante e carinhosa. Use emojis de salão de beleza.`,
      });
      setCareTips(response.text || "");
    } catch (e) {
      setCareTips("Lembre-se de hidratar a pele e usar protetor solar.");
    } finally {
      setIsLoadingTips(false);
    }
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => onUpdateProfile({ profilePhoto: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="min-h-screen bg-[#F9FBFA] pb-32 animate-fade-in font-sans">
      <header className="bg-tea-900 pt-10 pb-24 px-6 rounded-b-[4rem] shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-80 h-80 bg-white/5 rounded-full -mr-32 -mt-32 blur-3xl"></div>
        <div className="max-w-md mx-auto relative z-10 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="relative group">
              <div className="w-16 h-16 rounded-2xl border-2 border-white/20 overflow-hidden bg-tea-800 flex items-center justify-center shadow-inner">
                {customer.profilePhoto ? (
                  <img src={customer.profilePhoto} className="w-full h-full object-cover" alt="Perfil" />
                ) : (
                  <span className="text-3xl font-serif text-white">{customer.name.charAt(0)}</span>
                )}
              </div>
              <label className="absolute -bottom-1 -right-1 bg-white p-1.5 rounded-lg shadow-lg cursor-pointer hover:scale-110 transition-transform">
                <svg className="w-3 h-3 text-tea-900" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path></svg>
                <input type="file" className="hidden" onChange={handlePhotoUpload} />
              </label>
            </div>
            <div>
              <p className="text-[9px] font-bold text-tea-300 uppercase tracking-[0.3em] mb-0.5">Olá, querida</p>
              <h1 className="text-xl font-serif font-bold text-white italic tracking-wide">{customer.name.split(' ')[0]}</h1>
            </div>
          </div>
          <button onClick={onLogout} className="p-3 bg-white/10 rounded-2xl text-white hover:bg-white/20 transition-colors">🚪</button>
        </div>
      </header>

      <main className="max-w-md mx-auto px-4 -mt-12 relative z-20">

        {activeTab === 'home' && (
          <div className="space-y-6 animate-slide-up">
            {nextBooking ? (
              <div className="bg-white rounded-[3rem] shadow-xl border border-tea-50 overflow-hidden">
                <div className="bg-tea-50/50 px-8 py-4 border-b border-tea-100 flex justify-between items-center">
                  <span className="text-[9px] font-bold text-tea-700 uppercase tracking-widest">Sua Próxima Sessão</span>
                  <div className="flex gap-1">
                    <div className="w-1.5 h-1.5 bg-tea-500 rounded-full animate-pulse"></div>
                    <div className="w-1.5 h-1.5 bg-tea-500 rounded-full animate-pulse delay-75"></div>
                  </div>
                </div>
                <div className="p-8">
                  <h3 className="text-2xl font-serif font-bold text-tea-950 mb-1">{nextBooking.serviceName}</h3>
                  <p className="text-xs text-tea-600 font-bold uppercase tracking-tight mb-8">Com {nextBooking.teamMemberName || 'nossa equipe'}</p>

                  <div className="grid grid-cols-2 gap-4 mb-8">
                    <div className="bg-gray-50 p-4 rounded-2xl text-center">
                      <p className="text-[9px] font-bold text-gray-400 uppercase mb-1">Dia</p>
                      <p className="font-bold text-tea-900">{new Date(nextBooking.dateTime).toLocaleDateString('pt-BR', {day:'2-digit', month:'short'})}</p>
                    </div>
                    <div className="bg-gray-50 p-4 rounded-2xl text-center">
                      <p className="text-[9px] font-bold text-gray-400 uppercase mb-1">Hora</p>
                      <p className="font-bold text-tea-900">{new Date(nextBooking.dateTime).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</p>
                    </div>
                  </div>

                  <button onClick={() => setActiveTab('agenda')} className="w-full py-5 bg-tea-800 text-white rounded-[2rem] font-bold text-[10px] uppercase tracking-widest shadow-lg shadow-tea-100/50">Gerenciar Reserva</button>
                </div>
              </div>
            ) : (
              <div className="bg-white p-12 rounded-[3.5rem] shadow-sm border border-gray-100 text-center space-y-6">
                <div className="w-20 h-20 bg-tea-50 rounded-full flex items-center justify-center text-4xl mx-auto shadow-inner">🕯️</div>
                <h3 className="text-2xl font-serif font-bold text-tea-950 italic">Pausa para Você</h3>
                <p className="text-xs text-gray-400 leading-relaxed px-4 font-light">Você ainda não agendou seu próximo cuidado. Nossa agenda está pronta para te receber.</p>
                <button onClick={() => setActiveTab('agendar')} className="bg-tea-800 text-white px-10 py-5 rounded-[2rem] font-bold text-[10px] uppercase tracking-widest shadow-xl shadow-tea-900/10">Reservar Horário</button>
              </div>
            )}

            <div className="grid grid-cols-2 gap-4">
              <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-tea-50 flex flex-col items-center text-center gap-3">
                 <div className="text-3xl">🎁</div>
                 <p className="text-[9px] font-bold text-tea-800 uppercase tracking-widest">Meus Pontos</p>
                 <p className="font-bold text-tea-950 text-xl">120 <span className="text-xs text-tea-300">pts</span></p>
              </div>
              <a 
                href={settings.googleMapsLink} 
                target="_blank" 
                rel="noreferrer"
                className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-tea-50 flex flex-col items-center text-center gap-3 active:bg-tea-50 transition-colors"
              >
                 <div className="text-3xl">📍</div>
                 <p className="text-[9px] font-bold text-tea-800 uppercase tracking-widest">Localização</p>
                 <p className="font-bold text-tea-900 text-xs">Ver no Mapa</p>
              </a>
            </div>

            <div className="bg-white p-8 rounded-[3rem] shadow-sm border border-tea-50 relative overflow-hidden group">
               <div className="absolute top-0 left-0 w-1 h-full bg-tea-600"></div>
               <div className="flex items-center gap-3 mb-5">
                  <div className="w-10 h-10 bg-tea-50 rounded-2xl flex items-center justify-center text-xl shadow-sm">✨</div>
                  <h4 className="font-bold text-tea-900 text-sm tracking-tight">Dicas Moriá para Você</h4>
               </div>
               {isLoadingTips ? (
                 <div className="space-y-3 animate-pulse">
                    <div className="h-3 bg-gray-100 rounded-full w-full"></div>
                    <div className="h-3 bg-gray-100 rounded-full w-[80%]"></div>
                 </div>
               ) : (
                 <div className="text-xs text-gray-500 leading-relaxed italic font-light">
                   {careTips || "Reserve um horário para receber dicas personalizadas da nossa IA."}
                 </div>
               )}
            </div>
          </div>
        )}

        {activeTab === 'agendar' && (
          <div className="space-y-6 animate-slide-up">
            {bookingStep === 1 && (
              <>
                <div className="flex items-center justify-between px-4 mb-4">
                   <h3 className="text-2xl font-serif font-bold text-tea-950 italic">Catálogo Moriá</h3>
                </div>
                <div className="space-y-4">
                  {services.filter(s => s.isVisible).map(service => (
                    <button 
                      key={service.id}
                      onClick={() => { setSelectedService(service); setBookingStep(2); }}
                      className="w-full bg-white p-8 rounded-[2.5rem] border border-gray-50 shadow-sm flex items-center justify-between group active:scale-[0.98] transition-all text-left"
                    >
                      <div className="flex-1">
                        <h4 className="font-bold text-tea-900 text-lg mb-1">{service.name}</h4>
                        <div className="flex items-center gap-4">
                          <span className="text-[10px] font-bold text-tea-600 bg-tea-50 px-2.5 py-1 rounded-lg uppercase tracking-widest">R$ {service.price.toFixed(2)}</span>
                          <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest flex items-center gap-1">🕒 {service.duration} min</span>
                        </div>
                      </div>
                      <div className="w-12 h-12 bg-tea-900 text-white rounded-2xl flex items-center justify-center group-hover:bg-tea-700 transition-colors shadow-lg">✨</div>
                    </button>
                  ))}
                </div>
              </>
            )}

            {bookingStep === 2 && selectedService && (
              <div className="bg-white rounded-[3rem] p-10 shadow-2xl border border-tea-50 space-y-8 animate-fade-in mb-8">
                <div className="flex items-center gap-4 border-b border-gray-50 pb-6">
                   <button onClick={() => setBookingStep(1)} className="w-10 h-10 bg-gray-50 rounded-xl flex items-center justify-center text-gray-400 hover:text-tea-800">←</button>
                   <div>
                     <h3 className="font-bold text-tea-950">{selectedService.name}</h3>
                     <p className="text-[10px] text-gray-400 uppercase font-bold tracking-widest">Personalize seu momento</p>
                   </div>
                </div>

                <div className="space-y-6">
                  <div className="space-y-2">
                    <label className="text-[9px] font-bold text-gray-400 uppercase tracking-widest ml-1">Data Desejada</label>
                    <input 
                      type="date" 
                      value={selectedDate}
                      min={new Date().toISOString().split('T')[0]}
                      max={settings.agendaOpenUntil || undefined}
                      onChange={(e) => setSelectedDate(e.target.value)}
                      className="w-full p-5 bg-gray-50 rounded-3xl border-none font-bold text-tea-900 outline-none focus:ring-4 focus:ring-tea-100 transition-all"
                    />
                  </div>

                  <div className="space-y-3">
                    <label className="text-[9px] font-bold text-gray-400 uppercase tracking-widest ml-1">Horário</label>
                    <div className="grid grid-cols-3 gap-3">
                      {allPossibleSlots.map(slot => {
                        const available = !!currentSlotsAvailability[slot];
                        return (
                          <button 
                            key={slot}
                            disabled={!available}
                            onClick={() => setSelectedTime(slot)}
                            className={`p-4 rounded-2xl text-[10px] font-bold border-2 transition-all ${
                              selectedTime === slot ? 'bg-tea-800 border-tea-800 text-white shadow-xl shadow-tea-900/20' :
                              available ? 'bg-white border-tea-50 text-tea-900 hover:border-tea-200' :
                              'bg-gray-50 border-transparent text-gray-200 opacity-50 cursor-not-allowed'
                            }`}
                          >
                            {slot}
                          </button>
                        );
                      })}
                    </div>
                  </div>

                  {selectedTime && (
                    <div className="space-y-3 animate-fade-in pt-2">
                       <label className="text-[9px] font-bold text-gray-400 uppercase tracking-widest ml-1">Profissional Disponível</label>
                       <div className="space-y-3">
                          {currentSlotsAvailability[selectedTime]?.map(pro => (
                            <button 
                              key={pro.id}
                              onClick={() => setSelectedProId(pro.id)}
                              className={`w-full p-5 rounded-[2rem] border-2 flex items-center justify-between transition-all ${selectedProId === pro.id ? 'border-tea-600 bg-tea-50 shadow-sm' : 'bg-white border-gray-50 hover:border-tea-100'}`}
                            >
                              <div className="flex items-center gap-4">
                                <div className="w-10 h-10 bg-tea-800 text-white rounded-2xl flex items-center justify-center font-bold text-sm shadow-lg">{pro.name.charAt(0)}</div>
                                <span className="font-bold text-sm text-tea-900">{pro.name}</span>
                              </div>
                              {selectedProId === pro.id && <span className="text-tea-600 text-xs font-bold">✓</span>}
                            </button>
                          ))}
                       </div>
                    </div>
                  )}
                </div>

                <button 
                  disabled={!selectedTime || !selectedProId}
                  onClick={handleBookSubmit}
                  className="w-full py-6 bg-tea-800 text-white rounded-[2rem] font-bold text-[10px] uppercase tracking-widest shadow-2xl shadow-tea-950/20 disabled:bg-gray-100 disabled:text-gray-300 disabled:shadow-none transition-all"
                >
                  Agendar Procedimento
                </button>
              </div>
            )}

            {bookingStep === 3 && (
              <div className="text-center py-16 space-y-8 animate-slide-up bg-white rounded-[4rem] border border-tea-50 shadow-xl px-8">
