                      className="w-full bg-white p-10 rounded-[3rem] border border-gray-50 shadow-sm flex items-center justify-between group active:scale-[0.98] transition-all text-left"
                    >
                      <div className="flex-1">
                        <h4 className="font-bold text-tea-950 text-xl mb-2">{service.name}</h4>
                        <div className="flex items-center gap-5">
                          <span className="text-[10px] font-bold text-tea-700 bg-tea-50 px-3 py-1.5 rounded-xl uppercase tracking-widest">
                            <span className="opacity-50 text-[8px] mr-1">a partir de</span>
                            R$ {service.price.toFixed(2)}
                          </span>
                          <span className="text-[10px] font-bold text-gray-300 uppercase tracking-widest flex items-center gap-1.5">
                             <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                             {service.duration} min
                          </span>
                        </div>
                      </div>
                      <div className="w-12 h-12 bg-tea-900 text-white rounded-[1.5rem] flex items-center justify-center shadow-xl group-hover:bg-tea-800 transition-colors">✨</div>
                    </button>
                  ))}
                </div>
              </>
            )}

            {bookingStep === 2 && selectedService && (
              <div className="bg-white rounded-[3.5rem] p-10 shadow-2xl border border-tea-50 space-y-10 animate-fade-in mb-10">
                <div className="flex items-center gap-5 border-b border-gray-50 pb-8">
                   <button onClick={() => setBookingStep(1)} className="w-12 h-12 bg-gray-50 rounded-2xl flex items-center justify-center text-gray-400 hover:text-tea-800">←</button>
                   <div>
                     <h3 className="font-bold text-tea-950 text-lg">{selectedService.name}</h3>
                     <p className="text-[9px] text-gray-400 uppercase font-bold tracking-[0.3em]">Escolha data e horário</p>
                   </div>
                </div>

                <div className="space-y-8">
                  <div className="space-y-3">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] ml-2">Data</label>
                    <input 
                      type="date" 
                      value={selectedDate}
                      min={new Date().toISOString().split('T')[0]}
                      max={settings.agendaOpenUntil || undefined}
                      onChange={(e) => { setSelectedDate(e.target.value); setSelectedTime(''); }}
                      className="w-full p-6 bg-gray-50/80 rounded-[2rem] border-none font-bold text-tea-900 outline-none focus:ring-4 focus:ring-tea-50 transition-all"
                    />
                  </div>

                  <div className="space-y-4">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] ml-2">Horário disponível</label>
                    <div className="grid grid-cols-3 gap-3">
                      {allPossibleSlots.map(slot => {
                        const available = !!currentSlotsAvailability[slot];
                        return (
                          <button 
                            key={slot}
                            disabled={!available}
                            onClick={() => setSelectedTime(slot)}
                            className={`p-5 rounded-2xl text-[10px] font-bold border-2 transition-all ${
                              selectedTime === slot ? 'bg-tea-800 border-tea-800 text-white shadow-2xl shadow-tea-900/20' :
                              available ? 'bg-white border-tea-50 text-tea-900 hover:border-tea-200 shadow-sm' :
                              'bg-gray-50 border-transparent text-gray-200 opacity-50 cursor-not-allowed'
                            }`}
                          >
                            {slot}
                          </button>
                        );
                      })}
                    </div>
                  </div>

                  {selectedTime && (
                    <div className="space-y-4 animate-fade-in pt-4">
                       <label className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] ml-2">Profissional</label>
                       <div className="space-y-3">
                          {currentSlotsAvailability[selectedTime]?.map(pro => (
                            <button 
                              key={pro.id}
                              onClick={() => setSelectedProId(pro.id)}
                              className={`w-full p-6 rounded-[2.5rem] border-2 flex items-center justify-between transition-all ${selectedProId === pro.id ? 'border-tea-600 bg-tea-50 shadow-md' : 'bg-white border-gray-50 hover:border-tea-100'}`}
                            >
                              <div className="flex items-center gap-5">
                                <div className="w-12 h-12 bg-tea-900 text-white rounded-2xl flex items-center justify-center font-bold text-base shadow-lg">{pro.name.charAt(0)}</div>
                                <span className="font-bold text-base text-tea-900">{pro.name}</span>
                              </div>
                              {selectedProId === pro.id && (
                                <div className="w-8 h-8 bg-tea-600 text-white rounded-full flex items-center justify-center text-sm">✓</div>
                              )}
                            </button>
                          ))}
                       </div>
                    </div>
                  )}
                </div>

                <button 
                  disabled={!selectedTime || !selectedProId}
                  onClick={handleBookSubmit}
                  className="w-full py-7 bg-tea-800 text-white rounded-[2.5rem] font-bold text-[11px] uppercase tracking-[0.2em] shadow-2xl disabled:bg-gray-100 disabled:text-gray-300 disabled:shadow-none transition-all active:scale-95"
                >
                  Confirmar agora
                </button>
              </div>
            )}

            {bookingStep === 3 && (
              <div className="text-center py-20 space-y-10 animate-slide-up bg-white rounded-[4rem] border border-tea-50 shadow-2xl px-10">
                <div className="w-32 h-32 bg-tea-50 rounded-full flex items-center justify-center text-7xl mx-auto shadow-inner border-4 border-white animate-bounce">⏳</div>
                <div className="space-y-3">
                  <h3 className="text-4xl font-serif font-bold text-tea-950 italic">Solicitado!</h3>
                  <p className="text-gray-400 text-[11px] leading-relaxed max-w-[220px] mx-auto font-light">Para validar sua vaga, envie agora o comprovante do sinal pelo WhatsApp.</p>
                </div>
                <button 
                  onClick={() => {
                    const msg = `Olá Studio Moriá! Solicitei ${selectedService?.name} para ${selectedDate} às ${selectedTime}. Segue comprovante do sinal.`;
                    window.open(`https://wa.me/${settings.socialLinks.whatsapp.replace(/\D/g, '')}?text=${encodeURIComponent(msg)}`, '_blank');
                    setActiveTab('agenda');
                    setBookingStep(1);
                  }}
                  className="w-full py-7 bg-tea-950 text-white rounded-[2.5rem] font-bold text-[10px] uppercase tracking-[0.2em] shadow-3xl flex items-center justify-center gap-4 hover:bg-black transition-colors"
                >
                   📱 Validar no WhatsApp
                </button>
              </div>
            )}
          </div>
        )}

        {/* Outras abas permanecem com o mesmo fluxo lógico */}
        {activeTab === 'agenda' && (
          <div className="space-y-6 animate-slide-up">
             <div className="flex items-center justify-between px-4">
                <h3 className="text-2xl font-serif font-bold text-tea-950 italic">Minha Agenda</h3>
             </div>
             <div className="space-y-4">
                {myBookings.length > 0 ? myBookings.map(b => (
                  <div key={b.id} className="bg-white p-8 rounded-[3rem] border border-gray-100 flex items-center justify-between shadow-sm">
                    <div className="flex items-center gap-6">
                      <div className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center text-3xl ${b.status === 'completed' ? 'bg-green-50 text-green-600' : 'bg-tea-50 text-tea-700 shadow-inner'}`}>
                         {b.status === 'completed' ? '✨' : '📅'}
                      </div>
                      <div>
                        <h4 className="font-bold text-tea-950 text-lg mb-1">{b.serviceName}</h4>
                        <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">
                           {new Date(b.dateTime).toLocaleDateString()} às {new Date(b.dateTime).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}
                        </p>
                      </div>
                    </div>
                    <div className={`px-4 py-2 rounded-full text-[9px] font-bold uppercase tracking-widest border ${
                      b.status === 'completed' ? 'bg-green-50 text-green-700 border-green-100' :
                      b.status === 'pending' ? 'bg-orange-50 text-orange-700 border-orange-100 animate-pulse' :
                      'bg-blue-50 text-blue-700 border-blue-100'
                    }`}>
                      {b.status === 'completed' ? 'Finalizado' : b.status === 'pending' ? 'Pendente' : 'Confirmado'}
                    </div>
                  </div>
                )) : (
                  <div className="py-24 text-center opacity-30 italic font-serif text-xl px-10 leading-relaxed">Você ainda não possui atendimentos registrados.</div>
                )}
             </div>
          </div>
        )}

        {activeTab === 'perfil' && (
          <div className="space-y-8 animate-slide-up">
             <div className="bg-white p-12 rounded-[4rem] shadow-sm border border-gray-100 space-y-10">
                <div className="space-y-6">
                  <div className="space-y-2">
                     <label className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.3em] ml-3">Nome</label>
                     <div className="p-6 bg-gray-50 rounded-[2rem] font-bold text-tea-950 text-sm shadow-inner">{customer.name}</div>
                  </div>
                  <div className="space-y-2">
                     <label className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.3em] ml-3">WhatsApp</label>
                     <div className="p-6 bg-gray-50 rounded-[2rem] font-bold text-tea-950 text-sm shadow-inner">{customer.whatsapp}</div>
                  </div>
                </div>
                <button onClick={onLogout} className="w-full py-6 bg-red-50 text-red-500 rounded-[2rem] font-bold text-[10px] uppercase tracking-[0.2em] border border-red-100 active:scale-95 transition-all">Sair da Conta</button>
             </div>

             <div className="text-center py-12 opacity-30 flex flex-col items-center gap-6">
                <div className="w-16 h-16 bg-tea-900 rounded-2xl flex items-center justify-center shadow-lg">
                   <span className="text-white font-serif font-bold text-2xl">M</span>
                </div>
                <p className="text-[10px] font-bold uppercase tracking-[0.8em]">Studio Moriá</p>
             </div>
          </div>
        )}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-3xl border-t border-gray-100 px-10 py-8 flex justify-between items-center z-[100] shadow-[0_-20px_60px_rgba(0,0,0,0.08)] rounded-t-[4rem]">
         {[
           { id: 'home', icon: '🏠', label: 'Início' },
           { id: 'agendar', icon: '✨', label: 'Agendar' },
           { id: 'agenda', icon: '🗓️', label: 'Agenda' },
           { id: 'perfil', icon: '👤', label: 'Eu' }
         ].map(tab => (
           <button 
             key={tab.id}
             onClick={() => { setActiveTab(tab.id as any); if(tab.id === 'agendar') setBookingStep(1); }}
             className={`flex flex-col items-center gap-2 transition-all duration-300 ${activeTab === tab.id ? 'text-tea-900 scale-110 -translate-y-2' : 'text-gray-300'}`}
           >
              <span className={`text-2xl ${activeTab === tab.id ? 'drop-shadow-[0_0_12px_rgba(41,91,53,0.4)]' : ''}`}>{tab.icon}</span>
              <span className={`text-[9px] font-bold uppercase tracking-[0.2em] ${activeTab === tab.id ? 'opacity-100' : 'opacity-0 h-0 overflow-hidden'}`}>{tab.label}</span>
              {activeTab === tab.id && <div className="w-1.5 h-1.5 bg-tea-900 rounded-full mt-1"></div>}
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState } from 'react';
import { SalonSettings, Service, TeamMember, BusinessHours } from '../types.ts';
import { db } from '../firebase.ts';
import { doc, setDoc, deleteDoc, updateDoc } from "firebase/firestore";

interface AdminSettingsViewProps {
  settings: SalonSettings;
  setSettings: (s: SalonSettings) => void;
  services: Service[];
  setServices: (s: Service[]) => void;
  customers: any[];
  bookings: any[];
  transactions: any[];
  onImport: (data: any) => void;
}

const AdminSettingsView: React.FC<AdminSettingsViewProps> = ({ 
  settings, 
  services = [],
}) => {
  const [newService, setNewService] = useState({ name: '', price: 0, duration: 30, description: '', isVisible: true });
  const [editingService, setEditingService] = useState<Service | null>(null);
  const [newMemberName, setNewMemberName] = useState('');

  const updateGlobalSettings = async (newSet: SalonSettings) => {
    await setDoc(doc(db, "settings", "main"), newSet);
  };

  const addTeamMember = () => {
    if (newMemberName.trim()) {
      const newMember: TeamMember = {
        id: Math.random().toString(36).substr(2, 9),
        name: newMemberName.trim(),
        assignedServiceIds: [],
        businessHours: { start: settings.businessHours.start, end: settings.businessHours.end },
        offDays: [0] // Domingo como folga padrão
      };
      const updated = { ...settings, teamMembers: [...settings.teamMembers, newMember] };
      updateGlobalSettings(updated);
      setNewMemberName('');
    }
  };

  const removeTeamMember = (id: string) => {
    if (confirm("Remover profissional?")) {
      const updated = { ...settings, teamMembers: settings.teamMembers.filter(m => m.id !== id) };
      updateGlobalSettings(updated);
    }
  };

  const updateMemberField = (memberId: string, field: keyof TeamMember, value: any) => {
    const updatedMembers = settings.teamMembers.map(m => {
      if (m.id === memberId) {
        return { ...m, [field]: value };
      }
      return m;
    });
    updateGlobalSettings({ ...settings, teamMembers: updatedMembers });
  };

  const toggleOffDay = (memberId: string, day: number) => {
    const member = settings.teamMembers.find(m => memberId === memberId); // Fix potential reference error
    const targetMember = settings.teamMembers.find(m => m.id === memberId);
    if (!targetMember) return;
    const currentOffDays = targetMember.offDays || [];
    const newOffDays = currentOffDays.includes(day)
      ? currentOffDays.filter(d => d !== day)
      : [...currentOffDays, day];
    updateMemberField(memberId, 'offDays', newOffDays);
  };

  const toggleServiceToMember = (memberId: string, serviceId: string) => {
    const member = settings.teamMembers.find(m => m.id === memberId);
    if (!member) return;
    const hasService = member.assignedServiceIds.includes(serviceId);
    const newServices = hasService 
      ? member.assignedServiceIds.filter(id => id !== serviceId)
      : [...member.assignedServiceIds, serviceId];
    updateMemberField(memberId, 'assignedServiceIds', newServices);
  };

  const addService = async () => {
    if (newService.name && newService.price > 0) {
      const id = Math.random().toString(36).substr(2, 9);
      await setDoc(doc(db, "services", id), { ...newService, id });
      setNewService({ name: '', price: 0, duration: 30, description: '', isVisible: true });
    }
  };

  const saveEditedService = async () => {
    if (editingService && editingService.name && editingService.price > 0) {
      const serviceRef = doc(db, "services", editingService.id);
      await updateDoc(serviceRef, {
        name: editingService.name,
        price: editingService.price,
        duration: editingService.duration,
        description: editingService.description
      });
      setEditingService(null);
    }
  };

  const toggleServiceVisibility = async (id: string, current: boolean) => {
    await setDoc(doc(db, "services", id), { isVisible: !current }, { merge: true });
  };

  const handleDeleteService = async (id: string) => {
    if (confirm("Tem certeza que deseja excluir permanentemente este serviço?")) {
      await deleteDoc(doc(db, "services", id));
    }
  };

  const weekDays = [
    { n: 0, label: 'Dom' },
    { n: 1, label: 'Seg' },
    { n: 2, label: 'Ter' },
    { n: 3, label: 'Qua' },
    { n: 4, label: 'Qui' },
    { n: 5, label: 'Sex' },
    { n: 6, label: 'Sáb' },
  ];

  return (
    <div className="space-y-12 pb-32 animate-fade-in">
      <div className="bg-tea-900 text-white p-10 rounded-[3rem] shadow-xl">
        <h2 className="text-3xl font-serif font-bold mb-2">Configurações Gerais</h2>
        <p className="text-tea-100 font-light text-sm italic">Defina as bases do seu salão e controle o período de agendamento aberto.</p>
      </div>

      <section className="bg-white p-10 rounded-[3rem] border border-gray-100 shadow-sm">
        <h3 className="text-2xl font-serif text-tea-900 mb-8 italic tracking-tight flex items-center gap-3">
          <span className="text-3xl">📅</span> Janela de Agendamento
        </h3>
        <div className="bg-tea-50/50 p-8 rounded-3xl border border-tea-100 space-y-6">
           <div className="max-w-md">
             <label className="text-[10px] font-bold text-tea-700 uppercase tracking-widest ml-1 mb-2 block">Agenda Aberta para Clientes Até:</label>
             <input 
              type="date" 
              className="w-full p-4 bg-white border-2 border-tea-100 rounded-2xl font-bold text-tea-900 outline-none focus:border-tea-400"
              value={settings.agendaOpenUntil || ''}
              onChange={e => updateGlobalSettings({...settings, agendaOpenUntil: e.target.value})}
             />
           </div>
           <div className="flex items-center gap-3">
              <span className="text-xl">💡</span>
              <p className="text-[11px] text-tea-800 leading-relaxed font-medium uppercase tracking-tight">
                Clientes não conseguirão visualizar horários após esta data. Use este controle para abrir sua agenda mensal ou quinzenal conforme sua conveniência.
              </p>
           </div>
        </div>
      </section>

      <section className="bg-white p-10 rounded-[3rem] border border-gray-100 shadow-sm">
        <h3 className="text-2xl font-serif text-tea-900 mb-8 italic tracking-tight flex items-center gap-3">
          <span className="text-3xl">🏢</span> Turno Padrão do Salão
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="space-y-2">
             <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Abertura Padrão</label>
             <input type="time" className="w-full p-5 bg-gray-50 rounded-2xl border-none font-bold" value={settings.businessHours.start} onChange={e => updateGlobalSettings({...settings, businessHours: {...settings.businessHours, start: e.target.value}})} />
          </div>
          <div className="space-y-2">
             <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Fechamento Padrão</label>
             <input type="time" className="w-full p-5 bg-gray-50 rounded-2xl border-none font-bold" value={settings.businessHours.end} onChange={e => updateGlobalSettings({...settings, businessHours: {...settings.businessHours, end: e.target.value}})} />
          </div>
        </div>
      </section>

      <section className="bg-white p-10 rounded-[3rem] border border-gray-100 shadow-sm">
        <h3 className="text-2xl font-serif text-tea-900 mb-8 italic tracking-tight flex items-center gap-3">
           <span className="text-3xl">👥</span> Profissionais & Disponibilidade Base
        </h3>
        <div className="flex gap-4 mb-10">
          <input placeholder="Nome da nova profissional..." className="flex-grow p-5 bg-gray-50 rounded-2xl font-bold outline-none shadow-inner" value={newMemberName} onChange={e => setNewMemberName(e.target.value)} />
          <button onClick={addTeamMember} className="bg-tea-800 text-white px-10 py-5 rounded-2xl font-bold hover:bg-tea-950 transition-colors shadow-lg">Adicionar</button>
        </div>

        <div className="space-y-8">
          {settings.teamMembers.map(member => (
            <div key={member.id} className="p-8 border-2 border-gray-50 rounded-[2.5rem] bg-white shadow-sm hover:border-tea-100 transition-all space-y-8">
              <div className="flex justify-between items-center border-b border-gray-50 pb-6">
                <div>
                  <span className="font-serif font-bold text-2xl text-tea-950">{member.name}</span>
                  <p className="text-[10px] text-tea-600 font-bold uppercase tracking-widest mt-1">Definições Semanais Padrão</p>
                </div>
                <button onClick={() => removeTeamMember(member.id)} className="text-red-400 text-xs font-bold uppercase tracking-widest hover:text-red-600 p-3 bg-red-50 rounded-xl">Remover do Time</button>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                <div className="space-y-6">
                  <div>
                    <h4 className="text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-4">⏰ Turno de Trabalho Semanal</h4>
                    <div className="flex items-center gap-4">
                      <input 
                        type="time" 
                        className="flex-1 p-4 bg-gray-50 rounded-xl border-none font-bold text-sm" 
                        value={member.businessHours?.start || settings.businessHours.start} 
                        onChange={e => updateMemberField(member.id, 'businessHours', { ... (member.businessHours || settings.businessHours), start: e.target.value })} 
                      />
                      <span className="text-gray-300">até</span>
                      <input 
                        type="time" 
                        className="flex-1 p-4 bg-gray-50 rounded-xl border-none font-bold text-sm" 
                        value={member.businessHours?.end || settings.businessHours.end} 
                        onChange={e => updateMemberField(member.id, 'businessHours', { ... (member.businessHours || settings.businessHours), end: e.target.value })} 
                      />
                    </div>
                  </div>

                  <div>
                    <h4 className="text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-4">📅 Folgas Semanais Fixas</h4>
                    <div className="flex flex-wrap gap-2">
                      {weekDays.map(day => (
                        <button 
                          key={day.n}
                          onClick={() => toggleOffDay(member.id, day.n)}
                          className={`px-4 py-2 rounded-xl text-[10px] font-bold border-2 transition-all ${member.offDays?.includes(day.n) ? 'bg-red-500 border-red-500 text-white' : 'bg-tea-50 border-tea-100 text-tea-700 hover:bg-tea-100'}`}
                        >
                          {day.label}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>

                <div className="space-y-6">
                  <h4 className="text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-4">💅 Serviços Autorizados</h4>
                  <div className="flex flex-wrap gap-2">
                    {services.map(s => (
                      <button 
                        key={s.id} 
                        onClick={() => toggleServiceToMember(member.id, s.id)} 
                        className={`px-4 py-2 rounded-xl text-[10px] font-bold border-2 transition-all ${member.assignedServiceIds?.includes(s.id) ? 'bg-tea-800 border-tea-800 text-white' : 'bg-gray-50 border-gray-100 text-gray-400 hover:bg-gray-100'}`}
                      >
                        {s.name}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>

      <section className="bg-white p-10 rounded-[3rem] border border-gray-100 shadow-sm">
        <h3 className="text-2xl font-serif text-tea-900 mb-8 italic tracking-tight flex items-center gap-3">
           <span className="text-3xl">📋</span> Catálogo de Serviços
        </h3>

        <div className="bg-tea-50/50 p-8 rounded-3xl mb-10 border border-tea-100">
           <h4 className="text-[10px] font-bold text-tea-700 uppercase tracking-widest mb-6 ml-1">Criar Novo Procedimento</h4>
           <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
              <input placeholder="Ex: Micropigmentação" className="p-4 rounded-xl bg-white outline-none font-bold shadow-inner" value={newService.name} onChange={e => setNewService({...newService, name: e.target.value})} />
              <input type="number" placeholder="Preço Base R$" className="p-4 rounded-xl bg-white outline-none font-bold shadow-inner" value={newService.price || ''} onChange={e => setNewService({...newService, price: parseFloat(e.target.value)})} />
              <input type="number" placeholder="Minutos (aprox)" className="p-4 rounded-xl bg-white outline-none font-bold shadow-inner" value={newService.duration || ''} onChange={e => setNewService({...newService, duration: parseInt(e.target.value)})} />
           </div>
           <button onClick={addService} className="w-full bg-tea-800 text-white py-5 rounded-2xl font-bold uppercase tracking-widest text-[11px] hover:bg-tea-950 transition-all shadow-lg">Salvar Novo Procedimento</button>
        </div>

        <div className="space-y-4">
          {services.map(s => (
            <div key={s.id} className={`p-6 border-2 rounded-3xl flex justify-between items-center transition-all ${s.isVisible ? 'border-gray-50 hover:bg-gray-50/30' : 'bg-red-50/10 opacity-60 border-transparent'}`}>
              <div>
                <p className="font-bold text-lg text-tea-950">{s.name}</p>
                <p className="text-[10px] text-gray-400 font-bold uppercase">a partir de R$ {s.price.toFixed(2)} • {s.duration} min</p>
              </div>
              <div className="flex gap-2 items-center">
                <button 
                  onClick={() => setEditingService(s)} 
                  className="p-3 bg-white text-tea-600 rounded-xl border border-tea-50 hover:border-tea-200 transition-all shadow-sm"
                  title="Editar Serviço"
                >
                  ✏️
                </button>
                <button 
                  onClick={() => toggleServiceVisibility(s.id, s.isVisible)} 
                  className={`px-6 py-3 rounded-xl text-[10px] font-bold border-2 transition-all ${s.isVisible ? 'bg-white text-tea-700 border-tea-100 hover:bg-tea-50' : 'bg-tea-800 text-white border-tea-800 hover:bg-tea-900'}`}
                >
                  {s.isVisible ? 'OCULTAR' : 'EXIBIR'}
                </button>
                <button onClick={() => handleDeleteService(s.id)} className="p-3 text-red-200 hover:text-red-500 transition-colors">🗑️</button>
              </div>
            </div>
          ))}
        </div>
      </section>

      {editingService && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
          <div className="bg-white w-full max-w-lg rounded-[3rem] p-10 shadow-2xl animate-slide-up">
            <h3 className="text-2xl font-serif text-tea-900 mb-8 italic">Editar Procedimento</h3>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Nome do Procedimento</label>
                <input 
                  className="w-full p-4 rounded-2xl bg-gray-50 border-2 border-transparent focus:border-tea-200 focus:bg-white outline-none font-bold transition-all"
                  value={editingService.name}
                  onChange={e => setEditingService({...editingService, name: e.target.value})}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Preço Base R$</label>
                  <input 
                    type="number"
                    className="w-full p-4 rounded-2xl bg-gray-50 border-2 border-transparent focus:border-tea-200 focus:bg-white outline-none font-bold transition-all"
                    value={editingService.price}
                    onChange={e => setEditingService({...editingService, price: parseFloat(e.target.value)})}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Duração (Min)</label>
                  <input 
                    type="number"
                    className="w-full p-4 rounded-2xl bg-gray-50 border-2 border-transparent focus:border-tea-200 focus:bg-white outline-none font-bold transition-all"
                    value={editingService.duration}
                    onChange={e => setEditingService({...editingService, duration: parseInt(e.target.value)})}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Descrição curta</label>
                <textarea 
                  className="w-full p-4 rounded-2xl bg-gray-50 border-2 border-transparent focus:border-tea-200 focus:bg-white outline-none transition-all resize-none h-24"
                  value={editingService.description}
                  onChange={e => setEditingService({...editingService, description: e.target.value})}
                />
              </div>

              <div className="flex gap-4 pt-4">
                <button 
                  onClick={() => setEditingService(null)} 
                  className="flex-1 py-4 text-gray-400 font-bold hover:text-gray-600 transition-colors"
                >
                  Cancelar
                </button>
                <button 
                  onClick={saveEditedService}
                  className="flex-[2] bg-tea-800 text-white py-4 rounded-2xl font-bold shadow-xl hover:bg-tea-950 transition-all"
                >
                  Salvar Alterações
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

