      <section id="localizacao" className="bg-gray-50 py-16 md:py-32 px-6 rounded-[3rem] md:rounded-[5rem]">
        <div className="max-w-7xl mx-auto flex flex-col lg:flex-row gap-10 md:gap-20 items-center">
