  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [waitlist, setWaitlist] = useState<WaitlistEntry[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  useEffect(() => {
    const unsubSettings = onSnapshot(doc(db, "settings", "main"), (doc) => {
      if (doc.exists()) {
        setSettings(doc.data() as SalonSettings);
      } else {
        setDoc(doc.ref, DEFAULT_SETTINGS);
      }
    });

    const unsubServices = onSnapshot(collection(db, "services"), (snapshot) => {
      const data = snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Service));
      if (data.length === 0) {
        INITIAL_SERVICES.forEach(s => setDoc(doc(db, "services", s.id), s));
      }
      setServices(data);
    });

    const unsubCustomers = onSnapshot(collection(db, "customers"), (snapshot) => {
      setCustomers(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Customer)));
    });

    const unsubBookings = onSnapshot(collection(db, "bookings"), (snapshot) => {
      setBookings(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Booking)));
    });

    const unsubTransactions = onSnapshot(collection(db, "transactions"), (snapshot) => {
      setTransactions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Transaction)));
    });

    const unsubWaitlist = onSnapshot(collection(db, "waitlist"), (snapshot) => {
      setWaitlist(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as WaitlistEntry)));
    });

    return () => {
      unsubSettings(); unsubServices(); unsubCustomers();
      unsubBookings(); unsubTransactions(); unsubWaitlist();
    };
  }, []);

  useEffect(() => {
    const savedUser = localStorage.getItem('moria_user_session');
    if (savedUser) {
      try {
        const parsed = JSON.parse(savedUser);
        if (parsed && typeof parsed === 'object') setCurrentUser(parsed);
      } catch (e) { console.error("Error loading session"); }
    }
    if (localStorage.getItem('moria_admin_session') === 'true') setIsAdminAuthenticated(true);
  }, []);

  useEffect(() => {
    if (currentUser) {
      const cleanUser = {
        id: currentUser.id,
        name: currentUser.name,
        whatsapp: currentUser.whatsapp,
        cpf: currentUser.cpf,
        profilePhoto: currentUser.profilePhoto,
        receivesNotifications: !!currentUser.receivesNotifications
      };
      localStorage.setItem('moria_user_session', JSON.stringify(cleanUser));
      if (currentView === View.CUSTOMER_HOME || currentView === View.CUSTOMER_LOGIN) {
        setCurrentView(View.CUSTOMER_DASHBOARD);
      }
    } else {
      localStorage.removeItem('moria_user_session');
    }
    localStorage.setItem('moria_admin_session', isAdminAuthenticated.toString());
  }, [currentUser, isAdminAuthenticated, currentView]);

  const handleRegister = async (name: string, whatsapp: string, cpf: string, password: string, receivesNotifications: boolean) => {
    const id = Math.random().toString(36).substr(2, 9);
    const newCustomer: Customer = { id, name, whatsapp, cpf, password, receivesNotifications, agreedToTerms: true, history: [] };
    await setDoc(doc(db, "customers", id), newCustomer);
    setCurrentUser(newCustomer);
    setCurrentView(View.CUSTOMER_DASHBOARD);
  };

  const handleLogin = (cpf: string, pass: string) => {
    const user = customers.find(c => c.cpf === cpf && c.password === pass);
    if (user) { setCurrentUser(user); setCurrentView(View.CUSTOMER_DASHBOARD); }
    else alert("Dados incorretos.");
  };

  const handleBook = async (sid: string, dt: string, mid: string) => {
    if (!currentUser) { setCurrentView(View.CUSTOMER_LOGIN); return; }
    const srv = services.find(s => s.id === sid);
    const booking = {
      customerId: currentUser.id,
      customerName: currentUser.name,
      serviceId: sid,
      serviceName: srv?.name || '',
      dateTime: dt,
      duration: srv?.duration || 30,
      status: 'pending',
      depositStatus: 'pending',
      teamMemberId: mid,
      teamMemberName: settings.teamMembers.find(m => m.id === mid)?.name,
      agreedToCancellationPolicy: true,
      policyAgreedAt: new Date().toISOString()
    };
    await addDoc(collection(db, "bookings"), booking);
  };

  const handleAddToWaitlist = async (sid: string, dt: string) => {
    if (!currentUser) return;
    const srv = services.find(s => s.id === sid);
    await addDoc(collection(db, "waitlist"), {
      customerId: currentUser.id,
      customerName: currentUser.name,
      customerWhatsapp: currentUser.whatsapp,
      serviceId: sid,
      serviceName: srv?.name || '',
      preferredDate: dt,
      createdAt: new Date().toISOString()
    });
  };

  const handleUpdateStatus = async (id: string, status: any) => {
    await updateDoc(doc(db, "bookings", id), { status });
  };

  const handleUpdateDeposit = async (id: string, depositStatus: 'paid' | 'pending') => {
    await updateDoc(doc(db, "bookings", id), { depositStatus });
  };

  const handleDeleteBooking = async (id: string) => {
    if (confirm("Tem certeza que deseja excluir permanentemente este agendamento? Esta ação não pode ser desfeita.")) {
      await deleteDoc(doc(db, "bookings", id));
    }
  };

  const renderView = () => {
    if (isAdmin) {
      if (!isAdminAuthenticated) return <AdminLogin onLogin={() => { setIsAdminAuthenticated(true); setCurrentView(View.ADMIN_DASHBOARD); }} onBack={() => setIsAdmin(false)} />;
      switch (currentView) {
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} setSettings={() => {}} services={services} setServices={() => {}} customers={customers} bookings={bookings} transactions={transactions} onImport={() => {}} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} services={services} customers={customers} teamMembers={settings.teamMembers} settings={settings} />;
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} onUpdateStatus={handleUpdateStatus} onUpdateDeposit={handleUpdateDeposit} onDeleteBooking={handleDeleteBooking} waitlist={waitlist} onRemoveWaitlist={(id) => deleteDoc(doc(db, "waitlist", id))} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={(id) => deleteDoc(doc(db, "customers", id))} onUpdate={(id, data) => updateDoc(doc(db, "customers", id), data)} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} setTransactions={() => {}} customers={customers} services={services} />;
        case View.ADMIN_VEO: return <AdminVeo />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} />;
      }
    }

    if (currentUser && currentView === View.CUSTOMER_DASHBOARD) {
       return (
         <CustomerDashboard 
            customer={currentUser} 
            bookings={bookings} 
            services={services}
            settings={settings}
            onBook={handleBook}
            onUpdateProfile={(upd) => updateDoc(doc(db, "customers", currentUser.id), upd)}
            onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }}
            onCancelBooking={async (id) => {
              await updateDoc(doc(db, "bookings", id), { status: 'cancelled' });
            }}
            onAddToWaitlist={handleAddToWaitlist}
            waitlist={waitlist.filter(w => w.customerId === currentUser.id)}
            onRemoveWaitlist={(id) => deleteDoc(doc(db, "waitlist", id))}
         />
       );
    }

    switch (currentView) {
      case View.CUSTOMER_REGISTER: return <CustomerRegister onRegister={handleRegister} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_LOGIN: return <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      default: return (
        <CustomerHome 
          settings={settings} services={services} bookings={bookings} 
          onBook={handleBook} 
          onAuthClick={() => setCurrentView(View.CUSTOMER_LOGIN)} 
          onAddToWaitlist={handleAddToWaitlist} 
          currentUser={currentUser} 
        />
      );
    }
  };

  return (
    <div className="min-h-screen bg-white">
      {currentView !== View.CUSTOMER_DASHBOARD && (
        <Navbar view={currentView} setView={setCurrentView} isAdmin={isAdmin} onToggleAdmin={() => { setIsAdmin(!isAdmin); if(!isAdminAuthenticated) setCurrentView(View.ADMIN_LOGIN); else setCurrentView(isAdmin ? View.CUSTOMER_HOME : View.ADMIN_DASHBOARD); }} salonName={settings.name} logo={settings.logo} currentUser={currentUser} onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }} onAdminLogout={() => { setIsAdminAuthenticated(false); setIsAdmin(false); setCurrentView(View.CUSTOMER_HOME); }} isAdminAuthenticated={isAdminAuthenticated} pendingBookingsCount={bookings.filter(b => b.status === 'pending').length} />
      )}
      <main className={currentView === View.CUSTOMER_DASHBOARD ? "" : "max-w-7xl mx-auto px-4 py-8"}>
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { Customer, Booking, Service, SalonSettings, TeamMember, WaitlistEntry } from '../types';
import { GoogleGenAI } from '@google/genai';

interface CustomerDashboardProps {
  customer: Customer;
  bookings: Booking[];
  services: Service[];
  settings: SalonSettings;
  onBook: (serviceId: string, dateTime: string, teamMemberId?: string) => void;
  onUpdateProfile: (updated: Partial<Customer>) => void;
  onLogout: () => void;
  onCancelBooking: (id: string) => void;
  onAddToWaitlist?: (serviceId: string, date: string) => void;
  waitlist?: WaitlistEntry[];
  onRemoveWaitlist?: (id: string) => void;
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ 
  customer, 
  bookings, 
  services, 
  settings,
  onBook,
  onUpdateProfile, 
  onLogout,
  onCancelBooking,
  onAddToWaitlist,
  waitlist = [],
  onRemoveWaitlist
}) => {
  const [activeTab, setActiveTab] = useState<'home' | 'agendar' | 'agenda' | 'perfil'>('home');
  const [careTips, setCareTips] = useState<string>('');
  const [isLoadingTips, setIsLoadingTips] = useState(false);

  const [bookingStep, setBookingStep] = useState<1 | 2 | 3>(1);
  const [selectedService, setSelectedService] = useState<Service | null>(null);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedTime, setSelectedTime] = useState<string>('');
  const [selectedProId, setSelectedProId] = useState<string>('');
  const [agreedToCancellation, setAgreedToCancellation] = useState(false);

  const myBookings = useMemo(() => 
    bookings.filter(b => b.customerId === customer.id && b.status !== 'cancelled')
      .sort((a, b) => new Date(b.dateTime).getTime() - new Date(a.dateTime).getTime()),
    [bookings, customer.id]
  );

  const nextBooking = useMemo(() => 
    myBookings.find(b => b.status === 'scheduled' || b.status === 'pending'),
    [myBookings]
  );

  const allPossibleSlots = useMemo(() => {
    const slots: string[] = [];
    const start = parseInt((settings.businessHours?.start || "08:00").split(':')[0]);
    const end = parseInt((settings.businessHours?.end || "19:00").split(':')[0]);
    for (let h = start; h < end; h++) {
      slots.push(`${h.toString().padStart(2, '0')}:00`);
      slots.push(`${h.toString().padStart(2, '0')}:30`);
    }
    return slots;
  }, [settings.businessHours]);

  const timeToMinutes = (time: string) => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
  };

  const currentSlotsAvailability = useMemo(() => {
    if (!selectedService) return {};
    const availability: Record<string, TeamMember[]> = {};
    const dateObj = new Date(selectedDate + 'T12:00:00');
    const dayOfWeek = dateObj.getDay();
    const pros = settings.teamMembers.filter(m => m.assignedServiceIds.includes(selectedService.id));

    allPossibleSlots.forEach(slot => {
      const slotStartMin = timeToMinutes(slot);
      const slotEndMin = slotStartMin + selectedService.duration;
      const freePros = pros.filter(pro => {
        if (pro.offDays?.includes(dayOfWeek)) return false;
        const proStartMin = timeToMinutes(pro.businessHours?.start || settings.businessHours.start);
        const proEndMin = timeToMinutes(pro.businessHours?.end || settings.businessHours.end);
        if (slotStartMin < proStartMin || slotEndMin > proEndMin) return false;
        const hasConflict = bookings.some(b => {
          if (b.teamMemberId !== pro.id || b.status === 'cancelled' || !b.dateTime.startsWith(selectedDate)) return false;
          const bStartMin = timeToMinutes(b.dateTime.split(' ')[1]);
          const bEndMin = bStartMin + (b.duration || 30);
          return slotStartMin < bEndMin && slotEndMin > bStartMin;
        });
        return !hasConflict;
      });
      if (freePros.length > 0) availability[slot] = freePros;
    });
    return availability;
  }, [selectedService, selectedDate, settings, bookings, allPossibleSlots]);

  const handleBookSubmit = () => {
    if (selectedService && selectedProId && selectedTime && agreedToCancellation) {
      onBook(selectedService.id, `${selectedDate} ${selectedTime}`, selectedProId);
      setBookingStep(3);
    } else if (!agreedToCancellation) {
      alert("Para agendar, você precisa estar ciente da nossa política de cancelamento.");
    }
  };

  const handleCancelClick = (bookingId: string) => {
    if (confirm("ATENÇÃO: O cancelamento deste agendamento implica na PERDA INTEGRAL do valor pago como sinal/reserva. Deseja prosseguir com o cancelamento?")) {
      onCancelBooking(bookingId);
      alert("Agendamento cancelado. Conforme nossa política, o sinal não será reembolsado.");
    }
  };

  const handleWaitlist = async (service: Service) => {
    if (onAddToWaitlist) {
      await onAddToWaitlist(service.id, new Date().toISOString().split('T')[0]);
      alert("Excelente! Você entrou na lista de espera para " + service.name + ". Avisaremos você assim que abrirmos a agenda!");
    }
  };

  useEffect(() => {
    if (activeTab === 'home' && myBookings.length > 0 && !careTips) {
      generateCareTips();
    }
  }, [activeTab]);

  const generateCareTips = async () => {
    setIsLoadingTips(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const lastService = myBookings[0]?.serviceName || "Estética";
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Dê 3 dicas curtas de cuidados para quem acabou de fazer ${lastService}. Seja elegante e carinhosa. Use emojis de beleza.`,
      });
      setCareTips(response.text || "");
    } catch (e) {
      setCareTips("Lembre-se de hidratar a pele e usar protetor solar diariamente.");
    } finally {
      setIsLoadingTips(false);
    }
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => onUpdateProfile({ profilePhoto: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="min-h-screen bg-[#FDFDFD] pb-32 animate-fade-in">
      {/* Header Estilo Mobile com Ícone M Dominante */}
      <header className="bg-tea-900 pt-12 pb-24 px-8 rounded-b-[4.5rem] shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-80 h-80 bg-white/5 rounded-full -mr-32 -mt-32 blur-[80px]"></div>
        <div className="max-w-md mx-auto flex flex-col items-center gap-6 relative z-10">
          <div className="w-full flex justify-between items-start mb-2">
            <button onClick={onLogout} className="p-4 bg-white/10 rounded-2xl text-white">🚪</button>
            <div className="text-right">
              <p className="text-[9px] font-bold text-tea-300 uppercase tracking-[0.3em] mb-1">Bem-vinda de volta</p>
              <h2 className="text-xl font-serif font-bold text-white italic">Studio Moriá</h2>
            </div>
          </div>

          <div className="flex items-center gap-6 w-full mt-4">
            <div className="w-24 h-24 rounded-[2.5rem] bg-white p-1.5 shadow-2xl relative group overflow-hidden flex-shrink-0">
              <div className="w-full h-full rounded-[2rem] overflow-hidden bg-tea-800 flex items-center justify-center">
                {customer.profilePhoto ? (
                  <img src={customer.profilePhoto} className="w-full h-full object-cover" alt="Perfil" />
                ) : (
                  <span className="text-white font-serif font-bold text-4xl">M</span>
                )}
              </div>
              <label className="absolute inset-0 cursor-pointer opacity-0 group-hover:opacity-100 bg-black/60 flex flex-col items-center justify-center transition-opacity">
                <span className="text-[7px] text-white font-bold uppercase tracking-widest">Alterar Foto</span>
                <input type="file" className="hidden" onChange={handlePhotoUpload} />
              </label>
            </div>
            <div className="flex-1">
              <p className="text-[10px] font-bold text-tea-200 uppercase tracking-widest mb-1">Olá, querida</p>
              <h1 className="text-2xl font-serif font-bold text-white italic tracking-wide">
                {customer.name.split(' ')[0]}
              </h1>
              <div className="h-px w-10 bg-tea-400/30 mt-2"></div>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-md mx-auto px-6 -mt-12 relative z-20">

        {/* Aba HOME */}
        {activeTab === 'home' && (
          <div className="space-y-6 animate-slide-up">
            {nextBooking ? (
              <div className="bg-white rounded-[3rem] shadow-2xl border border-tea-50 overflow-hidden">
                <div className="bg-tea-50/50 px-8 py-4 border-b border-tea-100 flex justify-between items-center">
                  <span className="text-[9px] font-bold text-tea-700 uppercase tracking-widest">Seu Próximo Cuidado</span>
                  <div className="flex gap-1">
                    <div className="w-1.5 h-1.5 bg-tea-500 rounded-full animate-pulse"></div>
                    <div className="w-1.5 h-1.5 bg-tea-500 rounded-full animate-pulse delay-75"></div>
                  </div>
                </div>
                <div className="p-10 text-center">
                  <h3 className="text-3xl font-serif font-bold text-tea-950 mb-2">{nextBooking.serviceName}</h3>
                  <p className="text-xs text-tea-500 font-bold uppercase tracking-widest mb-10 italic">Com nossa equipe</p>

                  <div className="grid grid-cols-2 gap-4 mb-10">
                    <div className="bg-gray-50/80 p-5 rounded-[2rem] border border-gray-100">
                      <p className="text-[9px] font-bold text-gray-400 uppercase mb-2 tracking-widest">Data</p>
                      <p className="font-bold text-tea-900 text-lg">{new Date(nextBooking.dateTime).toLocaleDateString()}</p>
                    </div>
                    <div className="bg-gray-50/80 p-5 rounded-[2rem] border border-gray-100">
                      <p className="text-[9px] font-bold text-gray-400 uppercase mb-2 tracking-widest">Hora</p>
                      <p className="font-bold text-tea-900 text-lg">{new Date(nextBooking.dateTime).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</p>
                    </div>
                  </div>

                  <button onClick={() => setActiveTab('agenda')} className="w-full py-6 bg-tea-800 text-white rounded-[2rem] font-bold text-[10px] uppercase tracking-[0.2em] shadow-xl shadow-tea-900/10 active:scale-95 transition-all">Ver agendamento</button>
                </div>
              </div>
            ) : (
              <div className="bg-white p-14 rounded-[4rem] shadow-xl border border-gray-50 text-center space-y-8">
                <div className="w-24 h-24 bg-tea-50 rounded-full flex items-center justify-center text-5xl mx-auto shadow-inner border-2 border-white">✨</div>
                <div className="space-y-3">
                  <h3 className="text-2xl font-serif font-bold text-tea-950 italic">Cuidado Studio Moriá</h3>
                  <p className="text-[11px] text-gray-400 font-light leading-relaxed max-w-[200px] mx-auto">Sua jornada de autocuidado merece um novo capítulo.</p>
                </div>
                <button onClick={() => setActiveTab('agendar')} className="bg-tea-800 text-white px-12 py-5 rounded-full font-bold text-[10px] uppercase tracking-widest shadow-2xl active:scale-95 transition-all">Escolher procedimento</button>
              </div>
            )}

            <div className="grid grid-cols-2 gap-4">
              <a 
                href={settings.googleMapsLink} 
                target="_blank" 
                rel="noreferrer"
                className="bg-white p-8 rounded-[3rem] shadow-sm border border-tea-50 flex flex-col items-center gap-4 active:scale-95 transition-all"
              >
                 <div className="text-3xl">📍</div>
                 <div className="text-center">
                    <p className="text-[9px] font-bold text-tea-600 uppercase tracking-widest mb-1">Localização</p>
                    <p className="text-[10px] text-tea-950 font-bold uppercase tracking-tight">Ver no Mapa</p>
                 </div>
              </a>
              <div className="bg-white p-8 rounded-[3rem] shadow-sm border border-tea-50 flex flex-col items-center gap-4">
                 <div className="text-3xl">🎁</div>
                 <div className="text-center">
                    <p className="text-[9px] font-bold text-tea-600 uppercase tracking-widest mb-1">Pontos</p>
                    <p className="text-[10px] text-tea-950 font-bold uppercase tracking-tight">Fidelidade</p>
                 </div>
              </div>
            </div>

            <div className="bg-white p-10 rounded-[3.5rem] shadow-sm border border-tea-50 relative overflow-hidden group">
               <div className="absolute top-0 left-0 w-1.5 h-full bg-tea-600"></div>
               <div className="flex items-center gap-4 mb-6">
                  <div className="w-12 h-12 bg-tea-50 rounded-2xl flex items-center justify-center text-2xl shadow-sm">🌿</div>
                  <h4 className="font-bold text-tea-900 text-sm tracking-widest uppercase">Dica Especial</h4>
               </div>
               {isLoadingTips ? (
                 <div className="space-y-3 animate-pulse">
                    <div className="h-3 bg-gray-100 rounded-full w-full"></div>
                    <div className="h-3 bg-gray-100 rounded-full w-4/5"></div>
                 </div>
               ) : (
                 <div className="text-xs text-gray-500 leading-relaxed italic font-light">
                   {careTips || "Realize um serviço para receber orientações personalizadas pós-procedimento."}
                 </div>
               )}
            </div>
          </div>
        )}

        {/* Aba AGENDAR */}
        {activeTab === 'agendar' && (
          <div className="space-y-6 animate-slide-up">
            {bookingStep === 1 && (
              <>
                <div className="flex items-center justify-between px-2 mb-4">
                   <h3 className="text-2xl font-serif font-bold text-tea-950 italic">Catálogo de Serviços</h3>
                   <span className="text-[10px] text-tea-400 font-bold uppercase tracking-widest">Moriá</span>
                </div>
                <div className="space-y-4">
                  {services.filter(s => s.isVisible).map(service => (
                    <div key={service.id} className="bg-white p-8 md:p-10 rounded-[3rem] border border-gray-100 shadow-sm flex flex-col gap-4">
                      <div className="flex items-center justify-between">
                        <div className="flex-1 pr-4">
                          <h4 className="font-bold text-tea-950 text-xl mb-1">{service.name}</h4>
                          {service.description && (
                            <p className="text-gray-400 text-xs font-light mb-4 line-clamp-3 leading-relaxed">
                              {service.description}
                            </p>
                          )}
                          <div className="flex items-center gap-5">
                            <span className="text-[10px] font-bold text-tea-700 bg-tea-50 px-3 py-1.5 rounded-xl uppercase tracking-widest">
                              <span className="opacity-50 text-[8px] mr-1">a partir de</span>
                              R$ {service.price.toFixed(2)}
                            </span>
                            <span className="text-[10px] font-bold text-gray-300 uppercase tracking-widest flex items-center gap-1.5">
                               <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                               {service.duration} min
                            </span>
                          </div>
                        </div>
                        <div className="w-12 h-12 bg-tea-900 text-white rounded-[1.5rem] flex items-center justify-center shadow-xl flex-shrink-0">✨</div>
                      </div>
                      <div className="grid grid-cols-2 gap-3 mt-4">
                        <button 
                          onClick={() => { setSelectedService(service); setBookingStep(2); }}
                          className="py-4 bg-tea-900 text-white rounded-2xl font-bold uppercase tracking-widest text-[9px] shadow-lg active:scale-95 transition-all"
                        >
                          Agendar
                        </button>
                        <button 
                          onClick={() => handleWaitlist(service)}
                          className="py-4 bg-white text-tea-700 border border-tea-100 rounded-2xl font-bold uppercase tracking-widest text-[8px] active:scale-95 transition-all"
                        >
                          Lista de Espera
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              </>
            )}

            {bookingStep === 2 && selectedService && (
              <div className="bg-white rounded-[3.5rem] p-10 shadow-2xl border border-tea-50 space-y-10 animate-fade-in mb-10">
                <div className="flex items-center gap-5 border-b border-gray-50 pb-8">
                   <button onClick={() => setBookingStep(1)} className="w-12 h-12 bg-gray-50 rounded-2xl flex items-center justify-center text-gray-400 hover:text-tea-800">←</button>
                   <div>
                     <h3 className="font-bold text-tea-950 text-lg">{selectedService.name}</h3>
                     <p className="text-[9px] text-gray-400 uppercase font-bold tracking-[0.3em]">Escolha data e horário</p>
                   </div>
                </div>

                <div className="space-y-8">
                  <div className="space-y-3">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] ml-2">Data</label>
                    <input 
                      type="date" 
                      value={selectedDate}
                      min={new Date().toISOString().split('T')[0]}
                      max={settings.agendaOpenUntil || undefined}
                      onChange={(e) => { setSelectedDate(e.target.value); setSelectedTime(''); }}
                      className="w-full p-6 bg-gray-50/80 rounded-[2rem] border-none font-bold text-tea-900 outline-none focus:ring-4 focus:ring-tea-50 transition-all"
                    />
                  </div>

                  <div className="space-y-4">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] ml-2">Horário disponível</label>
                    <div className="grid grid-cols-3 gap-3">
                      {allPossibleSlots.map(slot => {
                        const available = !!currentSlotsAvailability[slot];
                        return (
                          <button 
                            key={slot}
                            disabled={!available}
                            onClick={() => setSelectedTime(slot)}
                            className={`p-5 rounded-2xl text-[10px] font-bold border-2 transition-all ${
                              selectedTime === slot ? 'bg-tea-800 border-tea-800 text-white shadow-2xl shadow-tea-900/20' :
                              available ? 'bg-white border-tea-50 text-tea-900 hover:border-tea-200 shadow-sm' :
                              'bg-gray-50 border-transparent text-gray-200 opacity-50 cursor-not-allowed'
                            }`}
                          >
                            {slot}
                          </button>
                        );
                      })}
                    </div>
                  </div>

                  {selectedTime && (
                    <div className="space-y-4 animate-fade-in pt-4">
                       <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Profissional</label>
                       <div className="space-y-3">
                          {currentSlotsAvailability[selectedTime]?.map(pro => (
                            <button 
                              key={pro.id}
                              onClick={() => setSelectedProId(pro.id)}
                              className={`w-full p-6 rounded-[2.5rem] border-2 flex items-center justify-between transition-all ${selectedProId === pro.id ? 'border-tea-600 bg-tea-50 shadow-md' : 'bg-white border-gray-50 hover:border-tea-100'}`}
                            >
                              <div className="flex items-center gap-5">
                                <div className="w-12 h-12 bg-tea-900 text-white rounded-2xl flex items-center justify-center font-bold text-base shadow-lg">{pro.name.charAt(0)}</div>
                                <span className="font-bold text-base text-tea-900">{pro.name}</span>
                              </div>
                              {selectedProId === pro.id && (
                                <div className="w-8 h-8 bg-tea-600 text-white rounded-full flex items-center justify-center text-sm">✓</div>
                              )}
                            </button>
                          ))}
                       </div>
                    </div>
                  )}

                  {selectedProId && (
                    <div className="p-6 bg-red-50 rounded-[2rem] border border-red-100 space-y-4 animate-slide-up">
                      <label className="flex items-start gap-4 cursor-pointer group">
                        <div className="relative mt-1">
                          <input 
                            type="checkbox"
                            checked={agreedToCancellation}
                            onChange={(e) => setAgreedToCancellation(e.target.checked)}
                            className="peer appearance-none w-5 h-5 rounded border-2 border-red-200 checked:bg-red-600 checked:border-red-600 transition-all cursor-pointer"
                          />
                          <svg className="absolute top-0.5 left-0.5 w-4 h-4 text-white opacity-0 peer-checked:opacity-100 pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
                        </div>
                        <div className="flex-1">
                          <span className="text-[10px] font-bold text-red-900 uppercase tracking-widest leading-relaxed">
                            Estou ciente que o cancelamento do agendamento implica na perda integral do valor da antecipação (sinal).
                          </span>
                        </div>
                      </label>
                    </div>
                  )}
                </div>

                <button 
                  disabled={!selectedTime || !selectedProId || !agreedToCancellation}
                  onClick={handleBookSubmit}
                  className="w-full py-7 bg-tea-800 text-white rounded-[2.5rem] font-bold text-[11px] uppercase tracking-[0.2em] shadow-2xl disabled:bg-gray-100 disabled:text-gray-300 disabled:shadow-none transition-all active:scale-95"
                >
                  Confirmar agora
                </button>
              </div>
            )}

            {bookingStep === 3 && (
              <div className="text-center py-20 space-y-10 animate-slide-up bg-white rounded-[4rem] border border-tea-50 shadow-2xl px-10">
                <div className="w-32 h-32 bg-tea-50 rounded-full flex items-center justify-center text-7xl mx-auto shadow-inner border-4 border-white animate-bounce">⏳</div>
                <div className="space-y-3">
                  <h3 className="text-4xl font-serif font-bold text-tea-950 italic">Solicitado!</h3>
                  <p className="text-gray-400 text-[11px] leading-relaxed max-w-[220px] mx-auto font-light">Para validar sua vaga, envie agora o comprovante do sinal pelo WhatsApp.</p>
                </div>
                <button 
                  onClick={() => {
                    const msg = `Olá Studio Moriá! Solicitei ${selectedService?.name} para ${selectedDate} às ${selectedTime}. Segue comprovante do sinal.`;
                    window.open(`https://wa.me/${settings.socialLinks.whatsapp.replace(/\D/g, '')}?text=${encodeURIComponent(msg)}`, '_blank');
                    setActiveTab('agenda');
                    setBookingStep(1);
                  }}
                  className="w-full py-7 bg-tea-950 text-white rounded-[2.5rem] font-bold text-[10px] uppercase tracking-[0.2em] shadow-3xl flex items-center justify-center gap-4 hover:bg-black transition-colors"
                >
                   📱 Validar no WhatsApp
                </button>
              </div>
            )}
          </div>
        )}

        {/* Aba AGENDAMENTOS */}
        {activeTab === 'agenda' && (
          <div className="space-y-8 animate-slide-up">
             <div className="flex items-center justify-between px-4">
                <h3 className="text-2xl font-serif font-bold text-tea-950 italic">Minha Agenda</h3>
             </div>

             {/* Lista de Espera */}
             {waitlist && waitlist.length > 0 && (
               <div className="space-y-4">
                  <h4 className="text-[10px] font-bold text-orange-600 uppercase tracking-widest ml-4">Na Lista de Espera</h4>
                  {waitlist.map(entry => (
                    <div key={entry.id} className="bg-orange-50/30 p-8 rounded-[3rem] border border-orange-100 flex flex-col gap-4 shadow-sm relative overflow-hidden">
                      <div className="absolute top-0 right-0 p-3 text-orange-400 opacity-20 text-4xl">✨</div>
                      <div className="flex items-center gap-6">
                        <div className="w-16 h-16 rounded-[1.5rem] bg-orange-50 text-orange-600 flex items-center justify-center text-3xl shadow-inner">📝</div>
                        <div>
                          <h4 className="font-bold text-tea-950 text-lg mb-1">{entry.serviceName}</h4>
                          <div className="flex items-center gap-2">
                             <span className="px-3 py-1 bg-orange-100 text-orange-800 rounded-full text-[8px] font-bold uppercase tracking-widest">Aguardando Vaga</span>
                             <span className="text-[9px] text-orange-400 font-medium italic">Criado em {new Date(entry.createdAt).toLocaleDateString()}</span>
                          </div>
                        </div>
                      </div>
                      <button 
                        onClick={() => { if(confirm("Deseja sair da lista de espera para este serviço?")) onRemoveWaitlist?.(entry.id); }}
                        className="w-full py-4 text-orange-700 bg-white border border-orange-100 rounded-2xl font-bold uppercase text-[9px] tracking-widest hover:bg-orange-50 transition-colors"
                      >
                        Não quero mais aguardar
                      </button>
                    </div>
                  ))}
               </div>
             )}

             <div className="space-y-4">
                {myBookings.length > 0 && <h4 className="text-[10px] font-bold text-tea-400 uppercase tracking-widest ml-4">Meus Procedimentos</h4>}
                {myBookings.length > 0 ? myBookings.map(b => (
                  <div key={b.id} className="bg-white p-8 rounded-[3rem] border border-gray-100 flex flex-col gap-6 shadow-sm">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-6">
                        <div className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center text-3xl ${b.status === 'completed' ? 'bg-green-50 text-green-600' : 'bg-tea-50 text-tea-700 shadow-inner'}`}>
                           {b.status === 'completed' ? '✨' : '📅'}
                        </div>
                        <div>
                          <h4 className="font-bold text-tea-950 text-lg mb-1">{b.serviceName}</h4>
                          <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">
                             {new Date(b.dateTime).toLocaleDateString()} às {new Date(b.dateTime).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}
                          </p>
                        </div>
                      </div>
                      <div className={`px-4 py-2 rounded-full text-[9px] font-bold uppercase tracking-widest border ${
                        b.status === 'completed' ? 'bg-green-50 text-green-700 border-green-100' :
                        b.status === 'pending' ? 'bg-orange-50 text-orange-700 border-orange-100 animate-pulse' :
                        'bg-blue-50 text-blue-700 border-blue-100'
                      }`}>
                        {b.status === 'completed' ? 'Finalizado' : b.status === 'pending' ? 'Pendente' : 'Confirmado'}
                      </div>
                    </div>

                    {b.status !== 'completed' && b.status !== 'cancelled' && (
                      <div className="flex gap-2">
                        <button 
                          onClick={() => handleCancelClick(b.id)}
                          className="flex-1 py-4 text-red-500 bg-red-50 rounded-2xl font-bold uppercase text-[9px] tracking-widest border border-red-100 hover:bg-red-100 transition-colors"
                        >
                          Cancelar Agendamento
                        </button>
                      </div>
                    )}
                  </div>
                )) : (waitlist.length === 0 && (
                  <div className="py-24 text-center opacity-30 italic font-serif text-xl px-10 leading-relaxed">Você ainda não possui atendimentos ou registros de espera.</div>
                ))}
             </div>
          </div>
        )}

        {/* Aba PERFIL */}
        {activeTab === 'perfil' && (
          <div className="space-y-8 animate-slide-up">
             <div className="bg-white p-12 rounded-[4rem] shadow-sm border border-gray-100 space-y-10">
                <div className="space-y-6">
                  <div className="space-y-2">
                     <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-3">Nome</label>
                     <div className="p-6 bg-gray-50 rounded-[2rem] font-bold text-tea-950 text-sm shadow-inner">{customer.name}</div>
                  </div>
                  <div className="space-y-2">
                     <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-3">WhatsApp</label>
                     <div className="p-6 bg-gray-50 rounded-[2rem] font-bold text-tea-950 text-sm shadow-inner">{customer.whatsapp}</div>
                  </div>
                </div>
                <button onClick={onLogout} className="w-full py-6 bg-red-50 text-red-500 rounded-[2rem] font-bold text-[10px] uppercase tracking-[0.2em] border border-red-100 active:scale-95 transition-all">Sair da Conta</button>
             </div>

             <div className="text-center py-12 opacity-30 flex flex-col items-center gap-6">
                <div className="w-16 h-16 bg-tea-900 rounded-2xl flex items-center justify-center shadow-lg">
                   <span className="text-white font-serif font-bold text-2xl">M</span>
                </div>
                <p className="text-[10px] font-bold uppercase tracking-[0.8em]">Studio Moriá</p>
             </div>
          </div>
        )}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-3xl border-t border-gray-100 px-10 py-8 flex justify-between items-center z-[100] shadow-[0_-20px_60px_rgba(0,0,0,0.08)] rounded-t-[4rem]">
         {[
           { id: 'home', icon: '🏠', label: 'Início' },
           { id: 'agendar', icon: '✨', label: 'Agendar' },
           { id: 'agenda', icon: '🗓️', label: 'Agenda' },
           { id: 'perfil', icon: '👤', label: 'Eu' }
         ].map(tab => (
           <button 
             key={tab.id}
             onClick={() => { setActiveTab(tab.id as any); if(tab.id === 'agendar') setBookingStep(1); }}
             className={`flex flex-col items-center gap-2 transition-all duration-300 ${activeTab === tab.id ? 'text-tea-900 scale-110 -translate-y-2' : 'text-gray-300'}`}
           >
              <span className={`text-2xl ${activeTab === tab.id ? 'drop-shadow-[0_0_12px_rgba(41,91,53,0.4)]' : ''}`}>{tab.icon}</span>
              <span className={`text-[9px] font-bold uppercase tracking-[0.2em] ${activeTab === tab.id ? 'opacity-100' : 'opacity-0 h-0 overflow-hidden'}`}>{tab.label}</span>
              {activeTab === tab.id && <div className="w-1.5 h-1.5 bg-tea-900 rounded-full mt-1"></div>}
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

export enum View {
  CUSTOMER_HOME = 'CUSTOMER_HOME',
  CUSTOMER_LOGIN = 'CUSTOMER_LOGIN',
  CUSTOMER_REGISTER = 'CUSTOMER_REGISTER',
  CUSTOMER_PROFILE = 'CUSTOMER_PROFILE',
  CUSTOMER_DASHBOARD = 'CUSTOMER_DASHBOARD',
  ADMIN_LOGIN = 'ADMIN_LOGIN',
  ADMIN_DASHBOARD = 'ADMIN_DASHBOARD',
  ADMIN_CALENDAR = 'ADMIN_CALENDAR',
  ADMIN_FINANCE = 'ADMIN_FINANCE',
  ADMIN_CLIENTS = 'ADMIN_CLIENTS',
  ADMIN_CONFIRMATIONS = 'ADMIN_CONFIRMATIONS',
  ADMIN_VEO = 'ADMIN_VEO',
  ADMIN_SETTINGS = 'ADMIN_SETTINGS'
}

export interface Customer {
  id: string;
  name: string;
  whatsapp: string;
  cpf: string;
  password?: string;
  profilePhoto?: string;
  receivesNotifications: boolean;
  agreedToTerms: boolean;
  history: Booking[];
}

export interface Service {
  id: string;
  name: string;
  price: number;
  duration: number;
  description: string;
  isVisible: boolean;
}

export interface BusinessHours {
  start: string; // HH:mm
  end: string;   // HH:mm
}

export interface TeamMember {
  id: string;
  name: string;
  assignedServiceIds: string[];
  businessHours?: BusinessHours; // Horário individual opcional
  offDays?: number[]; // Dias de folga (0-6, onde 0 é domingo)
}

export interface Booking {
  id: string;
  customerId: string;
  customerName: string;
  serviceId: string;
  serviceName: string;
  teamMemberId?: string;
  teamMemberName?: string;
  dateTime: string;
  duration: number;
  status: 'pending' | 'scheduled' | 'completed' | 'cancelled' | 'blocked';
  depositStatus: 'pending' | 'paid'; 
  rescheduledCount?: number; 
  // Campos de Conformidade Jurídica
  agreedToCancellationPolicy: boolean;
  policyAgreedAt: string;
  ipAddress?: string; // Opcional, para rastro digital
  cancelledAt?: string;
}

export interface WaitlistEntry {
  id: string;
  customerId: string;
  customerName: string;
  customerWhatsapp: string;
  serviceId: string;
  serviceName: string;
  preferredDate: string;
  createdAt: string;
  status?: 'active' | 'cancelled';
  cancelledAt?: string;
}

export interface Transaction {
  id: string;
  type: 'payable' | 'receivable';
  description: string;
  amount: number;
  date: string;
  dueDate?: string;
  paidAt?: string; 
  status: 'pending' | 'paid';
  customerId?: string;
  customerName?: string;
  serviceId?: string;
  serviceName?: string;
  observation?: string;
}

export interface SalonSettings {
  name: string;
  primaryColor: string;
  logo: string;
  address?: string;
  googleMapsLink?: string;
  lastUpdated: number;
  teamMembers: TeamMember[];
  businessHours: BusinessHours;
  agendaOpenUntil?: string;
  servicesSectionTitle?: string;
  servicesSectionSubtitle?: string;
  socialLinks: {
    instagram: string;
    facebook: string;
    whatsapp: string;
  };
  usefulLinks: Array<{ label: string; url: string }>;
  comments: Array<{ author: string; text: string }>;
  photos: string[];
}

import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, WaitlistEntry } from './types.ts';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants.ts';
import { db } from './firebase.ts';
import { 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  addDoc, 
  updateDoc, 
  deleteDoc
} from "firebase/firestore";

import Navbar from './components/Navbar.tsx';
import CustomerHome from './components/CustomerHome.tsx';
import CustomerRegister from './components/CustomerRegister.tsx';
import CustomerLoginView from './components/CustomerLoginView.tsx';
import CustomerProfile from './components/CustomerProfile.tsx';
import CustomerDashboard from './components/CustomerDashboard.tsx';
import AdminDashboard from './components/AdminDashboard.tsx';
import AdminCalendar from './components/AdminCalendar.tsx';
import AdminFinance from './components/AdminFinance.tsx';
import AdminClients from './components/AdminClients.tsx';
import AdminConfirmations from './components/AdminConfirmations.tsx';
import AdminSettingsView from './components/AdminSettingsView.tsx';
import AdminVeo from './components/AdminVeo.tsx';
import AdminLogin from './components/AdminLogin.tsx';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);

  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [waitlist, setWaitlist] = useState<WaitlistEntry[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  useEffect(() => {
    const unsubSettings = onSnapshot(doc(db, "settings", "main"), (doc) => {
      if (doc.exists()) {
        setSettings(doc.data() as SalonSettings);
      } else {
        setDoc(doc.ref, DEFAULT_SETTINGS);
      }
    });

    const unsubServices = onSnapshot(collection(db, "services"), (snapshot) => {
      const data = snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Service));
      if (data.length === 0) {
        INITIAL_SERVICES.forEach(s => setDoc(doc(db, "services", s.id), s));
      }
      setServices(data);
    });

    const unsubCustomers = onSnapshot(collection(db, "customers"), (snapshot) => {
      setCustomers(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Customer)));
    });

    const unsubBookings = onSnapshot(collection(db, "bookings"), (snapshot) => {
      setBookings(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Booking)));
    });

    const unsubTransactions = onSnapshot(collection(db, "transactions"), (snapshot) => {
      setTransactions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Transaction)));
    });

    const unsubWaitlist = onSnapshot(collection(db, "waitlist"), (snapshot) => {
      setWaitlist(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as WaitlistEntry)));
    });

    return () => {
      unsubSettings(); unsubServices(); unsubCustomers();
      unsubBookings(); unsubTransactions(); unsubWaitlist();
    };
  }, []);

  useEffect(() => {
    const savedUser = localStorage.getItem('moria_user_session');
    if (savedUser) {
      try {
        const parsed = JSON.parse(savedUser);
        if (parsed && typeof parsed === 'object') setCurrentUser(parsed);
      } catch (e) { console.error("Error loading session"); }
    }
    if (localStorage.getItem('moria_admin_session') === 'true') setIsAdminAuthenticated(true);
  }, []);

  useEffect(() => {
    if (currentUser) {
      const cleanUser = {
        id: currentUser.id,
        name: currentUser.name,
        whatsapp: currentUser.whatsapp,
        cpf: currentUser.cpf,
        profilePhoto: currentUser.profilePhoto,
        receivesNotifications: !!currentUser.receivesNotifications
      };
      localStorage.setItem('moria_user_session', JSON.stringify(cleanUser));
      if (currentView === View.CUSTOMER_HOME || currentView === View.CUSTOMER_LOGIN) {
        setCurrentView(View.CUSTOMER_DASHBOARD);
      }
    } else {
      localStorage.removeItem('moria_user_session');
    }
    localStorage.setItem('moria_admin_session', isAdminAuthenticated.toString());
  }, [currentUser, isAdminAuthenticated, currentView]);

  const handleRegister = async (name: string, whatsapp: string, cpf: string, password: string, receivesNotifications: boolean) => {
    const id = Math.random().toString(36).substr(2, 9);
    const newCustomer: Customer = { id, name, whatsapp, cpf, password, receivesNotifications, agreedToTerms: true, history: [] };
    await setDoc(doc(db, "customers", id), newCustomer);
    setCurrentUser(newCustomer);
    setCurrentView(View.CUSTOMER_DASHBOARD);
  };

  const handleLogin = (cpf: string, pass: string) => {
    const user = customers.find(c => c.cpf === cpf && c.password === pass);
    if (user) { setCurrentUser(user); setCurrentView(View.CUSTOMER_DASHBOARD); }
    else alert("Dados incorretos.");
  };

  const handleBook = async (sid: string, dt: string, mid: string) => {
    if (!currentUser) { setCurrentView(View.CUSTOMER_LOGIN); return; }
    const srv = services.find(s => s.id === sid);
    const booking = {
      customerId: currentUser.id,
      customerName: currentUser.name,
      serviceId: sid,
      serviceName: srv?.name || '',
      dateTime: dt,
      duration: srv?.duration || 30,
      status: 'pending',
      depositStatus: 'pending',
      teamMemberId: mid,
      teamMemberName: settings.teamMembers.find(m => m.id === mid)?.name,
      agreedToCancellationPolicy: true,
      policyAgreedAt: new Date().toISOString()
    };
    await addDoc(collection(db, "bookings"), booking);
  };

  const handleAddToWaitlist = async (sid: string, dt: string) => {
    if (!currentUser) return;
    const srv = services.find(s => s.id === sid);
    await addDoc(collection(db, "waitlist"), {
      customerId: currentUser.id,
      customerName: currentUser.name,
      customerWhatsapp: currentUser.whatsapp,
      serviceId: sid,
      serviceName: srv?.name || '',
      preferredDate: dt,
      status: 'active',
      createdAt: new Date().toISOString()
    });
  };

  const handleUpdateStatus = async (id: string, status: any) => {
    const updateData: any = { status };
    if (status === 'cancelled') updateData.cancelledAt = new Date().toISOString();
    await updateDoc(doc(db, "bookings", id), updateData);
  };

  const handleUpdateDeposit = async (id: string, depositStatus: 'paid' | 'pending') => {
    await updateDoc(doc(db, "bookings", id), { depositStatus });
  };

  const handleCancelBooking = async (id: string) => {
    if (confirm("Deseja cancelar este agendamento? O registro será mantido no histórico da equipe.")) {
      await updateDoc(doc(db, "bookings", id), { 
        status: 'cancelled',
        cancelledAt: new Date().toISOString()
      });
    }
  };

  const handleCancelWaitlist = async (id: string) => {
    await updateDoc(doc(db, "waitlist", id), { 
      status: 'cancelled',
      cancelledAt: new Date().toISOString()
    });
  };

  const renderView = () => {
    if (isAdmin) {
      if (!isAdminAuthenticated) return <AdminLogin onLogin={() => { setIsAdminAuthenticated(true); setCurrentView(View.ADMIN_DASHBOARD); }} onBack={() => setIsAdmin(false)} />;
      switch (currentView) {
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} setSettings={() => {}} services={services} setServices={() => {}} customers={customers} bookings={bookings} transactions={transactions} onImport={() => {}} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} services={services} customers={customers} teamMembers={settings.teamMembers} settings={settings} />;
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} onUpdateStatus={handleUpdateStatus} onUpdateDeposit={handleUpdateDeposit} onDeleteBooking={handleCancelBooking} waitlist={waitlist} onRemoveWaitlist={handleCancelWaitlist} onReactivateWaitlist={(id) => updateDoc(doc(db, "waitlist", id), { status: 'active', cancelledAt: null })} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={(id) => updateDoc(doc(db, "customers", id), { status: 'inactive' })} onUpdate={(id, data) => updateDoc(doc(db, "customers", id), data)} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} setTransactions={() => {}} customers={customers} services={services} />;
        case View.ADMIN_VEO: return <AdminVeo />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} />;
      }
    }

    if (currentUser && currentView === View.CUSTOMER_DASHBOARD) {
       return (
         <CustomerDashboard 
            customer={currentUser} 
            bookings={bookings} 
            services={services}
            settings={settings}
            onBook={handleBook}
            onUpdateProfile={(upd) => updateDoc(doc(db, "customers", currentUser.id), upd)}
            onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }}
            onCancelBooking={handleCancelBooking}
            onAddToWaitlist={handleAddToWaitlist}
            waitlist={waitlist.filter(w => w.customerId === currentUser.id && w.status !== 'cancelled')}
            onRemoveWaitlist={handleCancelWaitlist}
         />
       );
    }

    switch (currentView) {
      case View.CUSTOMER_REGISTER: return <CustomerRegister onRegister={handleRegister} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_LOGIN: return <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      default: return (
        <CustomerHome 
          settings={settings} services={services} bookings={bookings} 
          onBook={handleBook} 
          onAuthClick={() => setCurrentView(View.CUSTOMER_LOGIN)} 
          onAddToWaitlist={handleAddToWaitlist} 
          currentUser={currentUser} 
        />
      );
    }
  };

  return (
    <div className="min-h-screen bg-white">
      {currentView !== View.CUSTOMER_DASHBOARD && (
        <Navbar view={currentView} setView={setCurrentView} isAdmin={isAdmin} onToggleAdmin={() => { setIsAdmin(!isAdmin); if(!isAdminAuthenticated) setCurrentView(View.ADMIN_LOGIN); else setCurrentView(isAdmin ? View.CUSTOMER_HOME : View.ADMIN_DASHBOARD); }} salonName={settings.name} logo={settings.logo} currentUser={currentUser} onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }} onAdminLogout={() => { setIsAdminAuthenticated(false); setIsAdmin(false); setCurrentView(View.CUSTOMER_HOME); }} isAdminAuthenticated={isAdminAuthenticated} pendingBookingsCount={bookings.filter(b => b.status === 'pending').length} />
      )}
      <main className={currentView === View.CUSTOMER_DASHBOARD ? "" : "max-w-7xl mx-auto px-4 py-8"}>
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Booking, Customer, WaitlistEntry } from '../types';

interface AdminConfirmationsProps {
  bookings: Booking[];
  customers: Customer[];
  onUpdateStatus: (id: string, status: 'scheduled' | 'cancelled' | 'completed') => void;
  onUpdateDeposit: (id: string, status: 'paid' | 'pending') => void;
  onDeleteBooking: (id: string) => void;
  waitlist: WaitlistEntry[];
  onRemoveWaitlist: (id: string) => void;
  onReactivateWaitlist?: (id: string) => void;
}

const AdminConfirmations: React.FC<AdminConfirmationsProps> = ({ 
  bookings, 
  onUpdateStatus, 
  onUpdateDeposit, 
  onDeleteBooking,
  waitlist = [], 
  onRemoveWaitlist,
  onReactivateWaitlist
}) => {
  const [activeTab, setActiveTab] = useState<'pending' | 'waitlist' | 'history'>('pending');

  const pending = bookings.filter(b => b.status === 'pending');
  const activeWaitlist = waitlist.filter(w => w.status !== 'cancelled');
  const cancelledBookings = bookings.filter(b => b.status === 'cancelled');
  const cancelledWaitlist = waitlist.filter(w => w.status === 'cancelled');

  const notifyWaitlist = (entry: WaitlistEntry) => {
    const text = `Olá ${entry.customerName}! O Studio Moriá Estética está com uma vaga disponível para ${entry.serviceName}. Você ainda tem interesse? Responda para confirmarmos seu horário!`;
    window.open(`https://wa.me/${entry.customerWhatsapp.replace(/\D/g, '')}?text=${encodeURIComponent(text)}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-fade-in">
      <div className="flex flex-wrap gap-3 border-b border-gray-100 pb-4 overflow-x-auto no-scrollbar">
        <button onClick={() => setActiveTab('pending')} className={`px-6 py-3 rounded-full text-[9px] font-bold uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === 'pending' ? 'bg-tea-900 text-white shadow-lg' : 'bg-gray-100 text-gray-400'}`}>Pedidos Pendentes ({pending.length})</button>
        <button onClick={() => setActiveTab('waitlist')} className={`px-6 py-3 rounded-full text-[9px] font-bold uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === 'waitlist' ? 'bg-orange-600 text-white shadow-lg' : 'bg-gray-100 text-gray-400'}`}>Lista de Espera ({activeWaitlist.length})</button>
        <button onClick={() => setActiveTab('history')} className={`px-6 py-3 rounded-full text-[9px] font-bold uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === 'history' ? 'bg-red-900 text-white shadow-lg' : 'bg-gray-100 text-gray-400'}`}>Histórico / Cancelados</button>
      </div>

      {activeTab === 'pending' && (
        <div className="grid grid-cols-1 gap-6">
          {pending.map(booking => (
            <div key={booking.id} className="bg-white p-8 rounded-[3rem] shadow-sm border border-gray-100 flex flex-col md:flex-row justify-between items-center gap-8 hover:border-tea-200 transition-all group">
              <div className="flex items-center gap-6">
                <div className="w-20 h-20 bg-tea-50 rounded-[2rem] flex items-center justify-center text-tea-700 text-3xl font-serif font-bold group-hover:bg-tea-100 transition-colors">{booking.customerName.charAt(0)}</div>
                <div>
                  <h3 className="text-2xl font-bold text-gray-800">{booking.customerName}</h3>
                  <div className="flex flex-wrap gap-2 mt-1">
                    <span className="text-[10px] text-tea-600 font-bold uppercase tracking-widest bg-tea-50 px-3 py-1 rounded-full">{booking.serviceName}</span>
                    <span className="text-[10px] text-gray-400 font-bold uppercase tracking-widest border border-gray-100 px-3 py-1 rounded-full">🗓️ {booking.dateTime}</span>
                    {booking.depositStatus === 'paid' ? (
                      <span className="text-[10px] bg-green-100 text-green-700 font-bold uppercase tracking-widest px-3 py-1 rounded-full">✅ Sinal Pago</span>
                    ) : (
                      <span className="text-[10px] bg-orange-100 text-orange-700 font-bold uppercase tracking-widest px-3 py-1 rounded-full">⏳ Aguardando Sinal</span>
                    )}
                  </div>
                </div>
              </div>
              <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto items-center">
                {booking.depositStatus !== 'paid' && (
                  <button 
                    onClick={() => onUpdateDeposit(booking.id, 'paid')}
                    className="px-6 py-4 bg-white border-2 border-orange-200 text-orange-700 rounded-2xl font-bold uppercase text-[10px] tracking-widest hover:bg-orange-50 transition-all"
                  >
                    Confirmar Sinal
                  </button>
                )}
                <button 
                  onClick={() => {
                    if(booking.depositStatus !== 'paid' && !confirm("O sinal ainda não consta como pago. Deseja confirmar mesmo assim?")) return;
                    onUpdateStatus(booking.id, 'scheduled');
                  }} 
                  className={`px-8 py-4 rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl transition-all ${booking.depositStatus === 'paid' ? 'bg-tea-800 text-white hover:bg-tea-950' : 'bg-gray-200 text-gray-400'}`}
                >
                  Aprovar Agenda
                </button>
                <button onClick={() => onUpdateStatus(booking.id, 'cancelled')} className="px-4 py-4 text-red-300 font-bold uppercase text-[10px] tracking-widest hover:text-red-500 transition-colors">Recusar</button>
              </div>
            </div>
          ))}
          {pending.length === 0 && <p className="text-center py-24 text-gray-300 italic font-serif text-lg">Nenhum pedido aguardando sua análise.</p>}
        </div>
      )}

      {activeTab === 'waitlist' && (
        <div className="grid grid-cols-1 gap-6">
          {activeWaitlist.map(entry => (
            <div key={entry.id} className="bg-white p-8 rounded-[3rem] shadow-sm border border-orange-100 flex flex-col md:flex-row justify-between items-center gap-8">
              <div className="flex items-center gap-6">
                <div className="w-16 h-16 bg-orange-50 rounded-2xl flex items-center justify-center text-orange-600 text-2xl font-serif font-bold">✨</div>
                <div>
                  <h3 className="text-xl font-bold text-gray-800">{entry.customerName}</h3>
                  <p className="text-xs text-orange-600 font-bold uppercase tracking-widest">Interesse em: {entry.serviceName}</p>
                </div>
              </div>
              <div className="flex gap-3">
                <button onClick={() => notifyWaitlist(entry)} className="px-8 py-4 bg-orange-600 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-lg">Avisar Vaga 📱</button>
                <button onClick={() => onRemoveWaitlist(entry.id)} className="px-8 py-4 text-gray-300 font-bold uppercase text-[10px] tracking-widest">Remover</button>
              </div>
            </div>
          ))}
          {activeWaitlist.length === 0 && <p className="text-center py-24 text-gray-300 italic">Lista de espera ativa vazia.</p>}
        </div>
      )}

      {activeTab === 'history' && (
        <div className="space-y-12">
           <section>
              <h4 className="text-[10px] font-bold text-red-900 uppercase tracking-[0.3em] mb-6 ml-4">Agendamentos Cancelados</h4>
              <div className="grid grid-cols-1 gap-4">
                {cancelledBookings.map(b => (
                  <div key={b.id} className="bg-red-50/20 p-6 rounded-[2rem] border border-red-100 flex justify-between items-center">
                    <div className="flex items-center gap-4">
                      <div className="text-2xl opacity-40">📅</div>
                      <div>
                        <p className="font-bold text-gray-800">{b.customerName}</p>
                        <p className="text-[10px] text-gray-400 font-medium uppercase tracking-widest">{b.serviceName} • {b.dateTime}</p>
                      </div>
                    </div>
                    <div className="text-right">
                       <p className="text-[8px] font-bold text-red-400 uppercase tracking-widest">Cancelado em:</p>
                       <p className="text-[10px] text-red-800 font-bold">{b.cancelledAt ? new Date(b.cancelledAt).toLocaleString() : 'Não registrado'}</p>
                    </div>
                  </div>
                ))}
                {cancelledBookings.length === 0 && <p className="text-center py-10 text-gray-300 italic text-sm">Nenhum agendamento cancelado.</p>}
              </div>
           </section>

           <section>
              <h4 className="text-[10px] font-bold text-orange-900 uppercase tracking-[0.3em] mb-6 ml-4">Desistências de Lista de Espera</h4>
              <div className="grid grid-cols-1 gap-4">
                {cancelledWaitlist.map(w => (
                  <div key={w.id} className="bg-orange-50/20 p-6 rounded-[2rem] border border-orange-100 flex justify-between items-center">
                    <div className="flex items-center gap-4">
                      <div className="text-2xl opacity-40">✨</div>
                      <div>
                        <p className="font-bold text-gray-800">{w.customerName}</p>
                        <p className="text-[10px] text-gray-400 font-medium uppercase tracking-widest">{w.serviceName}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-4">
                       <div className="text-right mr-4">
                          <p className="text-[8px] font-bold text-orange-400 uppercase tracking-widest">Removido em:</p>
                          <p className="text-[10px] text-orange-800 font-bold">{w.cancelledAt ? new Date(w.cancelledAt).toLocaleString() : 'Não registrado'}</p>
                       </div>
                       <button onClick={() => onReactivateWaitlist?.(w.id)} className="px-4 py-2 bg-white text-orange-600 border border-orange-100 rounded-xl text-[8px] font-bold uppercase tracking-widest hover:bg-orange-50 transition-all">Reativar</button>
                    </div>
                  </div>
                ))}
                {cancelledWaitlist.length === 0 && <p className="text-center py-10 text-gray-300 italic text-sm">Nenhuma desistência de espera.</p>}
              </div>
           </section>
        </div>
      )}
    </div>
  );
};

