import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, WaitlistEntry } from './types.ts';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants.ts';
import { db } from './firebase.ts';
import { 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  addDoc, 
  updateDoc, 
  deleteDoc
} from "firebase/firestore";

import Navbar from './components/Navbar.tsx';
import CustomerHome from './components/CustomerHome.tsx';
import CustomerRegister from './components/CustomerRegister.tsx';
import CustomerLoginView from './components/CustomerLoginView.tsx';
import CustomerProfile from './components/CustomerProfile.tsx';
import CustomerDashboard from './components/CustomerDashboard.tsx';
import AdminDashboard from './components/AdminDashboard.tsx';
import AdminCalendar from './components/AdminCalendar.tsx';
import AdminFinance from './components/AdminFinance.tsx';
import AdminClients from './components/AdminClients.tsx';
import AdminConfirmations from './components/AdminConfirmations.tsx';
import AdminSettingsView from './components/AdminSettingsView.tsx';
import AdminVeo from './components/AdminVeo.tsx';
import AdminLogin from './components/AdminLogin.tsx';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);

  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [waitlist, setWaitlist] = useState<WaitlistEntry[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  useEffect(() => {
    const unsubSettings = onSnapshot(doc(db, "settings", "main"), (doc) => {
      if (doc.exists()) {
        setSettings(doc.data() as SalonSettings);
      } else {
        setDoc(doc.ref, DEFAULT_SETTINGS);
      }
    });

    const unsubServices = onSnapshot(collection(db, "services"), (snapshot) => {
      const data = snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Service));
      if (data.length === 0) {
        INITIAL_SERVICES.forEach(s => setDoc(doc(db, "services", s.id), s));
      }
      setServices(data);
    });

    const unsubCustomers = onSnapshot(collection(db, "customers"), (snapshot) => {
      setCustomers(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Customer)));
    });

    const unsubBookings = onSnapshot(collection(db, "bookings"), (snapshot) => {
      setBookings(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Booking)));
    });

    const unsubTransactions = onSnapshot(collection(db, "transactions"), (snapshot) => {
      setTransactions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Transaction)));
    });

    const unsubWaitlist = onSnapshot(collection(db, "waitlist"), (snapshot) => {
      setWaitlist(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as WaitlistEntry)));
    });

    return () => {
      unsubSettings(); unsubServices(); unsubCustomers();
      unsubBookings(); unsubTransactions(); unsubWaitlist();
    };
  }, []);

  useEffect(() => {
    const savedUser = localStorage.getItem('moria_user_session');
    if (savedUser) {
      try {
        const parsed = JSON.parse(savedUser);
        if (parsed && typeof parsed === 'object') setCurrentUser(parsed);
      } catch (e) { console.error("Error loading session"); }
    }
    if (localStorage.getItem('moria_admin_session') === 'true') setIsAdminAuthenticated(true);
  }, []);

  useEffect(() => {
    if (currentUser) {
      const cleanUser = {
        id: currentUser.id,
        name: currentUser.name,
        whatsapp: currentUser.whatsapp,
        cpf: currentUser.cpf,
        profilePhoto: currentUser.profilePhoto,
        receivesNotifications: !!currentUser.receivesNotifications
      };
      localStorage.setItem('moria_user_session', JSON.stringify(cleanUser));
      if (currentView === View.CUSTOMER_HOME || currentView === View.CUSTOMER_LOGIN) {
        setCurrentView(View.CUSTOMER_DASHBOARD);
      }
    } else {
      localStorage.removeItem('moria_user_session');
    }
    localStorage.setItem('moria_admin_session', isAdminAuthenticated.toString());
  }, [currentUser, isAdminAuthenticated, currentView]);

  const handleRegister = async (name: string, whatsapp: string, cpf: string, password: string, receivesNotifications: boolean) => {
    const id = Math.random().toString(36).substr(2, 9);
    const newCustomer: Customer = { id, name, whatsapp, cpf, password, receivesNotifications, agreedToTerms: true, history: [] };
    await setDoc(doc(db, "customers", id), newCustomer);
    setCurrentUser(newCustomer);
    setCurrentView(View.CUSTOMER_DASHBOARD);
  };

  const handleLogin = (cpf: string, pass: string) => {
    const user = customers.find(c => c.cpf === cpf && c.password === pass);
    if (user) { setCurrentUser(user); setCurrentView(View.CUSTOMER_DASHBOARD); }
    else alert("Dados incorretos.");
  };

  const handleBook = async (sid: string, dt: string, mid: string) => {
    if (!currentUser) { setCurrentView(View.CUSTOMER_LOGIN); return; }
    const srv = services.find(s => s.id === sid);
    const booking = {
      customerId: currentUser.id,
      customerName: currentUser.name,
      serviceId: sid,
      serviceName: srv?.name || '',
      dateTime: dt,
      duration: srv?.duration || 30,
      status: 'pending',
      depositStatus: 'pending',
      teamMemberId: mid,
      teamMemberName: settings.teamMembers.find(m => m.id === mid)?.name,
      agreedToCancellationPolicy: true,
      policyAgreedAt: new Date().toISOString()
    };
    await addDoc(collection(db, "bookings"), booking);
  };

  const handleAddToWaitlist = async (sid: string, dt: string) => {
    if (!currentUser) return;
    const srv = services.find(s => s.id === sid);
    await addDoc(collection(db, "waitlist"), {
      customerId: currentUser.id,
      customerName: currentUser.name,
      customerWhatsapp: currentUser.whatsapp,
      serviceId: sid,
      serviceName: srv?.name || '',
      preferredDate: dt,
      status: 'active',
      createdAt: new Date().toISOString()
    });
  };

  const handleUpdateStatus = async (id: string, status: any) => {
    const updateData: any = { status };
    if (status === 'cancelled') updateData.cancelledAt = new Date().toISOString();
    await updateDoc(doc(db, "bookings", id), updateData);
  };

  const handleUpdateDeposit = async (id: string, depositStatus: 'paid' | 'pending') => {
    await updateDoc(doc(db, "bookings", id), { depositStatus });
  };

  const handleCancelBooking = async (id: string) => {
    if (confirm("Deseja cancelar este agendamento? O registro será mantido no histórico da equipe.")) {
      await updateDoc(doc(db, "bookings", id), { 
        status: 'cancelled',
        cancelledAt: new Date().toISOString()
      });
    }
  };

  const handleCancelWaitlist = async (id: string) => {
    await updateDoc(doc(db, "waitlist", id), { 
      status: 'cancelled',
      cancelledAt: new Date().toISOString()
    });
  };

  const handleAddTransaction = async (data: any) => {
    await addDoc(collection(db, "transactions"), data);
  };

  const handleUpdateTransaction = async (id: string, data: any) => {
    await updateDoc(doc(db, "transactions", id), data);
  };

  const handleDeleteTransaction = async (id: string) => {
    if (confirm("Deseja excluir permanentemente este registro financeiro?")) {
      await deleteDoc(doc(db, "transactions", id));
    }
  };

  const renderView = () => {
    if (isAdmin) {
      if (!isAdminAuthenticated) return <AdminLogin onLogin={() => { setIsAdminAuthenticated(true); setCurrentView(View.ADMIN_DASHBOARD); }} onBack={() => setIsAdmin(false)} />;
      switch (currentView) {
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} setSettings={() => {}} services={services} setServices={() => {}} customers={customers} bookings={bookings} transactions={transactions} onImport={() => {}} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} services={services} customers={customers} teamMembers={settings.teamMembers} settings={settings} />;
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} onUpdateStatus={handleUpdateStatus} onUpdateDeposit={handleUpdateDeposit} onDeleteBooking={handleCancelBooking} waitlist={waitlist} onRemoveWaitlist={handleCancelWaitlist} onReactivateWaitlist={(id) => updateDoc(doc(db, "waitlist", id), { status: 'active', cancelledAt: null })} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={(id) => updateDoc(doc(db, "customers", id), { status: 'inactive' })} onUpdate={(id, data) => updateDoc(doc(db, "customers", id), data)} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} onAdd={handleAddTransaction} onUpdate={handleUpdateTransaction} onDelete={handleDeleteTransaction} customers={customers} services={services} />;
        case View.ADMIN_VEO: return <AdminVeo />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} />;
      }
    }

    if (currentUser && currentView === View.CUSTOMER_DASHBOARD) {
       return (
         <CustomerDashboard 
            customer={currentUser} 
            bookings={bookings} 
            services={services}
            settings={settings}
            onBook={handleBook}
            onUpdateProfile={(upd) => updateDoc(doc(db, "customers", currentUser.id), upd)}
            onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }}
            onCancelBooking={handleCancelBooking}
            onAddToWaitlist={handleAddToWaitlist}
            waitlist={waitlist.filter(w => w.customerId === currentUser.id && w.status !== 'cancelled')}
            onRemoveWaitlist={handleCancelWaitlist}
         />
       );
    }

    switch (currentView) {
      case View.CUSTOMER_REGISTER: return <CustomerRegister onRegister={handleRegister} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_LOGIN: return <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      default: return (
        <CustomerHome 
          settings={settings} services={services} bookings={bookings} 
          onBook={handleBook} 
          onAuthClick={() => setCurrentView(View.CUSTOMER_LOGIN)} 
          onAddToWaitlist={handleAddToWaitlist} 
          currentUser={currentUser} 
        />
      );
    }
  };

  return (
    <div className="min-h-screen bg-white">
      {currentView !== View.CUSTOMER_DASHBOARD && (
        <Navbar view={currentView} setView={setCurrentView} isAdmin={isAdmin} onToggleAdmin={() => { setIsAdmin(!isAdmin); if(!isAdminAuthenticated) setCurrentView(View.ADMIN_LOGIN); else setCurrentView(isAdmin ? View.CUSTOMER_HOME : View.ADMIN_DASHBOARD); }} salonName={settings.name} logo={settings.logo} currentUser={currentUser} onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }} onAdminLogout={() => { setIsAdminAuthenticated(false); setIsAdmin(false); setCurrentView(View.CUSTOMER_HOME); }} isAdminAuthenticated={isAdminAuthenticated} pendingBookingsCount={bookings.filter(b => b.status === 'pending').length} />
      )}
      <main className={currentView === View.CUSTOMER_DASHBOARD ? "" : "max-w-7xl mx-auto px-4 py-8"}>
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Transaction, Customer, Service } from '../types';

interface AdminFinanceProps {
  transactions: Transaction[];
  onAdd: (data: any) => Promise<void>;
  onUpdate: (id: string, data: any) => Promise<void>;
  onDelete: (id: string) => Promise<void>;
  customers: Customer[];
  services: Service[];
}

const AdminFinance: React.FC<AdminFinanceProps> = ({ transactions, onAdd, onUpdate, onDelete, customers, services }) => {
  const [filter, setFilter] = useState<'all' | 'payable' | 'receivable'>('all');
  const [period, setPeriod] = useState<'current' | 'next' | 'custom'>('current');
  const [dateRange, setDateRange] = useState({
    start: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0],
    end: new Date(new Date().getFullYear(), new Date().getMonth() + 1, 0).toISOString().split('T')[0]
  });

  const [showAdd, setShowAdd] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [newTransaction, setNewTransaction] = useState({ 
    description: '', 
    amount: 0, 
    type: 'receivable' as 'payable' | 'receivable',
    customerId: '',
    serviceId: '',
    dueDate: new Date().toISOString().split('T')[0],
    status: 'pending' as 'pending' | 'paid',
    observation: ''
  });

  const handlePeriodChange = (p: 'current' | 'next' | 'custom') => {
    setPeriod(p);
    const now = new Date();
    if (p === 'current') {
      const start = new Date(now.getFullYear(), now.getMonth(), 1);
      const end = new Date(now.getFullYear(), now.getMonth() + 1, 0);
      setDateRange({ start: start.toISOString().split('T')[0], end: end.toISOString().split('T')[0] });
    } else if (p === 'next') {
      const start = new Date(now.getFullYear(), now.getMonth() + 1, 1);
      const end = new Date(now.getFullYear(), now.getMonth() + 2, 0);
      setDateRange({ start: start.toISOString().split('T')[0], end: end.toISOString().split('T')[0] });
    }
  };

  const handleServiceChange = (id: string) => {
    const service = services.find(s => s.id === id);
    if (service) {
      setNewTransaction({
        ...newTransaction,
        serviceId: id,
        description: service.name,
        amount: service.price
      });
    } else {
      setNewTransaction({ ...newTransaction, serviceId: '', description: '' });
    }
  };

  const handleAdd = async () => {
    if (newTransaction.description && newTransaction.amount > 0) {
      setIsSaving(true);
      try {
        const selectedCustomer = customers.find(c => c.id === newTransaction.customerId);
        const selectedService = services.find(s => s.id === newTransaction.serviceId);

        const transactionData = {
          description: newTransaction.description,
          amount: newTransaction.amount,
          type: newTransaction.type,
          date: new Date().toISOString(),
          dueDate: newTransaction.dueDate,
          paidAt: newTransaction.status === 'paid' ? new Date().toISOString() : null,
          status: newTransaction.status,
          customerId: newTransaction.customerId || null,
          customerName: selectedCustomer?.name || null,
          serviceId: newTransaction.serviceId || null,
          serviceName: selectedService?.name || null,
          observation: newTransaction.observation || null
        };

        await onAdd(transactionData);
        setShowAdd(false);
        setNewTransaction({ 
          description: '', 
          amount: 0, 
          type: 'receivable', 
          customerId: '', 
          serviceId: '',
          dueDate: new Date().toISOString().split('T')[0],
          status: 'pending',
          observation: ''
        });
      } finally {
        setIsSaving(false);
      }
    }
  };

  const toggleStatus = async (t: Transaction) => {
    const newStatus = t.status === 'paid' ? 'pending' : 'paid';
    await onUpdate(t.id, { 
      status: newStatus,
      paidAt: newStatus === 'paid' ? new Date().toISOString() : null
    });
  };

  const sendReminder = (t: Transaction) => {
    const customer = customers.find(c => c.id === t.customerId);
    if (!customer) return;

    const message = `Olá ${customer.name}! Passando para lembrar do seu pagamento de R$ ${t.amount.toFixed(2)} (${t.description}) que vence em ${new Date(t.dueDate!).toLocaleDateString()}. Studio Moriá Estética.`;
    window.open(`https://wa.me/${customer.whatsapp.replace(/\D/g, '')}?text=${encodeURIComponent(message)}`, '_blank');
  };

  const filtered = useMemo(() => {
    const start = new Date(dateRange.start + 'T00:00:00').getTime();
    const end = new Date(dateRange.end + 'T23:59:59').getTime();

    return transactions.filter(t => {
      // Filtrando pela data de VENCIMENTO para permitir previsibilidade
      const dateToCompare = t.dueDate || t.date;
      const d = new Date(dateToCompare).getTime();
      const inPeriod = d >= start && d <= end;
      const matchType = filter === 'all' || t.type === filter;
      return inPeriod && matchType;
    });
  }, [transactions, filter, dateRange]);

  const summary = useMemo(() => {
    const rec = filtered.filter(t => t.type === 'receivable').reduce((a, b) => a + b.amount, 0);
    const pay = filtered.filter(t => t.type === 'payable').reduce((a, b) => a + b.amount, 0);
    return { rec, pay, balance: rec - pay };
  }, [filtered]);

  const todayStr = new Date().toISOString().split('T')[0];

  return (
    <div className="space-y-8 animate-fade-in">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm">
        <div>
          <h2 className="text-2xl font-bold text-tea-950">Contas Financeiras</h2>
          <p className="text-gray-500 text-sm">Controle seu fluxo de caixa por data de vencimento.</p>
        </div>

        <div className="flex flex-wrap items-center gap-4">
          <div className="bg-gray-100 p-1 rounded-2xl flex gap-1">
            <button onClick={() => handlePeriodChange('current')} className={`px-4 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all ${period === 'current' ? 'bg-white text-tea-900 shadow-sm' : 'text-gray-400'}`}>Mês Atual</button>
            <button onClick={() => handlePeriodChange('next')} className={`px-4 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all ${period === 'next' ? 'bg-white text-tea-900 shadow-sm' : 'text-gray-400'}`}>Próximo</button>
            <button onClick={() => setPeriod('custom')} className={`px-4 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all ${period === 'custom' ? 'bg-white text-tea-900 shadow-sm' : 'text-gray-400'}`}>Personalizado</button>
          </div>

          {period === 'custom' && (
            <div className="flex items-center gap-2 animate-fade-in">
              <input type="date" value={dateRange.start} onChange={e => setDateRange({...dateRange, start: e.target.value})} className="p-2 bg-gray-50 rounded-xl text-[10px] font-bold border-none outline-none focus:ring-2 focus:ring-tea-100" />
              <input type="date" value={dateRange.end} onChange={e => setDateRange({...dateRange, end: e.target.value})} className="p-2 bg-gray-50 rounded-xl text-[10px] font-bold border-none outline-none focus:ring-2 focus:ring-tea-100" />
            </div>
          )}

          <button onClick={() => setShowAdd(true)} className="bg-tea-900 text-white px-6 py-4 rounded-2xl font-bold uppercase text-[10px] tracking-widest hover:bg-black transition-all shadow-lg">+ Novo Registro</button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-green-50 p-6 rounded-[2rem] border border-green-100">
          <p className="text-[10px] font-bold text-green-700 uppercase tracking-widest mb-1">Receitas Previstas</p>
          <p className="text-2xl font-bold text-green-900">R$ {summary.rec.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
        </div>
        <div className="bg-red-50 p-6 rounded-[2rem] border border-red-100">
          <p className="text-[10px] font-bold text-red-700 uppercase tracking-widest mb-1">Despesas Previstas</p>
          <p className="text-2xl font-bold text-red-900">R$ {summary.pay.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
        </div>
        <div className={`${summary.balance >= 0 ? 'bg-tea-50 border-tea-100' : 'bg-orange-50 border-orange-100'} p-6 rounded-[2rem] border`}>
          <p className={`text-[10px] font-bold ${summary.balance >= 0 ? 'text-tea-700' : 'text-orange-700'} uppercase tracking-widest mb-1`}>Saldo Operacional</p>
          <p className={`text-2xl font-bold ${summary.balance >= 0 ? 'text-tea-900' : 'text-orange-900'}`}>R$ {summary.balance.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
        </div>
      </div>

      <div className="flex gap-2">
        {(['all', 'receivable', 'payable'] as const).map(f => (
          <button 
            key={f}
            onClick={() => setFilter(f)}
            className={`px-5 py-2.5 rounded-full text-[10px] font-bold uppercase tracking-widest transition-all ${filter === f ? 'bg-tea-900 text-white shadow-md' : 'bg-gray-100 text-gray-400'}`}
          >
            {f === 'all' ? 'Tudo' : f === 'receivable' ? 'Receitas' : 'Despesas'}
          </button>
        ))}
      </div>

      {showAdd && (
        <div className="bg-white p-10 rounded-[3.5rem] shadow-2xl border border-tea-100 animate-slide-up">
          <h3 className="text-xl font-bold text-tea-900 mb-8 font-serif italic">Novo Registro Financeiro</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-10">
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase ml-2 tracking-widest">Serviço (Catálogo)</label>
              <select className="w-full p-5 bg-gray-50 rounded-2xl font-bold outline-none" value={newTransaction.serviceId} onChange={(e) => handleServiceChange(e.target.value)}>
                <option value="">Lançamento Manual...</option>
                {services.map(s => <option key={s.id} value={s.id}>{s.name} - R$ {s.price.toFixed(2)}</option>)}
              </select>
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase ml-2 tracking-widest">Descrição</label>
              <input className="w-full p-5 bg-gray-50 rounded-2xl font-bold outline-none" value={newTransaction.description} onChange={(e) => setNewTransaction({...newTransaction, description: e.target.value})} />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase ml-2 tracking-widest">Valor R$</label>
              <input type="number" className="w-full p-5 bg-gray-50 rounded-2xl font-bold outline-none" value={newTransaction.amount || ''} onChange={(e) => setNewTransaction({...newTransaction, amount: parseFloat(e.target.value)})} />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase ml-2 tracking-widest">Tipo</label>
              <select className="w-full p-5 bg-gray-50 rounded-2xl font-bold outline-none" value={newTransaction.type} onChange={(e) => setNewTransaction({...newTransaction, type: e.target.value as 'payable' | 'receivable'})}>
                <option value="receivable">Receita (Entrada)</option>
                <option value="payable">Despesa (Saída)</option>
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase ml-2 tracking-widest">Cliente</label>
              <select className="w-full p-5 bg-gray-50 rounded-2xl font-bold outline-none" value={newTransaction.customerId} onChange={(e) => setNewTransaction({...newTransaction, customerId: e.target.value})}>
                <option value="">Lançamento Avulso</option>
                {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase ml-2 tracking-widest">Vencimento</label>
              <input type="date" className="w-full p-5 bg-gray-50 rounded-2xl font-bold outline-none" value={newTransaction.dueDate} onChange={(e) => setNewTransaction({...newTransaction, dueDate: e.target.value})} />
            </div>
          </div>
          <div className="flex justify-end gap-4">
            <button onClick={() => setShowAdd(false)} className="px-8 py-4 text-gray-400 font-bold uppercase text-[10px] tracking-widest">Cancelar</button>
            <button 
              disabled={isSaving}
              onClick={handleAdd} 
              className="bg-tea-900 text-white px-12 py-4 rounded-2xl font-bold uppercase text-[10px] tracking-[0.2em] shadow-xl disabled:bg-gray-200 transition-colors"
            >
              {isSaving ? 'Salvando...' : 'Salvar Registro'}
            </button>
          </div>
        </div>
      )}

      <div className="bg-white rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-100">
                <th className="px-8 py-5 text-[9px] font-bold text-gray-400 uppercase tracking-widest">Data de Vencimento</th>
                <th className="px-8 py-5 text-[9px] font-bold text-gray-400 uppercase tracking-widest">Descrição</th>
                <th className="px-8 py-5 text-[9px] font-bold text-gray-400 uppercase tracking-widest">Status</th>
                <th className="px-8 py-5 text-[9px] font-bold text-gray-400 uppercase tracking-widest text-right">Valor</th>
                <th className="px-8 py-5 text-[9px] font-bold text-gray-400 uppercase tracking-widest text-center">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filtered.map(t => (
                <tr key={t.id} className={`hover:bg-tea-50/20 transition-all group ${t.dueDate === todayStr ? 'bg-orange-50/20' : ''}`}>
                  <td className="px-8 py-6">
                    <p className={`font-bold text-xs ${t.dueDate === todayStr ? 'text-orange-600' : 'text-tea-950'}`}>
                      {t.dueDate ? new Date(t.dueDate + 'T12:00:00').toLocaleDateString() : '-'}
                      {t.dueDate === todayStr && <span className="ml-2 text-[8px] bg-orange-100 px-1.5 py-0.5 rounded text-orange-700">HOJE</span>}
                    </p>
                    <p className="text-[8px] text-gray-300 uppercase font-bold">Lançado em: {new Date(t.date).toLocaleDateString()}</p>
                  </td>
                  <td className="px-8 py-6">
                    <p className="font-bold text-gray-800 text-sm">{t.description}</p>
                    <div className="flex gap-2 mt-1">
                      {t.customerName && <span className="text-[8px] bg-tea-50 text-tea-700 px-1.5 py-0.5 rounded font-bold uppercase">{t.customerName}</span>}
                      {t.serviceName && <span className="text-[8px] bg-blue-50 text-blue-700 px-1.5 py-0.5 rounded font-bold uppercase">{t.serviceName}</span>}
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <button 
                      onClick={() => toggleStatus(t)}
                      className={`px-3 py-1 rounded-full text-[9px] font-bold uppercase tracking-widest transition-all ${t.status === 'paid' ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-orange-700 shadow-sm'}`}
                    >
                      {t.status === 'paid' ? 'Pago' : 'Pendente'}
                    </button>
                  </td>
                  <td className={`px-8 py-6 font-bold text-right text-sm ${t.type === 'receivable' ? 'text-tea-700' : 'text-red-500'}`}>
                    {t.type === 'receivable' ? '+' : '-'} R$ {t.amount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                  </td>
                  <td className="px-8 py-6 text-center">
                    <div className="flex justify-center gap-2">
                      {t.customerId && t.status === 'pending' && (
                        <button onClick={() => sendReminder(t)} className="p-3 bg-white border border-tea-50 rounded-xl text-lg shadow-sm hover:scale-110 transition-transform">📱</button>
                      )}
                      <button onClick={() => onDelete(t.id)} className="p-3 text-red-200 hover:text-red-500 transition-colors">🗑️</button>
                    </div>
                  </td>
                </tr>
              ))}
              {filtered.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-8 py-24 text-center text-gray-300 italic font-serif">Nenhum registro de vencimento encontrado para este período.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

