                  </span>
                </button>
              ))}
            </div>

            <textarea
              className="w-full p-5 bg-gray-50 rounded-2xl border-none outline-none focus:ring-2 focus:ring-tea-100 text-xs mb-8 h-24 resize-none placeholder-gray-300"
