                            type="password" 
                            required
                            className="w-full p-4 rounded-2xl bg-white border border-gray-100 outline-none focus:ring-2 focus:ring-tea-100"
                            value={pwdData.new}
                            onChange={(e) => setPwdData({...pwdData, new: e.target.value})}
