import React, { useState } from 'react';
import { Customer, Promotion } from '../types';
import { GoogleGenAI } from '@google/genai';
import { db } from '../firebase.ts';
import { collection, addDoc, deleteDoc, doc, updateDoc } from "firebase/firestore";

interface AdminMarketingProps {
  customers: Customer[];
  promotions: Promotion[];
}

const AdminMarketing: React.FC<AdminMarketingProps> = ({ customers, promotions }) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [topic, setTopic] = useState('');
  const [type, setType] = useState<'promotion' | 'tip'>('promotion');
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [showHistory, setShowHistory] = useState(false);

  const eligibleCustomers = customers.filter(c => c.receivesNotifications);

  const generateSmartContent = async () => {
    if (!topic) return alert("Dê um tema para a IA trabalhar.");
    setIsGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Crie uma ${type === 'promotion' ? 'promoção irresistível' : 'dica de beleza elegante'} para um salão de estética de luxo chamado Studio Moriá. Tema: ${topic}. 
      Retorne em formato JSON: { "title": "Título curto e chamativo", "content": "Texto envolvente com emojis" }`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { responseMimeType: "application/json" }
      });

      const data = JSON.parse(response.text);
      setTitle(data.title);
      setContent(data.content);
    } catch (e) {
      console.error(e);
      alert("Erro ao gerar conteúdo inteligente.");
    } finally {
      setIsGenerating(false);
    }
  };

  const saveAndBroadcast = async () => {
    if (!title || !content) return alert("Preencha título e conteúdo.");
    try {
      await addDoc(collection(db, "promotions"), {
        title,
        content,
        type,
        createdAt: new Date().toISOString(),
        isActive: true
      });
      alert(`Conteúdo salvo! Ele agora aparece para as clientes no painel. Total de clientes elegíveis para WhatsApp: ${eligibleCustomers.length}`);
      setTitle('');
      setContent('');
      setTopic('');
    } catch (e) {
      console.error(e);
    }
  };

  const sendWhatsAppBatch = (promo: Promotion) => {
    if (eligibleCustomers.length === 0) return alert("Nenhuma cliente aceitou receber notificações.");

    const message = `🌟 *STUDIO MORIÁ ESTÉTICA* 🌟\n\n*${promo.title}*\n\n${promo.content}\n\nAcesse nosso app para agendar seu horário!`;

    // Como estamos no browser, abrimos o primeiro link ou fornecemos uma lista para o admin clicar
    const first = eligibleCustomers[0];
    const url = `https://wa.me/${first.whatsapp.replace(/\D/g, '')}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');

    alert(`Iniciamos o envio para ${first.name}. Para os demais ${eligibleCustomers.length - 1} clientes, você pode gerenciar individualmente na lista de clientes.`);
  };

  const deletePromotion = async (id: string) => {
    if (confirm("Deseja remover este conteúdo da visualização das clientes?")) {
      await deleteDoc(doc(db, "promotions", id));
    }
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="bg-white p-10 rounded-[3rem] shadow-sm border border-gray-100">
        <div className="flex justify-between items-center mb-10">
           <div>
             <h2 className="text-3xl font-serif text-tea-950 font-bold italic">Marketing Inteligente</h2>
             <p className="text-gray-400 text-sm italic">Crie campanhas e dicas para suas clientes fiéis.</p>
           </div>
           <button 
             onClick={() => setShowHistory(!showHistory)}
             className="px-6 py-3 border-2 border-tea-100 text-tea-700 rounded-2xl text-[10px] font-bold uppercase tracking-widest hover:bg-tea-50 transition-all"
           >
             {showHistory ? "Criar Novo" : "Ver Histórico"}
           </button>
        </div>

        {!showHistory ? (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
            <div className="space-y-8">
              <div className="bg-tea-50/50 p-8 rounded-[2.5rem] border border-tea-100 space-y-6">
                <h4 className="text-[10px] font-bold text-tea-700 uppercase tracking-widest">IA Copywriter</h4>
                <div className="space-y-4">
                  <div className="flex gap-2">
                    <button 
                      onClick={() => setType('promotion')}
                      className={`flex-1 py-3 rounded-xl text-[10px] font-bold uppercase transition-all ${type === 'promotion' ? 'bg-tea-900 text-white shadow-md' : 'bg-white text-gray-400 border border-gray-100'}`}
                    >
                      Promoção
                    </button>
                    <button 
                      onClick={() => setType('tip')}
                      className={`flex-1 py-3 rounded-xl text-[10px] font-bold uppercase transition-all ${type === 'tip' ? 'bg-tea-900 text-white shadow-md' : 'bg-white text-gray-400 border border-gray-100'}`}
                    >
                      Dica de Beleza
                    </button>
                  </div>
                  <input 
                    type="text" 
                    placeholder="Sobre o que quer falar? (Ex: Dia das Mães, Verão, Limpeza de Pele)"
                    className="w-full p-5 rounded-2xl bg-white border border-tea-100 outline-none focus:ring-4 focus:ring-tea-50 transition-all text-sm"
                    value={topic}
                    onChange={(e) => setTopic(e.target.value)}
                  />
                  <button 
                    onClick={generateSmartContent}
                    disabled={isGenerating}
                    className="w-full py-5 bg-tea-800 text-white rounded-2xl font-bold uppercase tracking-widest text-[10px] shadow-xl hover:bg-black transition-all disabled:bg-gray-200"
                  >
                    {isGenerating ? "Criando magia..." : "✨ Gerar com Inteligência Artificial"}
                  </button>
                </div>
              </div>

              <div className="p-8 bg-orange-50/50 rounded-[2.5rem] border border-orange-100 flex items-center gap-6">
                 <div className="text-3xl">🎯</div>
                 <div>
                    <p className="text-[10px] font-bold text-orange-700 uppercase tracking-widest mb-1">Público Alvo</p>
                    <p className="text-lg font-bold text-orange-950">{eligibleCustomers.length} Clientes</p>
                    <p className="text-[9px] text-orange-400 italic">Cadastrados que aceitam receber notificações promocionais.</p>
                 </div>
              </div>
            </div>

            <div className="space-y-6">
               <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Conteúdo da Campanha</h4>
               <input 
                 type="text" 
                 placeholder="Título da Campanha"
                 className="w-full p-5 rounded-2xl bg-gray-50 border-none font-bold text-tea-950 text-lg outline-none focus:ring-4 focus:ring-tea-50"
                 value={title}
                 onChange={(e) => setTitle(e.target.value)}
               />
               <textarea 
                 rows={8}
                 placeholder="Escreva aqui a mensagem ou a dica..."
                 className="w-full p-6 rounded-3xl bg-gray-50 border-none text-gray-700 text-sm outline-none focus:ring-4 focus:ring-tea-50 resize-none leading-relaxed"
                 value={content}
                 onChange={(e) => setContent(e.target.value)}
               />
               <button 
                 onClick={saveAndBroadcast}
                 className="w-full py-6 bg-tea-950 text-white rounded-3xl font-bold uppercase tracking-[0.2em] text-[11px] shadow-2xl hover:bg-black transition-all active:scale-95"
               >
                 Publicar no App das Clientes 📢
               </button>
            </div>
          </div>
        ) : (
          <div className="space-y-4">
            {promotions.sort((a,b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()).map(promo => (
              <div key={promo.id} className="p-8 bg-gray-50 rounded-[2.5rem] border border-gray-100 flex flex-col md:flex-row justify-between items-center gap-6">
                <div className="flex-1">
                   <div className="flex items-center gap-3 mb-2">
                      <span className={`px-3 py-1 rounded-full text-[8px] font-bold uppercase tracking-widest ${promo.type === 'promotion' ? 'bg-tea-900 text-white' : 'bg-blue-100 text-blue-700'}`}>
                        {promo.type === 'promotion' ? 'Promoção' : 'Dica'}
                      </span>
                      <span className="text-[9px] text-gray-400 italic">{new Date(promo.createdAt).toLocaleDateString()}</span>
                   </div>
                   <h4 className="font-bold text-tea-950 text-xl mb-1">{promo.title}</h4>
                   <p className="text-gray-500 text-xs line-clamp-2 italic">{promo.content}</p>
                </div>
                <div className="flex gap-2">
                   <button 
                     onClick={() => sendWhatsAppBatch(promo)}
                     className="px-6 py-4 bg-white text-tea-700 border border-tea-100 rounded-2xl text-[9px] font-bold uppercase tracking-widest shadow-sm hover:bg-tea-50 transition-all"
                   >
                     📱 WhatsApp
                   </button>
                   <button 
                     onClick={() => deletePromotion(promo.id)}
                     className="p-4 text-red-300 hover:text-red-500 transition-colors"
                   >
                     🗑️
                   </button>
                </div>
              </div>
            ))}
            {promotions.length === 0 && <p className="text-center py-20 text-gray-300 italic">Nenhuma campanha realizada ainda.</p>}
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminMarketing;

import React, { useState, useEffect, useMemo } from 'react';
import { Customer, Booking, Service, SalonSettings, TeamMember, WaitlistEntry, Promotion } from '../types';
import { GoogleGenAI } from '@google/genai';
import { db } from '../firebase.ts';
import { doc, updateDoc } from "firebase/firestore";

interface CustomerDashboardProps {
  customer: Customer;
  bookings: Booking[];
  services: Service[];
  settings: SalonSettings;
  onBook: (serviceId: string, dateTime: string, teamMemberId?: string) => void;
  onUpdateProfile: (updated: Partial<Customer>) => void;
  onLogout: () => void;
  onCancelBooking: (id: string) => void;
  onAddToWaitlist?: (serviceId: string, date: string) => void;
  waitlist?: WaitlistEntry[];
  onRemoveWaitlist?: (id: string) => void;
  promotions?: Promotion[];
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ 
  customer, 
  bookings, 
  services, 
  settings,
  onBook,
  onUpdateProfile, 
  onLogout,
  onCancelBooking,
  onAddToWaitlist,
  waitlist = [],
  onRemoveWaitlist,
  promotions = []
}) => {
  const [activeTab, setActiveTab] = useState<'home' | 'agendar' | 'agenda' | 'perfil'>('home');
  const [careTips, setCareTips] = useState<string>('');
  const [isLoadingTips, setIsLoadingTips] = useState(false);

  // Estados de Agendamento
  const [bookingStep, setBookingStep] = useState<1 | 2 | 3>(1);
  const [selectedService, setSelectedService] = useState<Service | null>(null);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedTime, setSelectedTime] = useState<string>('');
  const [selectedProId, setSelectedProId] = useState<string>('');
  const [agreedToCancellation, setAgreedToCancellation] = useState(false);

  // Estados de Avaliação
  const [reviewModal, setReviewModal] = useState<{ open: boolean; booking: Booking | null }>({ open: false, booking: null });
  const [rating, setRating] = useState(0);
  const [hoverRating, setHoverRating] = useState(0);
  const [comment, setComment] = useState('');
  const [reviewPhoto, setReviewPhoto] = useState<string | null>(null);
  const [isSubmittingReview, setIsSubmittingReview] = useState(false);

  // Estados de Troca de Senha
  const [showPasswordForm, setShowPasswordForm] = useState(false);
  const [pwdData, setPwdData] = useState({ current: '', new: '', confirm: '' });
  const [isUpdatingPwd, setIsUpdatingPwd] = useState(false);

  const myBookings = useMemo(() => 
    bookings.filter(b => b.customerId === customer.id && b.status !== 'cancelled')
      .sort((a, b) => new Date(b.dateTime).getTime() - new Date(a.dateTime).getTime()),
    [bookings, customer.id]
  );

  // Verificar se há agendamentos finalizados sem avaliação ao carregar
  useEffect(() => {
    const unreviewed = myBookings.find(b => b.status === 'completed' && !b.rating);
    if (unreviewed) {
      setReviewModal({ open: true, booking: unreviewed });
    }
  }, [myBookings]);

  const nextBooking = useMemo(() => 
    myBookings.find(b => b.status === 'scheduled' || b.status === 'pending'),
    [myBookings]
  );

  const activePromotions = useMemo(() => 
    promotions.filter(p => p.isActive).sort((a,b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()),
    [promotions]
  );

  const allPossibleSlots = useMemo(() => {
    const slots: string[] = [];
    const start = parseInt((settings.businessHours?.start || "08:00").split(':')[0]);
    const end = parseInt((settings.businessHours?.end || "19:00").split(':')[0]);
    for (let h = start; h < end; h++) {
      slots.push(`${h.toString().padStart(2, '0')}:00`);
      slots.push(`${h.toString().padStart(2, '0')}:30`);
    }
    return slots;
  }, [settings.businessHours]);

  const timeToMinutes = (time: string) => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
  };

  const currentSlotsAvailability = useMemo(() => {
    if (!selectedService) return {};
    const availability: Record<string, TeamMember[]> = {};
    const dateObj = new Date(selectedDate + 'T12:00:00');
    const dayOfWeek = dateObj.getDay();
    const pros = settings.teamMembers.filter(m => m.assignedServiceIds.includes(selectedService.id));

    allPossibleSlots.forEach(slot => {
      const slotStartMin = timeToMinutes(slot);
      const slotEndMin = slotStartMin + selectedService.duration;
      const freePros = pros.filter(pro => {
        if (pro.offDays?.includes(dayOfWeek)) return false;
        const proStartMin = timeToMinutes(pro.businessHours?.start || settings.businessHours.start);
        const proEndMin = timeToMinutes(pro.businessHours?.end || settings.businessHours.end);
        if (slotStartMin < proStartMin || slotEndMin > proEndMin) return false;
        const hasConflict = bookings.some(b => {
          if (b.teamMemberId !== pro.id || b.status === 'cancelled' || !b.dateTime.startsWith(selectedDate)) return false;
          const bStartMin = timeToMinutes(b.dateTime.split(' ')[1]);
          const bEndMin = bStartMin + (b.duration || 30);
          return slotStartMin < bEndMin && slotEndMin > bStartMin;
        });
        return !hasConflict;
      });
      if (freePros.length > 0) availability[slot] = freePros;
    });
    return availability;
  }, [selectedService, selectedDate, settings, bookings, allPossibleSlots]);

  const handleBookSubmit = () => {
    if (selectedService && selectedProId && selectedTime && agreedToCancellation) {
      onBook(selectedService.id, `${selectedDate} ${selectedTime}`, selectedProId);
      setBookingStep(3);
    } else if (!agreedToCancellation) {
      alert("Para agendar, você precisa estar ciente da nossa política de cancelamento.");
    }
  };

  const handleCancelClick = (bookingId: string) => {
    if (confirm("ATENÇÃO: O cancelamento deste agendamento implica na PERDA INTEGRAL do valor pago como sinal/reserva. Deseja prosseguir com o cancelamento?")) {
      onCancelBooking(bookingId);
      alert("Agendamento cancelado. Conforme nossa política, o sinal não será reembolsado.");
    }
  };

  const submitReview = async () => {
    if (!reviewModal.booking || rating === 0) return;
    setIsSubmittingReview(true);
    try {
      const bookingRef = doc(db, "bookings", reviewModal.booking.id);
      await updateDoc(bookingRef, {
        rating,
        reviewComment: comment,
        reviewPhoto: reviewPhoto,
        reviewedAt: new Date().toISOString()
      });
      setReviewModal({ open: false, booking: null });
      setRating(0);
      setComment('');
      setReviewPhoto(null);
      alert("Obrigada pelo carinho! Sua avaliação é muito importante para nós.");
    } catch (e) {
      console.error(e);
      alert("Erro ao salvar avaliação. Tente novamente.");
    } finally {
      setIsSubmittingReview(false);
    }
  };

  const handleReviewPhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setReviewPhoto(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handlePasswordUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (pwdData.current !== customer.password) {
      alert("Senha atual incorreta.");
      return;
    }
    if (pwdData.new !== pwdData.confirm) {
      alert("As novas senhas não coincidem.");
      return;
    }
    if (pwdData.new.length < 6) {
      alert("A nova senha deve ter no mínimo 6 caracteres.");
      return;
    }

    setIsUpdatingPwd(true);
    try {
      const customerRef = doc(db, "customers", customer.id);
      await updateDoc(customerRef, { password: pwdData.new });
      alert("Senha atualizada com sucesso!");
      setShowPasswordForm(false);
      setPwdData({ current: '', new: '', confirm: '' });
    } catch (error) {
      console.error(error);
      alert("Erro ao atualizar senha.");
    } finally {
      setIsUpdatingPwd(false);
    }
  };

  const handleWaitlist = async (service: Service) => {
    if (onAddToWaitlist) {
      await onAddToWaitlist(service.id, new Date().toISOString().split('T')[0]);
      alert("Excelente! Você entrou na lista de espera para " + service.name + ". Avisaremos você assim que abrirmos a agenda!");
    }
  };

  useEffect(() => {
    if (activeTab === 'home' && myBookings.length > 0 && !careTips) {
      generateCareTips();
    }
  }, [activeTab]);

  const generateCareTips = async () => {
    setIsLoadingTips(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const lastService = myBookings[0]?.serviceName || "Estética";
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Dê 3 dicas curtas de cuidados para quem acabou de fazer ${lastService}. Seja elegante e carinhosa. Use emojis de beleza.`,
      });
      setCareTips(response.text || "");
    } catch (e) {
      setCareTips("Lembre-se de hidratar a pele e usar protetor solar diariamente.");
    } finally {
      setIsLoadingTips(false);
    }
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => onUpdateProfile({ profilePhoto: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="min-h-screen bg-[#FDFDFD] pb-32 animate-fade-in">
      {/* Header Estilo Mobile com Ícone M Dominante */}
      <header className="bg-tea-900 pt-12 pb-24 px-8 rounded-b-[4.5rem] shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-80 h-80 bg-white/5 rounded-full -mr-32 -mt-32 blur-[80px]"></div>
        <div className="max-w-md mx-auto flex flex-col items-center gap-6 relative z-10">
          <div className="w-full flex justify-between items-start mb-2">
            <button onClick={onLogout} className="p-4 bg-white/10 rounded-2xl text-white">🚪</button>
            <div className="text-right">
              <p className="text-[9px] font-bold text-tea-300 uppercase tracking-[0.3em] mb-1">Bem-vinda de volta</p>
              <h2 className="text-xl font-serif font-bold text-white italic">Studio Moriá</h2>
            </div>
          </div>

          <div className="flex items-center gap-6 w-full mt-4">
            <div className="w-24 h-24 rounded-[2.5rem] bg-white p-1.5 shadow-2xl relative group overflow-hidden flex-shrink-0">
              <div className="w-full h-full rounded-[2rem] overflow-hidden bg-tea-800 flex items-center justify-center">
                {customer.profilePhoto ? (
                  <img src={customer.profilePhoto} className="w-full h-full object-cover" alt="Perfil" />
                ) : (
                  <span className="text-white font-serif font-bold text-4xl">M</span>
                )}
              </div>
              <label className="absolute inset-0 cursor-pointer opacity-0 group-hover:opacity-100 bg-black/60 flex flex-col items-center justify-center transition-opacity">
                <span className="text-[7px] text-white font-bold uppercase tracking-widest">Alterar Foto</span>
                <input type="file" className="hidden" onChange={handlePhotoUpload} />
              </label>
            </div>
            <div className="flex-1">
              <p className="text-[10px] font-bold text-tea-200 uppercase tracking-widest mb-1">Olá, querida</p>
              <h1 className="text-2xl font-serif font-bold text-white italic tracking-wide">
                {customer.name.split(' ')[0]}
              </h1>
              <div className="h-px w-10 bg-tea-400/30 mt-2"></div>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-md mx-auto px-6 -mt-12 relative z-20">

        {/* Aba HOME */}
        {activeTab === 'home' && (
          <div className="space-y-6 animate-slide-up">
            {nextBooking ? (
              <div className="bg-white rounded-[3rem] shadow-2xl border border-tea-50 overflow-hidden">
                <div className="bg-tea-50/50 px-8 py-4 border-b border-tea-100 flex justify-between items-center">
                  <span className="text-[9px] font-bold text-tea-700 uppercase tracking-widest">Seu Próximo Cuidado</span>
                  <div className="flex gap-1">
                    <div className="w-1.5 h-1.5 bg-tea-500 rounded-full animate-pulse"></div>
