                  {activePromotions.map(promo => (
                    <div key={promo.id} className="min-w-[260px] max-w-[260px] bg-white p-6 rounded-[2.5rem] shadow-md border border-tea-50 space-y-3 flex-shrink-0">
                      <span className={`px-3 py-1 rounded-full text-[8px] font-bold uppercase tracking-widest ${promo.type === 'promotion' ? 'bg-orange-100 text-orange-700' : 'bg-tea-100 text-tea-700'}`}>
                        {promo.type === 'promotion' ? 'Promoção' : 'Dica de Beleza'}
                      </span>
                      <h5 className="font-bold text-tea-950 text-sm italic">{promo.title}</h5>
                      <p className="text-[10px] text-gray-500 leading-relaxed line-clamp-3 italic font-light">
