                      <div className="pt-2">
                         <button onClick={() => setActiveTab('agendar')} className="text-[8px] font-bold text-tea-900 uppercase tracking-widest flex items-center gap-2 group-hover:gap-3 transition-all">
                            Ver mais <span className="text-xs">→</span>
