import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, WaitlistEntry, Promotion } from './types.ts';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants.ts';
import { db } from './firebase.ts';
import { 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  addDoc, 
  updateDoc, 
  deleteDoc,
  increment
} from "firebase/firestore";

import Navbar from './components/Navbar.tsx';
import CustomerHome from './components/CustomerHome.tsx';
import CustomerRegister from './components/CustomerRegister.tsx';
import CustomerLoginView from './components/CustomerLoginView.tsx';
import CustomerProfile from './components/CustomerProfile.tsx';
import CustomerDashboard from './components/CustomerDashboard.tsx';
import AdminDashboard from './components/AdminDashboard.tsx';
import AdminCalendar from './components/AdminCalendar.tsx';
import AdminFinance from './components/AdminFinance.tsx';
import AdminClients from './components/AdminClients.tsx';
import AdminConfirmations from './components/AdminConfirmations.tsx';
import AdminSettingsView from './components/AdminSettingsView.tsx';
import AdminLogin from './components/AdminLogin.tsx';
import AdminMarketing from './components/AdminMarketing.tsx';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);

  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [waitlist, setWaitlist] = useState<WaitlistEntry[]>([]);
  const [promotions, setPromotions] = useState<Promotion[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  useEffect(() => {
    const unsubSettings = onSnapshot(doc(db, "settings", "main"), (doc) => {
      if (doc.exists()) {
        setSettings(doc.data() as SalonSettings);
      } else {
        setDoc(doc.ref, DEFAULT_SETTINGS);
      }
    });

    // Incrementar contador de visitas ao carregar a página
    if (currentView === View.CUSTOMER_HOME) {
      updateDoc(doc(db, "settings", "main"), {
        visitCount: increment(1)
      }).catch(() => {});
    }

    const unsubServices = onSnapshot(collection(db, "services"), (snapshot) => {
      const data = snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Service));
      if (data.length === 0) {
        INITIAL_SERVICES.forEach(s => setDoc(doc(db, "services", s.id), s));
      }
      setServices(data);
    });

    const unsubCustomers = onSnapshot(collection(db, "customers"), (snapshot) => {
      setCustomers(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Customer)));
    });

    const unsubBookings = onSnapshot(collection(db, "bookings"), (snapshot) => {
      setBookings(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Booking)));
    });

    const unsubTransactions = onSnapshot(collection(db, "transactions"), (snapshot) => {
      setTransactions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Transaction)));
    });

    const unsubWaitlist = onSnapshot(collection(db, "waitlist"), (snapshot) => {
      setWaitlist(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as WaitlistEntry)));
    });

    const unsubPromotions = onSnapshot(collection(db, "promotions"), (snapshot) => {
      setPromotions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Promotion)));
    });

    return () => {
      unsubSettings(); unsubServices(); unsubCustomers();
      unsubBookings(); unsubTransactions(); unsubWaitlist(); unsubPromotions();
    };
  }, []);

  useEffect(() => {
    const savedUser = localStorage.getItem('moria_user_session');
    if (savedUser) {
      try {
        const parsed = JSON.parse(savedUser);
        if (parsed && typeof parsed === 'object') setCurrentUser(parsed);
      } catch (e) { console.error("Error loading session"); }
    }
    if (localStorage.getItem('moria_admin_session') === 'true') setIsAdminAuthenticated(true);
  }, []);

  useEffect(() => {
    if (currentUser) {
      const cleanUser = {
        id: currentUser.id,
        name: currentUser.name,
        whatsapp: currentUser.whatsapp,
        cpf: currentUser.cpf,
        profilePhoto: currentUser.profilePhoto,
        receivesNotifications: !!currentUser.receivesNotifications
      };
      localStorage.setItem('moria_user_session', JSON.stringify(cleanUser));
      if (currentView === View.CUSTOMER_HOME || currentView === View.CUSTOMER_LOGIN) {
        setCurrentView(View.CUSTOMER_DASHBOARD);
      }
    } else {
      localStorage.removeItem('moria_user_session');
    }
    localStorage.setItem('moria_admin_session', isAdminAuthenticated.toString());
  }, [currentUser, isAdminAuthenticated, currentView]);

  const handleRegister = async (name: string, whatsapp: string, cpf: string, password: string, receivesNotifications: boolean) => {
    const id = Math.random().toString(36).substr(2, 9);
    const newCustomer: Customer = { id, name, whatsapp, cpf, password, receivesNotifications, agreedToTerms: true, history: [] };
    await setDoc(doc(db, "customers", id), newCustomer);
    setCurrentUser(newCustomer);
    setCurrentView(View.CUSTOMER_DASHBOARD);
  };

  const handleLogin = (cpf: string, pass: string) => {
    const user = customers.find(c => c.cpf === cpf && c.password === pass);
    if (user) { setCurrentUser(user); setCurrentView(View.CUSTOMER_DASHBOARD); }
    else alert("Dados incorretos.");
  };

  const handleBook = async (sid: string, dt: string, mid: string) => {
    if (!currentUser) { setCurrentView(View.CUSTOMER_LOGIN); return; }
    const srv = services.find(s => s.id === sid);
    const booking = {
      customerId: currentUser.id,
      customerName: currentUser.name,
      serviceId: sid,
      serviceName: srv?.name || '',
      dateTime: dt,
      duration: srv?.duration || 30,
      status: 'pending',
      depositStatus: 'pending',
      teamMemberId: mid,
      teamMemberName: settings.teamMembers.find(m => m.id === mid)?.name,
      agreedToCancellationPolicy: true,
      policyAgreedAt: new Date().toISOString()
    };
    await addDoc(collection(db, "bookings"), booking);
  };

  const handleAddToWaitlist = async (sid: string, dt: string) => {
    if (!currentUser) return;
    const srv = services.find(s => s.id === sid);
    await addDoc(collection(db, "waitlist"), {
      customerId: currentUser.id,
      customerName: currentUser.name,
      customerWhatsapp: currentUser.whatsapp,
      serviceId: sid,
      serviceName: srv?.name || '',
      preferredDate: dt,
      status: 'active',
      createdAt: new Date().toISOString()
    });
  };

  const handleUpdateStatus = async (id: string, status: any) => {
    const updateData: any = { status };
    if (status === 'cancelled') updateData.cancelledAt = new Date().toISOString();
    await updateDoc(doc(db, "bookings", id), updateData);
  };

  const handleUpdateDeposit = async (id: string, depositStatus: 'paid' | 'pending') => {
    await updateDoc(doc(db, "bookings", id), { depositStatus });
  };

  const handleCancelBooking = async (id: string) => {
    if (confirm("Deseja cancelar este agendamento? O registro será mantido no histórico da equipe.")) {
      await updateDoc(doc(db, "bookings", id), { 
        status: 'cancelled',
        cancelledAt: new Date().toISOString()
      });
    }
  };

  const handleCancelWaitlist = async (id: string) => {
    await updateDoc(doc(db, "waitlist", id), { 
      status: 'cancelled',
      cancelledAt: new Date().toISOString()
    });
  };

  const handleAddTransaction = async (data: any) => {
    await addDoc(collection(db, "transactions"), data);
  };

  const handleUpdateTransaction = async (id: string, data: any) => {
    await updateDoc(doc(db, "transactions", id), data);
  };

  const handleDeleteTransaction = async (id: string) => {
    if (confirm("Deseja excluir permanentemente este registro financeiro?")) {
      await deleteDoc(doc(db, "transactions", id));
    }
  };

  const renderView = () => {
    if (isAdmin) {
      if (!isAdminAuthenticated) return <AdminLogin onLogin={() => { setIsAdminAuthenticated(true); setCurrentView(View.ADMIN_DASHBOARD); }} onBack={() => setIsAdmin(false)} />;
      switch (currentView) {
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} setSettings={() => {}} services={services} setServices={() => {}} customers={customers} bookings={bookings} transactions={transactions} onImport={() => {}} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} services={services} customers={customers} teamMembers={settings.teamMembers} settings={settings} onUpdateStatus={handleUpdateStatus} />;
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} onUpdateStatus={handleUpdateStatus} onUpdateDeposit={handleUpdateDeposit} onDeleteBooking={handleCancelBooking} waitlist={waitlist} onRemoveWaitlist={handleCancelWaitlist} onReactivateWaitlist={(id) => updateDoc(doc(db, "waitlist", id), { status: 'active', cancelledAt: null })} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={(id) => updateDoc(doc(db, "customers", id), { status: 'inactive' })} onUpdate={(id, data) => updateDoc(doc(db, "customers", id), data)} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} onAdd={handleAddTransaction} onUpdate={handleUpdateTransaction} onDelete={handleDeleteTransaction} customers={customers} services={services} />;
        case View.ADMIN_MARKETING: return <AdminMarketing customers={customers} promotions={promotions} />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} settings={settings} />;
      }
    }

    if (currentUser && currentView === View.CUSTOMER_DASHBOARD) {
       return (
         <CustomerDashboard 
            customer={currentUser} 
            bookings={bookings} 
            services={services}
            settings={settings}
            onBook={handleBook}
            onUpdateProfile={(upd) => updateDoc(doc(db, "customers", currentUser.id), upd)}
            onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }}
            onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }}
            onCancelBooking={handleCancelBooking}
            onAddToWaitlist={handleAddToWaitlist}
            waitlist={waitlist.filter(w => w.customerId === currentUser.id && w.status !== 'cancelled')}
            onRemoveWaitlist={handleCancelWaitlist}
            promotions={promotions}
         />
       );
    }

    switch (currentView) {
      case View.CUSTOMER_REGISTER: return <CustomerRegister onRegister={handleRegister} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_LOGIN: return <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      default: return (
        <CustomerHome 
          settings={settings} services={services} bookings={bookings} 
          onBook={handleBook} 
          onAuthClick={() => setCurrentView(View.CUSTOMER_LOGIN)} 
          onAddToWaitlist={handleAddToWaitlist} 
          currentUser={currentUser} 
        />
      );
    }
  };

  return (
    <div className="min-h-screen bg-white">
      {currentView !== View.CUSTOMER_DASHBOARD && (
        <Navbar view={currentView} setView={setCurrentView} isAdmin={isAdmin} onToggleAdmin={() => { setIsAdmin(!isAdmin); if(!isAdminAuthenticated) setCurrentView(View.ADMIN_LOGIN); else setCurrentView(isAdmin ? View.CUSTOMER_HOME : View.ADMIN_DASHBOARD); }} salonName={settings.name} logo={settings.logo} currentUser={currentUser} onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }} onAdminLogout={() => { setIsAdminAuthenticated(false); setIsAdmin(false); setCurrentView(View.CUSTOMER_HOME); }} isAdminAuthenticated={isAdminAuthenticated} pendingBookingsCount={bookings.filter(b => b.status === 'pending').length} />
      )}
      <main className={currentView === View.CUSTOMER_DASHBOARD ? "" : "max-w-7xl mx-auto px-4 py-8"}>
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Booking, Transaction, Customer, SalonSettings } from '../types';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell,
  PieChart, Pie, Legend 
} from 'recharts';

interface AdminDashboardProps {
  bookings: Booking[];
  transactions: Transaction[];
  customers: Customer[];
  settings: SalonSettings;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ bookings, transactions, customers, settings }) => {
  const [period, setPeriod] = useState<'current' | 'next' | 'custom'>('current');
  const [dateRange, setDateRange] = useState({
    start: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0],
    end: new Date(new Date().getFullYear(), new Date().getMonth() + 1, 0).toISOString().split('T')[0]
  });

  const handlePeriodChange = (p: 'current' | 'next' | 'custom') => {
    setPeriod(p);
    const now = new Date();
    if (p === 'current') {
      const start = new Date(now.getFullYear(), now.getMonth(), 1);
      const end = new Date(now.getFullYear(), now.getMonth() + 1, 0);
      setDateRange({ start: start.toISOString().split('T')[0], end: end.toISOString().split('T')[0] });
    } else if (p === 'next') {
      const start = new Date(now.getFullYear(), now.getMonth() + 1, 1);
      const end = new Date(now.getFullYear(), now.getMonth() + 2, 0);
      setDateRange({ start: start.toISOString().split('T')[0], end: end.toISOString().split('T')[0] });
    }
  };

  const filteredData = useMemo(() => {
    const start = new Date(dateRange.start + 'T00:00:00').getTime();
    const end = new Date(dateRange.end + 'T23:59:59').getTime();

    const fTransactions = transactions.filter(t => {
      const d = new Date(t.dueDate || t.date).getTime();
      return d >= start && d <= end;
    });

    const fBookings = bookings.filter(b => {
      const d = new Date(b.dateTime.replace(' ', 'T')).getTime();
      return d >= start && d <= end;
    });

    return { transactions: fTransactions, bookings: fBookings };
  }, [transactions, bookings, dateRange]);

  // Cálculos de KPIs Avançados
  const totalReceivable = filteredData.transactions
    .filter(t => t.type === 'receivable')
    .reduce((acc, t) => acc + t.amount, 0);

  const totalPayable = filteredData.transactions
    .filter(t => t.type === 'payable')
    .reduce((acc, t) => acc + t.amount, 0);

  const completedBookings = filteredData.bookings.filter(b => b.status === 'completed');
  const cancelledBookings = filteredData.bookings.filter(b => b.status === 'cancelled');

  const ticketMedio = completedBookings.length > 0 ? totalReceivable / completedBookings.length : 0;

  const totalVisits = (settings as any).visitCount || 0;

  const cancellationRate = filteredData.bookings.length > 0 
    ? (cancelledBookings.length / filteredData.bookings.length) * 100 
    : 0;

  // Ranking: Clientes que mais gastaram (LTV no período)
  const topSpenders = useMemo(() => {
    const spenders: Record<string, { name: string, total: number }> = {};
    filteredData.transactions
      .filter(t => t.type === 'receivable' && t.status === 'paid' && t.customerId)
      .forEach(t => {
        if (!spenders[t.customerId!]) spenders[t.customerId!] = { name: t.customerName || 'Cliente', total: 0 };
        spenders[t.customerId!].total += t.amount;
      });
    return Object.values(spenders).sort((a, b) => b.total - a.total).slice(0, 5);
  }, [filteredData.transactions]);

  // Ranking: Clientes mais frequentes
  const topFrequent = useMemo(() => {
    const frequent: Record<string, { name: string, count: number }> = {};
    filteredData.bookings
      .filter(b => b.status === 'completed')
      .forEach(b => {
        if (!frequent[b.customerId]) frequent[b.customerId] = { name: b.customerName, count: 0 };
        frequent[b.customerId].count += 1;
      });
    return Object.values(frequent).sort((a, b) => b.count - a.count).slice(0, 5);
  }, [filteredData.bookings]);

  // Dados para Gráfico de Pizza: Distribuição de Serviços
  const serviceDistribution = useMemo(() => {
    const dist: Record<string, number> = {};
    filteredData.bookings.forEach(b => {
      dist[b.serviceName] = (dist[b.serviceName] || 0) + 1;
    });
    return Object.entries(dist).map(([name, value]) => ({ name, value }));
  }, [filteredData.bookings]);

  const COLORS = ['#418d50', '#8ec99a', '#2a5b35', '#bbe1c2', '#1e3d28', '#5eaa6e'];

  const stats = [
    { label: 'Visitas ao Site', value: totalVisits.toLocaleString(), icon: '👁️', color: 'bg-indigo-50 text-indigo-600' },
    { label: 'Ticket Médio', value: `R$ ${ticketMedio.toFixed(2)}`, icon: '📈', color: 'bg-blue-50 text-blue-600' },
    { label: 'Taxa de Cancelamento', value: `${cancellationRate.toFixed(1)}%`, icon: '⚠️', color: cancellationRate > 15 ? 'bg-red-50 text-red-600' : 'bg-tea-50 text-tea-600' },
    { label: 'Receitas (Total)', value: `R$ ${totalReceivable.toLocaleString('pt-BR')}`, icon: '💰', color: 'bg-green-50 text-green-600' },
  ];

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      {/* Header com Filtros */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm">
        <div>
          <h1 className="text-3xl font-serif font-bold text-tea-950 italic">Inteligência Moriá</h1>
          <p className="text-gray-400 text-sm">Visão estratégica e comportamento das clientes.</p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <div className="bg-gray-100 p-1.5 rounded-2xl flex gap-1">
            {['current', 'next', 'custom'].map((p) => (
              <button 
                key={p}
                onClick={() => handlePeriodChange(p as any)}
                className={`px-4 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all ${period === p ? 'bg-white text-tea-900 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
              >
                {p === 'current' ? 'Mês Atual' : p === 'next' ? 'Próximo Mês' : 'Período'}
              </button>
            ))}
          </div>

          {period === 'custom' && (
            <div className="flex items-center gap-2 animate-fade-in">
              <input type="date" value={dateRange.start} onChange={(e) => setDateRange({ ...dateRange, start: e.target.value })} className="p-2 bg-gray-50 border border-gray-100 rounded-xl text-[10px] font-bold outline-none" />
              <input type="date" value={dateRange.end} onChange={(e) => setDateRange({ ...dateRange, end: e.target.value })} className="p-2 bg-gray-50 border border-gray-100 rounded-xl text-[10px] font-bold outline-none" />
            </div>
          )}
        </div>
      </div>

      {/* Grid de KPIs */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {stats.map((stat, i) => (
          <div key={i} className={`bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100 hover:border-tea-100 transition-all`}>
            <div className={`w-12 h-12 rounded-2xl ${stat.color} flex items-center justify-center text-2xl mb-4 shadow-sm`}>
              {stat.icon}
            </div>
            <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest mb-1">{stat.label}</p>
            <p className="text-2xl font-serif font-bold text-gray-900 italic">{stat.value}</p>
          </div>
        ))}
      </div>

      {/* Seção Central: Gráficos e Rankings */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

        {/* Distribuição de Serviços (Pizza) */}
        <div className="lg:col-span-4 bg-white p-8 rounded-[3rem] shadow-sm border border-gray-100">
          <h3 className="text-lg font-bold text-tea-900 mb-6 font-serif italic">Serviços Favoritos</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={serviceDistribution}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {serviceDistribution.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip 
                   contentStyle={{ borderRadius: '1rem', border: 'none', boxShadow: '0 10px 25px rgba(0,0,0,0.05)', fontSize: '12px' }}
                />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-4 space-y-2">
            {serviceDistribution.slice(0, 3).map((s, i) => (
              <div key={i} className="flex justify-between items-center text-[10px] font-bold uppercase tracking-widest">
                <span className="flex items-center gap-2">
                   <div className="w-2 h-2 rounded-full" style={{ backgroundColor: COLORS[i] }}></div>
                   {s.name}
                </span>
                <span className="text-gray-400">{s.value}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Top Clientes - Faturamento */}
        <div className="lg:col-span-4 bg-white p-8 rounded-[3rem] shadow-sm border border-gray-100">
           <h3 className="text-lg font-bold text-tea-900 mb-6 font-serif italic">Maiores Faturamentos</h3>
           <div className="space-y-4">
              {topSpenders.map((s, i) => (
                <div key={i} className="flex items-center justify-between p-4 bg-gray-50/50 rounded-2xl border border-gray-50 hover:bg-white transition-all">
                   <div className="flex items-center gap-3">
                      <div className="w-8 h-8 bg-tea-900 text-white rounded-lg flex items-center justify-center font-bold text-xs">{i + 1}</div>
                      <span className="text-xs font-bold text-gray-800 line-clamp-1">{s.name}</span>
                   </div>
                   <span className="text-sm font-bold text-tea-800">R$ {s.total.toFixed(0)}</span>
                </div>
              ))}
              {topSpenders.length === 0 && <p className="text-center py-10 text-gray-300 italic">Sem dados financeiros.</p>}
           </div>
        </div>

        {/* Top Clientes - Frequência */}
        <div className="lg:col-span-4 bg-white p-8 rounded-[3rem] shadow-sm border border-gray-100">
           <h3 className="text-lg font-bold text-tea-900 mb-6 font-serif italic">Clientes Mais Assíduas</h3>
           <div className="space-y-4">
              {topFrequent.map((s, i) => (
                <div key={i} className="flex items-center justify-between p-4 bg-tea-50/30 rounded-2xl border border-tea-50 hover:bg-white transition-all">
                   <div className="flex items-center gap-3">
                      <div className="w-8 h-8 bg-tea-200 text-tea-900 rounded-lg flex items-center justify-center font-bold text-xs">{i + 1}</div>
                      <span className="text-xs font-bold text-gray-800 line-clamp-1">{s.name}</span>
                   </div>
                   <span className="text-[10px] font-bold uppercase tracking-widest text-tea-700">{s.count} visitas</span>
                </div>
              ))}
              {topFrequent.length === 0 && <p className="text-center py-10 text-gray-300 italic">Sem agendamentos concluídos.</p>}
           </div>
        </div>

      </div>

      {/* Gráfico de Barras Financeiro de Vencimentos */}
      <div className="bg-white p-10 rounded-[3.5rem] shadow-sm border border-gray-100">
        <div className="flex justify-between items-center mb-10">
          <h3 className="text-xl font-bold text-tea-900 font-serif italic">Tendência de Receita x Despesa</h3>
          <div className="text-right">
             <p className="text-[8px] font-bold text-gray-400 uppercase tracking-widest">Saldo Previsto</p>
             <p className={`text-xl font-bold ${(totalReceivable - totalPayable) >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                R$ {(totalReceivable - totalPayable).toLocaleString('pt-BR')}
             </p>
          </div>
        </div>
        <div className="h-80">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={[{ name: 'Receitas', value: totalReceivable }, { name: 'Despesas', value: totalPayable }]}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f3f4f6" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#9ca3af'}} />
              <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#9ca3af'}} />
              <Tooltip cursor={{fill: '#f9fafb'}} contentStyle={{ borderRadius: '1rem', border: 'none', boxShadow: '0 10px 25px rgba(0,0,0,0.05)', fontSize: '12px' }} />
              <Bar dataKey="value" radius={[15, 15, 15, 15]} barSize={60}>
                 <Cell fill="#418d50" />
                 <Cell fill="#ef4444" />
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Rodapé do Dashboard com Insights IA (Simulados) */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
         <div className="bg-tea-950 p-10 rounded-[3rem] text-white relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-10 text-6xl">💡</div>
            <h4 className="text-tea-400 font-bold uppercase text-[10px] tracking-widest mb-4">Moriá Business Insight</h4>
            <p className="font-serif italic text-lg leading-relaxed">
               {totalVisits > 1000 ? "Seu tráfego está excelente! Considere uma campanha de 'Primeira Visita' para converter esses acessos em agendamentos." : "Tráfego moderado. Que tal publicar uma Dica de Especialista para atrair novos olhares no app?"}
            </p>
         </div>
         <div className="bg-gray-50 p-10 rounded-[3rem] border border-gray-100 flex items-center gap-6">
            <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center text-4xl shadow-sm">🌿</div>
            <div>
               <h4 className="font-bold text-tea-950 text-sm tracking-widest uppercase">Saúde do Salão</h4>
               <p className="text-xs text-gray-500 italic mt-1">
                  {cancellationRate < 10 ? "Sua taxa de cancelamento está abaixo da média do mercado (Excelente!)." : "Atenção à taxa de cancelamento. Verifique se o processo de cobrança de sinal está claro para as clientes."}
               </p>
            </div>
         </div>
      </div>
    </div>
  );
};

export default AdminDashboard;

export enum View {
  CUSTOMER_HOME = 'CUSTOMER_HOME',
  CUSTOMER_LOGIN = 'CUSTOMER_LOGIN',
  CUSTOMER_REGISTER = 'CUSTOMER_REGISTER',
  CUSTOMER_PROFILE = 'CUSTOMER_PROFILE',
  CUSTOMER_DASHBOARD = 'CUSTOMER_DASHBOARD',
  ADMIN_LOGIN = 'ADMIN_LOGIN',
  ADMIN_DASHBOARD = 'ADMIN_DASHBOARD',
  ADMIN_CALENDAR = 'ADMIN_CALENDAR',
  ADMIN_FINANCE = 'ADMIN_FINANCE',
  ADMIN_CLIENTS = 'ADMIN_CLIENTS',
  ADMIN_CONFIRMATIONS = 'ADMIN_CONFIRMATIONS',
  ADMIN_SETTINGS = 'ADMIN_SETTINGS',
  ADMIN_MARKETING = 'ADMIN_MARKETING'
}

export interface Customer {
  id: string;
  name: string;
  whatsapp: string;
  cpf: string;
  password?: string;
  profilePhoto?: string;
  receivesNotifications: boolean;
  agreedToTerms: boolean;
  history: Booking[];
}

export interface Service {
  id: string;
  name: string;
  price: number;
  duration: number;
  description: string;
  isVisible: boolean;
}

export interface BusinessHours {
  start: string; // HH:mm
  end: string;   // HH:mm
}

export interface TeamMember {
  id: string;
  name: string;
  assignedServiceIds: string[];
  businessHours?: BusinessHours; // Horário individual opcional
  offDays?: number[]; // Dias de folga (0-6, onde 0 é domingo)
}

export interface Booking {
  id: string;
  customerId: string;
  customerName: string;
  serviceId: string;
  serviceName: string;
  teamMemberId?: string;
  teamMemberName?: string;
  dateTime: string;
  duration: number;
  status: 'pending' | 'scheduled' | 'completed' | 'cancelled' | 'blocked';
  depositStatus: 'pending' | 'paid'; 
  rescheduledCount?: number; 
  // Campos de Conformidade Jurídica
  agreedToCancellationPolicy: boolean;
  policyAgreedAt: string;
  ipAddress?: string; // Opcional, para rastro digital
  cancelledAt?: string;
  // Feedback do Cliente
  rating?: number;
  reviewComment?: string;
  reviewPhoto?: string;
}

export interface Promotion {
  id: string;
  title: string;
  content: string;
  type: 'promotion' | 'tip';
  createdAt: string;
  isActive: boolean;
}

export interface WaitlistEntry {
  id: string;
  customerId: string;
  customerName: string;
  customerWhatsapp: string;
  serviceId: string;
  serviceName: string;
  preferredDate: string;
  createdAt: string;
  status?: 'active' | 'cancelled';
  cancelledAt?: string;
}

export interface Transaction {
  id: string;
  type: 'payable' | 'receivable';
  description: string;
  amount: number;
  date: string;
  dueDate?: string;
  paidAt?: string; 
  status: 'pending' | 'paid';
  customerId?: string;
  customerName?: string;
  serviceId?: string;
  serviceName?: string;
  observation?: string;
}

export interface SalonSettings {
  name: string;
  primaryColor: string;
  logo: string;
  address?: string;
  googleMapsLink?: string;
  lastUpdated: number;
  visitCount?: number; // Contador de BI
  teamMembers: TeamMember[];
  businessHours: BusinessHours;
  agendaOpenUntil?: string;
  servicesSectionTitle?: string;
  servicesSectionSubtitle?: string;
  socialLinks: {
    instagram: string;
    facebook: string;
    whatsapp: string;
  };
  usefulLinks: Array<{ label: string; url: string }>;
  comments: Array<{ author: string; text: string }>;
  photos: string[];
}

import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, WaitlistEntry, Promotion } from './types.ts';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants.ts';
import { db } from './firebase.ts';
import { 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  addDoc, 
  updateDoc, 
  deleteDoc,
  increment
} from "firebase/firestore";

import Navbar from './components/Navbar.tsx';
import CustomerHome from './components/CustomerHome.tsx';
import CustomerRegister from './components/CustomerRegister.tsx';
import CustomerLoginView from './components/CustomerLoginView.tsx';
import CustomerProfile from './components/CustomerProfile.tsx';
import CustomerDashboard from './components/CustomerDashboard.tsx';
import AdminDashboard from './components/AdminDashboard.tsx';
import AdminCalendar from './components/AdminCalendar.tsx';
import AdminFinance from './components/AdminFinance.tsx';
import AdminClients from './components/AdminClients.tsx';
import AdminConfirmations from './components/AdminConfirmations.tsx';
import AdminSettingsView from './components/AdminSettingsView.tsx';
import AdminLogin from './components/AdminLogin.tsx';
import AdminMarketing from './components/AdminMarketing.tsx';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);

  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [waitlist, setWaitlist] = useState<WaitlistEntry[]>([]);
  const [promotions, setPromotions] = useState<Promotion[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  useEffect(() => {
    const unsubSettings = onSnapshot(doc(db, "settings", "main"), (doc) => {
      if (doc.exists()) {
        setSettings(doc.data() as SalonSettings);
      } else {
        setDoc(doc.ref, DEFAULT_SETTINGS);
      }
    });

    // Incrementar contador de visitas ao carregar a página
    if (currentView === View.CUSTOMER_HOME) {
      updateDoc(doc(db, "settings", "main"), {
        visitCount: increment(1)
      }).catch(() => {});
    }

    const unsubServices = onSnapshot(collection(db, "services"), (snapshot) => {
      const data = snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Service));
      if (data.length === 0) {
        INITIAL_SERVICES.forEach(s => setDoc(doc(db, "services", s.id), s));
      }
      setServices(data);
    });

    const unsubCustomers = onSnapshot(collection(db, "customers"), (snapshot) => {
      setCustomers(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Customer)));
    });

    const unsubBookings = onSnapshot(collection(db, "bookings"), (snapshot) => {
      setBookings(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Booking)));
    });

    const unsubTransactions = onSnapshot(collection(db, "transactions"), (snapshot) => {
      setTransactions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Transaction)));
    });

    const unsubWaitlist = onSnapshot(collection(db, "waitlist"), (snapshot) => {
      setWaitlist(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as WaitlistEntry)));
    });

    const unsubPromotions = onSnapshot(collection(db, "promotions"), (snapshot) => {
      setPromotions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Promotion)));
    });

    return () => {
      unsubSettings(); unsubServices(); unsubCustomers();
      unsubBookings(); unsubTransactions(); unsubWaitlist(); unsubPromotions();
    };
  }, []);

  useEffect(() => {
    const savedUser = localStorage.getItem('moria_user_session');
    if (savedUser) {
      try {
        const parsed = JSON.parse(savedUser);
        if (parsed && typeof parsed === 'object') setCurrentUser(parsed);
      } catch (e) { console.error("Error loading session"); }
    }
    if (localStorage.getItem('moria_admin_session') === 'true') setIsAdminAuthenticated(true);
  }, []);

  useEffect(() => {
    if (currentUser) {
      const cleanUser = {
        id: currentUser.id,
        name: currentUser.name,
        whatsapp: currentUser.whatsapp,
        cpf: currentUser.cpf,
        profilePhoto: currentUser.profilePhoto,
        receivesNotifications: !!currentUser.receivesNotifications
      };
      localStorage.setItem('moria_user_session', JSON.stringify(cleanUser));
      if (currentView === View.CUSTOMER_HOME || currentView === View.CUSTOMER_LOGIN) {
        setCurrentView(View.CUSTOMER_DASHBOARD);
      }
    } else {
      localStorage.removeItem('moria_user_session');
    }
    localStorage.setItem('moria_admin_session', isAdminAuthenticated.toString());
  }, [currentUser, isAdminAuthenticated, currentView]);

  const handleRegister = async (name: string, whatsapp: string, cpf: string, password: string, receivesNotifications: boolean) => {
    const id = Math.random().toString(36).substr(2, 9);
    const newCustomer: Customer = { id, name, whatsapp, cpf, password, receivesNotifications, agreedToTerms: true, history: [] };
    await setDoc(doc(db, "customers", id), newCustomer);
    setCurrentUser(newCustomer);
    setCurrentView(View.CUSTOMER_DASHBOARD);
  };

  const handleLogin = (cpf: string, pass: string) => {
    const user = customers.find(c => c.cpf === cpf && c.password === pass);
    if (user) { setCurrentUser(user); setCurrentView(View.CUSTOMER_DASHBOARD); }
    else alert("Dados incorretos.");
  };

  const handleBook = async (sid: string, dt: string, mid: string) => {
    if (!currentUser) { setCurrentView(View.CUSTOMER_LOGIN); return; }
    const srv = services.find(s => s.id === sid);
    const booking = {
      customerId: currentUser.id,
      customerName: currentUser.name,
      serviceId: sid,
      serviceName: srv?.name || '',
      dateTime: dt,
      duration: srv?.duration || 30,
      status: 'pending',
      depositStatus: 'pending',
      teamMemberId: mid,
      teamMemberName: settings.teamMembers.find(m => m.id === mid)?.name,
      agreedToCancellationPolicy: true,
      policyAgreedAt: new Date().toISOString()
    };
    await addDoc(collection(db, "bookings"), booking);
  };

  const handleAddToWaitlist = async (sid: string, dt: string) => {
    if (!currentUser) return;
    const srv = services.find(s => s.id === sid);
    await addDoc(collection(db, "waitlist"), {
      customerId: currentUser.id,
      customerName: currentUser.name,
      customerWhatsapp: currentUser.whatsapp,
      serviceId: sid,
      serviceName: srv?.name || '',
      preferredDate: dt,
      status: 'active',
      createdAt: new Date().toISOString()
    });
  };

  const handleUpdateStatus = async (id: string, status: any) => {
    const updateData: any = { status };
    if (status === 'cancelled') updateData.cancelledAt = new Date().toISOString();
    await updateDoc(doc(db, "bookings", id), updateData);
  };

  const handleUpdateDeposit = async (id: string, depositStatus: 'paid' | 'pending') => {
    await updateDoc(doc(db, "bookings", id), { depositStatus });
  };

  const handleCancelBooking = async (id: string) => {
    if (confirm("Deseja cancelar este agendamento? O registro será mantido no histórico da equipe.")) {
      await updateDoc(doc(db, "bookings", id), { 
        status: 'cancelled',
        cancelledAt: new Date().toISOString()
      });
    }
  };

  const handleCancelWaitlist = async (id: string) => {
    await updateDoc(doc(db, "waitlist", id), { 
      status: 'cancelled',
      cancelledAt: new Date().toISOString()
    });
  };

  const handleAddTransaction = async (data: any) => {
    await addDoc(collection(db, "transactions"), data);
  };

  const handleUpdateTransaction = async (id: string, data: any) => {
    await updateDoc(doc(db, "transactions", id), data);
  };

  const handleDeleteTransaction = async (id: string) => {
    if (confirm("Deseja excluir permanentemente este registro financeiro?")) {
      await deleteDoc(doc(db, "transactions", id));
    }
  };

  const renderView = () => {
    if (isAdmin) {
      if (!isAdminAuthenticated) return <AdminLogin onLogin={() => { setIsAdminAuthenticated(true); setCurrentView(View.ADMIN_DASHBOARD); }} onBack={() => setIsAdmin(false)} />;
      switch (currentView) {
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} setSettings={() => {}} services={services} setServices={() => {}} customers={customers} bookings={bookings} transactions={transactions} onImport={() => {}} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} services={services} customers={customers} teamMembers={settings.teamMembers} settings={settings} onUpdateStatus={handleUpdateStatus} />;
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} onUpdateStatus={handleUpdateStatus} onUpdateDeposit={handleUpdateDeposit} onDeleteBooking={handleCancelBooking} waitlist={waitlist} onRemoveWaitlist={handleCancelWaitlist} onReactivateWaitlist={(id) => updateDoc(doc(db, "waitlist", id), { status: 'active', cancelledAt: null })} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={(id) => updateDoc(doc(db, "customers", id), { status: 'inactive' })} onUpdate={(id, data) => updateDoc(doc(db, "customers", id), data)} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} onAdd={handleAddTransaction} onUpdate={handleUpdateTransaction} onDelete={handleDeleteTransaction} customers={customers} services={services} />;
        case View.ADMIN_MARKETING: return <AdminMarketing customers={customers} promotions={promotions} />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} settings={settings} />;
      }
    }

    if (currentUser && currentView === View.CUSTOMER_DASHBOARD) {
       return (
         <CustomerDashboard 
            customer={currentUser} 
            bookings={bookings} 
            services={services}
            settings={settings}
            onBook={handleBook}
            onUpdateProfile={(upd) => updateDoc(doc(db, "customers", currentUser.id), upd)}
            onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }}
            onCancelBooking={handleCancelBooking}
            onAddToWaitlist={handleAddToWaitlist}
            waitlist={waitlist.filter(w => w.customerId === currentUser.id && w.status !== 'cancelled')}
            onRemoveWaitlist={handleCancelWaitlist}
            promotions={promotions}
         />
       );
    }

    switch (currentView) {
      case View.CUSTOMER_REGISTER: return <CustomerRegister onRegister={handleRegister} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_LOGIN: return <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      default: return (
        <CustomerHome 
          settings={settings} services={services} bookings={bookings} 
          onBook={handleBook} 
          onAuthClick={() => setCurrentView(View.CUSTOMER_LOGIN)} 
          onAddToWaitlist={handleAddToWaitlist} 
          currentUser={currentUser} 
        />
      );
    }
  };

  return (
    <div className="min-h-screen bg-white">
      {currentView !== View.CUSTOMER_DASHBOARD && (
        <Navbar view={currentView} setView={setCurrentView} isAdmin={isAdmin} onToggleAdmin={() => { setIsAdmin(!isAdmin); if(!isAdminAuthenticated) setCurrentView(View.ADMIN_LOGIN); else setCurrentView(isAdmin ? View.CUSTOMER_HOME : View.ADMIN_DASHBOARD); }} salonName={settings.name} logo={settings.logo} currentUser={currentUser} onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }} onAdminLogout={() => { setIsAdminAuthenticated(false); setIsAdmin(false); setCurrentView(View.CUSTOMER_HOME); }} isAdminAuthenticated={isAdminAuthenticated} pendingBookingsCount={bookings.filter(b => b.status === 'pending').length} />
      )}
      <main className={currentView === View.CUSTOMER_DASHBOARD ? "" : "max-w-7xl mx-auto px-4 py-8"}>
        {renderView()}
      </main>
    </div>
  );
};

