import React, { useState, useMemo } from 'react';
import { Customer, Promotion, Service } from '../types';
import { GoogleGenAI } from '@google/genai';
import { db } from '../firebase.ts';
import { collection, addDoc, deleteDoc, doc } from "firebase/firestore";

interface AdminMarketingProps {
  customers: Customer[];
  promotions: Promotion[];
  services: Service[];
}

const AdminMarketing: React.FC<AdminMarketingProps> = ({ customers, promotions, services }) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [topic, setTopic] = useState('');
  const [type, setType] = useState<'promotion' | 'tip'>('promotion');
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [showHistory, setShowHistory] = useState(false);
  const [isBroadcasting, setIsBroadcasting] = useState(false);

  // Regras da Promoção
  const [discount, setDiscount] = useState(0);
  const [selectedServices, setSelectedServices] = useState<string[]>([]);
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [endDate, setEndDate] = useState(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]);

  // Seleção de Clientes
  const [selectedCustomerIds, setSelectedCustomerIds] = useState<Set<string>>(new Set());
  const [searchTerm, setSearchTerm] = useState('');

  const eligibleCustomers = useMemo(() => 
    customers.filter(c => c.receivesNotifications && 
      (c.name.toLowerCase().includes(searchTerm.toLowerCase()) || c.whatsapp.includes(searchTerm))
    ), [customers, searchTerm]);

  const toggleService = (id: string) => {
    setSelectedServices(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const toggleSelectAll = () => {
    if (selectedCustomerIds.size === eligibleCustomers.length) {
      setSelectedCustomerIds(new Set());
    } else {
      setSelectedCustomerIds(new Set(eligibleCustomers.map(c => c.id)));
    }
  };

  const generateSmartContent = async () => {
    if (!topic) return alert("Digite um tema para a IA.");
    setIsGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Crie uma ${type === 'promotion' ? `promoção de ${discount}% de desconto` : 'dica de beleza'} para Studio Moriá. Tema: ${topic}. Retorne JSON: { "title": "Título", "content": "Texto" }`;
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { responseMimeType: "application/json" }
      });
      const data = JSON.parse(response.text);
      setTitle(data.title);
      setContent(data.content);
    } catch (e) { alert("Erro na IA."); } finally { setIsGenerating(false); }
  };

  const publishCampaign = async () => {
    if (!title || !content) return alert("Título e conteúdo são obrigatórios.");
    if (selectedCustomerIds.size === 0) return alert("Selecione clientes para a campanha.");

    setIsBroadcasting(true);
    try {
      const promoData = {
        title,
        content,
        type,
        discountPercentage: discount,
        applicableServiceIds: selectedServices,
        targetCustomerIds: Array.from(selectedCustomerIds),
        startDate,
        endDate,
        createdAt: new Date().toISOString(),
        isActive: true
      };

      await addDoc(collection(db, "promotions"), promoData);

      // WhatsApp Loop
      const message = `🌟 *STUDIO MORIÁ* 🌟\n\n*${title}*\n\n${content}\n\n🎁 Desconto: ${discount}%\n📅 Válido até: ${new Date(endDate).toLocaleDateString()}`;

      const targetCustomers = customers.filter(c => selectedCustomerIds.has(c.id));
      targetCustomers.forEach((c, i) => {
        const url = `https://wa.me/${c.whatsapp.replace(/\D/g, '')}?text=${encodeURIComponent(message)}`;
        setTimeout(() => window.open(url, '_blank'), i * 1000);
      });

      alert("Campanha lançada com sucesso!");
      setTitle(''); setContent(''); setDiscount(0); setSelectedServices([]);
    } catch (e) { alert("Erro ao salvar."); } finally { setIsBroadcasting(false); }
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="bg-white p-8 md:p-10 rounded-[3rem] shadow-sm border border-gray-100">
        <div className="flex justify-between items-center mb-10">
           <h2 className="text-3xl font-serif text-tea-950 font-bold italic">Campanhas Inteligentes</h2>
           <button onClick={() => setShowHistory(!showHistory)} className="px-6 py-3 border-2 border-tea-100 text-tea-700 rounded-2xl text-[10px] font-bold uppercase">
             {showHistory ? "← Criar Campanha" : "Ver Histórico"}
           </button>
        </div>

        {!showHistory ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-8 space-y-8">
              {/* Seção Regras */}
              <div className="bg-gray-50 p-8 rounded-[2.5rem] border border-gray-100 grid grid-cols-1 md:grid-cols-3 gap-6">
                <div>
                   <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest block mb-2">Desconto (%)</label>
                   <input type="number" min="0" max="100" value={discount} onChange={e => setDiscount(Number(e.target.value))} className="w-full p-4 rounded-xl border border-gray-200 font-bold" />
                </div>
                <div>
                   <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest block mb-2">Início</label>
                   <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full p-4 rounded-xl border border-gray-200 font-bold" />
                </div>
                <div>
                   <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest block mb-2">Término (Validade)</label>
                   <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full p-4 rounded-xl border border-gray-200 font-bold" />
                </div>
              </div>

              {/* Serviços */}
              <div className="space-y-3">
                 <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest block ml-2">Aplicar aos Serviços (Opcional)</label>
                 <div className="flex flex-wrap gap-2">
                    {services.map(s => (
                      <button key={s.id} onClick={() => toggleService(s.id)} className={`px-4 py-2 rounded-xl text-[10px] font-bold border-2 transition-all ${selectedServices.includes(s.id) ? 'bg-tea-900 text-white border-tea-900' : 'bg-white text-gray-400 border-gray-100'}`}>
                        {s.name}
                      </button>
                    ))}
                 </div>
              </div>

              {/* IA e Conteúdo */}
              <div className="bg-tea-50/50 p-8 rounded-[2.5rem] border border-tea-100 space-y-4">
                 <input type="text" placeholder="Tema para a IA..." value={topic} onChange={e => setTopic(e.target.value)} className="w-full p-4 rounded-xl border-none outline-none shadow-sm" />
                 <button onClick={generateSmartContent} disabled={isGenerating} className="w-full py-4 bg-tea-800 text-white rounded-xl font-bold uppercase text-[10px]">
                   {isGenerating ? "Criando..." : "Gerar Texto com IA"}
                 </button>
              </div>

              <div className="space-y-4">
                <input type="text" placeholder="Título" value={title} onChange={e => setTitle(e.target.value)} className="w-full p-5 rounded-2xl bg-gray-50 border-none font-bold text-lg" />
                <textarea rows={5} placeholder="Mensagem do WhatsApp..." value={content} onChange={e => setContent(e.target.value)} className="w-full p-5 rounded-2xl bg-gray-50 border-none" />
              </div>
            </div>

            {/* Seleção de Clientes */}
            <div className="lg:col-span-4 flex flex-col bg-gray-50/50 rounded-[3rem] border border-gray-100 overflow-hidden">
               <div className="p-6 bg-white border-b border-gray-100">
                  <div className="flex justify-between items-center mb-4">
                     <span className="text-[10px] font-bold text-tea-950 uppercase">Público ({selectedCustomerIds.size})</span>
                     <button onClick={toggleSelectAll} className="text-[10px] font-bold text-tea-600 uppercase">Todos</button>
                  </div>
                  <input type="text" placeholder="Buscar..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full p-3 bg-gray-50 rounded-xl text-xs outline-none" />
               </div>
               <div className="flex-grow overflow-y-auto p-4 space-y-2 max-h-[500px]">
                 {eligibleCustomers.map(c => (
                   <label key={c.id} className={`flex items-center gap-3 p-4 rounded-2xl border-2 transition-all cursor-pointer ${selectedCustomerIds.has(c.id) ? 'bg-tea-50 border-tea-200' : 'bg-white border-transparent'}`}>
                      <input type="checkbox" checked={selectedCustomerIds.has(c.id)} onChange={() => {
                        const next = new Set(selectedCustomerIds);
                        next.has(c.id) ? next.delete(c.id) : next.add(c.id);
                        setSelectedCustomerIds(next);
                      }} className="w-4 h-4 rounded border-gray-300 text-tea-900 focus:ring-tea-900" />
                      <div className="text-xs">
                        <p className="font-bold text-tea-950">{c.name}</p>
                        <p className="text-gray-400">{c.whatsapp}</p>
                      </div>
                   </label>
                 ))}
               </div>
               <div className="p-6 bg-white border-t border-gray-100">
                 <button onClick={publishCampaign} disabled={isBroadcasting || selectedCustomerIds.size === 0} className="w-full py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] shadow-xl disabled:bg-gray-200">
                    {isBroadcasting ? "Lançando..." : "🚀 Disparar Campanha"}
                 </button>
               </div>
            </div>
          </div>
        ) : (
          <div className="space-y-4">
            {promotions.map(promo => (
              <div key={promo.id} className="p-6 bg-gray-50 rounded-3xl border border-gray-100 flex justify-between items-center">
                <div>
                  <div className="flex items-center gap-3 mb-1">
                    <span className="bg-orange-100 text-orange-700 px-2 py-0.5 rounded text-[8px] font-bold uppercase">{promo.discountPercentage}% OFF</span>
                    <span className="text-[9px] text-gray-400">Até {new Date(promo.endDate).toLocaleDateString()}</span>
                  </div>
                  <h4 className="font-bold text-tea-950">{promo.title}</h4>
                </div>
                <button onClick={async () => { if(confirm("Excluir?")) await deleteDoc(doc(db, "promotions", promo.id)); }} className="text-red-300">🗑️</button>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

