import React, { useState, useMemo } from 'react';
import { Customer, Promotion, Service } from '../types';
import { GoogleGenAI } from '@google/genai';
import { db } from '../firebase.ts';
import { collection, addDoc, deleteDoc, doc, updateDoc } from "firebase/firestore";

interface AdminMarketingProps {
  customers: Customer[];
  promotions: Promotion[];
  services: Service[];
}

const AdminMarketing: React.FC<AdminMarketingProps> = ({ customers, promotions, services }) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [showForm, setShowForm] = useState(false);

  // Estado do Formulário de Campanha
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [discount, setDiscount] = useState(0);
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [endDate, setEndDate] = useState(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]);
  const [selectedServices, setSelectedServices] = useState<string[]>([]);
  const [selectedCustomerIds, setSelectedCustomerIds] = useState<Set<string>>(new Set());
  const [searchTerm, setSearchTerm] = useState('');

  const eligibleCustomers = useMemo(() => 
    customers.filter(c => c.receivesNotifications && 
      (c.name.toLowerCase().includes(searchTerm.toLowerCase()) || c.whatsapp.includes(searchTerm))
    ), [customers, searchTerm]);

  const toggleService = (id: string) => {
    setSelectedServices(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const toggleSelectAll = () => {
    if (selectedCustomerIds.size === eligibleCustomers.length) {
      setSelectedCustomerIds(new Set());
    } else {
      setSelectedCustomerIds(new Set(eligibleCustomers.map(c => c.id)));
    }
  };

  const generateSmartContent = async () => {
    if (!title && !discount) return alert("Defina um título ou desconto para a IA ter contexto.");
    setIsGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Crie uma mensagem persuasiva de WhatsApp para Studio Moriá. Promoção: ${title}. Desconto: ${discount}%. Validade: até ${new Date(endDate).toLocaleDateString()}. Seja elegante e use emojis. Retorne apenas o texto da mensagem.`;
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });
      setContent(response.text || '');
    } catch (e) { alert("Erro na IA."); } finally { setIsGenerating(false); }
  };

  const saveCampaign = async () => {
    if (!title || !content) return alert("Título e conteúdo são obrigatórios.");
    if (selectedCustomerIds.size === 0) return alert("Selecione pelo menos uma cliente.");

    try {
      const promoData: Omit<Promotion, 'id'> = {
        title,
        content,
        type: 'promotion',
        discountPercentage: discount,
        applicableServiceIds: selectedServices,
        targetCustomerIds: Array.from(selectedCustomerIds),
        startDate,
        endDate,
        createdAt: new Date().toISOString(),
        isActive: true
      };

      await addDoc(collection(db, "promotions"), promoData);

      // Disparo WhatsApp Simulado (Abre o link para o usuário disparar)
      const message = `🌟 *STUDIO MORIÁ* 🌟\n\n${content}`;
      const targetCustomers = customers.filter(c => selectedCustomerIds.has(c.id));

      if (confirm(`Campanha salva! Deseja abrir os links de WhatsApp para as ${targetCustomers.length} clientes agora?`)) {
        targetCustomers.forEach((c, i) => {
          const url = `https://wa.me/${c.whatsapp.replace(/\D/g, '')}?text=${encodeURIComponent(message)}`;
          setTimeout(() => window.open(url, '_blank'), i * 1500);
        });
      }

      setShowForm(false);
      resetForm();
    } catch (e) { alert("Erro ao salvar campanha."); }
  };

  const resetForm = () => {
    setTitle(''); setContent(''); setDiscount(0); 
    setSelectedServices([]); setSelectedCustomerIds(new Set());
  };

  const sortedPromotions = [...promotions].sort((a,b) => b.createdAt.localeCompare(a.createdAt));

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-3xl font-serif text-tea-950 font-bold italic">Campanhas & Promoções</h2>
          <p className="text-gray-400 text-sm">Gerencie seus descontos e envie para as clientes.</p>
        </div>
        <button 
          onClick={() => setShowForm(!showForm)} 
          className="bg-tea-900 text-white px-8 py-4 rounded-2xl font-bold uppercase tracking-widest text-[10px] shadow-xl hover:bg-black transition-all"
        >
          {showForm ? '← Voltar à Lista' : '+ Nova Campanha'}
        </button>
      </div>

      {showForm ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-slide-up">
          <div className="lg:col-span-8 bg-white p-8 md:p-10 rounded-[3rem] shadow-sm border border-gray-100 space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Título da Campanha</label>
                <input type="text" value={title} onChange={e => setTitle(e.target.value)} placeholder="Ex: Especial Mês das Noivas" className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Desconto (%)</label>
                <input type="number" value={discount} onChange={e => setDiscount(Number(e.target.value))} min="0" max="100" className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none" />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Início da Validade</label>
                <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Fim da Validade</label>
                <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none" />
              </div>
            </div>

            <div className="space-y-3">
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Serviços Inclusos (Se vazio, aplica a todos)</label>
              <div className="flex flex-wrap gap-2">
                {services.map(s => (
                  <button 
                    key={s.id} 
                    onClick={() => toggleService(s.id)} 
                    className={`px-4 py-2 rounded-xl text-[10px] font-bold border-2 transition-all ${selectedServices.includes(s.id) ? 'bg-tea-800 border-tea-800 text-white' : 'bg-white border-gray-100 text-gray-400'}`}
                  >
                    {s.name}
                  </button>
                ))}
              </div>
            </div>

            <div className="space-y-4 pt-4 border-t border-gray-50">
               <div className="flex justify-between items-center">
                 <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Texto para WhatsApp</label>
                 <button onClick={generateSmartContent} disabled={isGenerating} className="text-[9px] font-bold text-tea-600 uppercase hover:underline">{isGenerating ? 'IA está escrevendo...' : 'Gerar com IA ✨'}</button>
               </div>
               <textarea rows={6} value={content} onChange={e => setContent(e.target.value)} placeholder="O que a cliente vai receber no WhatsApp..." className="w-full p-6 bg-gray-50 rounded-3xl outline-none focus:ring-2 focus:ring-tea-100 transition-all resize-none text-sm leading-relaxed" />
            </div>
          </div>

          <div className="lg:col-span-4 flex flex-col gap-6">
             <div className="bg-white p-8 rounded-[3rem] shadow-sm border border-gray-100 flex-grow flex flex-col">
                <div className="flex justify-between items-center mb-6">
                   <h3 className="text-xs font-bold text-tea-950 uppercase tracking-widest">Selecionar Clientes</h3>
                   <button onClick={toggleSelectAll} className="text-[9px] font-bold text-tea-600 uppercase">{selectedCustomerIds.size === eligibleCustomers.length ? 'Ninguém' : 'Todos'}</button>
                </div>
                <input type="text" placeholder="Buscar cliente..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full p-3 bg-gray-50 rounded-xl text-xs mb-4 outline-none" />
                <div className="flex-grow overflow-y-auto max-h-[400px] space-y-2 custom-scroll pr-2">
                   {eligibleCustomers.map(c => (
                     <label key={c.id} className={`flex items-center gap-3 p-4 rounded-2xl border-2 transition-all cursor-pointer ${selectedCustomerIds.has(c.id) ? 'bg-tea-50 border-tea-200' : 'bg-white border-transparent hover:bg-gray-50'}`}>
                        <input type="checkbox" checked={selectedCustomerIds.has(c.id)} onChange={() => {
                          const next = new Set(selectedCustomerIds);
                          next.has(c.id) ? next.delete(c.id) : next.add(c.id);
                          setSelectedCustomerIds(next);
                        }} className="w-4 h-4 rounded text-tea-900 focus:ring-tea-900 border-gray-300" />
                        <div className="text-[11px]">
                          <p className="font-bold text-tea-950">{c.name}</p>
                          <p className="text-gray-400">{c.whatsapp}</p>
                        </div>
                     </label>
                   ))}
                </div>
                <div className="pt-6 mt-4 border-t border-gray-50">
                   <button onClick={saveCampaign} disabled={selectedCustomerIds.size === 0} className="w-full py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl disabled:bg-gray-100">Criar Campanha e Disparar</button>
                </div>
             </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          {sortedPromotions.map(promo => {
            const today = new Date().toISOString().split('T')[0];
            const isPast = promo.endDate < today;
            const isFuture = promo.startDate > today;
            const isOngoing = !isPast && !isFuture;

            return (
              <div key={promo.id} className={`bg-white p-8 rounded-[2.5rem] border-2 shadow-sm flex flex-col md:flex-row justify-between items-center gap-6 transition-all ${isPast ? 'opacity-50 border-gray-100' : 'border-tea-50 hover:border-tea-100'}`}>
                <div className="flex items-center gap-6">
                  <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-2xl ${isPast ? 'bg-gray-100' : 'bg-tea-900 text-white'}`}>
                    {promo.discountPercentage}%
                  </div>
                  <div>
                    <div className="flex items-center gap-3 mb-1">
                      <h3 className="font-bold text-tea-950 text-xl font-serif">{promo.title}</h3>
                      {isOngoing && <span className="bg-green-100 text-green-700 px-2 py-0.5 rounded text-[8px] font-bold uppercase">Ativa</span>}
                      {isPast && <span className="bg-gray-100 text-gray-500 px-2 py-0.5 rounded text-[8px] font-bold uppercase">Encerrada</span>}
                    </div>
                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">
                      Validade: {new Date(promo.startDate).toLocaleDateString()} até {new Date(promo.endDate).toLocaleDateString()}
                    </p>
                    <p className="text-xs text-tea-600 font-medium mt-1">
                      {promo.applicableServiceIds.length === 0 ? 'Válido para todos os serviços' : `${promo.applicableServiceIds.length} serviços selecionados`}
                      {' • '} {promo.targetCustomerIds.length} clientes participando
                    </p>
                  </div>
                </div>
                <div className="flex gap-2">
                   <button onClick={async () => { if(confirm("Deseja encerrar esta campanha?")) await updateDoc(doc(db, "promotions", promo.id), { isActive: false, endDate: today }); }} className="p-3 bg-gray-50 text-gray-400 rounded-xl hover:text-red-500 transition-colors">⏹️</button>
                   <button onClick={async () => { if(confirm("Excluir histórico da campanha?")) await deleteDoc(doc(db, "promotions", promo.id)); }} className="p-3 bg-gray-50 text-gray-400 rounded-xl hover:text-red-500 transition-colors">🗑️</button>
                </div>
              </div>
            );
          })}
          {sortedPromotions.length === 0 && (
            <div className="text-center py-32 bg-gray-50 rounded-[4rem] border-2 border-dashed border-gray-200">
               <p className="text-gray-300 font-serif italic text-xl">Nenhuma campanha criada ainda.</p>
               <button onClick={() => setShowForm(true)} className="text-tea-600 font-bold text-xs uppercase tracking-widest mt-4 hover:underline">Criar minha primeira campanha</button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default AdminMarketing;

import React, { useState, useEffect, useMemo } from 'react';
import { Customer, Booking, Service, SalonSettings, TeamMember, WaitlistEntry, Promotion } from '../types';
import { db } from '../firebase.ts';
import { doc, updateDoc, collection, addDoc } from "firebase/firestore";

interface CustomerDashboardProps {
  customer: Customer;
  bookings: Booking[];
  services: Service[];
  settings: SalonSettings;
  onBook: (serviceId: string, dateTime: string, teamMemberId?: string, promoData?: any) => void;
  onUpdateProfile: (updated: Partial<Customer>) => void;
  onLogout: () => void;
  onCancelBooking: (id: string) => void;
  onAddToWaitlist?: (serviceId: string, date: string) => void;
  waitlist?: WaitlistEntry[];
  onRemoveWaitlist?: (id: string) => void;
  promotions?: Promotion[];
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ 
  customer, 
  bookings, 
  services, 
  settings,
  onUpdateProfile, 
  onLogout,
  onCancelBooking,
  onAddToWaitlist,
  waitlist = [],
  onRemoveWaitlist,
  promotions = []
}) => {
  const [activeTab, setActiveTab] = useState<'home' | 'agendar' | 'agenda' | 'perfil'>('home');

  // Agendamento
  const [bookingStep, setBookingStep] = useState<1 | 2 | 3>(1);
  const [selectedService, setSelectedService] = useState<Service | null>(null);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedTime, setSelectedTime] = useState<string>('');
  const [selectedProId, setSelectedProId] = useState<string>('');
  const [agreedToCancellation, setAgreedToCancellation] = useState(false);

  // Lógica de Promoção Ativa para o Cliente Logado
  const activePromoForService = useMemo(() => {
    if (!selectedService) return null;
    const today = new Date().toISOString().split('T')[0];

    // Filtra promoções válidas, ativas e que incluem este cliente e este serviço
    return promotions.find(p => 
      p.isActive &&
      today >= p.startDate &&
      today <= p.endDate &&
      p.targetCustomerIds.includes(customer.id) &&
      (p.applicableServiceIds.length === 0 || p.applicableServiceIds.includes(selectedService.id))
    );
  }, [selectedService, promotions, customer.id]);

  const priceInfo = useMemo(() => {
    if (!selectedService) return { original: 0, final: 0, discount: 0 };
    const original = selectedService.price;
    const discountPercent = activePromoForService?.discountPercentage || 0;
    const discountVal = (original * discountPercent) / 100;
    return {
      original,
      final: original - discountVal,
      discount: discountVal
    };
  }, [selectedService, activePromoForService]);

  const allPossibleSlots = useMemo(() => {
    const slots: string[] = [];
    const start = parseInt((settings.businessHours?.start || "08:00").split(':')[0]);
    const end = parseInt((settings.businessHours?.end || "19:00").split(':')[0]);
    for (let h = start; h < end; h++) {
      slots.push(`${h.toString().padStart(2, '0')}:00`);
      slots.push(`${h.toString().padStart(2, '0')}:30`);
    }
    return slots;
  }, [settings.businessHours]);

  const timeToMinutes = (time: string) => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
  };

  const currentSlotsAvailability = useMemo(() => {
    if (!selectedService) return {};
    const availability: Record<string, TeamMember[]> = {};
    const dateObj = new Date(selectedDate + 'T12:00:00');
    const dayOfWeek = dateObj.getDay();
    const pros = settings.teamMembers.filter(m => m.assignedServiceIds.includes(selectedService.id));

    allPossibleSlots.forEach(slot => {
      const slotStartMin = timeToMinutes(slot);
      const slotEndMin = slotStartMin + selectedService.duration;
      const freePros = pros.filter(pro => {
        if (pro.offDays?.includes(dayOfWeek)) return false;
        const proStartMin = timeToMinutes(pro.businessHours?.start || settings.businessHours.start);
        const proEndMin = timeToMinutes(pro.businessHours?.end || settings.businessHours.end);
        if (slotStartMin < proStartMin || slotEndMin > proEndMin) return false;
        const hasConflict = bookings.some(b => {
          if (b.teamMemberId !== pro.id || b.status === 'cancelled' || !b.dateTime.startsWith(selectedDate)) return false;
          const bStartMin = timeToMinutes(b.dateTime.split(' ')[1]);
          const bEndMin = bStartMin + (b.duration || 30);
          return slotStartMin < bEndMin && slotEndMin > bStartMin;
        });
        return !hasConflict;
      });
      if (freePros.length > 0) availability[slot] = freePros;
    });
    return availability;
  }, [selectedService, selectedDate, settings, bookings, allPossibleSlots]);

  const handleBookSubmit = async () => {
    if (selectedService && selectedProId && selectedTime && agreedToCancellation) {
      const pro = settings.teamMembers.find(m => m.id === selectedProId);

      const bookingData: Omit<Booking, 'id'> = {
        customerId: customer.id,
        customerName: customer.name,
        serviceId: selectedService.id,
        serviceName: selectedService.name,
        dateTime: `${selectedDate} ${selectedTime}`,
        duration: selectedService.duration,
        status: 'pending',
        depositStatus: 'pending',
        teamMemberId: selectedProId,
        teamMemberName: pro?.name,
        agreedToCancellationPolicy: true,
        policyAgreedAt: new Date().toISOString(),
        // Dados da Promoção
        promotionId: activePromoForService?.id || undefined,
        promotionTitle: activePromoForService?.title || undefined,
        originalPrice: priceInfo.original,
        discountApplied: priceInfo.discount,
        finalPrice: priceInfo.final
      };

      await addDoc(collection(db, "bookings"), bookingData);
      setBookingStep(3);
    }
  };

  const myBookings = bookings.filter(b => b.customerId === customer.id).sort((a,b) => b.dateTime.localeCompare(a.dateTime));

  return (
    <div className="min-h-screen bg-[#FDFDFD] pb-32 animate-fade-in">
      <header className="bg-tea-900 pt-12 pb-24 px-8 rounded-b-[4.5rem] shadow-2xl relative">
        <div className="max-w-md mx-auto flex flex-col items-center gap-6 relative z-10 text-white">
          <div className="w-full flex justify-between items-start">
            <button onClick={onLogout} className="p-4 bg-white/10 rounded-2xl">🚪</button>
            <div className="text-right">
              <p className="text-[9px] font-bold text-tea-300 uppercase tracking-widest">Studio Moriá</p>
              <h2 className="text-xl font-serif font-bold italic">Dashboard</h2>
            </div>
          </div>
          <div className="flex items-center gap-6 w-full mt-4">
             <div className="w-20 h-20 bg-white/10 rounded-3xl border border-white/20 flex items-center justify-center text-3xl font-serif">
                {customer.name.charAt(0)}
             </div>
             <div>
                <p className="text-[10px] font-bold uppercase text-tea-200">Bem-vinda de volta,</p>
                <h1 className="text-2xl font-serif font-bold italic">{customer.name.split(' ')[0]}</h1>
             </div>
          </div>
        </div>
      </header>

      <main className="max-w-md mx-auto px-6 -mt-12 relative z-20">
        {activeTab === 'home' && (
          <div className="space-y-6 animate-slide-up">
            <div className="bg-white p-10 rounded-[3.5rem] shadow-xl border border-gray-50 text-center space-y-6">
               <h3 className="text-2xl font-serif font-bold text-tea-950 italic">Sua beleza começa aqui</h3>
               <button onClick={() => setActiveTab('agendar')} className="w-full py-5 bg-tea-800 text-white rounded-[2rem] font-bold text-[10px] uppercase tracking-widest shadow-xl">Novo Agendamento</button>
            </div>

            {promotions.filter(p => p.targetCustomerIds.includes(customer.id) && p.isActive).length > 0 && (
              <div className="space-y-4">
                <h4 className="text-[10px] font-bold text-tea-950 uppercase tracking-widest ml-4">Minhas Ofertas ✨</h4>
                {promotions.filter(p => p.targetCustomerIds.includes(customer.id) && p.isActive).map(p => (
                  <div key={p.id} className="bg-white p-6 rounded-[2.5rem] border-2 border-tea-50 shadow-sm flex items-center gap-5">
                    <div className="w-14 h-14 bg-tea-900 text-white rounded-2xl flex items-center justify-center text-xl font-bold">{p.discountPercentage}%</div>
                    <div>
                      <h5 className="font-bold text-tea-950 text-sm">{p.title}</h5>
                      <p className="text-[9px] text-tea-600 font-bold uppercase tracking-widest">Válido até {new Date(p.endDate).toLocaleDateString()}</p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === 'agendar' && (
          <div className="space-y-6 animate-slide-up">
            {bookingStep === 1 && (
              <div className="space-y-4">
                {services.filter(s => s.isVisible).map(service => (
                  <div key={service.id} className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm hover:border-tea-200 transition-all group">
                    <h4 className="font-bold text-tea-950 text-xl mb-1">{service.name}</h4>
                    <p className="text-gray-400 text-xs mb-6 line-clamp-2">{service.description}</p>
                    <div className="flex justify-between items-center">
                       <div className="text-tea-800 font-bold">R$ {service.price.toFixed(2)}</div>
                       <button onClick={() => { setSelectedService(service); setBookingStep(2); }} className="px-8 py-3 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[9px] tracking-widest group-hover:bg-black transition-all">Selecionar</button>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {bookingStep === 2 && selectedService && (
              <div className="bg-white rounded-[3.5rem] p-10 shadow-2xl border border-tea-50 space-y-8">
                <div className="flex items-center gap-4">
                   <button onClick={() => setBookingStep(1)} className="p-2 bg-tea-50 rounded-xl text-tea-800">←</button>
                   <h3 className="font-bold text-tea-950 text-lg">{selectedService.name}</h3>
                </div>

                {/* Bloco de Preço com Inteligência de Promoção */}
                <div className="bg-tea-50 p-6 rounded-[2.5rem] border border-tea-100 space-y-4">
                  <div className="flex justify-between items-center">
                     <span className="text-[10px] font-bold text-tea-700 uppercase tracking-widest">Valor do Procedimento</span>
                     <span className={`font-bold ${activePromoForService ? 'line-through text-gray-400' : 'text-tea-950'}`}>R$ {priceInfo.original.toFixed(2)}</span>
                  </div>
                  {activePromoForService && (
                    <div className="flex justify-between items-center pt-2 border-t border-tea-100">
                       <div>
                         <p className="text-[9px] font-bold text-tea-900 uppercase tracking-widest">Bônus: {activePromoForService.title}</p>
                         <p className="text-[8px] text-tea-600 font-bold uppercase tracking-tighter">({activePromoForService.discountPercentage}% OFF aplicado)</p>
                       </div>
                       <span className="text-2xl font-serif font-bold text-tea-900">R$ {priceInfo.final.toFixed(2)}</span>
                    </div>
                  )}
                </div>

                <div className="space-y-4">
                   <label className="text-[10px] font-bold text-tea-700 uppercase tracking-widest ml-1">Data Preferida</label>
                   <input type="date" value={selectedDate} onChange={e => setSelectedDate(e.target.value)} className="w-full p-5 bg-gray-50 rounded-2xl font-bold border-none outline-none" />

                   <label className="text-[10px] font-bold text-tea-700 uppercase tracking-widest ml-1 block mt-4">Horário</label>
                   <div className="grid grid-cols-3 gap-2">
                     {allPossibleSlots.map(slot => {
                        const available = !!currentSlotsAvailability[slot];
                        return (
                          <button key={slot} disabled={!available} onClick={() => setSelectedTime(slot)} className={`p-4 rounded-xl text-[10px] font-bold border-2 transition-all ${selectedTime === slot ? 'bg-tea-900 text-white border-tea-900 shadow-md' : available ? 'bg-white border-tea-100 text-tea-900' : 'bg-gray-50 text-gray-200 opacity-50 border-transparent cursor-not-allowed'}`}>
                             {slot}
                          </button>
                        );
                     })}
                   </div>

                   {selectedTime && (
                     <div className="animate-fade-in space-y-4 pt-2">
                       <label className="text-[10px] font-bold text-tea-700 uppercase tracking-widest ml-1 block">Profissional Disponível</label>
                       <select value={selectedProId} onChange={e => setSelectedProId(e.target.value)} className="w-full p-5 bg-gray-50 rounded-2xl font-bold border-none outline-none">
                          <option value="">Selecione...</option>
                          {currentSlotsAvailability[selectedTime]?.map(pro => <option key={pro.id} value={pro.id}>{pro.name}</option>)}
                       </select>
                     </div>
                   )}

                   <label className="flex items-start gap-4 p-5 bg-red-50 rounded-3xl cursor-pointer border border-red-100 mt-6">
                      <input type="checkbox" checked={agreedToCancellation} onChange={e => setAgreedToCancellation(e.target.checked)} className="mt-1 w-4 h-4 rounded text-red-600 border-red-200 focus:ring-red-500" />
                      <span className="text-[9px] font-bold text-red-900 uppercase leading-relaxed">Ciente: O sinal de agendamento não será devolvido em caso de cancelamento.</span>
                   </label>
                </div>

                <button disabled={!selectedTime || !selectedProId || !agreedToCancellation} onClick={handleBookSubmit} className="w-full py-6 bg-tea-900 text-white rounded-[2rem] font-bold uppercase text-[11px] tracking-widest shadow-2xl disabled:bg-gray-100 disabled:text-gray-400 transition-all transform active:scale-95">Solicitar Agendamento</button>
              </div>
            )}

            {bookingStep === 3 && (
              <div className="text-center py-20 bg-white rounded-[4rem] shadow-2xl px-10 space-y-8 animate-slide-up border border-tea-50">
                <div className="w-24 h-24 bg-green-50 text-green-600 rounded-full flex items-center justify-center text-5xl mx-auto">✓</div>
                <div className="space-y-2">
                  <h3 className="text-3xl font-serif font-bold text-tea-950">Solicitado!</h3>
                  <p className="text-xs text-gray-400 font-light leading-relaxed">Seu agendamento para <strong>{selectedService?.name}</strong> está sendo processado. Envie o comprovante de sinal para confirmarmos sua vaga.</p>
                </div>

                <div className="bg-gray-50 p-6 rounded-3xl space-y-1">
                   <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Valor do Sinal (30%)</p>
                   <p className="text-2xl font-bold text-tea-950">R$ {(priceInfo.final * 0.3).toFixed(2)}</p>
                </div>

                <button onClick={() => {
                  const msg = `Olá Moriá! Solicitei ${selectedService?.name} para o dia ${new Date(selectedDate).toLocaleDateString()} às ${selectedTime}. Segue o comprovante de sinal.`;
                  window.open(`https://wa.me/${settings.socialLinks.whatsapp.replace(/\D/g, '')}?text=${encodeURIComponent(msg)}`, '_blank');
                  setActiveTab('agenda'); setBookingStep(1);
                }} className="w-full py-6 bg-tea-900 text-white rounded-3xl font-bold uppercase text-[10px] tracking-[0.2em] shadow-xl hover:bg-black">📱 Enviar Comprovante</button>
              </div>
            )}
          </div>
        )}

        {activeTab === 'agenda' && (
          <div className="space-y-6 animate-slide-up">
            {myBookings.map(b => (
              <div key={b.id} className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm space-y-4 group hover:border-tea-100 transition-all">
                <div className="flex justify-between items-start">
                   <div>
                     <h4 className="font-bold text-tea-950 text-lg leading-tight">{b.serviceName}</h4>
                     <p className="text-[11px] text-gray-400 font-medium">{new Date(b.dateTime.replace(' ', 'T')).toLocaleDateString()} às {new Date(b.dateTime.replace(' ', 'T')).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</p>
                   </div>
                   <span className={`px-4 py-1.5 rounded-full text-[9px] font-bold uppercase tracking-widest ${
                     b.status === 'completed' ? 'bg-green-50 text-green-700' : 
                     b.status === 'cancelled' ? 'bg-red-50 text-red-700' :
                     'bg-tea-50 text-tea-700'
                   }`}>
                     {b.status === 'pending' ? 'Pendente' : b.status === 'scheduled' ? 'Confirmado' : b.status === 'completed' ? 'Concluído' : 'Cancelado'}
                   </span>
                </div>

                {b.promotionId && (
                  <div className="bg-tea-50 p-4 rounded-2xl border border-tea-100 flex items-center justify-between">
                    <div>
                      <p className="text-[8px] font-bold text-tea-700 uppercase tracking-widest">Bônus Aplicado</p>
                      <p className="text-[10px] font-bold text-tea-900 uppercase">{b.promotionTitle}</p>
                    </div>
                    <span className="text-tea-800 font-bold text-xs">- R$ {b.discountApplied?.toFixed(2)}</span>
                  </div>
                )}

                <div className="pt-4 flex justify-between items-center border-t border-gray-50">
                   <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Valor do Atendimento</span>
                   <span className="font-bold text-tea-950 text-lg">R$ {b.finalPrice?.toFixed(2)}</span>
                </div>
              </div>
            ))}
            {myBookings.length === 0 && (
              <div className="text-center py-32 bg-gray-50 rounded-[4rem] border-2 border-dashed border-gray-100">
                <p className="text-gray-300 italic font-serif text-lg">Nenhum atendimento agendado.</p>
              </div>
            )}
          </div>
        )}

        {activeTab === 'perfil' && (
          <div className="bg-white p-12 rounded-[4rem] shadow-sm border border-gray-100 text-center space-y-8 animate-slide-up">
             <div className="w-24 h-24 bg-tea-900 text-white rounded-[2rem] flex items-center justify-center text-4xl mx-auto shadow-xl font-serif">{customer.name.charAt(0)}</div>
             <div>
                <h3 className="text-2xl font-serif font-bold text-tea-950 italic">{customer.name}</h3>
                <p className="text-xs text-gray-400">CPF: {customer.cpf}</p>
             </div>
             <button onClick={onLogout} className="w-full py-5 bg-red-50 text-red-600 rounded-2xl font-bold uppercase text-[10px] tracking-widest hover:bg-red-100 transition-all">Sair da Conta</button>
          </div>
        )}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t border-gray-100 px-10 py-8 flex justify-between rounded-t-[4rem] z-50 shadow-2xl">
         {[
           { id: 'home', icon: '🏠', label: 'Início' },
           { id: 'agendar', icon: '✨', label: 'Agendar' },
           { id: 'agenda', icon: '🗓️', label: 'Agenda' },
           { id: 'perfil', icon: '👤', label: 'Eu' }
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex flex-col items-center gap-1 transition-all ${activeTab === tab.id ? 'text-tea-900 scale-110' : 'text-gray-300 hover:text-gray-500'}`}>
              <span className="text-2xl">{tab.icon}</span>
              <span className={`text-[8px] font-bold uppercase tracking-[0.2em] transition-opacity duration-300 ${activeTab === tab.id ? 'opacity-100' : 'opacity-0'}`}>{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState } from 'react';
import { Booking, Service, TeamMember, SalonSettings, Customer } from '../types';
import { db } from '../firebase.ts';
import { collection, addDoc, deleteDoc, doc } from "firebase/firestore";

interface AdminCalendarProps {
  bookings: Booking[];
  services: Service[];
  customers: Customer[];
  teamMembers: TeamMember[];
  settings?: SalonSettings; 
  onUpdateStatus?: (id: string, status: 'scheduled' | 'cancelled' | 'completed') => void;
}

const AdminCalendar: React.FC<AdminCalendarProps> = ({ bookings, services, customers, teamMembers, settings, onUpdateStatus }) => {
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedProId, setSelectedProId] = useState(teamMembers[0]?.id || '');

  const [bookingModal, setBookingModal] = useState<{ open: boolean; hour: string }>({ open: false, hour: '' });
  const [actionModal, setActionModal] = useState<{ open: boolean; booking: Booking | null }>({ open: false, booking: null });

  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [selectedServiceId, setSelectedServiceId] = useState('');
  const [customerSearch, setCustomerSearch] = useState('');

  const selectedPro = teamMembers.find(m => m.id === selectedProId);
  const startHour = settings?.businessHours?.start || "08:00";
  const endHour = settings?.businessHours?.end || "19:00";

  const dateObj = new Date(selectedDate + 'T12:00:00');
  const dayOfWeek = dateObj.getDay();

  const timeSlots = Array.from({ length: 29 }, (_, i) => {
    const totalMinutes = 7 * 60 + i * 30; 
    const h = Math.floor(totalMinutes / 60);
    const m = totalMinutes % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  });

  const timeToMinutes = (time: string) => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
  };

  const getSlotStatus = (hour: string) => {
    const slotStartMin = timeToMinutes(hour);

    const activeBooking = bookings.find(b => {
      if (b.teamMemberId !== selectedProId || b.status === 'cancelled' || !b.dateTime.startsWith(selectedDate)) return false;
      const bStartMin = timeToMinutes(b.dateTime.split(' ')[1]);
      const bDuration = b.duration || 30;
      const bEndMin = bStartMin + bDuration;
      return slotStartMin >= bStartMin && slotStartMin < bEndMin;
    });

    if (!activeBooking) return { type: 'free' };
    const isStart = activeBooking.dateTime.split(' ')[1] === hour;
    return { 
      type: activeBooking.status === 'blocked' ? 'blocked' : (activeBooking.status === 'completed' ? 'completed' : 'scheduled'),
      booking: activeBooking,
      isStart
    };
  };

  const handleSlotClick = (hour: string) => {
    const status = getSlotStatus(hour);
    if (status.type === 'free') {
      setBookingModal({ open: true, hour });
    } else if (status.booking) {
      setActionModal({ open: true, booking: status.booking });
    }
  };

  const confirmCustomerBooking = async () => {
    if (!selectedCustomerId || !selectedServiceId) return alert("Selecione cliente e serviço.");
    const customer = customers.find(c => c.id === selectedCustomerId);
    const service = services.find(s => s.id === selectedServiceId);

    if (customer && service) {
      await addDoc(collection(db, "bookings"), {
        customerId: customer.id,
        customerName: customer.name,
        serviceId: service.id,
        serviceName: service.name,
        teamMemberId: selectedProId,
        teamMemberName: selectedPro?.name,
        dateTime: `${selectedDate} ${bookingModal.hour}`,
        duration: service.duration,
        status: 'scheduled', 
        depositStatus: 'paid',
        finalPrice: service.price,
        originalPrice: service.price,
        discountApplied: 0
      });
      setBookingModal({ open: false, hour: '' });
      setCustomerSearch(''); setSelectedCustomerId(''); setSelectedServiceId('');
    }
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm flex flex-col md:flex-row gap-6 items-end">
        <div className="flex-1 space-y-2">
          <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Data da Agenda</label>
          <input type="date" value={selectedDate} onChange={e => setSelectedDate(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold" />
        </div>
        <div className="flex-1 space-y-2">
          <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Profissional</label>
          <select value={selectedProId} onChange={e => setSelectedProId(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold">
            {teamMembers.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
          </select>
        </div>
      </div>

      <div className="bg-white rounded-[3.5rem] shadow-sm border border-gray-100 overflow-hidden">
        <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-3 p-8">
          {timeSlots.map(hour => {
            const status = getSlotStatus(hour);
            const isOff = selectedPro?.offDays?.includes(dayOfWeek);

            let color = 'bg-white border-tea-50 text-tea-950';
            let label = 'Livre';

            if (status.type === 'scheduled') {
              color = 'bg-tea-800 text-white border-tea-800';
              label = status.isStart ? status.booking?.customerName.split(' ')[0] : '●';
            } else if (status.type === 'completed') {
              color = 'bg-green-600 text-white border-green-600';
              label = 'Concluído';
            } else if (status.type === 'blocked' || isOff) {
              color = 'bg-gray-100 text-gray-400 border-transparent';
              label = 'Fechado';
            }

            return (
              <button key={hour} onClick={() => handleSlotClick(hour)} className={`relative p-5 rounded-3xl border-2 transition-all flex flex-col items-center justify-center min-h-[90px] ${color} hover:shadow-lg transform active:scale-95`}>
                 <span className="text-lg font-serif font-bold italic leading-none">{hour}</span>
                 <span className="text-[8px] font-bold uppercase tracking-widest mt-1 opacity-80">{label}</span>
                 {status.isStart && status.booking?.promotionId && (
                   <span className="absolute top-2 right-2 text-[7px] bg-orange-400 text-white px-1.5 py-0.5 rounded-full font-bold shadow-sm">PROMO</span>
                 )}
              </button>
            );
          })}
        </div>
      </div>

      {actionModal.open && actionModal.booking && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white w-full max-w-sm rounded-[3rem] p-10 shadow-3xl animate-slide-up space-y-8">
            <div className="text-center">
              <h3 className="text-2xl font-serif text-tea-950 font-bold italic mb-2">{actionModal.booking.customerName}</h3>
              <p className="text-[10px] text-tea-600 font-bold uppercase tracking-widest">{actionModal.booking.serviceName}</p>
            </div>

            {actionModal.booking.promotionId && (
              <div className="bg-orange-50 p-6 rounded-2xl border border-orange-100 text-center">
                <p className="text-[10px] text-orange-400 font-bold uppercase tracking-widest mb-1">Atenção Equipe</p>
                <p className="text-xs font-bold text-orange-950">Cliente Participando da Campanha:</p>
                <p className="text-sm font-serif italic font-bold text-orange-900">"{actionModal.booking.promotionTitle}"</p>
                <div className="flex justify-between mt-4 text-[10px] font-bold uppercase border-t border-orange-100 pt-3">
                   <span>Valor Líquido:</span>
                   <span className="text-lg text-orange-950">R$ {actionModal.booking.finalPrice?.toFixed(2)}</span>
                </div>
              </div>
            )}

            <div className="flex flex-col gap-3">
              <button onClick={() => onUpdateStatus?.(actionModal.booking!.id, 'completed')} className="w-full py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest">Finalizar Atendimento</button>
              <button onClick={() => setActionModal({open:false, booking:null})} className="w-full py-4 text-gray-400 font-bold uppercase text-[10px]">Fechar</button>
            </div>
          </div>
        </div>
      )}

      {bookingModal.open && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
          <div className="bg-white w-full max-w-md rounded-[3rem] p-10 shadow-3xl animate-slide-up space-y-6">
            <h3 className="text-2xl font-serif text-tea-950 font-bold italic text-center">Agendamento Manual</h3>
            <div className="space-y-4">
               <input type="text" placeholder="Buscar cliente..." value={customerSearch} onChange={e => setCustomerSearch(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl outline-none" />
               <div className="max-h-32 overflow-y-auto space-y-1">
                 {customers.filter(c => c.name.toLowerCase().includes(customerSearch.toLowerCase())).slice(0, 3).map(c => (
                   <button key={c.id} onClick={() => { setSelectedCustomerId(c.id); setCustomerSearch(c.name); }} className={`w-full p-3 text-left text-xs rounded-xl ${selectedCustomerId === c.id ? 'bg-tea-50 font-bold' : 'bg-white'}`}>{c.name}</button>
                 ))}
               </div>
               <select value={selectedServiceId} onChange={e => setSelectedServiceId(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl outline-none font-bold">
                 <option value="">Selecione o serviço...</option>
                 {services.map(s => <option key={s.id} value={s.id}>{s.name} - R$ {s.price}</option>)}
               </select>
            </div>
            <div className="flex gap-4">
              <button onClick={() => setBookingModal({open:false, hour:''})} className="flex-1 py-4 text-gray-400 font-bold uppercase text-[10px]">Cancelar</button>
              <button onClick={confirmCustomerBooking} className="flex-[2] py-4 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px]">Confirmar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

