            <div className="space-y-3">
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Serviços Elegíveis (Opcional)</label>
              <div className="flex flex-wrap gap-2">
                {(services || []).map(s => (
                  <button 
                    key={s.id} 
                    onClick={() => toggleService(s.id)} 
                    className={`px-4 py-2 rounded-xl text-[10px] font-bold border-2 transition-all ${selectedServices.includes(s.id) ? 'bg-tea-800 border-tea-800 text-white' : 'bg-white border-gray-100 text-gray-400 hover:border-tea-50'}`}
                  >
                    {s.name}
                  </button>
                ))}
              </div>
            </div>

            <div className="space-y-4 pt-4 border-t border-gray-50">
               <div className="flex justify-between items-center">
                 <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Conteúdo da Mensagem</label>
                 <button onClick={generateSmartContent} disabled={isGenerating} className="text-[9px] font-bold text-tea-600 uppercase hover:underline">
                    {isGenerating ? 'IA escrevendo...' : 'Gerar com IA ✨'}
                 </button>
               </div>
               <textarea rows={6} value={content} onChange={e => setContent(e.target.value)} placeholder="Digite aqui o que será enviado para a cliente..." className="w-full p-6 bg-gray-50 rounded-3xl outline-none focus:ring-2 focus:ring-tea-100 transition-all resize-none text-sm leading-relaxed" />
            </div>
          </div>

          {/* Seleção de Clientes */}
          <div className="lg:col-span-4 flex flex-col gap-6">
             <div className="bg-white p-6 md:p-8 rounded-[3rem] shadow-sm border border-gray-100 flex-grow flex flex-col min-h-[400px]">
                <div className="flex justify-between items-center mb-6">
                   <h3 className="text-xs font-bold text-tea-950 uppercase tracking-widest">Público Alvo</h3>
                   <button onClick={toggleSelectAll} className="text-[9px] font-bold text-tea-600 uppercase hover:underline">
                      {selectedCustomerIds.size === eligibleCustomers.length ? 'Limpar' : 'Todos'}
                   </button>
                </div>
                <input type="text" placeholder="Buscar cliente..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full p-3 bg-gray-50 rounded-xl text-xs mb-4 outline-none border border-transparent focus:border-tea-50" />
                <div className="flex-grow overflow-y-auto max-h-[300px] space-y-2 custom-scroll pr-2">
                   {eligibleCustomers.map(c => (
                     <label key={c.id} className={`flex items-center gap-3 p-4 rounded-2xl border-2 transition-all cursor-pointer ${selectedCustomerIds.has(c.id) ? 'bg-tea-50 border-tea-200' : 'bg-white border-transparent hover:bg-gray-50'}`}>
                        <input type="checkbox" checked={selectedCustomerIds.has(c.id)} onChange={() => {
                          const next = new Set(selectedCustomerIds);
                          next.has(c.id) ? next.delete(c.id) : next.add(c.id);
                          setSelectedCustomerIds(next);
                        }} className="w-4 h-4 rounded text-tea-900 focus:ring-tea-900 border-gray-300" />
                        <div className="text-[11px]">
                          <p className="font-bold text-tea-950">{c.name || 'Sem Nome'}</p>
                          <p className="text-gray-400">{c.whatsapp || 'Sem WhatsApp'}</p>
                        </div>
                     </label>
                   ))}
                   {eligibleCustomers.length === 0 && <p className="text-center py-10 text-gray-300 text-xs italic">Nenhum cliente disponível.</p>}
                </div>
                <div className="pt-6 mt-4 border-t border-gray-50">
                   <button 
                    onClick={saveCampaign} 
                    disabled={selectedCustomerIds.size === 0} 
                    className="w-full py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl disabled:bg-gray-100 transition-all hover:bg-black"
                   >
                    Salvar & Enviar {selectedCustomerIds.size > 0 && `(${selectedCustomerIds.size})`}
                   </button>
                </div>
             </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          {sortedPromotions.map(promo => {
            if (!promo) return null;
            const today = new Date().toISOString().split('T')[0];
            const isPast = (promo.endDate || '') < today;
            const isFuture = (promo.startDate || '') > today;
            const isOngoing = !isPast && !isFuture;

            return (
              <div key={promo.id} className={`bg-white p-6 md:p-8 rounded-[2.5rem] border-2 shadow-sm flex flex-col md:flex-row justify-between items-center gap-6 transition-all ${isPast ? 'opacity-60 border-gray-100' : 'border-tea-50 hover:border-tea-100'}`}>
                <div className="flex items-center gap-6 w-full md:w-auto">
                  <div className={`w-14 h-14 md:w-16 md:h-16 rounded-2xl flex items-center justify-center text-xl md:text-2xl font-bold ${isPast ? 'bg-gray-100 text-gray-400' : 'bg-tea-900 text-white shadow-lg'}`}>
                    {promo.discountPercentage}%
                  </div>
                  <div>
                    <div className="flex items-center gap-3 mb-1">
                      <h3 className="font-bold text-tea-950 text-lg md:text-xl font-serif">{promo.title || 'Promoção sem título'}</h3>
                      {isOngoing && <span className="bg-green-100 text-green-700 px-2 py-0.5 rounded text-[8px] font-bold uppercase">Ativa</span>}
                      {isPast && <span className="bg-gray-100 text-gray-500 px-2 py-0.5 rounded text-[8px] font-bold uppercase">Encerrada</span>}
                    </div>
                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">
                      Validade: {promo.startDate ? new Date(promo.startDate).toLocaleDateString() : '?'} até {promo.endDate ? new Date(promo.endDate).toLocaleDateString() : '?'}
                    </p>
                    <p className="text-xs text-tea-600 font-medium mt-1">
                      {promo.applicableServiceIds?.length === 0 ? 'Todos os serviços' : `${promo.applicableServiceIds?.length} serviços selecionados`}
                      {' • '} {promo.targetCustomerIds?.length || 0} clientes participantes
                    </p>
                  </div>
                </div>
                <div className="flex gap-2 w-full md:w-auto justify-end">
                   <button 
                    onClick={async () => { if(confirm("Deseja encerrar esta campanha?")) await updateDoc(doc(db, "promotions", promo.id), { isActive: false, endDate: today }); }} 
                    className="p-3 bg-gray-50 text-gray-400 rounded-xl hover:text-orange-500 transition-colors"
                    title="Encerrar Agora"
                   >
                    ⏹️
                   </button>
                   <button 
                    onClick={async () => { if(confirm("Excluir permanentemente o registro desta campanha?")) await deleteDoc(doc(db, "promotions", promo.id)); }} 
                    className="p-3 bg-gray-50 text-gray-400 rounded-xl hover:text-red-500 transition-colors"
                    title="Excluir"
                   >
                    🗑️
                   </button>
                </div>
              </div>
            );
          })}

          {sortedPromotions.length === 0 && (
            <div className="text-center py-32 bg-gray-50 rounded-[4rem] border-2 border-dashed border-gray-200">
               <div className="text-4xl mb-4">📢</div>
               <p className="text-gray-400 font-serif italic text-xl">Sua lista de campanhas está vazia.</p>
               <button onClick={() => setShowForm(true)} className="text-tea-600 font-bold text-xs uppercase tracking-widest mt-4 hover:underline">
                  Começar minha primeira promoção
               </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default AdminMarketing;

import React, { useState, useMemo } from 'react';
import { Customer, Promotion, Service } from '../types';
import { GoogleGenAI } from '@google/genai';
import { db } from '../firebase.ts';
import { collection, addDoc, deleteDoc, doc, updateDoc } from "firebase/firestore";

interface AdminMarketingProps {
  customers: Customer[];
  promotions: Promotion[];
  services: Service[];
}

const AdminMarketing: React.FC<AdminMarketingProps> = ({ 
  customers = [], 
  promotions = [], 
  services = [] 
}) => {
  const [activeTab, setActiveTab] = useState<'promotions' | 'tips'>('promotions');
  const [isGenerating, setIsGenerating] = useState(false);
  const [showForm, setShowForm] = useState(false);

  // Estado do Formulário
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [discount, setDiscount] = useState(0);
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [endDate, setEndDate] = useState(new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]);
  const [selectedServices, setSelectedServices] = useState<string[]>([]);
  const [selectedCustomerIds, setSelectedCustomerIds] = useState<Set<string>>(new Set());
  const [searchTerm, setSearchTerm] = useState('');

  // Filtro de clientes com proteção contra campos nulos
  const eligibleCustomers = useMemo(() => {
    return (customers || []).filter(c => {
      if (!c) return false;
      const name = (c.name || '').toLowerCase();
      const whatsapp = (c.whatsapp || '');
      const search = (searchTerm || '').toLowerCase();
      return c.receivesNotifications && (name.includes(search) || whatsapp.includes(search));
    });
  }, [customers, searchTerm]);

  // Filtro e Ordenação por Tipo
  const displayItems = useMemo(() => {
    return [...(promotions || [])]
      .filter(p => activeTab === 'promotions' ? p.type === 'promotion' : p.type === 'tip')
      .sort((a, b) => (b.createdAt || '').localeCompare(a.createdAt || ''));
  }, [promotions, activeTab]);

  const toggleService = (id: string) => {
    setSelectedServices(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const toggleSelectAll = () => {
    if (selectedCustomerIds.size === eligibleCustomers.length) {
      setSelectedCustomerIds(new Set());
    } else {
      setSelectedCustomerIds(new Set(eligibleCustomers.map(c => c.id)));
    }
  };

  const generateAIContent = async () => {
    if (!title) return alert("Defina um título para a IA entender o tema.");
    setIsGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      let prompt = "";

      if (activeTab === 'promotions') {
        prompt = `Crie uma mensagem persuasiva de WhatsApp para Studio Moriá. Título: ${title}. Desconto: ${discount}%. Validade: até ${new Date(endDate).toLocaleDateString()}. Foco: Vendas e Agendamento. Seja elegante e use emojis. Retorne apenas o texto da mensagem.`;
      } else {
        prompt = `Crie uma dica de cuidados estéticos profissional para as clientes do Studio Moriá. Tema: ${title}. Seja educativa, carinhosa e elegante. Use emojis e organize em passos se necessário. Retorne apenas o texto da mensagem de WhatsApp.`;
      }

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });
      setContent(response.text || '');
    } catch (e) { 
      alert("Erro na IA."); 
    } finally { 
      setIsGenerating(false); 
    }
  };

  const saveCampaign = async () => {
    if (!title.trim() || !content.trim()) return alert("Título e conteúdo são obrigatórios.");
    if (selectedCustomerIds.size === 0) return alert("Selecione pelo menos uma cliente.");

    try {
      const promoData: Omit<Promotion, 'id'> = {
        title,
        content,
        type: activeTab === 'promotions' ? 'promotion' : 'tip',
        discountPercentage: activeTab === 'promotions' ? discount : 0,
        applicableServiceIds: selectedServices,
        targetCustomerIds: Array.from(selectedCustomerIds),
        startDate,
        endDate,
        createdAt: new Date().toISOString(),
        isActive: true
      };

      await addDoc(collection(db, "promotions"), promoData);

      const header = activeTab === 'promotions' ? '🌟 *PROMOÇÃO STUDIO MORIÁ* 🌟' : '🌿 *DICA DA MORIÁ* 🌿';
      const message = `${header}\n\n${content}`;
      const targetCustomers = customers.filter(c => selectedCustomerIds.has(c.id));

      if (confirm(`Registro salvo! Deseja abrir os links de WhatsApp para as ${targetCustomers.length} clientes agora?`)) {
        targetCustomers.forEach((c, i) => {
          const cleanPhone = (c.whatsapp || '').replace(/\D/g, '');
          if (cleanPhone) {
            const url = `https://wa.me/${cleanPhone}?text=${encodeURIComponent(message)}`;
            setTimeout(() => window.open(url, '_blank'), i * 1500);
          }
        });
      }

      setShowForm(false);
      resetForm();
    } catch (e) { alert("Erro ao salvar."); }
  };

  const resetForm = () => {
    setTitle(''); setContent(''); setDiscount(0); 
    setSelectedServices([]); setSelectedCustomerIds(new Set());
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6">
        <div>
          <h2 className="text-3xl font-serif text-tea-950 font-bold italic">Marketing Moriá</h2>
          <div className="flex gap-4 mt-2">
            <button 
              onClick={() => { setActiveTab('promotions'); setShowForm(false); }}
              className={`text-[10px] font-bold uppercase tracking-[0.2em] transition-all pb-1 border-b-2 ${activeTab === 'promotions' ? 'border-tea-900 text-tea-950' : 'border-transparent text-gray-400'}`}
            >
              Promoções 🏷️
            </button>
            <button 
              onClick={() => { setActiveTab('tips'); setShowForm(false); }}
              className={`text-[10px] font-bold uppercase tracking-[0.2em] transition-all pb-1 border-b-2 ${activeTab === 'tips' ? 'border-tea-900 text-tea-950' : 'border-transparent text-gray-400'}`}
            >
              Dicas de Estética ✨
            </button>
          </div>
        </div>
        <button 
          onClick={() => setShowForm(!showForm)} 
          className="w-full sm:w-auto bg-tea-900 text-white px-8 py-4 rounded-2xl font-bold uppercase tracking-widest text-[10px] shadow-xl hover:bg-black transition-all"
        >
          {showForm ? '← Voltar' : activeTab === 'promotions' ? '+ Nova Promoção' : '+ Nova Dica'}
        </button>
      </div>

      {showForm ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-slide-up">
          <div className="lg:col-span-8 bg-white p-6 md:p-10 rounded-[3rem] shadow-sm border border-gray-100 space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">{activeTab === 'promotions' ? 'Título da Promoção' : 'Título da Dica'}</label>
                <input type="text" value={title} onChange={e => setTitle(e.target.value)} placeholder={activeTab === 'promotions' ? "Ex: Mês das Noivas" : "Ex: Cuidados Pós-Micro"} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-tea-100 focus:bg-white transition-all" />
              </div>
              {activeTab === 'promotions' && (
                <div className="space-y-2">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Desconto (%)</label>
                  <input type="number" value={discount} onChange={e => setDiscount(Number(e.target.value))} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none" />
                </div>
              )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Data Início</label>
                <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Data Término</label>
                <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none" />
              </div>
            </div>

            <div className="space-y-4 pt-4 border-t border-gray-50">
               <div className="flex justify-between items-center">
                 <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Conteúdo para WhatsApp</label>
                 <button onClick={generateAIContent} disabled={isGenerating} className="text-[9px] font-bold text-tea-600 uppercase hover:underline">
                    {isGenerating ? 'A IA está escrevendo...' : 'Gerar com IA ✨'}
                 </button>
               </div>
               <textarea rows={8} value={content} onChange={e => setContent(e.target.value)} placeholder="O que a cliente receberá..." className="w-full p-6 bg-gray-50 rounded-3xl outline-none focus:ring-2 focus:ring-tea-100 transition-all text-sm leading-relaxed" />
            </div>
          </div>

          <div className="lg:col-span-4 flex flex-col gap-6">
             <div className="bg-white p-6 md:p-8 rounded-[3rem] shadow-sm border border-gray-100 flex-grow flex flex-col min-h-[400px]">
                <h3 className="text-xs font-bold text-tea-950 uppercase tracking-widest mb-6">Público Alvo</h3>
                <input type="text" placeholder="Filtrar clientes..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full p-3 bg-gray-50 rounded-xl text-xs mb-4 outline-none" />
                <div className="flex-grow overflow-y-auto max-h-[300px] space-y-2 custom-scroll pr-2">
                   {eligibleCustomers.map(c => (
                     <label key={c.id} className={`flex items-center gap-3 p-4 rounded-2xl border-2 transition-all cursor-pointer ${selectedCustomerIds.has(c.id) ? 'bg-tea-50 border-tea-200' : 'bg-white border-transparent hover:bg-gray-50'}`}>
                        <input type="checkbox" checked={selectedCustomerIds.has(c.id)} onChange={() => {
                          const next = new Set(selectedCustomerIds);
                          next.has(c.id) ? next.delete(c.id) : next.add(c.id);
                          setSelectedCustomerIds(next);
                        }} className="w-4 h-4 rounded text-tea-900 focus:ring-tea-900 border-gray-300" />
                        <div className="text-[11px]">
                          <p className="font-bold text-tea-950">{c.name}</p>
                          <p className="text-gray-400">{c.whatsapp}</p>
                        </div>
                     </label>
                   ))}
                </div>
                <div className="pt-6 mt-4 border-t border-gray-50">
                   <button onClick={saveCampaign} disabled={selectedCustomerIds.size === 0} className="w-full py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl transition-all hover:bg-black">
                    Finalizar & Enviar ({selectedCustomerIds.size})
                   </button>
                </div>
             </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          {displayItems.map(promo => {
            const today = new Date().toISOString().split('T')[0];
            const isPast = (promo.endDate || '') < today;

            return (
              <div key={promo.id} className={`bg-white p-6 md:p-8 rounded-[2.5rem] border-2 shadow-sm flex flex-col md:flex-row justify-between items-center gap-6 transition-all ${isPast ? 'opacity-50' : 'border-tea-50 hover:border-tea-100'}`}>
                <div className="flex items-center gap-6">
                  <div className={`w-14 h-14 md:w-16 md:h-16 rounded-2xl flex items-center justify-center text-xl md:text-2xl font-bold ${activeTab === 'promotions' ? 'bg-tea-900 text-white shadow-lg' : 'bg-tea-100 text-tea-900 border border-tea-200'}`}>
                    {activeTab === 'promotions' ? `${promo.discountPercentage}%` : '✨'}
                  </div>
                  <div>
                    <h3 className="font-bold text-tea-950 text-lg md:text-xl font-serif">{promo.title}</h3>
                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">
                      {activeTab === 'tips' ? 'Cuidados Publicados em:' : 'Validade:'} {new Date(promo.startDate).toLocaleDateString()}
                    </p>
                    <p className="text-xs text-tea-600 font-medium mt-1 line-clamp-1 italic">
                      "{promo.content.substring(0, 60)}..."
                    </p>
                  </div>
                </div>
                <div className="flex gap-2">
                   <button onClick={async () => { if(confirm("Remover permanentemente?")) await deleteDoc(doc(db, "promotions", promo.id)); }} className="p-3 bg-gray-50 text-gray-400 rounded-xl hover:text-red-500 transition-colors">🗑️</button>
                </div>
              </div>
            );
          })}

          {displayItems.length === 0 && (
            <div className="text-center py-32 bg-gray-50 rounded-[4rem] border-2 border-dashed border-gray-200">
               <p className="text-gray-400 font-serif italic text-xl">Nenhuma {activeTab === 'promotions' ? 'promoção' : 'dica'} cadastrada.</p>
               <button onClick={() => setShowForm(true)} className="text-tea-600 font-bold text-xs uppercase tracking-widest mt-4 hover:underline">
                  {activeTab === 'promotions' ? 'Criar minha primeira oferta' : 'Escrever minha primeira dica'}
               </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default AdminMarketing;

import React, { useState, useEffect, useMemo } from 'react';
import { Customer, Booking, Service, SalonSettings, TeamMember, WaitlistEntry, Promotion } from '../types';
import { db } from '../firebase.ts';
import { doc, updateDoc, collection, addDoc } from "firebase/firestore";

interface CustomerDashboardProps {
  customer: Customer;
  bookings: Booking[];
  services: Service[];
  settings: SalonSettings;
  onBook: (serviceId: string, dateTime: string, teamMemberId?: string, promoData?: any) => void;
  onUpdateProfile: (updated: Partial<Customer>) => void;
  onLogout: () => void;
  onCancelBooking: (id: string) => void;
  onAddToWaitlist?: (serviceId: string, date: string) => void;
  waitlist?: WaitlistEntry[];
  onRemoveWaitlist?: (id: string) => void;
  promotions?: Promotion[];
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ 
  customer, 
  bookings, 
  services, 
  settings,
  onLogout,
  promotions = []
}) => {
  const [activeTab, setActiveTab] = useState<'home' | 'agendar' | 'agenda' | 'perfil'>('home');
  const [selectedService, setSelectedService] = useState<Service | null>(null);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedTime, setSelectedTime] = useState<string>('');
  const [selectedProId, setSelectedProId] = useState<string>('');
  const [bookingStep, setBookingStep] = useState<1 | 2 | 3>(1);
  const [agreedToCancellation, setAgreedToCancellation] = useState(false);

  // Filtros de Marketing
  const myPromotions = useMemo(() => 
    promotions.filter(p => p.type === 'promotion' && p.targetCustomerIds.includes(customer.id) && p.isActive),
    [promotions, customer.id]);

  const myTips = useMemo(() => 
    promotions.filter(p => p.type === 'tip' && p.targetCustomerIds.includes(customer.id)),
    [promotions, customer.id]);

  // Lógica de Promoção Ativa ao Selecionar Serviço
  const activePromoForService = useMemo(() => {
    if (!selectedService) return null;
    const today = new Date().toISOString().split('T')[0];
    return myPromotions.find(p => 
      today >= p.startDate && today <= p.endDate &&
      (p.applicableServiceIds.length === 0 || p.applicableServiceIds.includes(selectedService.id))
    );
  }, [selectedService, myPromotions]);

  const priceInfo = useMemo(() => {
    if (!selectedService) return { original: 0, final: 0, discount: 0 };
    const original = selectedService.price;
    const discountPercent = activePromoForService?.discountPercentage || 0;
    const discountVal = (original * discountPercent) / 100;
    return { original, final: original - discountVal, discount: discountVal };
  }, [selectedService, activePromoForService]);

  const allPossibleSlots = useMemo(() => {
    const slots: string[] = [];
    const start = parseInt((settings.businessHours?.start || "08:00").split(':')[0]);
    const end = parseInt((settings.businessHours?.end || "19:00").split(':')[0]);
    for (let h = start; h < end; h++) {
      slots.push(`${h.toString().padStart(2, '0')}:00`, `${h.toString().padStart(2, '0')}:30`);
    }
    return slots;
  }, [settings.businessHours]);

  const timeToMinutes = (time: string) => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
  };

  const currentSlotsAvailability = useMemo(() => {
    if (!selectedService) return {};
    const availability: Record<string, TeamMember[]> = {};
    const dateObj = new Date(selectedDate + 'T12:00:00');
    const dayOfWeek = dateObj.getDay();
    const pros = settings.teamMembers.filter(m => m.assignedServiceIds.includes(selectedService.id));

    allPossibleSlots.forEach(slot => {
      const slotStartMin = timeToMinutes(slot);
      const slotEndMin = slotStartMin + selectedService.duration;
      const freePros = pros.filter(pro => {
        if (pro.offDays?.includes(dayOfWeek)) return false;
        const proStartMin = timeToMinutes(pro.businessHours?.start || settings.businessHours.start);
        const proEndMin = timeToMinutes(pro.businessHours?.end || settings.businessHours.end);
        if (slotStartMin < proStartMin || slotEndMin > proEndMin) return false;
        const hasConflict = bookings.some(b => {
          if (b.teamMemberId !== pro.id || b.status === 'cancelled' || !b.dateTime.startsWith(selectedDate)) return false;
          const bStartMin = timeToMinutes(b.dateTime.split(' ')[1]);
          return slotStartMin < (bStartMin + b.duration) && slotEndMin > bStartMin;
        });
        return !hasConflict;
      });
      if (freePros.length > 0) availability[slot] = freePros;
    });
    return availability;
  }, [selectedService, selectedDate, settings, bookings, allPossibleSlots]);

  const handleBookSubmit = async () => {
    if (selectedService && selectedProId && selectedTime && agreedToCancellation) {
      const pro = settings.teamMembers.find(m => m.id === selectedProId);
      await addDoc(collection(db, "bookings"), {
        customerId: customer.id,
        customerName: customer.name,
        serviceId: selectedService.id,
        serviceName: selectedService.name,
        dateTime: `${selectedDate} ${selectedTime}`,
        duration: selectedService.duration,
        status: 'pending',
        depositStatus: 'pending',
        teamMemberId: selectedProId,
        teamMemberName: pro?.name,
        agreedToCancellationPolicy: true,
        policyAgreedAt: new Date().toISOString(),
        promotionId: activePromoForService?.id,
        promotionTitle: activePromoForService?.title,
        originalPrice: priceInfo.original,
        discountApplied: priceInfo.discount,
        finalPrice: priceInfo.final
      });
      setBookingStep(3);
    }
  };

  const myBookings = bookings.filter(b => b.customerId === customer.id).sort((a,b) => b.dateTime.localeCompare(a.dateTime));

  return (
    <div className="min-h-screen bg-[#FDFDFD] pb-32 animate-fade-in">
      <header className="bg-tea-900 pt-12 pb-24 px-8 rounded-b-[4.5rem] shadow-2xl relative">
        <div className="max-w-md mx-auto flex flex-col items-center gap-6 relative z-10 text-white">
          <div className="w-full flex justify-between items-start">
            <button onClick={onLogout} className="p-4 bg-white/10 rounded-2xl">🚪</button>
            <div className="text-right">
              <p className="text-[9px] font-bold text-tea-300 uppercase tracking-widest">Studio Moriá</p>
              <h2 className="text-xl font-serif font-bold italic">Painel da Cliente</h2>
            </div>
          </div>
          <div className="flex items-center gap-6 w-full mt-4">
             <div className="w-20 h-20 bg-white/10 rounded-3xl border border-white/20 flex items-center justify-center text-3xl font-serif">{customer.name.charAt(0)}</div>
             <div>
                <p className="text-[10px] font-bold uppercase text-tea-200">Bem-vinda,</p>
                <h1 className="text-2xl font-serif font-bold italic">{customer.name.split(' ')[0]}</h1>
             </div>
          </div>
        </div>
      </header>

      <main className="max-w-md mx-auto px-6 -mt-12 relative z-20">
        {activeTab === 'home' && (
          <div className="space-y-8 animate-slide-up">
            <div className="bg-white p-10 rounded-[3.5rem] shadow-xl border border-gray-50 text-center space-y-6">
               <h3 className="text-2xl font-serif font-bold text-tea-950 italic">Sua beleza começa aqui</h3>
               <button onClick={() => setActiveTab('agendar')} className="w-full py-5 bg-tea-800 text-white rounded-[2rem] font-bold text-[10px] uppercase tracking-widest shadow-xl">Novo Agendamento</button>
            </div>

            {myPromotions.length > 0 && (
              <section className="space-y-4">
                <h4 className="text-[10px] font-bold text-tea-950 uppercase tracking-widest ml-4">Minhas Ofertas ✨</h4>
                <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar">
                  {myPromotions.map(p => (
                    <div key={p.id} className="min-w-[240px] bg-tea-900 p-6 rounded-[2.5rem] text-white shadow-lg space-y-3">
                      <div className="flex justify-between items-start">
                        <span className="text-3xl font-bold">{p.discountPercentage}%</span>
                        <span className="bg-white/20 px-3 py-1 rounded-full text-[8px] font-bold uppercase tracking-widest">OFF</span>
                      </div>
                      <h5 className="font-bold text-sm leading-tight">{p.title}</h5>
                      <p className="text-[9px] text-tea-300 font-bold uppercase tracking-widest">Até {new Date(p.endDate).toLocaleDateString()}</p>
                    </div>
                  ))}
                </div>
              </section>
            )}

            {myTips.length > 0 && (
              <section className="space-y-4">
                <h4 className="text-[10px] font-bold text-tea-950 uppercase tracking-widest ml-4">Dicas da Moriá 🌿</h4>
                <div className="space-y-4">
                  {myTips.map(tip => (
                    <div key={tip.id} className="bg-white p-6 rounded-[2.5rem] border border-tea-100 shadow-sm space-y-3">
                      <div className="flex items-center gap-3">
                         <div className="w-10 h-10 bg-tea-50 rounded-xl flex items-center justify-center text-lg">✨</div>
                         <h5 className="font-bold text-tea-900 text-sm">{tip.title}</h5>
                      </div>
                      <p className="text-xs text-gray-500 leading-relaxed italic">"{tip.content}"</p>
                    </div>
                  ))}
                </div>
              </section>
            )}
          </div>
        )}

        {activeTab === 'agendar' && (
          <div className="space-y-6 animate-slide-up">
             {bookingStep === 1 && (
              <div className="space-y-4">
                {services.filter(s => s.isVisible).map(service => (
                  <div key={service.id} className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm hover:border-tea-200 transition-all flex flex-col h-full">
                    <h4 className="font-bold text-tea-950 text-xl mb-1">{service.name}</h4>
                    <p className="text-gray-400 text-xs mb-6 line-clamp-2">{service.description}</p>
                    <div className="flex justify-between items-center mt-auto">
                       <div className="text-tea-800 font-bold">R$ {service.price.toFixed(2)}</div>
                       <button onClick={() => { setSelectedService(service); setBookingStep(2); }} className="px-8 py-3 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[9px] tracking-widest">Selecionar</button>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {bookingStep === 2 && selectedService && (
              <div className="bg-white rounded-[3.5rem] p-10 shadow-2xl border border-tea-50 space-y-8">
                <div className="flex items-center gap-4">
                   <button onClick={() => setBookingStep(1)} className="p-2 bg-tea-50 rounded-xl">←</button>
                   <h3 className="font-bold text-tea-950 text-lg">{selectedService.name}</h3>
                </div>

                <div className="bg-tea-50 p-6 rounded-[2.5rem] border border-tea-100 space-y-2">
                  <div className="flex justify-between items-center">
                     <span className="text-[10px] font-bold text-tea-700 uppercase tracking-widest">Procedimento</span>
                     <span className={`font-bold ${activePromoForService ? 'line-through text-gray-400' : 'text-tea-950'}`}>R$ {priceInfo.original.toFixed(2)}</span>
                  </div>
                  {activePromoForService && (
                    <div className="flex justify-between items-center pt-2 border-t border-tea-100">
                       <span className="text-[9px] font-bold text-tea-900 uppercase tracking-widest">Bônus: {activePromoForService.title}</span>
                       <span className="text-2xl font-serif font-bold text-tea-900">R$ {priceInfo.final.toFixed(2)}</span>
                    </div>
                  )}
                </div>

                <div className="space-y-6">
                   <div className="space-y-2">
                      <label className="text-[10px] font-bold text-tea-700 uppercase tracking-widest ml-1">Data</label>
                      <input type="date" value={selectedDate} onChange={e => setSelectedDate(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none" />
                   </div>

                   <div className="space-y-2">
                      <label className="text-[10px] font-bold text-tea-700 uppercase tracking-widest ml-1">Horário Disponível</label>
                      <div className="grid grid-cols-3 gap-2">
                        {allPossibleSlots.map(slot => {
                           const available = !!currentSlotsAvailability[slot];
                           return (
                             <button key={slot} disabled={!available} onClick={() => setSelectedTime(slot)} className={`p-4 rounded-xl text-[10px] font-bold border-2 transition-all ${selectedTime === slot ? 'bg-tea-900 text-white border-tea-900' : available ? 'bg-white border-tea-100 text-tea-900' : 'bg-gray-50 text-gray-200 border-transparent opacity-50 cursor-not-allowed'}`}>
                                {slot}
                             </button>
                           );
                        })}
                      </div>
                   </div>

                   {selectedTime && (
                     <div className="space-y-2 animate-fade-in">
                       <label className="text-[10px] font-bold text-tea-700 uppercase tracking-widest ml-1">Profissional</label>
                       <select value={selectedProId} onChange={e => setSelectedProId(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none">
                          <option value="">Selecione...</option>
                          {currentSlotsAvailability[selectedTime]?.map(pro => <option key={pro.id} value={pro.id}>{pro.name}</option>)}
                       </select>
                     </div>
                   )}

                   <label className="flex items-start gap-4 p-5 bg-red-50 rounded-3xl cursor-pointer border border-red-100">
                      <input type="checkbox" checked={agreedToCancellation} onChange={e => setAgreedToCancellation(e.target.checked)} className="mt-1" />
                      <span className="text-[9px] font-bold text-red-900 uppercase leading-relaxed">Entendo que o sinal de agendamento não é reembolsável em caso de desistência.</span>
                   </label>
                </div>

                <button disabled={!selectedTime || !selectedProId || !agreedToCancellation} onClick={handleBookSubmit} className="w-full py-6 bg-tea-900 text-white rounded-[2rem] font-bold uppercase text-[11px] tracking-widest shadow-2xl disabled:bg-gray-100 disabled:text-gray-400">Solicitar Agendamento</button>
              </div>
            )}

            {bookingStep === 3 && (
              <div className="text-center py-20 bg-white rounded-[4rem] shadow-2xl px-10 space-y-8 animate-slide-up border border-tea-50">
                <div className="w-24 h-24 bg-green-50 text-green-600 rounded-full flex items-center justify-center text-5xl mx-auto">✓</div>
                <h3 className="text-3xl font-serif font-bold text-tea-950">Solicitado!</h3>
                <p className="text-xs text-gray-400 font-light leading-relaxed">Seu agendamento para <strong>{selectedService?.name}</strong> está em análise. Envie o comprovante de sinal para confirmarmos.</p>
                <div className="bg-gray-50 p-6 rounded-3xl">
                   <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest mb-1">Valor do Sinal (30%)</p>
                   <p className="text-2xl font-bold text-tea-950">R$ {(priceInfo.final * 0.3).toFixed(2)}</p>
                </div>
                <button onClick={() => {
                  const msg = `Olá Moriá! Solicitei ${selectedService?.name} para o dia ${new Date(selectedDate).toLocaleDateString()} às ${selectedTime}. Segue o comprovante de sinal.`;
                  window.open(`https://wa.me/${settings.socialLinks.whatsapp.replace(/\D/g, '')}?text=${encodeURIComponent(msg)}`, '_blank');
                  setActiveTab('agenda'); setBookingStep(1);
                }} className="w-full py-6 bg-tea-900 text-white rounded-3xl font-bold uppercase text-[10px] tracking-[0.2em] shadow-xl">📱 Enviar Comprovante</button>
              </div>
            )}
          </div>
        )}

        {activeTab === 'agenda' && (
          <div className="space-y-6 animate-slide-up">
            {myBookings.map(b => (
              <div key={b.id} className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm space-y-4">
                <div className="flex justify-between items-start">
                   <div>
                     <h4 className="font-bold text-tea-950 text-lg">{b.serviceName}</h4>
                     <p className="text-[11px] text-gray-400 font-medium">{new Date(b.dateTime.replace(' ', 'T')).toLocaleDateString()} • {new Date(b.dateTime.replace(' ', 'T')).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</p>
                   </div>
                   <span className={`px-4 py-1.5 rounded-full text-[9px] font-bold uppercase tracking-widest ${
                     b.status === 'completed' ? 'bg-green-50 text-green-700' : 
                     b.status === 'cancelled' ? 'bg-red-50 text-red-700' : 'bg-tea-50 text-tea-700'
                   }`}>
                     {b.status === 'pending' ? 'Pendente' : b.status === 'scheduled' ? 'Confirmado' : b.status === 'completed' ? 'Concluído' : 'Cancelado'}
                   </span>
                </div>
                {b.promotionId && (
                  <div className="bg-tea-50 p-4 rounded-2xl border border-tea-100 flex items-center justify-between">
                    <p className="text-[10px] font-bold text-tea-900 uppercase tracking-widest">{b.promotionTitle}</p>
                    <span className="text-tea-800 font-bold text-xs">- R$ {b.discountApplied?.toFixed(2)}</span>
                  </div>
                )}
                <div className="pt-4 flex justify-between items-center border-t border-gray-50">
                   <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Valor</span>
                   <span className="font-bold text-tea-950 text-lg">R$ {b.finalPrice?.toFixed(2)}</span>
                </div>
              </div>
            ))}
            {myBookings.length === 0 && (
              <div className="text-center py-32 bg-gray-50 rounded-[4rem] border-2 border-dashed border-gray-200">
                <p className="text-gray-300 italic font-serif text-lg">Nenhum agendamento.</p>
              </div>
            )}
          </div>
        )}

        {activeTab === 'perfil' && (
          <div className="bg-white p-12 rounded-[4rem] shadow-sm border border-gray-100 text-center space-y-8 animate-slide-up">
             <div className="w-24 h-24 bg-tea-900 text-white rounded-[2rem] flex items-center justify-center text-4xl mx-auto shadow-xl font-serif">{customer.name.charAt(0)}</div>
             <div className="space-y-1">
                <h3 className="text-2xl font-serif font-bold text-tea-950 italic">{customer.name}</h3>
                <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">CPF: {customer.cpf}</p>
             </div>
             <button onClick={onLogout} className="w-full py-5 bg-red-50 text-red-600 rounded-2xl font-bold uppercase text-[10px] tracking-widest hover:bg-red-100 transition-all">Sair da Conta</button>
          </div>
        )}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t border-gray-100 px-10 py-8 flex justify-between rounded-t-[4rem] z-50 shadow-2xl">
         {[
           { id: 'home', icon: '🏠', label: 'Início' },
           { id: 'agendar', icon: '✨', label: 'Agendar' },
           { id: 'agenda', icon: '🗓️', label: 'Agenda' },
           { id: 'perfil', icon: '👤', label: 'Perfil' }
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex flex-col items-center gap-1 transition-all ${activeTab === tab.id ? 'text-tea-900 scale-110' : 'text-gray-300 hover:text-gray-500'}`}>
              <span className="text-2xl">{tab.icon}</span>
              <span className={`text-[8px] font-bold uppercase tracking-[0.2em] transition-opacity duration-300 ${activeTab === tab.id ? 'opacity-100' : 'opacity-0'}`}>{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

