              href={settings.googleMapsLink} 
              target="_blank" 
              rel="noreferrer" 
              className="inline-flex items-center gap-6 bg-tea-900 text-white px-12 py-6 rounded-full font-bold uppercase tracking-widest text-[11px] hover:bg-black transition-all shadow-2xl hover:-translate-y-1"
            >
              <span>Traçar Rota no Mapa</span>
              <span className="text-2xl">🌍</span>
            </a>
          </div>
          <div className="flex-1 w-full bg-white p-5 rounded-[4rem] md:rounded-[6rem] shadow-3xl border border-gray-100 h-[400px] md:h-[550px]">
            <iframe 
              src="https://maps.google.com/maps?q=-23.9004600,-46.4425140&hl=pt&z=15&output=embed" 
              width="100%" 
              height="100%" 
              style={{ border: 0, borderRadius: '3rem' }} 
              allowFullScreen={true} 
              loading="lazy"
              title="Localização Studio Moriá"
            ></iframe>
          </div>
        </div>
      </section>

      {/* Fale com a Moriá */}
      <section id="contato" className="py-24 md:py-40 px-6">
        <div className="max-w-4xl mx-auto text-center space-y-16">
          <div className="space-y-6">
            <p className="text-tea-600 font-bold text-[10px] uppercase tracking-[0.5em]">Atendimento VIP</p>
            <h2 className="text-4xl md:text-6xl font-serif text-tea-950 italic">Fale com a Moriá</h2>
            <p className="text-gray-500 font-light text-lg md:text-xl max-w-lg mx-auto leading-relaxed">Dúvidas? Procedimentos personalizados? Nossa fundadora está disponível para conversar com você.</p>
          </div>

          <form onSubmit={handleContactSubmit} className="max-w-2xl mx-auto bg-white p-12 md:p-20 rounded-[4rem] md:rounded-[6rem] shadow-[0_60px_120px_rgba(0,0,0,0.08)] border border-tea-50 space-y-8 relative">
            <div className="absolute top-0 left-1/2 -translate-x-1/2 -translate-y-1/2 w-24 h-24 bg-tea-900 rounded-3xl flex items-center justify-center text-4xl shadow-2xl">👩‍🎨</div>
            <div className="space-y-4">
              <input 
                type="text" 
                placeholder="Como deseja ser chamada?" 
                required 
                className="w-full p-6 bg-gray-50 rounded-3xl border-none focus:ring-2 focus:ring-tea-100 outline-none font-medium text-base shadow-inner"
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
