              <div className="mt-auto pt-6 border-t border-gray-50 flex justify-between items-center">
                <div>
                   <p className="text-[10px] text-gray-300 font-bold uppercase tracking-widest mb-1">Investimento</p>
                   <span className="text-xl font-serif font-bold text-tea-900 italic">R$ {service.price.toFixed(2)}</span>
