export default CustomerDashboard;

import React, { useState } from 'react';
import { Booking, Service, TeamMember, SalonSettings, Customer } from '../types';
import { db } from '../firebase.ts';
import { collection, addDoc, deleteDoc, doc, updateDoc } from "firebase/firestore";

interface AdminCalendarProps {
  bookings: Booking[];
  services: Service[];
  customers: Customer[];
  teamMembers: TeamMember[];
  settings?: SalonSettings; 
  onUpdateStatus?: (id: string, status: 'scheduled' | 'cancelled' | 'completed') => void;
}

const AdminCalendar: React.FC<AdminCalendarProps> = ({ bookings, services, customers, teamMembers, settings, onUpdateStatus }) => {
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedProId, setSelectedProId] = useState(teamMembers[0]?.id || '');

  const [bookingModal, setBookingModal] = useState<{ open: boolean; hour: string }>({ open: false, hour: '' });
  const [actionModal, setActionModal] = useState<{ open: boolean; booking: Booking | null; hour: string }>({ open: false, booking: null, hour: '' });

  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [selectedServiceId, setSelectedServiceId] = useState('');
  const [customerSearch, setCustomerSearch] = useState('');

  const selectedPro = teamMembers.find(m => m.id === selectedProId);
  const startHourNum = parseInt((settings?.businessHours?.start || "08:00").split(':')[0]);
  const endHourNum = parseInt((settings?.businessHours?.end || "19:00").split(':')[0]);

  const dateObj = new Date(selectedDate + 'T12:00:00');
  const dayOfWeek = dateObj.getDay();

  const timeSlots = Array.from({ length: (endHourNum - startHourNum) * 2 + 1 }, (_, i) => {
    const totalMinutes = startHourNum * 60 + i * 30; 
    const h = Math.floor(totalMinutes / 60);
    const m = totalMinutes % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  });

  const timeToMinutes = (time: string) => {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
  };

  const getSlotStatus = (hour: string) => {
    const slotStartMin = timeToMinutes(hour);

    const activeBooking = bookings.find(b => {
      if (b.teamMemberId !== selectedProId || b.status === 'cancelled' || !b.dateTime.startsWith(selectedDate)) return false;
      const bStartMin = timeToMinutes(b.dateTime.split(' ')[1]);
      const bDuration = b.duration || 30;
      const bEndMin = bStartMin + bDuration;
      return slotStartMin >= bStartMin && slotStartMin < bEndMin;
    });

    if (!activeBooking) return { type: 'free' };
    const isStart = activeBooking.dateTime.split(' ')[1] === hour;
    return { 
      type: activeBooking.status === 'blocked' ? 'blocked' : (activeBooking.status === 'completed' ? 'completed' : 'scheduled'),
      booking: activeBooking,
      isStart
    };
  };

  const handleSlotClick = (hour: string) => {
    const status = getSlotStatus(hour);
    if (status.type === 'free') {
      setBookingModal({ open: true, hour });
    } else {
      setActionModal({ open: true, booking: status.booking || null, hour });
    }
  };

  const confirmCustomerBooking = async () => {
    if (!selectedCustomerId || !selectedServiceId) return alert("Selecione cliente e serviço.");
    const customer = customers.find(c => c.id === selectedCustomerId);
    const service = services.find(s => s.id === selectedServiceId);

    if (customer && service) {
      await addDoc(collection(db, "bookings"), {
        customerId: customer.id,
        customerName: customer.name,
        serviceId: service.id,
        serviceName: service.name,
        teamMemberId: selectedProId,
        teamMemberName: selectedPro?.name,
        dateTime: `${selectedDate} ${bookingModal.hour}`,
        duration: service.duration,
        status: 'scheduled', 
        depositStatus: 'paid',
        finalPrice: service.price,
        originalPrice: service.price,
        discountApplied: 0,
        agreedToCancellationPolicy: true,
        policyAgreedAt: new Date().toISOString()
      });
      setBookingModal({ open: false, hour: '' });
      setCustomerSearch(''); setSelectedCustomerId(''); setSelectedServiceId('');
    }
  };

  const handleBlockSlot = async (hour: string) => {
    await addDoc(collection(db, "bookings"), {
      customerId: 'blocked',
      customerName: 'HORÁRIO BLOQUEADO',
      serviceId: 'blocked',
      serviceName: 'Bloqueio Manual',
      teamMemberId: selectedProId,
      teamMemberName: selectedPro?.name,
      dateTime: `${selectedDate} ${hour}`,
      duration: 30,
      status: 'blocked',
      depositStatus: 'paid',
      agreedToCancellationPolicy: false,
      policyAgreedAt: new Date().toISOString()
    });
    setBookingModal({ open: false, hour: '' });
  };

  const handleBlockFullDay = async () => {
    if (!confirm(`Deseja bloquear todos os horários livres de ${selectedPro?.name} para o dia ${new Date(selectedDate).toLocaleDateString()}?`)) return;

    for (const slot of timeSlots) {
      const status = getSlotStatus(slot);
      if (status.type === 'free') {
        await addDoc(collection(db, "bookings"), {
          customerId: 'blocked',
          customerName: 'BLOQUEIO TOTAL',
          serviceId: 'blocked',
          serviceName: 'Bloqueio de Agenda',
          teamMemberId: selectedProId,
          teamMemberName: selectedPro?.name,
          dateTime: `${selectedDate} ${slot}`,
          duration: 30,
          status: 'blocked',
          depositStatus: 'paid',
          agreedToCancellationPolicy: false,
          policyAgreedAt: new Date().toISOString()
        });
      }
    }
    alert("Agenda bloqueada com sucesso.");
  };

  const handleUnblockOrCancel = async (bookingId: string) => {
    if (!confirm("Tem certeza que deseja remover este registro da agenda?")) return;
    await updateDoc(doc(db, "bookings", bookingId), { status: 'cancelled', cancelledAt: new Date().toISOString() });
    setActionModal({ open: false, booking: null, hour: '' });
  };

  const handleComplete = async (bookingId: string) => {
    await updateDoc(doc(db, "bookings", bookingId), { status: 'completed' });
    setActionModal({ open: false, booking: null, hour: '' });
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm flex flex-col md:flex-row gap-6 items-end">
        <div className="flex-1 space-y-2">
          <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Data da Agenda</label>
          <input type="date" value={selectedDate} onChange={e => setSelectedDate(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold" />
        </div>
        <div className="flex-1 space-y-2">
          <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Profissional</label>
          <select value={selectedProId} onChange={e => setSelectedProId(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl font-bold">
            {teamMembers.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
          </select>
        </div>
        <button 
          onClick={handleBlockFullDay}
          className="bg-red-50 text-red-600 px-6 py-4 rounded-2xl font-bold uppercase text-[10px] tracking-widest hover:bg-red-100 transition-all border border-red-100"
        >
          Bloquear Dia Todo 🚫
        </button>
      </div>

      <div className="bg-white rounded-[3.5rem] shadow-sm border border-gray-100 overflow-hidden">
        <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-3 p-8">
          {timeSlots.map(hour => {
            const status = getSlotStatus(hour);
            const isOff = selectedPro?.offDays?.includes(dayOfWeek);

            let color = 'bg-white border-tea-50 text-tea-950';
            let label = 'Disponível';

            if (status.type === 'scheduled') {
              color = 'bg-tea-800 text-white border-tea-800';
              label = status.isStart ? status.booking?.customerName.split(' ')[0] : '●';
            } else if (status.type === 'completed') {
              color = 'bg-green-600 text-white border-green-600';
              label = 'Concluído';
            } else if (status.type === 'blocked' || isOff) {
              color = 'bg-gray-100 text-gray-400 border-transparent';
              label = 'Bloqueado';
            }

            return (
              <button key={hour} onClick={() => handleSlotClick(hour)} className={`relative p-5 rounded-3xl border-2 transition-all flex flex-col items-center justify-center min-h-[90px] ${color} hover:shadow-lg transform active:scale-95`}>
                 <span className="text-lg font-serif font-bold italic leading-none">{hour}</span>
                 <span className="text-[8px] font-bold uppercase tracking-widest mt-1 opacity-80">{label}</span>
              </button>
            );
          })}
        </div>
      </div>

      {actionModal.open && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white w-full max-w-sm rounded-[3rem] p-10 shadow-3xl animate-slide-up space-y-8">
            <div className="text-center">
              <h3 className="text-2xl font-serif text-tea-950 font-bold italic mb-2">
                {actionModal.booking ? actionModal.booking.customerName : 'Horário Bloqueado'}
              </h3>
              <p className="text-[10px] text-tea-600 font-bold uppercase tracking-widest">
                {actionModal.booking ? actionModal.booking.serviceName : actionModal.hour}
              </p>
            </div>

            <div className="flex flex-col gap-3">
              {actionModal.booking && actionModal.booking.status !== 'blocked' && (
                <button onClick={() => handleComplete(actionModal.booking!.id)} className="w-full py-5 bg-green-600 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-lg">Marcar como Concluído</button>
              )}
              <button 
                onClick={() => {
                  if (actionModal.booking) {
                    handleUnblockOrCancel(actionModal.booking.id);
                  } else {
                    // Se clicou num slot ocupado mas não tem objeto de booking (raro)
                    setActionModal({open:false, booking:null, hour:''});
                  }
                }} 
                className="w-full py-5 bg-red-50 text-red-600 rounded-2xl font-bold uppercase text-[10px] tracking-widest border border-red-100"
              >
                {actionModal.booking?.status === 'blocked' ? 'Desbloquear Horário' : 'Cancelar Procedimento'}
              </button>
              <button onClick={() => setActionModal({open:false, booking:null, hour:''})} className="w-full py-4 text-gray-400 font-bold uppercase text-[10px]">Fechar</button>
            </div>
          </div>
        </div>
      )}

      {bookingModal.open && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
          <div className="bg-white w-full max-w-md rounded-[3rem] p-10 shadow-3xl animate-slide-up space-y-6">
            <h3 className="text-2xl font-serif text-tea-950 font-bold italic text-center">Opções para {bookingModal.hour}</h3>

            <div className="space-y-6">
               <div className="p-6 bg-tea-50/50 rounded-3xl border border-tea-100 space-y-4">
                  <p className="text-[10px] font-bold text-tea-900 uppercase tracking-widest text-center">Agendar para Cliente</p>
                  <input type="text" placeholder="Buscar cliente..." value={customerSearch} onChange={e => setCustomerSearch(e.target.value)} className="w-full p-4 bg-white rounded-2xl outline-none shadow-sm border border-gray-100" />
                  <div className="max-h-32 overflow-y-auto space-y-1">
                    {customers.filter(c => c.name.toLowerCase().includes(customerSearch.toLowerCase())).slice(0, 4).map(c => (
                      <button key={c.id} onClick={() => { setSelectedCustomerId(c.id); setCustomerSearch(c.name); }} className={`w-full p-3 text-left text-xs rounded-xl transition-all ${selectedCustomerId === c.id ? 'bg-tea-800 text-white font-bold' : 'bg-white hover:bg-tea-50'}`}>{c.name}</button>
                    ))}
                  </div>
                  <select value={selectedServiceId} onChange={e => setSelectedServiceId(e.target.value)} className="w-full p-4 bg-white rounded-2xl outline-none font-bold border border-gray-100 shadow-sm">
                    <option value="">Selecione o serviço...</option>
                    {services.map(s => <option key={s.id} value={s.id}>{s.name} - R$ {s.price}</option>)}
                  </select>
                  <button onClick={confirmCustomerBooking} disabled={!selectedCustomerId || !selectedServiceId} className="w-full py-4 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl disabled:opacity-50">Confirmar Agendamento</button>
               </div>

               <div className="pt-4 border-t border-gray-100">
                  <button onClick={() => handleBlockSlot(bookingModal.hour)} className="w-full py-4 bg-red-50 text-red-700 rounded-2xl font-bold uppercase text-[10px] tracking-widest border border-red-100 hover:bg-red-100">Bloquear Horário Individual 🔒</button>
               </div>
            </div>

            <button onClick={() => setBookingModal({open:false, hour:''})} className="w-full py-2 text-gray-400 font-bold uppercase text-[9px] tracking-widest">Cancelar</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminCalendar;

import React, { useState, useEffect, useMemo } from 'react';
import { Customer, Booking, Service, SalonSettings, TeamMember, WaitlistEntry, Promotion } from '../types';
import { db } from '../firebase.ts';
import { doc, updateDoc, collection, addDoc } from "firebase/firestore";

interface CustomerDashboardProps {
  customer: Customer;
  bookings: Booking[];
  services: Service[];
  settings: SalonSettings;
  onBook: (serviceId: string, dateTime: string, teamMemberId?: string, promoData?: any) => void;
  onUpdateProfile: (updated: Partial<Customer>) => void;
  onLogout: () => void;
  onCancelBooking: (id: string) => void;
  onAddToWaitlist?: (serviceId: string, date: string) => void;
  waitlist?: WaitlistEntry[];
  onRemoveWaitlist?: (id: string) => void;
  promotions?: Promotion[];
}

const CustomerDashboard: React.FC<CustomerDashboardProps> = ({ 
  customer, 
  bookings, 
  services, 
  settings,
  onLogout,
  promotions = []
}) => {
  const [activeTab, setActiveTab] = useState<'home' | 'ofertas' | 'agendar' | 'agenda' | 'perfil'>('home');
  const [selectedService, setSelectedService] = useState<Service | null>(null);

  const todayStr = new Date().toISOString().split('T')[0];
  const [selectedDate, setSelectedDate] = useState(todayStr);
  const [selectedTime, setSelectedTime] = useState<string>('');
  const [selectedProId, setSelectedProId] = useState<string>('');
  const [bookingStep, setBookingStep] = useState<1 | 2 | 3>(1);
  const [agreedToCancellation, setAgreedToCancellation] = useState(false);
  const [viewingPromo, setViewingPromo] = useState<Promotion | null>(null);
  const [serviceSearch, setServiceSearch] = useState('');

  // Modal de Detalhes (Descrição Completa)
  const [viewingServiceDetail, setViewingServiceDetail] = useState<Service | null>(null);

  // Filtros de Marketing
  const allMyPromotions = useMemo(() => 
    promotions.filter(p => (p.targetCustomerIds || []).includes(customer.id))
    .sort((a, b) => (b.createdAt || '').localeCompare(a.createdAt || '')),
    [promotions, customer.id]);

  const activePromotions = useMemo(() => 
    allMyPromotions.filter(p => p.type === 'promotion' && p.isActive), [allMyPromotions]);

  const activeTips = useMemo(() => 
    allMyPromotions.filter(p => p.type === 'tip' && p.isActive), [allMyPromotions]);

  // Procedimentos em Destaque
  const highlightedServices = useMemo(() => 
    services.filter(s => s.isVisible && s.isHighlighted), [services]);

  const filteredServices = useMemo(() => {
    return services
      .filter(s => s.isVisible && s.name.toLowerCase().includes(serviceSearch.toLowerCase()))
      .sort((a, b) => (a.isHighlighted ? -1 : 1));
  }, [services, serviceSearch]);

  const activePromoForService = useMemo(() => {
    if (!selectedService) return null;
    return activePromotions.find(p => {
      if (p.linkedServiceId) return p.linkedServiceId === selectedService.id;
      return p.applicableServiceIds.length === 0 || p.applicableServiceIds.includes(selectedService.id);
    });
  }, [selectedService, activePromotions]);

  const priceInfo = useMemo(() => {
    if (!selectedService) return { original: 0, final: 0, discount: 0 };
    const original = selectedService.price;
    const discountPercent = activePromoForService?.discountPercentage || 0;
    const discountVal = (original * discountPercent) / 100;
    return { original, final: Math.max(0, original - discountVal), discount: discountVal };
  }, [selectedService, activePromoForService]);

  const allPossibleSlots = useMemo(() => {
    const slots: string[] = [];
    const start = parseInt((settings.businessHours?.start || "08:00").split(':')[0]);
    const end = parseInt((settings.businessHours?.end || "19:00").split(':')[0]);
    for (let h = start; h < end; h++) {
      slots.push(`${h.toString().padStart(2, '0')}:00`, `${h.toString().padStart(2, '0')}:30`);
    }
    return slots;
  }, [settings.businessHours]);

  const currentSlotsAvailability = useMemo(() => {
    if (!selectedService) return {};
    const availability: Record<string, TeamMember[]> = {};
    const dateObj = new Date(selectedDate + 'T12:00:00');
    const dayOfWeek = dateObj.getDay();
    const pros = settings.teamMembers.filter(m => m.assignedServiceIds.includes(selectedService.id));

    allPossibleSlots.forEach(slot => {
      const slotStartMin = (h:string)=>parseInt(h.split(':')[0])*60+parseInt(h.split(':')[1]);
      const sStartMin = slotStartMin(slot);
      const sEndMin = sStartMin + selectedService.duration;

      const freePros = pros.filter(pro => {
        // 1. Verifica se é dia de folga do profissional
        if (pro.offDays?.includes(dayOfWeek)) return false;

        // 2. Verifica se o horário pretendido está dentro do turno desse profissional
        const pStartMin = slotStartMin(pro.businessHours?.start || settings.businessHours.start);
        const pEndMin = slotStartMin(pro.businessHours?.end || settings.businessHours.end);
        if (sStartMin < pStartMin || sEndMin > pEndMin) return false;

        // 3. Verifica se já existe um agendamento ou BLOQUEIO para este profissional neste horário
        // Consideramos 'scheduled', 'pending', 'completed' e 'blocked' como ocupados.
        const isOccupied = bookings.some(b => 
          b.teamMemberId === pro.id && 
          b.status !== 'cancelled' && 
          b.dateTime === `${selectedDate} ${slot}`
        );

        return !isOccupied;
      });

      if (freePros.length > 0) availability[slot] = freePros;
    });
    return availability;
  }, [selectedService, selectedDate, settings, bookings, allPossibleSlots]);

  const handleBookSubmit = async () => {
    if (selectedService && selectedProId && selectedTime && agreedToCancellation) {
      const pro = settings.teamMembers.find(m => m.id === selectedProId);
      await addDoc(collection(db, "bookings"), {
        customerId: customer.id,
        customerName: customer.name,
        serviceId: selectedService.id,
        serviceName: selectedService.name,
        dateTime: `${selectedDate} ${selectedTime}`,
        duration: selectedService.duration,
        status: 'pending',
        depositStatus: 'pending',
        teamMemberId: selectedProId,
        teamMemberName: pro?.name,
        agreedToCancellationPolicy: true,
        policyAgreedAt: new Date().toISOString(),
        promotionId: activePromoForService?.id,
        promotionTitle: activePromoForService?.title,
        originalPrice: priceInfo.original,
        discountApplied: priceInfo.discount,
        finalPrice: priceInfo.final
      });
      setBookingStep(3);
    }
  };

  const myBookings = bookings.filter(b => b.customerId === customer.id).sort((a,b) => b.dateTime.localeCompare(a.dateTime));

  return (
    <div className="min-h-screen bg-[#FDFDFD] pb-32 animate-fade-in">
      <header className="bg-tea-900 pt-12 pb-24 px-8 rounded-b-[4.5rem] shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-tea-800 rounded-full -mr-32 -mt-32 opacity-20"></div>
        <div className="max-w-md mx-auto flex flex-col items-center gap-6 relative z-10 text-white">
          <div className="w-full flex justify-between items-start">
            <button onClick={onLogout} className="p-4 bg-white/10 rounded-2xl hover:bg-white/20 transition-all">🚪</button>
            <div className="text-right">
              <p className="text-[9px] font-bold text-tea-300 uppercase tracking-widest">Studio Moriá</p>
              <h2 className="text-xl font-serif font-bold italic">Painel Exclusivo</h2>
            </div>
          </div>
          <div className="flex items-center gap-6 w-full mt-4">
             <div className="w-20 h-20 bg-white/10 rounded-3xl border border-white/20 flex items-center justify-center text-3xl font-serif shadow-inner">{customer.name.charAt(0)}</div>
             <div>
                <p className="text-[10px] font-bold uppercase text-tea-200">Bem-vinda de volta,</p>
                <h1 className="text-2xl font-serif font-bold italic">{customer.name.split(' ')[0]}</h1>
             </div>
          </div>
        </div>
      </header>

      <main className="max-w-md mx-auto px-6 -mt-12 relative z-20 pb-20">
        {activeTab === 'home' && (
          <div className="space-y-10 animate-slide-up">
            <div className="bg-white p-10 rounded-[3.5rem] shadow-xl border border-gray-50 text-center space-y-6">
               <h3 className="text-2xl font-serif font-bold text-tea-950 italic">Cuidamos de Você</h3>
               <button onClick={() => setActiveTab('agendar')} className="w-full py-5 bg-tea-800 text-white rounded-[2rem] font-bold text-[10px] uppercase tracking-widest shadow-xl hover:bg-tea-950 transition-all">Novo Agendamento</button>
            </div>

            {/* Promoções e Dicas */}
            {(activePromotions.length > 0 || activeTips.length > 0) && (
              <section className="space-y-4">
                <div className="flex justify-between items-center px-4">
                  <h4 className="text-[10px] font-bold text-tea-950 uppercase tracking-widest">Especial Para Você ✨</h4>
                  <button onClick={() => setActiveTab('ofertas')} className="text-[9px] font-bold text-tea-600 uppercase hover:underline">Ver Todas</button>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar scroll-smooth">
                  {activePromotions.map(p => (
                    <div key={p.id} onClick={() => { setViewingPromo(p); setActiveTab('ofertas'); }} className="min-w-[260px] cursor-pointer bg-tea-900 p-8 rounded-[3rem] text-white shadow-lg space-y-4 transform hover:scale-[1.02] transition-all relative overflow-hidden">
                      <div className="absolute top-0 right-0 p-3 opacity-10 text-4xl">🎁</div>
                      <div className="flex justify-between items-start">
                        <span className="text-3xl font-bold">{p.discountPercentage === 100 ? 'FREE' : `${p.discountPercentage}%`}</span>
                        <span className="bg-white/20 px-3 py-1 rounded-full text-[8px] font-bold uppercase tracking-widest">OFF</span>
                      </div>
                      <h5 className="font-bold text-sm leading-tight line-clamp-2">{p.title}</h5>
                      <p className="text-[9px] text-tea-300 font-bold uppercase tracking-widest">Até {new Date(p.endDate).toLocaleDateString()}</p>
                    </div>
                  ))}
                  {activeTips.map(p => (
                    <div key={p.id} onClick={() => { setViewingPromo(p); setActiveTab('ofertas'); }} className="min-w-[260px] cursor-pointer bg-tea-50 p-8 rounded-[3rem] text-tea-900 border border-tea-100 shadow-sm space-y-4 transform hover:scale-[1.02] transition-all relative overflow-hidden">
                      <div className="absolute top-0 right-0 p-3 opacity-10 text-4xl text-tea-900">✨</div>
                      <span className="bg-tea-900/10 text-tea-900 px-3 py-1 rounded-full text-[8px] font-bold uppercase tracking-widest inline-block">Dica Moriá</span>
                      <h5 className="font-bold text-sm leading-tight line-clamp-2">{p.title}</h5>
                      <p className="text-[9px] text-tea-600 font-bold uppercase tracking-widest">Clique para ler</p>
                    </div>
                  ))}
                </div>
              </section>
            )}

            {/* Procedimentos em Destaque */}
            {highlightedServices.length > 0 && (
              <section className="space-y-4">
                <div className="px-4">
                  <h4 className="text-[10px] font-bold text-tea-950 uppercase tracking-widest">Procedimentos em Destaque ⭐</h4>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-6 no-scrollbar scroll-smooth">
                  {highlightedServices.map(service => (
                    <div 
                      key={service.id} 
                      onClick={() => setViewingServiceDetail(service)}
                      className="min-w-[280px] bg-white p-8 rounded-[3.5rem] border border-orange-50 shadow-md flex flex-col justify-between relative group hover:border-orange-100 transition-all cursor-pointer"
                    >
                      <div className="space-y-3">
                        <div className="flex justify-between items-center">
                          <span className="bg-orange-400 text-white px-3 py-1 rounded-full text-[7px] font-bold uppercase tracking-widest">Mais Pedido</span>
                          <span className="text-tea-900 font-serif font-bold text-sm italic">R$ {service.price.toFixed(2)}</span>
                        </div>
                        <h3 className="text-lg font-serif font-bold text-gray-900 leading-tight">{service.name}</h3>
                        <p className="text-gray-400 text-[10px] leading-relaxed line-clamp-2 italic">{service.description}</p>
                      </div>
                      <span className="mt-6 text-[8px] font-bold text-tea-600 uppercase tracking-widest text-center">Ver detalhes & Agendar</span>
                    </div>
                  ))}
                </div>
              </section>
            )}
          </div>
        )}

        {/* Modal de Detalhes do Serviço (Dashboard) */}
        {viewingServiceDetail && (
          <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-tea-950/80 backdrop-blur-md animate-fade-in">
            <div className="bg-white w-full max-sm:w-full max-w-sm rounded-[4rem] overflow-hidden shadow-3xl animate-slide-up flex flex-col border border-tea-50 max-h-[90vh]">
              <div className="p-10 overflow-y-auto custom-scroll space-y-8">
                <div className="flex justify-between items-start">
                   <h3 className="text-2xl font-serif text-tea-950 font-bold italic leading-tight">{viewingServiceDetail.name}</h3>
                   <button onClick={() => setViewingServiceDetail(null)} className="p-3 bg-gray-50 rounded-xl text-gray-300">✕</button>
                </div>

                <div className="space-y-4">
                   <p className="text-gray-500 text-base font-light leading-relaxed whitespace-pre-line italic">
                     {viewingServiceDetail.description}
                   </p>
                </div>

                <div className="grid grid-cols-2 gap-4">
                   <div className="p-4 bg-gray-50 rounded-3xl text-center">
                      <p className="text-[8px] font-bold text-gray-400 uppercase tracking-widest mb-1">Duração</p>
                      <p className="text-lg font-serif text-tea-900 font-bold">{viewingServiceDetail.duration} min</p>
                   </div>
                   <div className="p-4 bg-tea-900 rounded-3xl text-white text-center">
                      <p className="text-[8px] font-bold text-tea-300 uppercase tracking-widest mb-1">Valor</p>
                      <p className="text-lg font-serif font-bold">R$ {viewingServiceDetail.price.toFixed(2)}</p>
                   </div>
                </div>
              </div>

              <div className="p-8 bg-gray-50 border-t border-gray-100 flex flex-col gap-3">
                 <button 
                   onClick={() => { setSelectedService(viewingServiceDetail); setActiveTab('agendar'); setBookingStep(2); setViewingServiceDetail(null); }} 
                   className="w-full py-5 bg-tea-950 text-white rounded-[2rem] font-bold uppercase text-[10px] tracking-widest shadow-xl"
                 >
                   Continuar Agendamento
                 </button>
                 <button 
                   onClick={() => setViewingServiceDetail(null)} 
                   className="w-full py-3 text-gray-400 font-bold uppercase text-[9px] tracking-widest"
                 >
                   Voltar
                 </button>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'ofertas' && (
          <div className="space-y-6 animate-slide-up pb-10">
            <h3 className="text-center font-serif text-2xl font-bold text-tea-950 italic mb-8">Novidades & Ofertas</h3>
            {allMyPromotions.map(promo => (
              <div key={promo.id} className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm space-y-4">
                <div className="flex justify-between items-start">
                   <span className={`px-4 py-1.5 rounded-full text-[9px] font-bold uppercase tracking-widest ${promo.type === 'promotion' ? 'bg-tea-900 text-white' : 'bg-tea-50 text-tea-900'}`}>
                     {promo.type === 'promotion' ? 'Oferta' : 'Dica'}
                   </span>
                   <p className="text-[10px] text-gray-400 font-bold uppercase">{new Date(promo.createdAt).toLocaleDateString()}</p>
                </div>
                <h4 className="font-bold text-tea-950 text-xl font-serif italic">{promo.title}</h4>
                <p className="text-sm text-gray-500 leading-relaxed whitespace-pre-line">{promo.content}</p>
                {promo.type === 'promotion' && promo.linkedServiceId && (
                  <button 
                    onClick={() => { 
                      const s = services.find(x => x.id === promo.linkedServiceId);
                      if(s) { setSelectedService(s); setActiveTab('agendar'); setBookingStep(2); }
                    }} 
                    className="w-full py-4 bg-tea-50 text-tea-900 rounded-2xl font-bold uppercase text-[10px] tracking-widest hover:bg-tea-100"
                  >
                    Aproveitar Desconto
                  </button>
                )}
              </div>
            ))}
            {allMyPromotions.length === 0 && (
               <div className="text-center py-20 bg-gray-50 rounded-[4rem] border-2 border-dashed border-gray-200">
                  <p className="text-gray-400 font-serif italic">Nenhuma novidade no momento.</p>
               </div>
            )}
          </div>
        )}

        {activeTab === 'agendar' && (
          <div className="space-y-6 animate-slide-up pb-10">
             {bookingStep === 1 && (
              <div className="space-y-6">
                <div className="relative">
                  <span className="absolute left-5 top-1/2 -translate-y-1/2 opacity-30 text-lg">🔍</span>
                  <input 
                    type="text" 
                    placeholder="Qual procedimento deseja?" 
                    value={serviceSearch}
                    onChange={e => setServiceSearch(e.target.value)}
                    className="w-full p-5 pl-14 bg-white rounded-3xl shadow-sm border border-gray-100 outline-none focus:ring-2 focus:ring-tea-100 transition-all font-medium"
                  />
                </div>

                <div className="space-y-4">
                  {filteredServices.map(service => (
                    <div 
                      key={service.id} 
                      onClick={() => setViewingServiceDetail(service)}
                      className={`bg-white p-8 rounded-[3rem] border transition-all flex flex-col h-full relative overflow-hidden cursor-pointer ${service.isHighlighted ? 'border-orange-100 bg-orange-50/5' : 'border-gray-50 shadow-sm'}`}
                    >
                      {service.isHighlighted && (
                        <div className="absolute top-0 right-0 bg-orange-400 text-white px-4 py-1.5 rounded-bl-3xl text-[8px] font-bold uppercase tracking-widest">
                          Destaque ⭐
                        </div>
                      )}
                      <h4 className="font-bold text-tea-950 text-xl font-serif italic mb-2">{service.name}</h4>
                      <p className="text-gray-400 text-xs mb-8 line-clamp-2 italic">{service.description}</p>
                      <div className="flex justify-between items-center mt-auto">
                         <div className="text-tea-800 font-bold font-serif italic">R$ {service.price.toFixed(2)}</div>
                         <button onClick={(e) => { e.stopPropagation(); setSelectedService(service); setBookingStep(2); }} className="px-10 py-4 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl">Agendar</button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {bookingStep === 2 && selectedService && (
              <div className="bg-white rounded-[4rem] p-10 shadow-2xl border border-tea-50 space-y-10 animate-slide-up">
                <div className="flex items-center gap-5">
                   <button onClick={() => setBookingStep(1)} className="w-12 h-12 bg-tea-50 rounded-2xl flex items-center justify-center text-tea-900 font-bold hover:bg-tea-100 transition-all">←</button>
                   <div>
                      <h3 className="font-bold text-tea-950 text-lg font-serif italic">{selectedService.name}</h3>
                      <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Escolha Horário & Profissional</p>
                   </div>
                </div>
                <div className="space-y-8">
                   <div className="space-y-3">
                      <label className="text-[11px] font-bold text-tea-700 uppercase tracking-[0.2em] ml-2">Data da Sessão</label>
                      <input 
                        type="date" 
                        min={todayStr}
                        max={settings.agendaOpenUntil}
                        value={selectedDate} 
                        onChange={e => setSelectedDate(e.target.value)} 
                        className="w-full p-5 bg-gray-50 rounded-3xl font-bold outline-none border-none shadow-inner" 
                      />
                      {settings.agendaOpenUntil && (
                        <p className="text-[9px] text-gray-400 uppercase tracking-widest text-center">Agenda aberta até {new Date(settings.agendaOpenUntil + 'T12:00:00').toLocaleDateString()}</p>
                      )}
                   </div>
                   <div className="space-y-3">
                      <label className="text-[11px] font-bold text-tea-700 uppercase tracking-[0.2em] ml-2">Horários Disponíveis</label>
                      <div className="grid grid-cols-3 gap-3">
                        {allPossibleSlots.map(slot => {
                           const available = !!currentSlotsAvailability[slot];
                           return (
                             <button 
                               key={slot} 
                               disabled={!available} 
                               onClick={() => setSelectedTime(slot)} 
                               className={`p-5 rounded-2xl text-[11px] font-bold border-2 transition-all ${
                                 selectedTime === slot ? 'bg-tea-900 text-white border-tea-900 shadow-xl scale-105' : 
                                 available ? 'bg-white border-tea-100 text-tea-900 hover:bg-tea-50' : 
                                 'bg-gray-100 text-gray-300 border-transparent opacity-40 cursor-not-allowed grayscale'
                               }`}
                             >
                               {slot}
                             </button>
                           );
                        })}
                      </div>
                      {!Object.keys(currentSlotsAvailability).length && (
                        <p className="text-center py-4 bg-red-50 text-red-600 rounded-2xl text-[10px] font-bold uppercase tracking-widest border border-red-100">🚫 Sem horários para esta data</p>
                      )}
                   </div>
                   {selectedTime && (
                     <div className="space-y-3 animate-fade-in">
                        <label className="text-[11px] font-bold text-tea-700 uppercase tracking-[0.2em] ml-2">Profissional</label>
                        <select value={selectedProId} onChange={e => setSelectedProId(e.target.value)} className="w-full p-5 bg-gray-50 rounded-3xl font-bold outline-none appearance-none shadow-inner">
                           <option value="">Selecione...</option>
                           {currentSlotsAvailability[selectedTime]?.map(pro => <option key={pro.id} value={pro.id}>{pro.name}</option>)}
                        </select>
                     </div>
                   )}
                   <label className="flex items-start gap-4 p-6 bg-red-50/50 rounded-[2.5rem] cursor-pointer border border-red-100">
                      <input type="checkbox" checked={agreedToCancellation} onChange={e => setAgreedToCancellation(e.target.checked)} className="mt-1 w-5 h-5 accent-red-600" />
                      <span className="text-[10px] font-bold text-red-900 uppercase leading-relaxed tracking-wider">Declaro ciência da taxa de reserva de 30% em caso de falta.</span>
                   </label>
                </div>
                <button disabled={!selectedTime || !selectedProId || !agreedToCancellation} onClick={handleBookSubmit} className="w-full py-7 bg-tea-950 text-white rounded-[2.5rem] font-bold uppercase text-[11px] tracking-[0.3em] shadow-2xl disabled:bg-gray-100 disabled:text-gray-400 transition-all">Solicitar Horário</button>
              </div>
            )}

            {bookingStep === 3 && (
              <div className="bg-white rounded-[4rem] p-16 shadow-2xl border border-tea-100 text-center space-y-8 animate-slide-up">
                 <div className="w-24 h-24 bg-green-50 text-green-600 rounded-full flex items-center justify-center text-5xl mx-auto shadow-inner">✓</div>
                 <div>
                    <h3 className="text-3xl font-serif text-tea-950 font-bold italic mb-3">Enviado com Sucesso!</h3>
                    <p className="text-gray-500 text-sm leading-relaxed">Sua solicitação de agendamento está em análise pela equipe Moriá. Você receberá um WhatsApp de confirmação.</p>
                 </div>
                 <button onClick={() => { setActiveTab('agenda'); setBookingStep(1); }} className="w-full py-6 bg-tea-900 text-white rounded-3xl font-bold uppercase text-[11px] tracking-widest shadow-xl">Ver Minha Agenda</button>
              </div>
            )}
          </div>
        )}

        {activeTab === 'agenda' && (
          <div className="space-y-6 animate-slide-up pb-10">
            <h3 className="text-center font-serif text-2xl font-bold text-tea-950 italic mb-8">Minha Agenda</h3>
            {myBookings.map(b => (
              <div key={b.id} className="bg-white p-10 rounded-[3.5rem] border border-gray-100 shadow-sm space-y-6">
                <div className="flex justify-between items-start">
                   <div>
                     <h4 className="font-bold text-tea-950 text-xl font-serif italic mb-1">{b.serviceName}</h4>
                     <p className="text-[12px] text-gray-400 font-bold uppercase tracking-widest">{new Date(b.dateTime.replace(' ', 'T')).toLocaleDateString()} • {b.dateTime.split(' ')[1]}</p>
                   </div>
                   <span className={`px-4 py-2 rounded-full text-[10px] font-bold uppercase tracking-widest ${
                     b.status === 'completed' ? 'bg-green-50 text-green-700' : 
                     b.status === 'cancelled' ? 'bg-red-50 text-red-700' : 
                     b.status === 'scheduled' ? 'bg-blue-50 text-blue-700' :
                     'bg-orange-50 text-orange-700'
                   }`}>
                     {b.status === 'pending' ? 'Em Análise' : b.status === 'scheduled' ? 'Confirmado' : b.status === 'cancelled' ? 'Cancelado' : 'Concluído'}
                   </span>
                </div>
              </div>
            ))}
            {myBookings.length === 0 && (
              <div className="text-center py-20 bg-gray-50 rounded-[4rem] border-2 border-dashed border-gray-200">
                <p className="text-gray-400 font-serif italic">Você ainda não possui procedimentos agendados.</p>
              </div>
            )}
          </div>
        )}

        {activeTab === 'perfil' && (
          <div className="space-y-8 animate-slide-up pb-10">
             <div className="bg-white p-12 rounded-[4rem] shadow-xl border border-gray-100 text-center relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-tea-50 rounded-full -mr-16 -mt-16 opacity-40"></div>
                <div className="w-24 h-24 bg-tea-900 text-white rounded-[2rem] flex items-center justify-center text-4xl font-serif mx-auto mb-6 shadow-2xl">
                  {customer.name.charAt(0)}
                </div>
                <h3 className="text-3xl font-serif text-tea-950 font-bold italic mb-2">{customer.name}</h3>
                <p className="text-xs text-gray-400 font-bold uppercase tracking-widest mb-10">CPF: {customer.cpf}</p>

                <div className="space-y-4">
                   <div className="flex justify-between items-center p-6 bg-gray-50 rounded-3xl">
                      <span className="text-[10px] font-bold text-tea-950 uppercase tracking-widest">WhatsApp</span>
                      <span className="font-bold text-tea-800">{customer.whatsapp}</span>
                   </div>
                   <button onClick={onLogout} className="w-full py-5 bg-red-50 text-red-600 rounded-3xl font-bold uppercase text-[10px] tracking-widest hover:bg-red-100 transition-all mt-6">Sair da Conta</button>
                </div>
             </div>
          </div>
        )}
      </main>

      {/* Navegação Inferior */}
      <nav className="fixed bottom-6 left-6 right-6 bg-white/90 backdrop-blur-xl border border-gray-100 p-6 flex justify-between rounded-[3rem] z-50 shadow-[0_40px_80px_rgba(0,0,0,0.15)] max-w-md mx-auto">
         {[
           { id: 'home', icon: '🏠', label: 'Início' },
           { id: 'agendar', icon: '✨', label: 'Agendar' },
           { id: 'agenda', icon: '🗓️', label: 'Agenda' },
           { id: 'ofertas', icon: '🎁', label: 'Ofertas' },
           { id: 'perfil', icon: '👤', label: 'Perfil' }
         ].map(tab => (
           <button 
             key={tab.id} 
             onClick={() => setActiveTab(tab.id as any)} 
             className={`flex flex-col items-center gap-2 transition-all group ${activeTab === tab.id ? 'text-tea-900' : 'text-gray-300'}`}
           >
              <span className={`text-2xl transition-transform duration-300 ${activeTab === tab.id ? 'scale-125 -translate-y-1' : 'group-hover:scale-110'}`}>{tab.icon}</span>
              <span className={`text-[8px] font-bold uppercase tracking-[0.2em] transition-all duration-300 ${activeTab === tab.id ? 'opacity-100' : 'opacity-0 scale-50'}`}>{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, WaitlistEntry, Promotion } from './types.ts';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants.ts';
import { db } from './firebase.ts';
import { 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  addDoc, 
  updateDoc, 
  deleteDoc,
  increment,
  getDoc
} from "firebase/firestore";

import Navbar from './components/Navbar.tsx';
import CustomerHome from './components/CustomerHome.tsx';
import CustomerRegister from './components/CustomerRegister.tsx';
import CustomerLoginView from './components/CustomerLoginView.tsx';
import CustomerProfile from './components/CustomerProfile.tsx';
import CustomerDashboard from './components/CustomerDashboard.tsx';
import AdminDashboard from './components/AdminDashboard.tsx';
import AdminCalendar from './components/AdminCalendar.tsx';
import AdminFinance from './components/AdminFinance.tsx';
import AdminClients from './components/AdminClients.tsx';
import AdminConfirmations from './components/AdminConfirmations.tsx';
import AdminSettingsView from './components/AdminSettingsView.tsx';
import AdminLogin from './components/AdminLogin.tsx';
import AdminMarketing from './components/AdminMarketing.tsx';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [waitlist, setWaitlist] = useState<WaitlistEntry[]>([]);
  const [promotions, setPromotions] = useState<Promotion[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  useEffect(() => {
    // Sincronização inicial com o Firebase
    const unsubSettings = onSnapshot(doc(db, "settings", "main"), (snap) => {
      if (snap.exists()) {
        setSettings(snap.data() as SalonSettings);
        setIsLoading(false);
      } else {
        // Apenas cria se for a PRIMEIRA vez absoluta
        setDoc(doc(db, "settings", "main"), DEFAULT_SETTINGS).then(() => setIsLoading(false));
      }
    });

    const unsubServices = onSnapshot(collection(db, "services"), (snapshot) => {
      const data = snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Service));
      if (data.length === 0 && !isLoading) {
        INITIAL_SERVICES.forEach(s => setDoc(doc(db, "services", s.id), s));
      }
      setServices(data);
    });

    const unsubCustomers = onSnapshot(collection(db, "customers"), (snapshot) => {
      setCustomers(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Customer)));
    });

    const unsubBookings = onSnapshot(collection(db, "bookings"), (snapshot) => {
      setBookings(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Booking)));
    });

    const unsubTransactions = onSnapshot(collection(db, "transactions"), (snapshot) => {
      setTransactions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Transaction)));
    });

    const unsubWaitlist = onSnapshot(collection(db, "waitlist"), (snapshot) => {
      setWaitlist(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as WaitlistEntry)));
    });

    const unsubPromotions = onSnapshot(collection(db, "promotions"), (snapshot) => {
      setPromotions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Promotion)));
    });

    return () => {
      unsubSettings(); unsubServices(); unsubCustomers();
      unsubBookings(); unsubTransactions(); unsubWaitlist(); unsubPromotions();
    };
  }, []);

  // Contador de visitas só após carregar settings
  useEffect(() => {
    if (!isLoading && currentView === View.CUSTOMER_HOME) {
      updateDoc(doc(db, "settings", "main"), {
        visitCount: increment(1)
      }).catch(() => {});
    }
  }, [isLoading, currentView]);

  useEffect(() => {
    const savedUser = localStorage.getItem('moria_user_session');
    if (savedUser) {
      try {
        const parsed = JSON.parse(savedUser);
        if (parsed && typeof parsed === 'object') setCurrentUser(parsed);
      } catch (e) { console.error("Error loading session"); }
    }
    if (localStorage.getItem('moria_admin_session') === 'true') setIsAdminAuthenticated(true);
  }, []);

  useEffect(() => {
    if (currentUser) {
      const cleanUser = {
        id: currentUser.id,
        name: currentUser.name,
        whatsapp: currentUser.whatsapp,
        cpf: currentUser.cpf,
        profilePhoto: currentUser.profilePhoto,
        receivesNotifications: !!currentUser.receivesNotifications
      };
      localStorage.setItem('moria_user_session', JSON.stringify(cleanUser));
    } else {
      localStorage.removeItem('moria_user_session');
    }
    localStorage.setItem('moria_admin_session', isAdminAuthenticated.toString());
  }, [currentUser, isAdminAuthenticated]);

  const handleRegister = async (name: string, whatsapp: string, cpf: string, password: string, receivesNotifications: boolean) => {
    const id = Math.random().toString(36).substr(2, 9);
    const newCustomer: Customer = { id, name, whatsapp, cpf, password, receivesNotifications, agreedToTerms: true, history: [] };
    await setDoc(doc(db, "customers", id), newCustomer);
    setCurrentUser(newCustomer);
    setCurrentView(View.CUSTOMER_DASHBOARD);
  };

  const handleLogin = (cpf: string, pass: string) => {
    const user = customers.find(c => c.cpf === cpf && c.password === pass);
    if (user) { setCurrentUser(user); setCurrentView(View.CUSTOMER_DASHBOARD); }
    else alert("Dados incorretos.");
  };

  const handleBook = async (sid: string, dt: string, mid: string) => {
    if (!currentUser) { setCurrentView(View.CUSTOMER_LOGIN); return; }
    const srv = services.find(s => s.id === sid);
    const booking = {
      customerId: currentUser.id,
      customerName: currentUser.name,
      serviceId: sid,
      serviceName: srv?.name || '',
      dateTime: dt,
      duration: srv?.duration || 30,
      status: 'pending',
      depositStatus: 'pending',
      teamMemberId: mid,
      teamMemberName: settings.teamMembers.find(m => m.id === mid)?.name,
      agreedToCancellationPolicy: true,
      policyAgreedAt: new Date().toISOString()
    };
    await addDoc(collection(db, "bookings"), booking);
  };

  const handleAddToWaitlist = async (sid: string, dt: string) => {
    if (!currentUser) return;
    const srv = services.find(s => s.id === sid);
    await addDoc(collection(db, "waitlist"), {
      customerId: currentUser.id,
      customerName: currentUser.name,
      customerWhatsapp: currentUser.whatsapp,
      serviceId: sid,
      serviceName: srv?.name || '',
      preferredDate: dt,
      status: 'active',
      createdAt: new Date().toISOString()
    });
  };

  const handleUpdateStatus = async (id: string, status: any) => {
    const updateData: any = { status };
    if (status === 'cancelled') updateData.cancelledAt = new Date().toISOString();
    await updateDoc(doc(db, "bookings", id), updateData);
  };

  const handleUpdateDeposit = async (id: string, depositStatus: 'paid' | 'pending') => {
    await updateDoc(doc(db, "bookings", id), { depositStatus });
  };

  const handleCancelBooking = async (id: string) => {
    if (confirm("Deseja cancelar este agendamento? O registro será mantido no histórico da equipe.")) {
      await updateDoc(doc(db, "bookings", id), { 
        status: 'cancelled',
        cancelledAt: new Date().toISOString()
      });
    }
  };

  const handleCancelWaitlist = async (id: string) => {
    await updateDoc(doc(db, "waitlist", id), { 
      status: 'cancelled',
      cancelledAt: new Date().toISOString()
    });
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-tea-950 flex flex-col items-center justify-center space-y-6">
        <div className="w-16 h-16 border-4 border-tea-400 border-t-transparent rounded-full animate-spin"></div>
        <div className="text-center">
           <p className="text-tea-100 font-serif italic text-xl animate-pulse">Sincronizando com Studio Moriá...</p>
           <p className="text-[9px] text-tea-400 uppercase tracking-widest mt-2">Carregando dados da nuvem</p>
        </div>
      </div>
    );
  }

  const renderView = () => {
    if (isAdmin) {
      if (!isAdminAuthenticated) return <AdminLogin onLogin={() => { setIsAdminAuthenticated(true); setCurrentView(View.ADMIN_DASHBOARD); }} onBack={() => setIsAdmin(false)} />;
      switch (currentView) {
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} services={services} customers={customers} bookings={bookings} transactions={transactions} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} services={services} customers={customers} teamMembers={settings.teamMembers} settings={settings} onUpdateStatus={handleUpdateStatus} />;
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} onUpdateStatus={handleUpdateStatus} onUpdateDeposit={handleUpdateDeposit} onDeleteBooking={handleCancelBooking} waitlist={waitlist} onRemoveWaitlist={handleCancelWaitlist} onReactivateWaitlist={(id) => updateDoc(doc(db, "waitlist", id), { status: 'active', cancelledAt: null })} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={(id) => updateDoc(doc(db, "customers", id), { status: 'inactive' })} onUpdate={(id, data) => updateDoc(doc(db, "customers", id), data)} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} onAdd={(d) => addDoc(collection(db, "transactions"), d)} onUpdate={(id, d) => updateDoc(doc(db, "transactions", id), d)} onDelete={(id) => deleteDoc(doc(db, "transactions", id))} customers={customers} services={services} />;
        case View.ADMIN_MARKETING: return <AdminMarketing customers={customers} promotions={promotions} services={services} />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} settings={settings} />;
      }
    }

    if (currentUser && currentView === View.CUSTOMER_DASHBOARD) {
       return (
         <CustomerDashboard 
            customer={currentUser} 
            bookings={bookings} 
            services={services}
            settings={settings}
            onBook={handleBook}
            onUpdateProfile={(upd) => updateDoc(doc(db, "customers", currentUser.id), upd)}
            onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }}
            onCancelBooking={handleCancelBooking}
            onAddToWaitlist={handleAddToWaitlist}
            waitlist={waitlist.filter(w => w.customerId === currentUser.id && w.status !== 'cancelled')}
            onRemoveWaitlist={handleCancelWaitlist}
            promotions={promotions}
         />
       );
    }

    switch (currentView) {
      case View.CUSTOMER_REGISTER: return <CustomerRegister onRegister={handleRegister} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_LOGIN: return <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      default: return (
        <CustomerHome 
          settings={settings} services={services} bookings={bookings} 
          onBook={handleBook} 
          onAuthClick={() => setCurrentView(View.CUSTOMER_LOGIN)} 
          onAddToWaitlist={handleAddToWaitlist} 
          currentUser={currentUser} 
        />
      );
    }
  };

  return (
    <div className="min-h-screen bg-white">
      {currentView !== View.CUSTOMER_DASHBOARD && (
        <Navbar view={currentView} setView={setCurrentView} isAdmin={isAdmin} onToggleAdmin={() => { setIsAdmin(!isAdmin); if(!isAdminAuthenticated) setCurrentView(View.ADMIN_LOGIN); else setCurrentView(isAdmin ? View.CUSTOMER_HOME : View.ADMIN_DASHBOARD); }} salonName={settings.name} logo={settings.logo} currentUser={currentUser} onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }} onAdminLogout={() => { setIsAdminAuthenticated(false); setIsAdmin(false); setCurrentView(View.CUSTOMER_HOME); }} isAdminAuthenticated={isAdminAuthenticated} pendingBookingsCount={bookings.filter(b => b.status === 'pending').length} />
      )}
      <main className={currentView === View.CUSTOMER_DASHBOARD ? "" : "max-w-7xl mx-auto px-4 py-8"}>
        {renderView()}
      </main>
    </div>
  );
};

