                    </div>
                  )) : (
                    <div className="text-center py-16 bg-gray-50 rounded-[3rem] border border-dashed border-gray-200">
                       <p className="text-gray-400 font-serif italic text-sm">Novidades em breve...</p>
                    </div>
                  )}
