import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, WaitlistEntry, Promotion } from './types.ts';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants.ts';
import { db } from './firebase.ts';
import { 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  addDoc, 
  updateDoc, 
  deleteDoc,
  increment,
  getDoc
} from "firebase/firestore";

import Navbar from './components/Navbar.tsx';
import CustomerHome from './components/CustomerHome.tsx';
import CustomerRegister from './components/CustomerRegister.tsx';
import CustomerLoginView from './components/CustomerLoginView.tsx';
import CustomerProfile from './components/CustomerProfile.tsx';
import CustomerDashboard from './components/CustomerDashboard.tsx';
import AdminDashboard from './components/AdminDashboard.tsx';
import AdminCalendar from './components/AdminCalendar.tsx';
import AdminFinance from './components/AdminFinance.tsx';
import AdminClients from './components/AdminClients.tsx';
import AdminConfirmations from './components/AdminConfirmations.tsx';
import AdminSettingsView from './components/AdminSettingsView.tsx';
import AdminLogin from './components/AdminLogin.tsx';
import AdminMarketing from './components/AdminMarketing.tsx';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [waitlist, setWaitlist] = useState<WaitlistEntry[]>([]);
  const [promotions, setPromotions] = useState<Promotion[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  useEffect(() => {
    const unsubSettings = onSnapshot(doc(db, "settings", "main"), (snap) => {
      if (snap.exists()) {
        setSettings(snap.data() as SalonSettings);
        setIsLoading(false);
      } else {
        setDoc(doc(db, "settings", "main"), DEFAULT_SETTINGS).then(() => setIsLoading(false));
      }
    });

    const unsubServices = onSnapshot(collection(db, "services"), (snapshot) => {
      const data = snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Service));
      if (data.length === 0 && !isLoading) {
        INITIAL_SERVICES.forEach(s => setDoc(doc(db, "services", s.id), s));
      }
      setServices(data);
    });

    const unsubCustomers = onSnapshot(collection(db, "customers"), (snapshot) => {
      setCustomers(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Customer)));
    });

    const unsubBookings = onSnapshot(collection(db, "bookings"), (snapshot) => {
      setBookings(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Booking)));
    });

    const unsubTransactions = onSnapshot(collection(db, "transactions"), (snapshot) => {
      setTransactions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Transaction)));
    });

    const unsubWaitlist = onSnapshot(collection(db, "waitlist"), (snapshot) => {
      setWaitlist(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as WaitlistEntry)));
    });

    const unsubPromotions = onSnapshot(collection(db, "promotions"), (snapshot) => {
      setPromotions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Promotion)));
    });

    return () => {
      unsubSettings(); unsubServices(); unsubCustomers();
      unsubBookings(); unsubTransactions(); unsubWaitlist(); unsubPromotions();
    };
  }, []);

  useEffect(() => {
    if (!isLoading && currentView === View.CUSTOMER_HOME) {
      updateDoc(doc(db, "settings", "main"), {
        visitCount: increment(1)
      }).catch(() => {});
    }
  }, [isLoading, currentView]);

  useEffect(() => {
    const savedUser = localStorage.getItem('moria_user_session');
    if (savedUser) {
      try {
        const parsed = JSON.parse(savedUser);
        if (parsed && typeof parsed === 'object') setCurrentUser(parsed);
      } catch (e) { console.error("Error loading session"); }
    }
    if (localStorage.getItem('moria_admin_session') === 'true') setIsAdminAuthenticated(true);
  }, []);

  useEffect(() => {
    if (currentUser) {
      const cleanUser = {
        id: currentUser.id,
        name: currentUser.name,
        whatsapp: currentUser.whatsapp,
        cpf: currentUser.cpf,
        profilePhoto: currentUser.profilePhoto,
        receivesNotifications: !!currentUser.receivesNotifications
      };
      localStorage.setItem('moria_user_session', JSON.stringify(cleanUser));
    } else {
      localStorage.removeItem('moria_user_session');
    }
    localStorage.setItem('moria_admin_session', isAdminAuthenticated.toString());
  }, [currentUser, isAdminAuthenticated]);

  const handleRegister = async (name: string, whatsapp: string, cpf: string, password: string, receivesNotifications: boolean) => {
    // Verificação dupla de segurança
    if (customers.some(c => c.cpf === cpf)) {
      alert("Este CPF já está cadastrado.");
      return;
    }
    const id = Math.random().toString(36).substr(2, 9);
    const newCustomer: Customer = { id, name, whatsapp, cpf, password, receivesNotifications, agreedToTerms: true, history: [] };
    await setDoc(doc(db, "customers", id), newCustomer);
    setCurrentUser(newCustomer);
    setCurrentView(View.CUSTOMER_DASHBOARD);
  };

  const handleLogin = (cpf: string, pass: string) => {
    const user = customers.find(c => c.cpf === cpf && c.password === pass);
    if (user) { setCurrentUser(user); setCurrentView(View.CUSTOMER_DASHBOARD); }
    else alert("Dados incorretos.");
  };

  const handleBook = async (sid: string, dt: string, mid: string) => {
    if (!currentUser) { setCurrentView(View.CUSTOMER_LOGIN); return; }
    const srv = services.find(s => s.id === sid);
    const booking = {
      customerId: currentUser.id,
      customerName: currentUser.name,
      serviceId: sid,
      serviceName: srv?.name || '',
      dateTime: dt,
      duration: srv?.duration || 30,
      status: 'pending',
      depositStatus: 'pending',
      teamMemberId: mid,
      teamMemberName: settings.teamMembers.find(m => m.id === mid)?.name,
      agreedToCancellationPolicy: true,
      policyAgreedAt: new Date().toISOString()
    };
    await addDoc(collection(db, "bookings"), booking);
  };

  const handleAddToWaitlist = async (sid: string, dt: string) => {
    if (!currentUser) return;
    const srv = services.find(s => s.id === sid);
    await addDoc(collection(db, "waitlist"), {
      customerId: currentUser.id,
      customerName: currentUser.name,
      customerWhatsapp: currentUser.whatsapp,
      serviceId: sid,
      serviceName: srv?.name || '',
      preferredDate: dt,
      status: 'active',
      createdAt: new Date().toISOString()
    });
  };

  const handleUpdateStatus = async (id: string, status: any) => {
    const updateData: any = { status };
    if (status === 'cancelled') updateData.cancelledAt = new Date().toISOString();
    await updateDoc(doc(db, "bookings", id), updateData);
  };

  const handleUpdateDeposit = async (id: string, depositStatus: 'paid' | 'pending') => {
    await updateDoc(doc(db, "bookings", id), { depositStatus });
  };

  const handleCancelBooking = async (id: string) => {
    if (confirm("Deseja cancelar este agendamento? O registro será mantido no histórico da equipe.")) {
      await updateDoc(doc(db, "bookings", id), { 
        status: 'cancelled',
        cancelledAt: new Date().toISOString()
      });
    }
  };

  const handleCancelWaitlist = async (id: string) => {
    await updateDoc(doc(db, "waitlist", id), { 
      status: 'cancelled',
      cancelledAt: new Date().toISOString()
    });
  };

  // EXCLUSÃO REAL DE CLIENTE
  const handleDeleteCustomer = async (id: string) => {
    if (confirm("ATENÇÃO: Isso excluirá PERMANENTEMENTE o cadastro da cliente e seu acesso ao app. Deseja continuar?")) {
      await deleteDoc(doc(db, "customers", id));
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-tea-950 flex flex-col items-center justify-center space-y-6">
        <div className="w-16 h-16 border-4 border-tea-400 border-t-transparent rounded-full animate-spin"></div>
        <div className="text-center">
           <p className="text-tea-100 font-serif italic text-xl animate-pulse">Sincronizando Studio Moriá...</p>
        </div>
      </div>
    );
  }

  const renderView = () => {
    if (isAdmin) {
      if (!isAdminAuthenticated) return <AdminLogin onLogin={() => { setIsAdminAuthenticated(true); setCurrentView(View.ADMIN_DASHBOARD); }} onBack={() => setIsAdmin(false)} />;
      switch (currentView) {
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} services={services} customers={customers} bookings={bookings} transactions={transactions} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} services={services} customers={customers} teamMembers={settings.teamMembers} settings={settings} onUpdateStatus={handleUpdateStatus} />;
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} onUpdateStatus={handleUpdateStatus} onUpdateDeposit={handleUpdateDeposit} onDeleteBooking={handleCancelBooking} waitlist={waitlist} onRemoveWaitlist={handleCancelWaitlist} onReactivateWaitlist={(id) => updateDoc(doc(db, "waitlist", id), { status: 'active', cancelledAt: null })} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={handleDeleteCustomer} onUpdate={(id, data) => updateDoc(doc(db, "customers", id), data)} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} onAdd={(d) => addDoc(collection(db, "transactions"), d)} onUpdate={(id, d) => updateDoc(doc(db, "transactions", id), d)} onDelete={(id) => deleteDoc(doc(db, "transactions", id))} customers={customers} services={services} />;
        case View.ADMIN_MARKETING: return <AdminMarketing customers={customers} promotions={promotions} services={services} />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} settings={settings} />;
      }
    }

    if (currentUser && currentView === View.CUSTOMER_DASHBOARD) {
       return (
         <CustomerDashboard 
            customer={currentUser} 
            bookings={bookings} 
            services={services}
            settings={settings}
            onBook={handleBook}
            onUpdateProfile={(upd) => updateDoc(doc(db, "customers", currentUser.id), upd)}
            onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }}
            onCancelBooking={handleCancelBooking}
            onAddToWaitlist={handleAddToWaitlist}
            waitlist={waitlist.filter(w => w.customerId === currentUser.id && w.status !== 'cancelled')}
            onRemoveWaitlist={handleCancelWaitlist}
            promotions={promotions}
         />
       );
    }

    switch (currentView) {
      case View.CUSTOMER_REGISTER: return <CustomerRegister onRegister={handleRegister} customers={customers} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_LOGIN: return <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      default: return (
        <CustomerHome 
          settings={settings} services={services} bookings={bookings} 
          onBook={handleBook} 
          onAuthClick={() => setCurrentView(View.CUSTOMER_LOGIN)} 
          onAddToWaitlist={handleAddToWaitlist} 
          currentUser={currentUser} 
        />
      );
    }
  };

  return (
    <div className="min-h-screen bg-white">
      {currentView !== View.CUSTOMER_DASHBOARD && (
        <Navbar view={currentView} setView={setCurrentView} isAdmin={isAdmin} onToggleAdmin={() => { setIsAdmin(!isAdmin); if(!isAdminAuthenticated) setCurrentView(View.ADMIN_LOGIN); else setCurrentView(isAdmin ? View.CUSTOMER_HOME : View.ADMIN_DASHBOARD); }} salonName={settings.name} logo={settings.logo} currentUser={currentUser} onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }} onAdminLogout={() => { setIsAdminAuthenticated(false); setIsAdmin(false); setCurrentView(View.CUSTOMER_HOME); }} isAdminAuthenticated={isAdminAuthenticated} pendingBookingsCount={bookings.filter(b => b.status === 'pending').length} />
      )}
      <main className={currentView === View.CUSTOMER_DASHBOARD ? "" : "max-w-7xl mx-auto px-4 py-8"}>
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Customer } from '../types';
import TermsModal from './TermsModal';

interface CustomerRegisterProps {
  onRegister: (name: string, whatsapp: string, cpf: string, password: string, receivesNotifications: boolean) => void;
  onBack: () => void;
  customers: Customer[];
}

const CustomerRegister: React.FC<CustomerRegisterProps> = ({ onRegister, onBack, customers = [] }) => {
  const [name, setName] = useState('');
  const [whatsapp, setWhatsapp] = useState('');
  const [cpf, setCpf] = useState('');
  const [password, setPassword] = useState('');
  const [receivesNotifications, setReceivesNotifications] = useState(true);
  const [agreedToTerms, setAgreedToTerms] = useState(false);

  const [modalConfig, setModalConfig] = useState<{ open: boolean; title: string; type: 'terms' | 'privacy' }>({
    open: false,
    title: '',
    type: 'terms'
  });

  // Verificação de CPF Duplicado em Tempo Real
  const isDuplicateCpf = useMemo(() => {
    const cleanCpf = cpf.replace(/\D/g, '');
    if (cleanCpf.length < 11) return false;
    return customers.some(c => c.cpf.replace(/\D/g, '') === cleanCpf);
  }, [cpf, customers]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (isDuplicateCpf) {
      alert("Este CPF já possui um cadastro no Studio Moriá.");
      return;
    }
    if (name && whatsapp && cpf && password && agreedToTerms) {
      onRegister(name, whatsapp, cpf, password, receivesNotifications);
    } else {
      if (!agreedToTerms) {
        alert("Para sua segurança, é necessário aceitar os termos de uso.");
      } else {
        alert("Por favor, preencha todos os campos.");
      }
    }
  };

  const openModal = (type: 'terms' | 'privacy') => {
    setModalConfig({
      open: true,
      type,
      title: type === 'terms' ? 'Termos de Uso' : 'Privacidade (LGPD)'
    });
  };

  return (
    <div className="min-h-screen flex items-center justify-center px-4 py-20 bg-[#F9FBFA]">
      <div className="max-w-xl w-full bg-white rounded-[3.5rem] shadow-[0_40px_100px_rgba(0,0,0,0.05)] overflow-hidden p-12 border border-white">
        <button onClick={onBack} className="text-tea-600 text-sm font-bold flex items-center gap-3 mb-12 hover:-translate-x-1 transition-transform group">
          <svg className="w-5 h-5 group-hover:scale-125 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
          Voltar
        </button>

        <div className="mb-12">
          <h2 className="text-4xl font-serif text-tea-900 mb-4 italic">Sua Conta Moriá</h2>
          <p className="text-gray-500 font-light text-lg italic leading-relaxed">Cadastre-se para agendar seus procedimentos e acessar seu histórico de beleza.</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-8">
          <div className="space-y-4">
            <div className="relative group">
              <label className="block text-[11px] font-bold text-tea-700 uppercase tracking-[0.2em] mb-2 ml-2">Nome Completo</label>
              <input 
                type="text" 
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-transparent focus:bg-white focus:border-tea-200 outline-none transition-all placeholder-gray-300 shadow-inner"
                placeholder="Ex: Maria Santos"
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="relative group">
                <label className="block text-[11px] font-bold text-tea-700 uppercase tracking-[0.2em] mb-2 ml-2">WhatsApp</label>
                <input 
                  type="tel" 
                  required
                  value={whatsapp}
                  onChange={(e) => setWhatsapp(e.target.value)}
                  className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-transparent focus:bg-white focus:border-tea-200 outline-none transition-all placeholder-gray-300 shadow-inner"
                  placeholder="(00) 00000-0000"
                />
              </div>
              <div className="relative group">
                <label className="block text-[11px] font-bold text-tea-700 uppercase tracking-[0.2em] mb-2 ml-2">Seu CPF</label>
                <input 
                  type="text" 
                  required
                  value={cpf}
                  onChange={(e) => setCpf(e.target.value)}
                  className={`w-full px-6 py-4 rounded-2xl bg-gray-50 border-2 outline-none transition-all placeholder-gray-300 shadow-inner ${isDuplicateCpf ? 'border-red-300 bg-red-50' : 'border-transparent focus:bg-white focus:border-tea-200'}`}
                  placeholder="000.000.000-00"
                />
                {isDuplicateCpf && <p className="text-[10px] text-red-600 font-bold mt-2 ml-2 uppercase animate-pulse">CPF já cadastrado! Tente fazer login.</p>}
              </div>
            </div>

            <div className="relative group">
              <label className="block text-[11px] font-bold text-tea-700 uppercase tracking-[0.2em] mb-2 ml-2">Crie uma Senha</label>
              <input 
                type="password" 
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-6 py-4 rounded-2xl bg-gray-50 border-transparent focus:bg-white focus:border-tea-200 outline-none transition-all placeholder-gray-300 shadow-inner"
                placeholder="Mínimo 6 caracteres"
              />
            </div>
          </div>

          <div className="p-8 bg-tea-50/50 rounded-[2.5rem] border border-tea-100 space-y-6">
            <label className="flex items-start gap-5 cursor-pointer group">
              <div className="relative mt-1">
                <input 
                  type="checkbox"
                  checked={receivesNotifications}
                  onChange={(e) => setReceivesNotifications(e.target.checked)}
                  className="peer appearance-none w-6 h-6 rounded-lg border-2 border-tea-200 checked:bg-tea-500 checked:border-tea-500 transition-all cursor-pointer shadow-sm"
                />
                <svg className="absolute top-1 left-1 w-4 h-4 text-white opacity-0 peer-checked:opacity-100 transition-opacity pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
              </div>
              <div className="flex-1">
                <span className="text-sm font-bold text-tea-900 block mb-1">Receber lembretes via WhatsApp</span>
                <span className="text-xs text-tea-700/70 font-medium italic">Avisos de horários e promoções.</span>
              </div>
            </label>

            <label className="flex items-start gap-5 cursor-pointer group">
              <div className="relative mt-1">
                <input 
                  type="checkbox"
                  required
                  checked={agreedToTerms}
                  onChange={(e) => setAgreedToTerms(e.target.checked)}
                  className="peer appearance-none w-6 h-6 rounded-lg border-2 border-tea-200 checked:bg-tea-500 checked:border-tea-500 transition-all cursor-pointer shadow-sm"
                />
                <svg className="absolute top-1 left-1 w-4 h-4 text-white opacity-0 peer-checked:opacity-100 transition-opacity pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
              </div>
              <div className="flex-1">
                <span className="text-sm text-gray-700 leading-relaxed font-medium">
                  Aceito os <button type="button" onClick={() => openModal('terms')} className="text-tea-600 font-bold hover:underline">Termos</button> e a <button type="button" onClick={() => openModal('privacy')} className="text-tea-600 font-bold hover:underline">Política de Privacidade</button>.
                </span>
              </div>
            </label>
          </div>

          <button 
            type="submit"
            disabled={isDuplicateCpf || !agreedToTerms}
            className={`w-full py-6 rounded-[2rem] font-bold text-xl shadow-2xl transition-all duration-500 ${!isDuplicateCpf && agreedToTerms ? 'bg-tea-800 text-white hover:bg-tea-900 shadow-tea-200 hover:-translate-y-1' : 'bg-gray-100 text-gray-400 cursor-not-allowed opacity-70'}`}
          >
            {isDuplicateCpf ? 'CPF já em uso' : 'Concluir Cadastro'}
          </button>
        </form>
      </div>

      <TermsModal 
        isOpen={modalConfig.open} 
        onClose={() => setModalConfig({ ...modalConfig, open: false })}
        title={modalConfig.title}
        type={modalConfig.type}
      />
    </div>
  );
};

export default CustomerRegister;

import React, { useState, useEffect } from 'react';
import { View, Customer, Service, Booking, Transaction, SalonSettings, WaitlistEntry, Promotion } from './types.ts';
import { INITIAL_SERVICES, DEFAULT_SETTINGS } from './constants.ts';
import { db } from './firebase.ts';
import { 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  addDoc, 
  updateDoc, 
  deleteDoc,
  increment,
  getDoc
} from "firebase/firestore";

import Navbar from './components/Navbar.tsx';
import CustomerHome from './components/CustomerHome.tsx';
import CustomerRegister from './components/CustomerRegister.tsx';
import CustomerLoginView from './components/CustomerLoginView.tsx';
import CustomerProfile from './components/CustomerProfile.tsx';
import CustomerDashboard from './components/CustomerDashboard.tsx';
import AdminDashboard from './components/AdminDashboard.tsx';
import AdminCalendar from './components/AdminCalendar.tsx';
import AdminFinance from './components/AdminFinance.tsx';
import AdminClients from './components/AdminClients.tsx';
import AdminConfirmations from './components/AdminConfirmations.tsx';
import AdminSettingsView from './components/AdminSettingsView.tsx';
import AdminLogin from './components/AdminLogin.tsx';
import AdminMarketing from './components/AdminMarketing.tsx';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.CUSTOMER_HOME);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  const [settings, setSettings] = useState<SalonSettings>(DEFAULT_SETTINGS);
  const [services, setServices] = useState<Service[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [waitlist, setWaitlist] = useState<WaitlistEntry[]>([]);
  const [promotions, setPromotions] = useState<Promotion[]>([]);
  const [currentUser, setCurrentUser] = useState<Customer | null>(null);

  useEffect(() => {
    const unsubSettings = onSnapshot(doc(db, "settings", "main"), (snap) => {
      if (snap.exists()) {
        setSettings(snap.data() as SalonSettings);
        setIsLoading(false);
      } else {
        setDoc(doc(db, "settings", "main"), DEFAULT_SETTINGS).then(() => setIsLoading(false));
      }
    });

    const unsubServices = onSnapshot(collection(db, "services"), (snapshot) => {
      const data = snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Service));
      if (data.length === 0 && !isLoading) {
        INITIAL_SERVICES.forEach(s => setDoc(doc(db, "services", s.id), s));
      }
      setServices(data);
    });

    const unsubCustomers = onSnapshot(collection(db, "customers"), (snapshot) => {
      setCustomers(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Customer)));
    });

    const unsubBookings = onSnapshot(collection(db, "bookings"), (snapshot) => {
      setBookings(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Booking)));
    });

    const unsubTransactions = onSnapshot(collection(db, "transactions"), (snapshot) => {
      setTransactions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Transaction)));
    });

    const unsubWaitlist = onSnapshot(collection(db, "waitlist"), (snapshot) => {
      setWaitlist(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as WaitlistEntry)));
    });

    const unsubPromotions = onSnapshot(collection(db, "promotions"), (snapshot) => {
      setPromotions(snapshot.docs.map(d => ({ ...d.data(), id: d.id } as Promotion)));
    });

    return () => {
      unsubSettings(); unsubServices(); unsubCustomers();
      unsubBookings(); unsubTransactions(); unsubWaitlist(); unsubPromotions();
    };
  }, []);

  useEffect(() => {
    if (!isLoading && currentView === View.CUSTOMER_HOME) {
      updateDoc(doc(db, "settings", "main"), {
        visitCount: increment(1)
      }).catch(() => {});
    }
  }, [isLoading, currentView]);

  useEffect(() => {
    const savedUser = localStorage.getItem('moria_user_session');
    if (savedUser) {
      try {
        const parsed = JSON.parse(savedUser);
        if (parsed && typeof parsed === 'object') setCurrentUser(parsed);
      } catch (e) { console.error("Error loading session"); }
    }
    if (localStorage.getItem('moria_admin_session') === 'true') setIsAdminAuthenticated(true);
  }, []);

  useEffect(() => {
    if (currentUser) {
      const cleanUser = {
        id: currentUser.id,
        name: currentUser.name,
        whatsapp: currentUser.whatsapp,
        cpf: currentUser.cpf,
        profilePhoto: currentUser.profilePhoto,
        receivesNotifications: !!currentUser.receivesNotifications
      };
      localStorage.setItem('moria_user_session', JSON.stringify(cleanUser));
    } else {
      localStorage.removeItem('moria_user_session');
    }
    localStorage.setItem('moria_admin_session', isAdminAuthenticated.toString());
  }, [currentUser, isAdminAuthenticated]);

  const handleRegister = async (name: string, whatsapp: string, cpf: string, password: string, receivesNotifications: boolean) => {
    if (customers.some(c => c.cpf === cpf)) {
      alert("Este CPF já está cadastrado.");
      return;
    }
    const id = Math.random().toString(36).substr(2, 9);
    const newCustomer: Customer = { id, name, whatsapp, cpf, password, receivesNotifications, agreedToTerms: true, history: [] };
    await setDoc(doc(db, "customers", id), newCustomer);
    setCurrentUser(newCustomer);
    setCurrentView(View.CUSTOMER_DASHBOARD);
  };

  const handleLogin = (cpf: string, pass: string) => {
    const user = customers.find(c => c.cpf === cpf && c.password === pass);
    if (user) { setCurrentUser(user); setCurrentView(View.CUSTOMER_DASHBOARD); }
    else alert("Dados incorretos.");
  };

  const handleBook = async (sid: string, dt: string, mid: string) => {
    if (!currentUser) { setCurrentView(View.CUSTOMER_LOGIN); return; }
    const srv = services.find(s => s.id === sid);
    const booking = {
      customerId: currentUser.id,
      customerName: currentUser.name,
      serviceId: sid,
      serviceName: srv?.name || '',
      dateTime: dt,
      duration: srv?.duration || 30,
      status: 'pending',
      depositStatus: 'pending',
      teamMemberId: mid,
      teamMemberName: settings.teamMembers.find(m => m.id === mid)?.name,
      agreedToCancellationPolicy: true,
      policyAgreedAt: new Date().toISOString()
    };
    await addDoc(collection(db, "bookings"), booking);
  };

  const handleAddToWaitlist = async (sid: string, dt: string) => {
    if (!currentUser) return;
    const srv = services.find(s => s.id === sid);
    await addDoc(collection(db, "waitlist"), {
      customerId: currentUser.id,
      customerName: currentUser.name,
      customerWhatsapp: currentUser.whatsapp,
      serviceId: sid,
      serviceName: srv?.name || '',
      preferredDate: dt,
      status: 'active',
      createdAt: new Date().toISOString()
    });
  };

  const handleUpdateStatus = async (id: string, status: any) => {
    const updateData: any = { status };
    if (status === 'cancelled') updateData.cancelledAt = new Date().toISOString();
    await updateDoc(doc(db, "bookings", id), updateData);
  };

  const handleUpdateDeposit = async (id: string, depositStatus: 'paid' | 'pending') => {
    await updateDoc(doc(db, "bookings", id), { depositStatus });
  };

  const handleCancelBooking = async (id: string) => {
    if (confirm("Deseja cancelar este agendamento? O registro será mantido no histórico da equipe.")) {
      await updateDoc(doc(db, "bookings", id), { 
        status: 'cancelled',
        cancelledAt: new Date().toISOString()
      });
    }
  };

  const handleCancelWaitlist = async (id: string) => {
    await updateDoc(doc(db, "waitlist", id), { 
      status: 'cancelled',
      cancelledAt: new Date().toISOString()
    });
  };

  const handleDeleteCustomer = async (id: string) => {
    if (confirm("ATENÇÃO: Isso excluirá PERMANENTEMENTE o cadastro da cliente e seu acesso ao app. Deseja continuar?")) {
      await deleteDoc(doc(db, "customers", id));
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-tea-950 flex flex-col items-center justify-center space-y-6">
        <div className="w-16 h-16 border-4 border-tea-400 border-t-transparent rounded-full animate-spin"></div>
        <div className="text-center">
           <p className="text-tea-100 font-serif italic text-xl animate-pulse">Sincronizando Studio Moriá...</p>
        </div>
      </div>
    );
  }

  const renderView = () => {
    if (isAdmin) {
      if (!isAdminAuthenticated) return <AdminLogin onLogin={() => { setIsAdminAuthenticated(true); setCurrentView(View.ADMIN_DASHBOARD); }} onBack={() => setIsAdmin(false)} />;
      switch (currentView) {
        case View.ADMIN_SETTINGS: return <AdminSettingsView settings={settings} services={services} customers={customers} bookings={bookings} transactions={transactions} />;
        case View.ADMIN_CALENDAR: return <AdminCalendar bookings={bookings} services={services} customers={customers} teamMembers={settings.teamMembers} settings={settings} onUpdateStatus={handleUpdateStatus} />;
        case View.ADMIN_CONFIRMATIONS: return <AdminConfirmations bookings={bookings} customers={customers} onUpdateStatus={handleUpdateStatus} onUpdateDeposit={handleUpdateDeposit} onDeleteBooking={handleCancelBooking} waitlist={waitlist} onRemoveWaitlist={handleCancelWaitlist} onReactivateWaitlist={(id) => updateDoc(doc(db, "waitlist", id), { status: 'active', cancelledAt: null })} />;
        case View.ADMIN_CLIENTS: return <AdminClients customers={customers} bookings={bookings} transactions={transactions} onDelete={handleDeleteCustomer} onUpdate={(id, data) => updateDoc(doc(db, "customers", id), data)} />;
        case View.ADMIN_FINANCE: return <AdminFinance transactions={transactions} onAdd={(d) => addDoc(collection(db, "transactions"), d)} onUpdate={(id, d) => updateDoc(doc(db, "transactions", id), d)} onDelete={(id) => deleteDoc(doc(db, "transactions", id))} customers={customers} services={services} />;
        case View.ADMIN_MARKETING: return <AdminMarketing customers={customers} promotions={promotions} services={services} bookings={bookings} />;
        default: return <AdminDashboard bookings={bookings} transactions={transactions} customers={customers} settings={settings} />;
      }
    }

    if (currentUser && currentView === View.CUSTOMER_DASHBOARD) {
       return (
         <CustomerDashboard 
            customer={currentUser} 
            bookings={bookings} 
            services={services}
            settings={settings}
            onBook={handleBook}
            onUpdateProfile={(upd) => updateDoc(doc(db, "customers", currentUser.id), upd)}
            onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }}
            onCancelBooking={handleCancelBooking}
            onAddToWaitlist={handleAddToWaitlist}
            waitlist={waitlist.filter(w => w.customerId === currentUser.id && w.status !== 'cancelled')}
            onRemoveWaitlist={handleCancelWaitlist}
            promotions={promotions}
         />
       );
    }

    switch (currentView) {
      case View.CUSTOMER_REGISTER: return <CustomerRegister onRegister={handleRegister} customers={customers} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      case View.CUSTOMER_LOGIN: return <CustomerLoginView onLogin={handleLogin} onRegisterClick={() => setCurrentView(View.CUSTOMER_REGISTER)} onBack={() => setCurrentView(View.CUSTOMER_HOME)} />;
      default: return (
        <CustomerHome 
          settings={settings} services={services} bookings={bookings} 
          onBook={handleBook} 
          onAuthClick={() => setCurrentView(View.CUSTOMER_LOGIN)} 
          onAddToWaitlist={handleAddToWaitlist} 
          currentUser={currentUser} 
        />
      );
    }
  };

  return (
    <div className="min-h-screen bg-white">
      {currentView !== View.CUSTOMER_DASHBOARD && (
        <Navbar view={currentView} setView={setCurrentView} isAdmin={isAdmin} onToggleAdmin={() => { setIsAdmin(!isAdmin); if(!isAdminAuthenticated) setCurrentView(View.ADMIN_LOGIN); else setCurrentView(isAdmin ? View.CUSTOMER_HOME : View.ADMIN_DASHBOARD); }} salonName={settings.name} logo={settings.logo} currentUser={currentUser} onLogout={() => { setCurrentUser(null); setCurrentView(View.CUSTOMER_HOME); }} onAdminLogout={() => { setIsAdminAuthenticated(false); setIsAdmin(false); setCurrentView(View.CUSTOMER_HOME); }} isAdminAuthenticated={isAdminAuthenticated} pendingBookingsCount={bookings.filter(b => b.status === 'pending').length} />
      )}
      <main className={currentView === View.CUSTOMER_DASHBOARD ? "" : "max-w-7xl mx-auto px-4 py-8"}>
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Customer, Promotion, Service, Booking } from '../types';
import { GoogleGenAI } from '@google/genai';
import { db } from '../firebase.ts';
import { collection, addDoc, deleteDoc, doc, updateDoc } from "firebase/firestore";

interface AdminMarketingProps {
  customers: Customer[];
  promotions: Promotion[];
  services: Service[];
  bookings: Booking[];
}

const AdminMarketing: React.FC<AdminMarketingProps> = ({ 
  customers = [], 
  promotions = [], 
  services = [],
  bookings = []
}) => {
  const [activeTab, setActiveTab] = useState<'promotions' | 'tips'>('promotions');
  const [isGenerating, setIsGenerating] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [selectedPromotion, setSelectedPromotion] = useState<Promotion | null>(null);

  // Estado do Formulário
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [discount, setDiscount] = useState(0);
  const [linkedServiceId, setLinkedServiceId] = useState<string>('');
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [endDate, setEndDate] = useState(new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]);
  const [selectedServices, setSelectedServices] = useState<string[]>([]);
  const [selectedCustomerIds, setSelectedCustomerIds] = useState<Set<string>>(new Set());
  const [searchTerm, setSearchTerm] = useState('');

  // Filtro de clientes com proteção contra campos nulos
  const eligibleCustomers = useMemo(() => {
    return (customers || []).filter(c => {
      if (!c) return false;
      const name = (c.name || '').toLowerCase();
      const whatsapp = (c.whatsapp || '');
      const search = (searchTerm || '').toLowerCase();
      return c.receivesNotifications && (name.includes(search) || whatsapp.includes(search));
    });
  }, [customers, searchTerm]);

  // Filtro e Ordenação por Tipo
  const displayItems = useMemo(() => {
    return [...(promotions || [])]
      .filter(p => activeTab === 'promotions' ? p.type === 'promotion' : p.type === 'tip')
      .sort((a, b) => (b.createdAt || '').localeCompare(a.createdAt || ''));
  }, [promotions, activeTab]);

  const toggleService = (id: string) => {
    setSelectedServices(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const toggleSelectAll = () => {
    if (selectedCustomerIds.size === eligibleCustomers.length) {
      setSelectedCustomerIds(new Set());
    } else {
      setSelectedCustomerIds(new Set(eligibleCustomers.map(c => c.id)));
    }
  };

  const generateAIContent = async () => {
    if (!title) return alert("Defina um título para a IA entender o tema.");
    setIsGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const linkedService = services.find(s => s.id === linkedServiceId);
      let prompt = "";

      if (activeTab === 'promotions') {
        prompt = `Crie uma mensagem persuasiva de WhatsApp para Studio Moriá. Título: ${title}. ${linkedService ? `Procedimento Vinculado: ${linkedService.name}.` : ''} Desconto: ${discount}%. Validade: até ${new Date(endDate).toLocaleDateString()}. Foco: Vendas e Agendamento. Seja elegante e use emojis. Retorne apenas o texto da mensagem.`;
      } else {
        prompt = `Crie uma dica de cuidados estéticos profissional para as clientes do Studio Moriá. Tema: ${title}. ${linkedService ? `Relacionado ao serviço: ${linkedService.name}.` : ''} Seja educativa, carinhosa e elegante. Use emojis. Retorne apenas o texto da mensagem de WhatsApp.`;
      }

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });
      setContent(response.text || '');
    } catch (e) { 
      alert("Erro na IA."); 
    } finally { 
      setIsGenerating(false); 
    }
  };

  const saveCampaign = async () => {
    if (!title.trim() || !content.trim()) return alert("Título e conteúdo são obrigatórios.");
    if (selectedCustomerIds.size === 0) return alert("Selecione pelo menos uma cliente.");

    try {
      const promoData: Omit<Promotion, 'id'> = {
        title,
        content,
        type: activeTab === 'promotions' ? 'promotion' : 'tip',
        discountPercentage: activeTab === 'promotions' ? discount : 0,
        linkedServiceId: linkedServiceId || undefined,
        applicableServiceIds: selectedServices,
        targetCustomerIds: Array.from(selectedCustomerIds),
        startDate,
        endDate,
        createdAt: new Date().toISOString(),
        isActive: true
      };

      await addDoc(collection(db, "promotions"), promoData);

      const header = activeTab === 'promotions' ? '🌟 *PROMOÇÃO STUDIO MORIÁ* 🌟' : '🌿 *DICA DA MORIÁ* 🌿';
      const message = `${header}\n\n${content}`;
      const targetCustomers = customers.filter(c => selectedCustomerIds.has(c.id));

      if (confirm(`Registro salvo! Deseja abrir os links de WhatsApp para as ${targetCustomers.length} clientes agora?`)) {
        targetCustomers.forEach((c, i) => {
          const cleanPhone = (c.whatsapp || '').replace(/\D/g, '');
          if (cleanPhone) {
            const url = `https://wa.me/${cleanPhone}?text=${encodeURIComponent(message)}`;
            setTimeout(() => window.open(url, '_blank'), i * 1500);
          }
        });
      }

      setShowForm(false);
      resetForm();
    } catch (e) { alert("Erro ao salvar."); }
  };

  const resetForm = () => {
    setTitle(''); setContent(''); setDiscount(0); setLinkedServiceId('');
    setSelectedServices([]); setSelectedCustomerIds(new Set());
  };

  // Lógica de Performance
  const getPromotionStats = (promo: Promotion) => {
    // Clientes que receberam a promoção e agendaram
    const conversions = bookings.filter(b => 
      b.promotionId === promo.id || 
      (promo.targetCustomerIds.includes(b.customerId) && 
       b.serviceId === promo.linkedServiceId && 
       new Date(b.dateTime.replace(' ', 'T')) >= new Date(promo.startDate))
    );

    const uniqueConverteds = new Set(conversions.map(b => b.customerId));
    const totalAlvos = promo.targetCustomerIds.length;
    const effectiveness = totalAlvos > 0 ? (uniqueConverteds.size / totalAlvos) * 100 : 0;

    return {
      totalAlvos,
      conversionsCount: conversions.length,
      uniqueConverteds: uniqueConverteds.size,
      effectiveness
    };
  };

  if (selectedPromotion) {
    const stats = getPromotionStats(selectedPromotion);
    const alvos = customers.filter(c => selectedPromotion.targetCustomerIds.includes(c.id));

    return (
      <div className="space-y-8 animate-fade-in pb-20">
        <button onClick={() => setSelectedPromotion(null)} className="text-tea-700 font-bold uppercase text-[10px] tracking-widest flex items-center gap-2 group">
          <span className="group-hover:-translate-x-1 transition-transform">←</span> Voltar ao Histórico
        </button>

        <div className="bg-white p-10 rounded-[3.5rem] shadow-xl border border-gray-100 flex flex-col md:flex-row gap-10">
           <div className="flex-1 space-y-4">
              <div className="flex items-center gap-3">
                 <span className={`px-4 py-1.5 rounded-full text-[8px] font-bold uppercase tracking-widest ${selectedPromotion.type === 'promotion' ? 'bg-orange-500 text-white' : 'bg-tea-900 text-white'}`}>
                    {selectedPromotion.type === 'promotion' ? 'Análise de Conversão' : 'Alcance da Dica'}
                 </span>
                 <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Publicada em {new Date(selectedPromotion.createdAt).toLocaleDateString()}</p>
              </div>
              <h2 className="text-3xl font-serif text-tea-950 font-bold italic">{selectedPromotion.title}</h2>
              <div className="p-6 bg-gray-50 rounded-3xl border border-gray-100 italic text-gray-600 text-xs leading-relaxed whitespace-pre-line">
                "{selectedPromotion.content}"
              </div>
           </div>

           <div className="w-full md:w-80 space-y-4">
              <div className="bg-tea-950 p-8 rounded-[2.5rem] text-white space-y-2 relative overflow-hidden">
                 <div className="absolute top-0 right-0 p-4 opacity-10 text-6xl">📈</div>
                 <p className="text-[9px] font-bold text-tea-300 uppercase tracking-widest">Efetividade Moriá</p>
                 <p className="text-4xl font-serif font-bold italic">{stats.effectiveness.toFixed(1)}%</p>
                 <div className="w-full h-1.5 bg-white/10 rounded-full mt-4">
                    <div className="h-full bg-tea-400 rounded-full transition-all duration-1000" style={{ width: `${stats.effectiveness}%` }}></div>
                 </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div className="bg-white p-6 rounded-3xl border border-gray-100 text-center">
                    <p className="text-[8px] text-gray-400 font-bold uppercase mb-1">Impactadas</p>
                    <p className="text-2xl font-serif font-bold text-tea-950">{stats.totalAlvos}</p>
                 </div>
                 <div className="bg-white p-6 rounded-3xl border border-gray-100 text-center">
                    <p className="text-[8px] text-gray-400 font-bold uppercase mb-1">Convertidas</p>
                    <p className="text-2xl font-serif font-bold text-tea-950">{stats.uniqueConverteds}</p>
                 </div>
              </div>
           </div>
        </div>

        <section className="space-y-6">
           <h3 className="text-xl font-serif text-tea-950 italic font-bold ml-4">Monitoramento de Alvos ({alvos.length})</h3>
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {alvos.map(c => {
                const converted = bookings.some(b => b.customerId === c.id && (b.promotionId === selectedPromotion.id || (b.serviceId === selectedPromotion.linkedServiceId && b.status === 'completed')));
                return (
                  <div key={c.id} className="bg-white p-6 rounded-[2rem] border border-gray-50 flex items-center justify-between hover:border-tea-200 transition-all">
                    <div className="flex items-center gap-4">
                       <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-bold text-sm ${converted ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-400'}`}>
                          {c.name.charAt(0)}
                       </div>
                       <div>
                          <p className="font-bold text-tea-950 text-xs">{c.name}</p>
                          <p className="text-[9px] text-gray-400 uppercase tracking-widest">{c.whatsapp}</p>
                       </div>
                    </div>
                    {converted ? (
                      <span className="text-[8px] bg-green-50 text-green-600 px-2 py-1 rounded-full font-bold uppercase tracking-widest">Converteu ✓</span>
                    ) : (
                      <span className="text-[8px] bg-gray-50 text-gray-300 px-2 py-1 rounded-full font-bold uppercase tracking-widest italic">Aguardando</span>
                    )}
                  </div>
                );
              })}
           </div>
        </section>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6">
        <div>
          <h2 className="text-3xl font-serif text-tea-950 font-bold italic">Marketing Moriá</h2>
          <div className="flex gap-4 mt-2">
            <button 
              onClick={() => { setActiveTab('promotions'); setShowForm(false); }}
              className={`text-[10px] font-bold uppercase tracking-[0.2em] transition-all pb-1 border-b-2 ${activeTab === 'promotions' ? 'border-tea-900 text-tea-950' : 'border-transparent text-gray-400'}`}
            >
              Promoções 🏷️
            </button>
            <button 
              onClick={() => { setActiveTab('tips'); setShowForm(false); }}
              className={`text-[10px] font-bold uppercase tracking-[0.2em] transition-all pb-1 border-b-2 ${activeTab === 'tips' ? 'border-tea-900 text-tea-950' : 'border-transparent text-gray-400'}`}
            >
              Dicas de Estética ✨
            </button>
          </div>
        </div>
        <button 
          onClick={() => setShowForm(!showForm)} 
          className="w-full sm:w-auto bg-tea-900 text-white px-8 py-4 rounded-2xl font-bold uppercase tracking-widest text-[10px] shadow-xl hover:bg-black transition-all"
        >
          {showForm ? '← Voltar' : activeTab === 'promotions' ? '+ Nova Promoção' : '+ Nova Dica'}
        </button>
      </div>

      {showForm ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-slide-up">
          <div className="lg:col-span-8 bg-white p-6 md:p-10 rounded-[3rem] shadow-sm border border-gray-100 space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">{activeTab === 'promotions' ? 'Título da Promoção' : 'Título da Dica'}</label>
                <input type="text" value={title} onChange={e => setTitle(e.target.value)} placeholder={activeTab === 'promotions' ? "Ex: Mês das Noivas" : "Ex: Cuidados Pós-Micro"} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-tea-100 focus:bg-white transition-all" />
              </div>
              {activeTab === 'promotions' && (
                <div className="space-y-2">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Desconto (%)</label>
                  <input type="number" value={discount} onChange={e => setDiscount(Number(e.target.value))} min="0" max="100" className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none" />
                </div>
              )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Vincular Procedimento (Opcional)</label>
                <select 
                  value={linkedServiceId} 
                  onChange={e => setLinkedServiceId(e.target.value)}
                  className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-tea-100 transition-all appearance-none"
                >
                  <option value="">Nenhum procedimento específico</option>
                  {services.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Início</label>
                  <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Término</label>
                  <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none" />
                </div>
              </div>
            </div>

            <div className="space-y-4 pt-4 border-t border-gray-50">
               <div className="flex justify-between items-center">
                 <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-2">Conteúdo para WhatsApp</label>
                 <button onClick={generateAIContent} disabled={isGenerating} className="text-[9px] font-bold text-tea-600 uppercase hover:underline">
                    {isGenerating ? 'A IA está escrevendo...' : 'Gerar com IA ✨'}
                 </button>
               </div>
               <textarea rows={8} value={content} onChange={e => setContent(e.target.value)} placeholder="O que a cliente receberá..." className="w-full p-6 bg-gray-50 rounded-3xl outline-none focus:ring-2 focus:ring-tea-100 transition-all text-sm leading-relaxed" />
            </div>
          </div>

          <div className="lg:col-span-4 flex flex-col gap-6">
             <div className="bg-white p-6 md:p-8 rounded-[3rem] shadow-sm border border-gray-100 flex-grow flex flex-col min-h-[400px]">
                <h3 className="text-xs font-bold text-tea-950 uppercase tracking-widest mb-6">Público Alvo</h3>
                <input type="text" placeholder="Filtrar clientes..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full p-3 bg-gray-50 rounded-xl text-xs mb-4 outline-none" />
                <div className="flex-grow overflow-y-auto max-h-[300px] space-y-2 custom-scroll pr-2">
                   {eligibleCustomers.map(c => (
                     <label key={c.id} className={`flex items-center gap-3 p-4 rounded-2xl border-2 transition-all cursor-pointer ${selectedCustomerIds.has(c.id) ? 'bg-tea-50 border-tea-200' : 'bg-white border-transparent hover:bg-gray-50'}`}>
                        <input type="checkbox" checked={selectedCustomerIds.has(c.id)} onChange={() => {
                          const next = new Set(selectedCustomerIds);
                          next.has(c.id) ? next.delete(c.id) : next.add(c.id);
                          setSelectedCustomerIds(next);
                        }} className="w-4 h-4 rounded text-tea-900 focus:ring-tea-900 border-gray-300" />
                        <div className="text-[11px]">
                          <p className="font-bold text-tea-950">{c.name}</p>
                          <p className="text-gray-400">{c.whatsapp}</p>
                        </div>
                     </label>
                   ))}
                </div>
                <div className="pt-6 mt-4 border-t border-gray-50">
                   <button onClick={saveCampaign} disabled={selectedCustomerIds.size === 0} className="w-full py-5 bg-tea-900 text-white rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl transition-all hover:bg-black">
                    Finalizar & Enviar ({selectedCustomerIds.size})
                   </button>
                </div>
             </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          {displayItems.map(promo => {
            const today = new Date().toISOString().split('T')[0];
            const isPast = (promo.endDate || '') < today;
            const linkedService = services.find(s => s.id === promo.linkedServiceId);
            const stats = getPromotionStats(promo);

            return (
              <div key={promo.id} className={`bg-white p-6 md:p-8 rounded-[2.5rem] border-2 shadow-sm flex flex-col md:flex-row justify-between items-center gap-6 transition-all ${isPast ? 'opacity-50' : 'border-tea-50 hover:border-tea-100'}`}>
                <div className="flex items-center gap-6 w-full md:w-auto">
                  <div className={`w-14 h-14 md:w-16 md:h-16 rounded-2xl flex items-center justify-center text-xl md:text-2xl font-bold ${activeTab === 'promotions' ? 'bg-tea-900 text-white shadow-lg' : 'bg-tea-100 text-tea-900 border border-tea-200'}`}>
                    {activeTab === 'promotions' ? (promo.discountPercentage === 100 ? 'FREE' : `${promo.discountPercentage}%`) : '✨'}
                  </div>
                  <div className="flex-1">
                    <h3 className="font-bold text-tea-950 text-lg md:text-xl font-serif">{promo.title}</h3>
                    <div className="flex flex-wrap gap-2 mt-1">
                      <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">
                        {activeTab === 'tips' ? 'Publicada em:' : 'Expira em:'} {new Date(promo.endDate).toLocaleDateString()}
                      </p>
                      {linkedService && (
                        <span className="text-[9px] bg-tea-50 text-tea-700 px-2 py-0.5 rounded-full font-bold uppercase tracking-widest border border-tea-100">
                           Link: {linkedService.name}
                        </span>
                      )}
                      <span className="text-[9px] bg-gray-100 text-gray-600 px-2 py-0.5 rounded-full font-bold uppercase tracking-widest">
                         Efetividade: {stats.effectiveness.toFixed(0)}%
                      </span>
                    </div>
                  </div>
                </div>
                <div className="flex gap-2 w-full md:w-auto">
                   <button onClick={() => setSelectedPromotion(promo)} className="flex-grow md:flex-none px-6 py-3 bg-tea-50 text-tea-900 rounded-xl font-bold uppercase text-[9px] tracking-widest hover:bg-tea-100 transition-all">Ver Performance 📊</button>
                   <button onClick={async () => { if(confirm("Remover permanentemente?")) await deleteDoc(doc(db, "promotions", promo.id)); }} className="p-3 bg-gray-50 text-gray-400 rounded-xl hover:text-red-500 transition-colors">🗑️</button>
                </div>
              </div>
            );
          })}

          {displayItems.length === 0 && (
            <div className="text-center py-32 bg-gray-50 rounded-[4rem] border-2 border-dashed border-gray-200">
               <p className="text-gray-400 font-serif italic text-xl">Nenhum registro encontrado.</p>
               <button onClick={() => setShowForm(true)} className="text-tea-600 font-bold text-xs uppercase tracking-widest mt-4 hover:underline">
                  Começar agora
               </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

