      const updatedMembers = settings.teamMembers.map(m => 
        m.id === memberData.id ? memberData : m
      );
      const newSet = { ...settings, teamMembers: updatedMembers, lastUpdated: Date.now() };
      await setDoc(doc(db, "settings", "main"), newSet);
      alert("Seu perfil profissional foi atualizado com sucesso!");
    } catch (e) {
      alert("Erro ao salvar perfil.");
    }
