                 </div>
              </div>
           </div>

           <div className="space-y-6">
              <h4 className="text-[10px] font-bold text-tea-700 uppercase tracking-widest">Logotipo</h4>
              <div className="flex items-center gap-6">
                 <img src={globalSettings.logo} className="h-20 w-auto object-contain bg-tea-900 p-2 rounded-xl" alt="Logo" />
                 <input type="text" placeholder="Link do Logotipo" value={globalSettings.logo} onChange={e => setGlobalSettings({...globalSettings, logo: e.target.value})} className="flex-1 p-4 bg-gray-50 rounded-2xl font-bold" />
              </div>
           </div>
        </section>
      )}

      {/* Rodapé de Informação */}
      <div className="text-center opacity-30 italic text-[10px] uppercase tracking-widest">
        Studio Moriá Estética • Sistema de Gestão Inteligente
      </div>
    </div>
  );
};

